-- Rivals Coach — cartes manquantes et placement par rôle, « ce qui a bien marché », compo adverse,
-- rang dans le profil, stats communautaires par rang (saison 10.5), vocabulaire corrigé dans les guides.
-- À exécuter après 0013_maps_general_kits.sql. Ré-exécutable. Les icônes et captures ajoutées dans l'admin
-- sont conservées, mais le texte des guides listés ici est remplacé.

-- 1. Cartes manquantes
insert into public.maps (name, game_mode_id) select 'Lower Manhattan', id from public.game_modes where name = 'Convergence' on conflict (name) do nothing;
insert into public.maps (name, game_mode_id) select 'Museum of Contemplation', id from public.game_modes where name = 'Convoi' on conflict (name) do nothing;
insert into public.maps (name, game_mode_id) select 'Thebes', id from public.game_modes where name = 'Convoi' on conflict (name) do nothing;
insert into public.maps (name, game_mode_id) select 'Klyntar: Celestial Husk', id from public.game_modes where name = 'Domination' on conflict (name) do nothing;
insert into public.maps (name, game_mode_id) select 'God Quarry', id from public.game_modes where name = 'Domination' on conflict (name) do nothing;

-- 2. Tags de partie : « ce qui a coincé » (mistake) et « ce qui a bien marché » (strength)
alter table public.error_tags add column if not exists kind text not null default 'mistake';
alter table public.error_tags drop constraint if exists error_tags_kind_check;
alter table public.error_tags add constraint error_tags_kind_check check (kind in ('mistake', 'strength'));
insert into public.error_tags (name, sort, kind) values
  ('Bon placement', 100, 'strength'),
  ('Ult bien placée', 101, 'strength'),
  ('Bonnes comms', 102, 'strength'),
  ('Bon focus des cibles', 103, 'strength'),
  ('Cooldowns bien gérés', 104, 'strength'),
  ('Clutch / sauvetage', 105, 'strength'),
  ('Mental solide', 106, 'strength'),
  ('Bon swap', 107, 'strength')
on conflict (name) do update set kind = 'strength';

-- 3. Compo adverse d'une partie
create table if not exists public.match_opponents (
  match_id uuid not null references public.matches (id) on delete cascade,
  hero_id  int  not null references public.heroes (id) on delete cascade,
  primary key (match_id, hero_id)
);
create index if not exists match_opponents_hero_idx on public.match_opponents (hero_id);
alter table public.match_opponents enable row level security;
drop policy if exists match_opponents_select on public.match_opponents;
drop policy if exists match_opponents_write on public.match_opponents;
create policy match_opponents_select on public.match_opponents for select to authenticated
  using (exists (select 1 from public.matches m where m.id = match_id and (m.user_id = auth.uid() or public.is_coach_of(m.user_id))));
create policy match_opponents_write on public.match_opponents for all to authenticated
  using (exists (select 1 from public.matches m where m.id = match_id and m.user_id = auth.uid()))
  with check (exists (select 1 from public.matches m where m.id = match_id and m.user_id = auth.uid()));
revoke all on public.match_opponents from anon;

-- Enregistrement atomique d'une partie : ajoute la compo adverse (enemy_ids, 6 héros au plus)
create or replace function public.save_match(p jsonb)
returns uuid language plpgsql security invoker set search_path = public as $$
declare
  v_id uuid := nullif(p ->> 'id', '')::uuid;
  h jsonb;
  i int := 0;
begin
  if jsonb_array_length(coalesce(p -> 'heroes', '[]'::jsonb)) = 0 then
    raise exception 'Au moins un héros est requis';
  end if;
  if jsonb_array_length(coalesce(p -> 'enemy_ids', '[]'::jsonb)) > 6 then
    raise exception 'Six héros adverses au plus';
  end if;

  if v_id is null then
    insert into matches (played_at, queue_id, game_mode_id, map_id, rank_id, result, duration_min, feeling, award, note)
    values (
      coalesce((p ->> 'played_at')::timestamptz, now()),
      (p ->> 'queue_id')::int, (p ->> 'game_mode_id')::int, (p ->> 'map_id')::int, (p ->> 'rank_id')::int,
      p ->> 'result', (p ->> 'duration_min')::numeric, (p ->> 'feeling')::smallint,
      nullif(p ->> 'award', ''), nullif(p ->> 'note', '')
    )
    returning id into v_id;
  else
    update matches set
      played_at = coalesce((p ->> 'played_at')::timestamptz, played_at),
      queue_id = (p ->> 'queue_id')::int, game_mode_id = (p ->> 'game_mode_id')::int,
      map_id = (p ->> 'map_id')::int, rank_id = (p ->> 'rank_id')::int,
      result = p ->> 'result', duration_min = (p ->> 'duration_min')::numeric,
      feeling = (p ->> 'feeling')::smallint, award = nullif(p ->> 'award', ''), note = nullif(p ->> 'note', '')
    where id = v_id and user_id = auth.uid();
    if not found then
      raise exception 'Partie introuvable';
    end if;
    delete from match_heroes where match_id = v_id;
    delete from match_tags where match_id = v_id;
    delete from match_opponents where match_id = v_id;
  end if;

  for h in select * from jsonb_array_elements(p -> 'heroes') loop
    if not exists (select 1 from heroes where id = (h ->> 'hero_id')::int and (h ->> 'role')::hero_role = any (roles)) then
      raise exception 'Rôle incompatible avec ce héros';
    end if;
    insert into match_heroes (match_id, hero_id, role, play_minutes, kills, deaths, assists, final_hits, damage, damage_blocked, healing, accuracy, position)
    values (
      v_id, (h ->> 'hero_id')::int, (h ->> 'role')::hero_role, (h ->> 'play_minutes')::numeric,
      (h ->> 'kills')::int, (h ->> 'deaths')::int, (h ->> 'assists')::int, (h ->> 'final_hits')::int,
      (h ->> 'damage')::int, (h ->> 'damage_blocked')::int, (h ->> 'healing')::int, (h ->> 'accuracy')::numeric, i
    );
    i := i + 1;
  end loop;

  insert into match_tags (match_id, tag_id)
  select v_id, value::int from jsonb_array_elements_text(coalesce(p -> 'tag_ids', '[]'::jsonb))
  on conflict do nothing;

  insert into match_opponents (match_id, hero_id)
  select v_id, value::int from jsonb_array_elements_text(coalesce(p -> 'enemy_ids', '[]'::jsonb))
  on conflict do nothing;

  return v_id;
end $$;
grant execute on function public.save_match(jsonb) to authenticated;
revoke execute on function public.save_match(jsonb) from anon, public;

-- 4. Rang actuel dans le profil (sert à la comparaison avec les joueurs du même rang)
alter table public.profiles add column if not exists rank_id int references public.ranks (id) on delete set null;
grant update (rank_id) on public.profiles to authenticated;

-- 5. Stats communautaires par rang (winrate, pick, ban) : lecture pour tous, écriture admin
create table if not exists public.hero_meta_stats (
  id          serial primary key,
  season      text not null,
  bracket     text not null check (bracket in ('bronze','silver','gold','platinum','diamond','diamond_plus','grandmaster','grandmaster_plus','celestial','celestial_plus','eternity','eternity_plus','one_above_all')),
  hero_id     int not null references public.heroes (id) on delete cascade,
  variant     public.hero_role,
  tier        text not null default 'Unrated',
  win_rate    numeric(5, 2) not null check (win_rate between 0 and 100),
  pick_rate   numeric(5, 2) not null check (pick_rate between 0 and 100),
  ban_rate    numeric(5, 2) check (ban_rate between 0 and 100),
  matches     int not null check (matches >= 0),
  captured_on date not null default current_date,
  source      text not null default ''
);
create unique index if not exists hero_meta_stats_uniq on public.hero_meta_stats (season, bracket, hero_id, variant) nulls not distinct;
alter table public.hero_meta_stats enable row level security;
drop policy if exists hero_meta_stats_select on public.hero_meta_stats;
drop policy if exists hero_meta_stats_admin on public.hero_meta_stats;
create policy hero_meta_stats_select on public.hero_meta_stats for select to authenticated using (true);
create policy hero_meta_stats_admin on public.hero_meta_stats for all to authenticated using (public.is_admin()) with check (public.is_admin());
revoke all on public.hero_meta_stats from anon;
delete from public.hero_meta_stats where season = 'Saison 10.5';
