-- Fusionne un nouveau contenu de guide avec l'existant : garde les icônes et captures
-- ajoutées par un admin sur les sections de même titre.
create or replace function public.rc_merge_guide(cur jsonb, nxt jsonb) returns jsonb
language sql immutable as $fn$
  select case
    when cur is null or jsonb_typeof(cur->'sections') <> 'array' or jsonb_typeof(nxt->'sections') <> 'array' then nxt
    else jsonb_set(nxt, '{sections}', coalesce((
      select jsonb_agg(
        case when o.sec is null then n.sec
             else n.sec || jsonb_strip_nulls(jsonb_build_object(
               'icon', nullif(o.sec->>'icon', ''),
               'image', o.sec->'image'))
        end order by n.idx)
      from jsonb_array_elements(nxt->'sections') with ordinality as n(sec, idx)
      left join lateral (
        select s as sec from jsonb_array_elements(cur->'sections') s
        where s->>'title' = n.sec->>'title' limit 1
      ) o on true
    ), '[]'::jsonb))
  end
$fn$;

-- 6. Guides des héros : vocabulaire corrigé (« à couvert », headshot, heal, flank…), team-ups S10.5
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"tags": ["Angles décalés", "Dégâts", "Anti-ult", "Résurrection"], "tldr": ["Joue **sur un angle décalé** et fais des dégâts : c'est ce qui charge ta résurrection.", "Ton **lien d'âmes** est ta meilleure capacité : garde-le pour contrer une ult qui tuerait un allié.", "Place ta **résurrection à couvert**, loin des ennemis, et survis pendant qu'elle agit."], "combos": [{"note": "Bien placé, il élimine une cible fragile.", "steps": [{"key": "Clic G", "label": "tir"}, {"key": "Clic D", "label": "tir chargé"}, {"key": "Clic G", "label": "tir"}], "title": "Combo rapproché"}], "sources": [{"url": "https://www.youtube.com/watch?v=GqRusLyDjL0", "title": "Adam Warlock Guide", "author": "Paz (padswagger)"}], "summary": "Adam Warlock est le support le plus exigeant mais l'un des plus rentables : il gagne en mettant la pression depuis des angles décalés, en chargeant son ult à grande vitesse et en utilisant son lien d'âmes pour annuler les ults adverses.", "counters": [{"hero": "venom", "note": "Il fond sur toi et force tes deux soins très vite : Adam a peu de mobilité."}, {"hero": "captain-america", "note": "Même problème : il colle Adam et vide ses ressources."}, {"hero": "groot", "note": "Ses murs bloquent tes angles et sont longs à détruire."}, {"hero": "hela", "note": "Elle gagne le duel à distance si elle vise bien la tête."}], "sections": [{"kind": "tips", "lead": "Si tu restes en retrait à soigner, n'importe quel autre support fera mieux le travail. Adam se joue agressif.", "items": ["Prends des **angles décalés**, fais un maximum de dégâts et **charge ton ult** plus vite que les autres supports.", "Utilise ton **lien d'âmes** pour bloquer une ult adverse clé ou pour permettre à ton équipe de forcer un fight.", "Les meilleurs Adam ne sont pas ceux qui visent le mieux : ce sont ceux qui **combinent dégâts et soins au bon moment**."], "title": "Philosophie de jeu", "diagram": "heal"}, {"key": "Clic G · Clic D", "lead": "Ton tir principal touche instantanément et fait très mal pour un support. Deux headshots laissent la plupart des cibles à un souffle.", "items": ["Le tir principal est **instantané** (hitscan) : très fiable, mais il **perd de la puissance à longue distance**.", "Le tir chargé envoie une salve de projectiles **sans perte de dégâts** à distance : idéal pour finir une cible de loin. Écarte un peu ta visée pour toucher plus de projectiles.", "Combo rapproché : **tir principal, tir chargé, tir principal**. Bien placé, il élimine une cible fragile.", "Les deux tirs partagent les **mêmes munitions** : recharge avant le fight pour ne pas être à sec au mauvais moment.", "Charge ton tir chargé **en tournant les angles** pour poker. Mais évite les dégâts inutiles qui donnent de l'ult gratuite aux supports adverses.", "Entraîne-toi à la visée **par clics** (statique et dynamique) : c'est exactement ce que demande Adam."], "title": "Dégâts", "ability": "Quantum Magic · Cosmic Cluster"}, {"lead": "Ton soin rebondit entre les alliés proches de ta cible, en priorité vers ceux qui ont le moins de PV. Tu n'en as que deux charges.", "items": ["Le soin **rebondit** sur les alliés autour de la cible, toujours vers celui qui a **le moins de PV bruts**.", "Sans allié autour, les rebonds reviennent sur la cible, puis **sur toi**. Vise le sol pour te soigner directement.", "N'utilise pas une charge sur un allié **à peine touché** : attends qu'il ait perdu une bonne partie de sa vie pour rentabiliser chaque soin.", "Tes auto-soins font d'Adam un **excellent duelliste**, mais c'est risqué : si tu gâches tes deux charges sur toi, ton équipe n'a plus de soins.", "Sur ton angle, **prends le moins de dégâts possible** : joue autour des couvertures et sors de préférence par la droite."], "title": "Soin", "ability": "Regenerative Cocoon (« le snap »)"}, {"key": "Maj", "lead": "Le lien partage les dégâts entre tous les alliés liés et les soigne un peu. Sa portée est courte : reste proche de ton équipe.", "items": ["Garde-le pour **contrer une ult qui tuerait un allié** : un Magneto qui vise ton support en pleine ult, une Psylocke, un Winter Soldier…", "Lance-le **un peu en avance** : il y a un court temps d'incantation pendant lequel tu peux être tué ou étourdi.", "Il ne sauve pas tout : si l'ult adverse fait plus de dégâts que vos PV cumulés, la cible meurt quand même.", "Lie en priorité les **personnages fragiles**. Les tanks ont déjà assez de PV et leur grosse hitbox casse le lien trop vite.", "Erreur classique : le lancer **trop tôt**, ou au contraire **le garder éternellement**. Sans ult en face, il peut aussi servir à forcer un fight que vous perdriez sinon.", "Le lien se rompt si tu t'éloignes trop de ton équipe."], "title": "Lien d'âmes", "ability": "Soul Bond"}, {"key": "Q", "lead": "Tu ressuscites les alliés qui meurent pendant quelques secondes. C'est l'ult la plus longue à charger du jeu, et l'une des plus fortes.", "items": ["Les alliés ressuscités reviennent **très faibles** : place l'ult **derrière un mur**, hors de portée des ennemis.", "Tu peux **mourir pendant l'incantation** : lance-la depuis un endroit sûr.", "Contre un combo d'ults inévitable (par exemple un Groot prêt à combiner), **joue à l'écart et ressuscite après** : une ult en contre deux.", "La portée se compte **autour de toi**, pas autour du point posé : tu peux marcher vers les alliés tombés, même ceux sortis de la carte.", "Pas besoin de tout le monde : ramener **un seul joueur clé** (un allié sur le point d'avoir son ult) peut gagner le fight.", "Plus tu montes en rang, plus l'ennemi **surveille ton ult** : joue encore plus prudemment quand elle est prête."], "title": "Ultime", "ability": "Karmic Revival"}, {"lead": "Quand elle est disponible, tu peux te relever après ta mort. Ça te permet de prendre un angle un peu plus risqué.", "items": ["Avec l'auto-résurrection prête, ose **un cran plus d'agressivité** : tu trouveras des kills que tu n'aurais pas tentés.", "L'ennemi **voit ton fantôme** et peut camper ton corps : relève-toi à l'abri.", "Ne te relève pas si le fight est déjà perdu : **garde-la pour le prochain**."], "title": "Passif : auto-résurrection", "ability": "Soul Perseverance"}, {"kind": "mistakes", "items": ["Rester **en retrait à soigner** au lieu de prendre un angle.", "**Gâcher ses soins** sur des alliés presque pleins.", "Lancer le lien **trop tôt** ou ne jamais l'utiliser.", "Poser la résurrection **à découvert**, où les alliés meurent aussitôt.", "Être **à sec de munitions** au début d'un fight."], "title": "Erreurs fréquentes"}], "synergies": [{"hero": "luna-snow", "note": "Son ult longue couvre les fights où toi tu joues sur un angle."}, {"hero": "star-lord", "note": "Il tourne autour des ennemis : vos dégâts combinés trouvent vite des kills."}, {"hero": "loki", "note": "Bon duo de supports pour se protéger mutuellement pendant une résurrection."}], "difficulty": 3, "patch_note": "Guide tiré d'une vidéo de Paz (padswagger), reformulé en français. Les chiffres du kit ont été retirés car ils changent à chaque saison ; team-ups et derniers changements sont à jour (saison 10.5) dans la section dédiée.", "kit": {"season": "Saison 10.5", "health": "", "abilities": [], "teamups": [{"name": "Cosmic Cyclone", "partners": ["storm"], "key": "", "text": "Soul Bond donne un boost de vitesse. **Amélioré :** Ajoute un boost de dégâts."}, {"name": "Duality Dance", "partners": ["luna-snow"], "key": "", "text": "Soul Bond relie et soigne. **Amélioré :** Les critiques réduisent les cooldowns."}, {"name": "Flawless Design", "partners": ["ultron"], "key": "", "text": "Les Cosmic Cluster d'Adam soignent les alliés (18 par projectile en 10.5). **Amélioré :** Explosion de soin à l'impact (7 en 10.5)."}, {"name": "Star-Soul", "partners": ["star-lord"], "key": "", "text": "Téléportation sur une balise et réapparition en cocon. **Amélioré :** Les kills réduisent le cooldown de la balise."}, {"name": "Vitality Pact", "partners": ["mantis"], "key": "", "text": "L'état d'âme soigne et reforge (fleur à 12 + 3 %/s depuis la saison 10). **Amélioré :** Soul Bond avec soin sur la durée."}], "changes": [{"season": "Saison 10.5", "text": "Team-up avec Ultron : 18 de soin par Cosmic Cluster, 7 de soin d'explosion en version améliorée."}, {"season": "Saison 10", "text": "Tous les Strategists : l'ult se charge un peu moins vite (65 % du soin et 50 % des dégâts convertis en énergie, au lieu de 70 % et 55 %)."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · changements : patch notes des saisons 10 et 10.5", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'adam-warlock' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"tags": ["Pick", "Déplacement d'ennemis", "Brawl", "Vol"], "tldr": ["Ton rôle : **attraper une cible et la ramener** vers ton équipe, pas la tuer seule.", "Lance ta charge **quand tu as une ligne de retour** vers tes alliés.", "Après le pick, pose ta **zone de jugement** et brawle groupé : tes alliés gagnent de la vie bonus."], "combos": [{"note": "Lever le bouclier après le combo **regagne de la jauge**.", "steps": [{"key": "Mêlée", "label": ""}, {"key": "", "label": "Coup de lance"}, {"key": "Clic D", "label": "bouclier"}], "title": "Combo de base"}, {"note": "Porter une cible recharge vite ta jauge de dégâts.", "steps": [{"key": "", "label": "Coup de lance"}, {"key": "Maj", "label": "charge"}, {"key": "", "label": "Coup de lance"}], "title": "Recharger la jauge"}], "sources": [{"url": "https://www.youtube.com/watch?v=HRkY4e6CFow", "title": "Angela Guide", "author": "Paz (padswagger)"}], "summary": "Angela est un tank volant qui va chercher une cible sur un angle et la ramène dans son équipe pour qu'elle la finisse. Une fois le pick obtenu, elle passe aux haches et brawle avec ses alliés en leur donnant de la vie bonus.", "counters": [{"hero": "magneto", "note": "Sa bulle protège ta cible et annule ta charge."}, {"hero": "hulk", "note": "Même chose avec sa bulle sur ses alliés."}, {"hero": "the-punisher", "note": "Ses dégâts continus te font fondre."}, {"hero": "invisible-woman", "note": "Ses poussées et attractions coupent tout ce que tu tentes."}, {"hero": "luna-snow", "note": "Elle peut te geler en pleine charge."}], "sections": [{"kind": "tips", "lead": "Angela fait peu de dégâts seule. Sa force, c'est de déplacer un ennemi au bon endroit, au bon moment.", "items": ["Prends un **léger angle**, attrape une cible isolée et **ramène-la dans ton équipe** pour qu'elle la focus.", "Sans équipe pour suivre, le pick ne se convertit pas : **joue avec tes alliés**, pas seule dans leur dos.", "Elle est aussi bonne **contre le dive** : groupez-vous dans ta zone pour profiter de la vie bonus."], "title": "Philosophie de jeu", "diagram": "pull"}, {"lead": "Angela vole en permanence et charge la jauge sous son viseur en se déplaçant. Plus la jauge est pleine, plus la lance frappe fort.", "items": ["Le vol **remplit ta jauge de dégâts**. Astuce : vole contre un mur pour la charger **sans t'exposer** pendant les phases de poke.", "Tu es **très bruyante** en vol : n'espère pas surprendre. Ne pars en flank que si tu es sûre de revenir.", "Combo de base : **coup de mêlée puis coup de lance**, puis lève ton bouclier pour regagner de la jauge.", "La lance **transperce** : deux ennemis alignés prennent tous les deux.", "Garde un coup de lance chargé pour **pousser un ennemi dans le vide** : son effet de projection rend les éjections bien plus fiables."], "title": "Vol et lance", "ability": "Seraphic Sword · Spear of Ichor"}, {"key": "Maj", "lead": "Tu fonces et embarques jusqu'à deux ennemis. C'est ta capacité signature, et elle vide vite ton énergie quand tu portes quelqu'un.", "items": ["Lance-la quand tu as une **ligne directe vers ton équipe** : la cible doit atterrir chez tes alliés quand ton énergie s'épuise.", "Ne l'utilise **pas en début de fight** : place-toi d'abord, dépense ta jauge de dégâts, puis attrape.", "Porter une cible **recharge vite ta jauge de dégâts** : enchaîne coup de lance, charge, puis nouveau coup.", "Très forte pour **sortir un support de son ult** (Cloak & Dagger, Invisible Woman) : ton équipe n'a plus qu'à le focus.", "Les contrôles (gel, étourdissement, projection) **t'arrêtent net** en pleine charge.", "Option : le mode **maintenir pour charger** est plus précis, à tester dans les paramètres."], "title": "Charge de l'assassin", "ability": "Assassin's Charge"}, {"key": "E", "lead": "Tu plonges au sol, poses une zone et passes aux haches. Chaque coup dans la zone te donne de la vie bonus, et à tes alliés aussi.", "items": ["Dans la zone, tu vas **plus vite** et chaque coup de hache donne de la **vie bonus** à toi et à tes alliés présents.", "Les haches **frappent plusieurs ennemis** à la fois : idéal pour brawler sur le point.", "Le cooldown ne repart que quand tu **reprends ta forme de vol** : ne reste pas aux haches une fois la zone disparue.", "Exception : reste aux haches si tu frappes beaucoup d'ennemis à la fois (pendant une ult de support), ça charge ton ult."], "title": "Zone de jugement et haches", "ability": "Divine Judgment · Axes of Ichor"}, {"key": "Clic D", "lead": "Petit bouclier frontal qui ne te ralentit pas et remplit ta jauge de dégâts quand il encaisse.", "items": ["Ne bloque pas les petits dégâts : ta barre de vie s'en charge. **Garde-le pour l'important**.", "Bloque **les contrôles** quand tu repars, et les ults comme celles de Hela, Magneto ou Doctor Strange.", "Fonce sur un support **bouclier levé** pour ne pas te faire geler en approchant."], "title": "Bouclier"}, {"key": "Q", "lead": "Tu plantes ta lance au sol : les ennemis autour y sont attachés et fortement ralentis. Réappuie pour bondir dessus et créer une zone gratuite.", "items": ["Vise **le sol, un mur ou un plafond** : lancée sur un ennemi en l'air, la lance traverse et se perd. Évite les escaliers.", "Les ennemis attachés ne peuvent pas utiliser leurs **déplacements** : parfait pour enchaîner avec une ult de zone (Moon Knight, Phoenix, Human Torch…).", "Combo fort : **sortir un support de son ult** avec la charge, puis l'attacher pour que ton équipe le finisse.", "Le rebond sur la lance est une **zone de jugement gratuite** : utilise ta vraie zone tôt dans le fight, puis l'ult pour la seconde vague.", "Elle est **longue à charger** pour les dégâts que tu fais : optimise ton kit pour l'obtenir."], "title": "Ultime", "ability": "Heaven's Retribution"}, {"kind": "mistakes", "items": ["Charger une cible **sans ligne de retour** vers ton équipe.", "Utiliser la charge **dès le début** du fight.", "Partir en flank **bruyamment** et mourir seule.", "Lever le bouclier sur des **dégâts insignifiants**.", "Lancer l'ult **sur un ennemi en l'air** au lieu du sol."], "title": "Erreurs fréquentes"}], "synergies": [{"hero": "emma-frost", "note": "Elle tient la ligne de front pendant que tu joues ton angle."}, {"hero": "magneto", "note": "Autre tank solide pour tenir le point à ta place."}, {"hero": "phoenix", "note": "Elle finit facilement la cible que tu ramènes."}, {"hero": "jeff-the-land-shark", "note": "Ses bulles de vitesse te permettent d'emmener une cible beaucoup plus loin."}], "difficulty": 2, "patch_note": "Guide tiré d'une vidéo de Paz (padswagger), reformulé en français. Les chiffres du kit ont été retirés car ils changent à chaque saison ; team-ups et derniers changements sont à jour (saison 10.5) dans la section dédiée.", "kit": {"season": "Saison 10.5", "health": "", "abilities": [], "teamups": [{"name": "Asgardians of the Galaxy", "partners": ["star-lord"], "key": "", "text": "Révèle une zone et cloue les ennemis au sol avec un impact. **Amélioré :** Ajoute de la vie bonus."}, {"name": "Divine Armory", "partners": ["thor"], "key": "", "text": "La lance de foudre rend de la Thorforce. **Amélioré :** Vie bonus sur le saut."}, {"name": "Odin's Unacknowledged", "partners": ["loki"], "key": "", "text": "Une illusion d'estoc projette les ennemis (dégâts max encaissés : 150 depuis la saison 10). **Amélioré :** Deux charges."}], "changes": [{"season": "Saison 10", "text": "Team-up avec Loki : dégâts max encaissés par l'illusion 250 → 150."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · changements : patch notes des saisons 10 et 10.5", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'angela' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"tags": ["Dive", "Économie d'or", "Duels", "Utilitaire"], "tldr": ["**Pas d'or, pas de Black Cat** : touche ton grappin en début de fight pour te refaire.", "Combo de base : **grappin, dash aux pieds, coups, fouet, poursuite fantôme**.", "Ta poursuite fantôme te rend **intouchable** un court instant : garde-la pour esquiver un contrôle."], "sources": [{"url": "https://www.youtube.com/watch?v=pL7mAWytrB0", "title": "Black Cat Guide", "author": "Paz (padswagger)"}, {"title": "Ultimate Black Cat Guide (Beginner/Advanced)", "author": "Tephra98", "url": "https://www.youtube.com/watch?v=OZlJLd2sULs"}], "summary": "Black Cat est une héroïne de dive qui frappe vite et fort après avoir forcé les cooldowns adverses. Tout son kit tourne autour de l'or : elle en gagne en touchant ses capacités et le dépense pour des gadgets qui rendent ses engages mortels.", "counters": [{"hero": "the-thing", "note": "Il te verrouille au corps à corps."}, {"hero": "peni-parker", "note": "Son nid gêne tes dives. Contourne-le avec l'anneau-portail."}, {"hero": "phoenix", "note": "Ses auto-soins et ses étourdissements cassent tes combos."}, {"hero": "invisible-woman", "note": "Ses poussées et attractions la rendent très dure à diver."}], "sections": [{"kind": "tips", "lead": "Black Cat ne farme pas des dégâts sur la durée : elle force les cooldowns, puis frappe en rafale pour trouver un kill.", "items": ["Entre deux dives, **farme de l'or** : il rend ton prochain engage bien plus dangereux.", "Vise d'avoir un **bon matelas d'or** avant d'engager pour de vrai.", "Mourir te fait **perdre une partie de ton or** : si la mort est inévitable, achète un gadget avant, il reste après la réapparition.", "En duel isolé, elle est redoutable grâce à la **vie bonus** de ses coups : cherche les 1v1."], "title": "Philosophie de jeu", "diagram": "flank"}, {"key": "E", "lead": "Chaque capacité qui touche rapporte de l'or. Le grappin est ta principale source : rate-le et tu ne fais plus rien du fight.", "items": ["Le **grappin** rapporte beaucoup d'or et un peu de vie bonus. Vise les **tanks** : grosse hitbox, impossible à rater.", "En milieu de fight, un grappin sur une cible épaisse te donne de la **vie bonus** pour rester plus longtemps.", "Tes coups marquent les ennemis : tu les **vois à travers les murs** et ils ont une chance de rater leurs headshots sur toi.", "Concentre-toi sur la **précision du grappin** quand tu apprends le perso : tu vis ou tu meurs par l'or.", "Le grappin rapporte **la même quantité d'or quelle que soit la cible** : en manque d'or, accroche un tank, son cooldown est court.", "Garde **de quoi enchaîner fouet et poursuite** en réserve avant d'engager."], "title": "Gagner de l'or", "ability": "Sticky Paws · Turn of Fortune"}, {"key": "Clic G · Clic D", "lead": "Tes griffes et ton fouet font des dégâts de zone devant toi et te donnent de la vie bonus.", "items": ["Alterne **coups de griffes et fouet** : c'est rentable en or et tu gagnes de la vie bonus à chaque touche.", "Le fouet frappe **en cône** devant toi, plus efficace face à la cible qu'à ses côtés.", "**Poursuite fantôme** : un bond à distance qui te rend **insensible aux contrôles avec 50 % de réduction de dégâts** (elle n'est plus intouchable depuis la saison 10) un instant. Il esquive des ults (Doctor Strange, Winter Soldier, Magneto) ou des contrôles (boule de neige de Luna, flash de Cloak).", "Garde la poursuite pour **finir une cible qui fuit** ou **esquiver un contrôle**. En duel, le fouet suffit souvent.", "Combo de base : **grappin** juste avant d'entrer (or et dégâts), **dash**, fouet, poursuite fantôme, fouet, puis un dash ou un fouet pour finir.", "Le fouet touche en zone : **chaque ennemi touché rend de l'or** et donne de la vie bonus, il se rentabilise sur un groupe.", "Pour esquiver une ult avec la poursuite, vise **un espace dégagé** : l'animation dure plus longtemps."], "title": "Combat rapproché", "ability": "Feline Fury · Fortune's Favor"}, {"key": "Maj", "lead": "Deux dashes à long cooldown, un double saut et l'escalade des murs. Ta survie dépend de leur gestion.", "items": ["Le dash **traverse les cibles** : vise leurs **pieds** pour t'arrêter sur elles.", "Règle simple : **un dash pour entrer, un pour sortir**. Ne les gâche pas pour te déplacer.", "Chaque capacité **recharge ton double saut** : tu peux enchaîner saut, mur et capacités pour rester en l'air.", "Accroche-toi au-dessus d'un passage étroit et **tombe sur les supports** quand ils passent."], "title": "Mobilité", "ability": "Cat's Cradle"}, {"key": "F", "lead": "Six objets à usage unique contre de l'or. Bien choisis au bon moment, ce sont eux qui gagnent les fights.", "items": ["**Crâne enflammé** (pas cher) : montre les ennemis à travers les murs à toute ton équipe tant qu'il n'est pas détruit. À poser **en hauteur dans un coin**, et à déplacer s'ils le visent.", "**Poisson** : zone qui ralentit, bloque les déplacements et cloue les volants au sol. Le meilleur ouvreur d'engage, aussi utile pour **protéger tes supports**.", "**Invisibilité** : utile surtout **pour entrer** sans gaspiller un dash, et pour forcer les cooldowns adverses.", "**Anneau-portail** : passage à travers un mur ou un plafond pour toi **et ton équipe**. Très fort sur les cartes à goulots.", "**Cristal anti-contrôle** : correct si tu as de l'or en trop, mais la poursuite fantôme fait souvent le même travail.", "**Rune de jeu** : à éviter, sauf juste avant de mourir pour tenter ta chance à la réapparition.", "Contre un support mobile (Cloak & Dagger, Gambit), lance le **poisson** en engageant : il ne peut plus fuir.", "Contre Luna ou Mantis, avoir le **cristal anti-contrôle** déjà acheté te permet de casser leur gel ou leur sommeil."], "title": "Les gadgets", "ability": "Gilded Deal"}, {"key": "Q", "lead": "Tous les ennemis reçoivent une carte : tu peux bondir derrière n'importe lequel et l'exécuter. Chaque kill relance le bond.", "items": ["Trois appuis : **activer**, **bondir** sur la cible, puis **finir le combo**. Beaucoup de joueurs oublient le dernier.", "La carte devient **rouge quand la cible va mourir** au prochain appui.", "Évite de commencer par un héros **très mobile** (Scarlet Witch, White Fox) si son évasion est encore disponible.", "Attends que **ton équipe soit prête** à suivre : l'ult crée surtout de l'espace pour elle.", "Pas besoin d'or au départ : l'ult t'en donne largement."], "title": "Ultime", "ability": "Calling Card"}, {"kind": "mistakes", "items": ["Engager **sans or**.", "**Rater le grappin** et passer le fight à ne rien faire.", "Gâcher ses dashes pour **se déplacer**.", "Lancer l'ult **seule**, sans équipe prête à suivre.", "Miser sur la **rune de jeu**."], "title": "Erreurs fréquentes"}], "synergies": [{"hero": "venom", "note": "Le tank de dive idéal pour diver avec toi."}, {"hero": "captain-america", "note": "Autre tank de dive qui suit tes engages."}, {"hero": "daredevil", "note": "Duo de divers qui écrase la backline."}, {"hero": "psylocke", "note": "Pression combinée sur les supports."}], "difficulty": 3, "patch_note": "Guide tiré d'une vidéo de Paz (padswagger), reformulé en français. Les chiffres du kit ont été retirés car ils changent à chaque saison ; team-ups et derniers changements sont à jour (saison 10.5) dans la section dédiée.", "kit": {"season": "Saison 10.5", "health": "", "abilities": [], "teamups": [{"name": "Binding Ties", "partners": ["spider-man"], "key": "", "text": "Un grappin de toile vole de la Fortune et marque la cible, qui prend plus de dégâts."}, {"name": "Feline Alliance", "partners": ["black-panther"], "key": "", "text": "Explosion de vibranium au-delà d'un seuil ; chaque ennemi touché rend 50 de Fortune (100 max). **Amélioré :** Plus de seuil."}, {"name": "Lucky Loan", "partners": ["white-fox"], "key": "", "text": "Un orbe de vie alimente l'aura à neuf queues. **Amélioré :** Les queues spirituelles ne coûtent plus rien."}], "changes": [{"season": "Saison 10", "text": "Phantom Pursuit : plus d'invincibilité, mais 50 % de réduction des dégâts et Unstoppable ; coût en Fortune 300 → 250."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · changements : patch notes des saisons 10 et 10.5", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'black-cat' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"tags": ["Assassin", "Dive", "Burst", "Patience"], "tldr": ["Entre **plein de vie et sans être vu** : la surprise fait tout le travail.", "**Pas de dash disponible, pas d'engage** : chaque dash doit traverser une cible marquée pour se recharger.", "Cible les **personnages fragiles**, jamais les tanks, et repars dès que tu as ton kill."], "combos": [{"note": "Rapide, mais juste contre un support qui reçoit des soins.", "steps": [{"key": "", "label": "Lance"}, {"key": "", "label": "Lance"}, {"key": "Maj", "label": "dash"}, {"key": "Maj", "label": "dash"}], "title": "De base"}, {"note": "Idéal en prolongation, quand les soins manquent.", "steps": [{"key": "", "label": "Lance"}, {"key": "Maj", "label": "dash"}, {"key": "", "label": "Lance"}, {"key": "Maj", "label": "dash"}, {"key": "Maj", "label": "dash"}], "title": "Plus de dégâts"}, {"note": "", "steps": [{"key": "", "label": "Lance"}, {"key": "Maj", "label": "dash"}, {"key": "", "label": "Coup de pied"}, {"key": "Maj", "label": "dash"}], "title": "Variante courante"}], "sources": [{"url": "https://www.youtube.com/watch?v=0AkMzA-n-EA", "title": "Black Panther Guide", "author": "Paz (padswagger)"}], "summary": "Black Panther est un assassin qui vit de la surprise : il prépare son engage en silence, dive sur une cible fragile et enchaîne ses dashes en les rechargeant grâce à ses marques. S'il est repéré avant d'entrer, il perd son intérêt.", "counters": [{"hero": "magneto", "note": "Sa bulle annule le kill et la recharge de ton dash."}, {"hero": "the-thing", "note": "Force son impact au sol avant de lancer ton gros combo."}, {"hero": "peni-parker", "note": "Ses nids et ses toiles bloquent tes dives."}, {"hero": "invisible-woman", "note": "Ses poussées et attractions te sortent de ton combo."}, {"hero": "ultron", "note": "Il vole et ses drones protègent ses cibles."}, {"hero": "namor", "note": "Ses tourelles te repèrent et t'usent avant que tu entres."}], "sections": [{"kind": "tips", "lead": "Contrairement à d'autres divers, Panther doit s'engager à fond ou ne rien faire. Tout se joue avant d'entrer.", "items": ["Ne prends **aucun dégât** et ne te fais **pas repérer** avant ton engage.", "Sors par un flank, attends qu'un **support s'isole**, frappe, puis **repars** : inutile de rester une fois le kill obtenu.", "Tu n'es **pas obligé de finir un combo** : si tu vas mourir, sauve ta vie.", "Si l'ennemi lâche un gros cooldown défensif (bulle, runes de Loki), **pars** : tu as déjà gagné l'échange."], "title": "Philosophie de jeu", "diagram": "reset"}, {"key": "Maj", "lead": "Ton dash est ta principale source de dégâts. Traverser une cible marquée le recharge immédiatement et te donne de la vie bonus.", "items": ["**N'ouvre jamais** un engage au dash : marque d'abord, puis dash pour qu'il se recharge.", "Rythme de base : **capacité qui marque, dash, capacité, dash**… jusqu'à te mettre à l'abri.", "Une marque reste quelques secondes : si on te regarde, **attends derrière un mur**, la menace suffit à mettre la pression.", "Tu **vois les cibles marquées à travers les murs** : pratique pour repérer celle qui s'isole.", "Ton passif te fait **taper plus fort à bas PV**, mais n'entre jamais déjà blessé."], "title": "Dash et marques", "ability": "Spear Rend"}, {"lead": "Les lances marquent de loin, le coup de pied marque en te déplaçant. Ce sont tes outils pour préparer chaque dash.", "items": ["Les **lances** sont ta seule attaque à distance : lance-les **avec l'intention d'engager**, pas pour arroser.", "Astuce : lance en **tombant d'un mur**, puis dash dès que tu es à portée.", "Le **coup de pied** est orientable mais pas instantané. Une fois utilisé, tu es vulnérable : sois sûr de trouver le kill.", "Pour fuir, utilise de préférence le coup de pied : **le dash vaut plus cher** car il fait tes dégâts.", "Toute **projection** pendant le coup de pied l'annule : attention aux Invisible Woman et Magneto."], "title": "Lances et coup de pied", "ability": "Spear Toss · Spinning Kick"}, {"lead": "Tes pas sont bruyants. L'escalade des murs et le double saut te permettent d'approcher en silence.", "items": ["Déplace-toi **par les murs** pour arriver par surprise.", "Garde tes capacités pour le combat : elles font tes dégâts, pas tes trajets."], "title": "Déplacements discrets", "ability": "Subtle Step"}, {"kind": "tips", "lead": "Avec l'habitude, ces enchaînements deviennent automatiques. Ajoute un coup de griffe dès que possible pour sécuriser le kill.", "items": ["**De base** : lance, lance, dash, dash. Rapide, mais juste contre un support qui reçoit des soins.", "**Plus de dégâts** : lance, dash, lance, dash, dash. Plus long, idéal en prolongation quand les soins manquent.", "**Variante courante** : lance, dash, coup de pied, dash.", "**Tout lâcher** : lance, dash, coup de pied, dash, lance, double dash. Seulement quand il ne reste qu'un tank à abattre.", "Pour le coup final, **investis tes deux dashes**."], "title": "Combos"}, {"key": "Q", "lead": "Une panthère géante frappe et marque tous les ennemis touchés, et recharge ton dash.", "items": ["Ne l'utilise pas pour **ouvrir** : garde-la pour **finir** une cible ou ajouter du burst.", "Tu es **vulnérable pendant l'animation** : entre avec assez de vie.", "Quand les supports adverses n'ont pas d'ult, n'hésite pas à la lancer tôt : elle est **longue à recharger**.", "Avec l'ult prête, tu peux **insister** sur une cible même après avoir forcé un cooldown défensif."], "title": "Ultime", "ability": "Bast's Descent"}, {"kind": "mistakes", "items": ["Engager **sans dash** disponible.", "Se faire **repérer** ou blesser avant d'entrer.", "Diver sur **un tank**.", "**Rester** après avoir obtenu son kill.", "Utiliser le coup de pied **sans être sûr** du kill."], "title": "Erreurs fréquentes"}], "synergies": [{"hero": "venom", "note": "Il affaiblit les supports avant que tu dives."}, {"hero": "captain-america", "note": "Même logique de dive sur la backline."}, {"hero": "star-lord", "note": "Un DPS qui tire sur ta cible fait passer tous tes combos."}, {"hero": "luna-snow", "note": "Ses soins à distance t'aident à survivre en sortant."}], "difficulty": 3, "patch_note": "Guide tiré d'une vidéo de Paz (padswagger), reformulé en français. Les chiffres du kit ont été retirés car ils changent à chaque saison ; team-ups et derniers changements sont à jour (saison 10.5) dans la section dédiée.", "kit": {"season": "Saison 10.5", "health": "", "abilities": [], "teamups": [{"name": "Damisa-Yao", "partners": ["storm"], "key": "", "text": "Explosion élémentaire de l'armure qui ralentit et marque. **Amélioré :** Projette les ennemis vers Black Panther."}, {"name": "Dimensional Shortcut", "partners": ["magik"], "key": "", "text": "Un disque de Limbo ramène Black Panther à sa position précédente. **Amélioré :** Retour déclenchable à la main."}, {"name": "Feline Alliance", "partners": ["black-cat"], "key": "", "text": "Explosion de vibranium au-delà d'un seuil ; chaque ennemi touché rend 50 de Fortune (100 max). **Amélioré :** Plus de seuil."}, {"name": "Vibranium Mech", "partners": ["peni-parker"], "key": "", "text": "Bouclier de vibranium frontal et vitesse d'attaque (cooldown 15 s depuis la saison 10). **Amélioré :** Bouclier plus grand."}], "changes": [], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · changements : patch notes des saisons 10 et 10.5", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'black-panther' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"tags": ["Sniper", "Contrôle de zone", "Mobilité", "Pick"], "tldr": ["Choisis des **angles sûrs et durables** : un tir pris sans pression est bien plus facile à réussir.", "**Dé-scope régulièrement** pour surveiller les divers autour de toi.", "Ton coup de pied **étourdit** : garde-le pour couper une ult ou te défendre."], "combos": [{"note": "Sur une cible fragile, **pas besoin de headshot**.", "steps": [{"key": "Clic G", "label": "tir au corps"}, {"key": "E", "label": "coup de pied"}, {"key": "Clic G", "label": "tir au corps"}], "title": "Mise à mort sûre"}], "sources": [{"url": "https://www.youtube.com/watch?v=LMej9-pVFek", "title": "Black Widow Guide", "author": "Paz (padswagger)"}], "summary": "Black Widow est une sniper très mobile qui contrôle des zones entières de la carte. Avec un bonus de dégâts (Mantis, Storm, Cloak & Dagger), un headshot suffit à éliminer la plupart des personnages fragiles, ults de support comprises.", "counters": [{"hero": "psylocke", "note": "Elle te dive sans entrer dans la portée de ton coup de pied."}, {"hero": "captain-america", "note": "Il te rejoint facilement et tu peines à le tuer."}, {"hero": "venom", "note": "Même problème, surtout avec un autre diver."}, {"hero": "magneto", "note": "Son bouclier bloque tes tirs sur le point."}, {"hero": "luna-snow", "note": "Son ult est protégée par un bouclier : très dure à couper."}], "sections": [{"kind": "tips", "lead": "Widow ne cherche pas toujours le kill : elle interdit des zones à l'ennemi, ce qui ouvre le jeu pour ton autre DPS.", "items": ["Ton angle dépend de ta compo : **en brawl**, tire sur ce que ton équipe peut finir. **En dive**, va plus loin pour affaiblir les supports.", "Tu n'as **pas besoin de tout toucher** : ta seule présence empêche l'ennemi de se placer où il veut.", "Elle est bien plus forte avec un **bonus de dégâts** : un headshot devient alors mortel sur la plupart des cibles.", "Ce qui la distingue des autres tireurs : **portée + mobilité** pour changer d'angle en un instant."], "title": "Philosophie de jeu", "diagram": "highground"}, {"key": "Clic G · Clic D", "lead": "Oublie les matraques : le fusil fait plus de dégâts. Le vrai savoir-faire, c'est de savoir quand viser et quand tirer à la hanche.", "items": ["Les **matraques** sont moins efficaces que le fusil : ne les sors pas.", "**De près, tire à la hanche.** De loin, **vise** : la lunette supprime la perte de dégâts à distance.", "Ne reste pas **lunette collée** plusieurs tirs d'affilée : tu vois mal autour de toi et tu bouges lentement, une proie facile pour les divers.", "Visée : **un mouvement rapide vers la cible, puis un petit ajustement** vers la tête, plutôt qu'un seul flick.", "**Respire et détends le poignet** : tu n'as pas besoin de tout toucher pour être utile.", "Anticipe les trajectoires évidentes (un ennemi qui retombe d'un saut, qui revient du spawn en ligne droite) et attends-le."], "title": "Le fusil", "ability": "Red Room Rifle · Straight Shooter"}, {"key": "Maj", "lead": "Tu cours plus vite et sautes plus haut pendant quelques secondes. C'est ton outil pour changer d'angle.", "items": ["Utilise-la pour **passer d'un angle à l'autre** entre deux fights, ou quand ton angle ne marche plus.", "Les tirs en plein saut sont spectaculaires mais **rarement rentables** : ils vident ton énergie et te rendent vulnérable.", "Un saut au bon moment **esquive les attaques au sol** (impacts de Venom ou Captain America) et te laisse riposter."], "title": "Course", "ability": "Fleet Foot"}, {"key": "E", "lead": "Un premier coup de pied tout autour de toi, puis un second à distance qui étourdit. C'est ton seul vrai cooldown : rentabilise-le.", "items": ["Le second coup de pied reste disponible **quelques secondes** après le premier : charge-le sur un tank, puis garde-le en réserve.", "Il peut **interrompre des ults** (Doctor Strange, Scarlet Witch, ults de support) et **sortir Loki de sa copie** au moment où il redevient fragile.", "Combo sûr sur une cible fragile : **tir au corps, coup de pied, tir au corps**. Pas besoin de headshot.", "Garde-le pour **défendre tes supports** contre un diver : c'est l'un des meilleurs anti-Black Panther du jeu.", "Il te sauve aussi la vie : **étourdir le tank** qui fonce sur toi te laisse le temps de reculer."], "title": "Coup de pied", "ability": "Edge Dancer"}, {"key": "Q", "lead": "Un lance-grenade qui ralentit les ennemis et les rend plus vulnérables. Il se recharge très vite : lance-le à chaque fight.", "items": ["Plus tu **maintiens le tir**, plus l'explosion fait mal.", "Cibles idéales : un **support en ult** assez bas pour mourir, un **diver** sur tes supports, un **groupe** d'ennemis.", "Utilise-la pour **forcer les ults de support**, puis profite de la vulnérabilité pour les éliminer.", "La pire erreur : **la garder**. Elle revient très vite, lance-la."], "title": "Ultime", "ability": "Electro-Plasma Explosion"}, {"kind": "mistakes", "items": ["Rester **lunette collée** et se faire dive.", "Viser à longue distance **sans lunette**.", "Gaspiller le coup de pied quand un **diver** menace tes supports.", "Faire des **tirs sautés** sans raison.", "**Garder son ult** pour le moment parfait."], "title": "Erreurs fréquentes"}], "synergies": [{"hero": "mantis", "note": "Son bonus de dégâts rend tes headshots mortels."}, {"hero": "storm", "note": "Même effet, mais tu dois rester dans sa zone."}, {"hero": "cloak-and-dagger", "note": "Son flash donne aussi un bonus de dégâts."}, {"hero": "psylocke", "note": "Avec un Captain America, la pression combinée fait tomber les supports."}], "difficulty": 2, "patch_note": "Guide tiré d'une vidéo de Paz (padswagger), reformulé en français. Les chiffres du kit ont été retirés car ils changent à chaque saison ; team-ups et derniers changements sont à jour (saison 10.5) dans la section dédiée.", "kit": {"season": "Saison 10.5", "health": "", "abilities": [], "teamups": [{"name": "Allied Agents", "partners": ["hawkeye"], "key": "", "text": "Les cumuls de concentration donnent des balles renforcées ; les critiques gardent la concentration active."}, {"name": "Burning Bullets", "partners": ["phoenix"], "key": "", "text": "Le Plasma Cannon devient un tir instantané (hitscan). **Amélioré :** Une charge en plus."}, {"name": "Devilish Affair", "partners": ["daredevil"], "key": "", "text": "Devil's Chain frappe en croix et ralentit. **Amélioré :** Plus large, et rend de la Fureur."}], "changes": [{"season": "Saison 10", "text": "Red Room Rifle : 65 % des dégâts à 40 m au lieu de 75 % ; ult plus chère (2800 → 3100)."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · changements : patch notes des saisons 10 et 10.5", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'black-widow' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"tags": ["Mi-distance", "Anti-soin", "Parade", "Brawl"], "tldr": ["Ton fusil est un **blaster de mi-distance**, pas une arme de corps à corps.", "Garde ta **parade** pour les grosses menaces : ults, étourdissements, dives.", "Accumule tes **charges de rage** avant de t'engager : c'est là que Blade devient dangereux."], "combos": [{"note": "Le dash au fusil applique l'**anti-soin** entre deux tirs.", "steps": [{"key": "", "label": "Tir"}, {"key": "Maj", "label": "dash"}, {"key": "", "label": "Tir"}], "title": "Combo de base"}], "sources": [{"url": "https://www.youtube.com/watch?v=WPEDkYY4eGA", "title": "Blade Guide", "author": "Paz (padswagger)"}, {"title": "The Ultimate Blade Guide", "author": "Kingsman", "url": "https://www.youtube.com/watch?v=Cy5ZReSGxDA"}], "summary": "Blade est un duelliste de mi-distance méthodique : il accumule des charges de rage, coupe les soins adverses et pare les grosses menaces pour retourner les fights. Il se joue lentement et avec patience, pas en fonçant tête baissée.", "counters": [{"hero": "the-thing", "note": "Il te verrouille et encaisse sans broncher."}, {"hero": "human-torch", "note": "Ses dégâts de zone et son vol te compliquent la vie."}, {"hero": "hela", "note": "Elle te gagne à distance avant que tu sois à portée."}, {"hero": "phoenix", "note": "Ses étourdissements cassent ton rythme si tu rates ta parade."}, {"hero": "adam-warlock", "note": "Ses soins à rebond et son lien limitent ton anti-soin."}, {"hero": "ultron", "note": "Il vole hors de portée et soigne ses alliés à distance."}], "sections": [{"kind": "tips", "lead": "Blade n'est pas un assassin qui dive : il grignote, coupe les soins et attend le bon moment pour basculer en rage.", "items": ["Joue **lentement et méthodiquement** : construis tes charges, puis appuie quand l'ennemi est affaibli.", "Reste au **contact de ton équipe** et protège tes supports contre les divers (Captain America, Iron Fist…).", "Ton anti-soin est précieux : vise les cibles qui comptent sur leurs **soins pour survivre**.", "Joue **au front avec ton fusil** pour charger ta jauge, puis entre dans la backline **forme de rage pleine** sur un support.", "Contrairement à Magik ou Wolverine, tu n'as **ni bouclier ni réduction de dégâts** en brawl : ne reste pas à taper les tanks.", "Bon choix **quand Magik est bannie**, en dive ou face à une compo double bouclier."], "title": "Philosophie de jeu", "diagram": "brawl"}, {"lead": "Le fusil à pompe se joue comme un blaster de mi-distance. L'épée est faible tant que tu n'es pas en rage.", "items": ["Ne colle pas ta cible : le fusil est efficace **à mi-distance**, où tu restes à l'abri.", "L'épée hors rage fait **peu de dégâts** : ne l'utilise pas par défaut.", "Combo de base : **tir, dash, tir**. Le dash au fusil applique l'anti-soin entre deux tirs.", "Le fusil fait ses **meilleurs dégâts à moyenne portée** (autour de 10 m), quand les plombs sont dispersés, pas au contact.", "Tu peux **annuler la fin du rechargement** du fusil en passant à l'épée.", "**Ne te bats jamais à l'épée sans ta forme de rage** : c'est juste te faire tuer."], "title": "Fusil et épée"}, {"key": "Clic D", "lead": "La parade bloque les dégâts de face et te rend insensible aux contrôles au tout début. Les dégâts bloqués rechargent ton dash.", "items": ["Le tout début de la parade **ignore les contrôles** : un réflexe rapide suffit.", "Pare les **moments clés** : ults d'Iron Man ou Magneto, étourdissements de Phoenix ou Hela, dive de Human Torch, ult de Jeff.", "Ne la gâche pas sur des **petits dégâts** : elle vaut beaucoup plus contre une vraie menace.", "Bloquer des dégâts **recharge ton dash** : une bonne parade relance ton combo.", "Pendant une courte fenêtre, la parade **bloque tous les contrôles**, même l'étranglement d'Emma Frost ou une ult lancée sur toi ; ensuite, tu encaisses beaucoup moins de dégâts.", "En forme de rage, tu **recules plus vite** en parant."], "title": "Parade"}, {"key": "Maj", "lead": "Deux charges. Au fusil, il applique l'anti-soin ; à l'épée, il ralentit et fait un tourbillon.", "items": ["Au fusil : un **outil d'anti-soin** à placer entre deux tirs, pas seulement un déplacement.", "À l'épée (en rage) : il **ralentit** et frappe tout autour de toi, idéal pour finir.", "Garde une charge pour **sortir** d'un mauvais fight.", "Garde la règle : **un dash pour entrer, un pour sortir**.", "Au fusil, le dash pose l'**anti-soin** sur la cible et sa zone est large : il suffit de tirer près d'elle.", "À l'épée, il ralentit, repousse et **coupe les dashes adverses** (Black Panther) ; il remplit aussi ta jauge de rage.", "En forme de rage, **maintenir l'épée** fait plus de dégâts que spammer les dashes."], "title": "Dash", "ability": "Daywalker Dash"}, {"key": "E", "lead": "En rage, tu voles de la vie et tu frappes plus vite à chaque charge accumulée. Les ennemis à bas PV deviennent visibles à travers les murs.", "items": ["Accumule des charges **avant** de basculer : la rage est plus forte quand elle est déjà bien remplie.", "Passe d'une arme à l'autre avec **la touche dédiée** plutôt qu'à la molette : c'est plus fiable en combat.", "Profite de la **vision à travers les murs** pour traquer les cibles qui fuient à bas PV.", "Le **vol de vie** te permet de tenir dans un brawl où d'autres duellistes fondraient."], "title": "Forme de rage", "ability": "Bloodline Awakening"}, {"key": "Q", "lead": "Un coup d'épée à distance qui laisse une zone d'anti-soin. Elle se recharge vite : utilise-la souvent.", "items": ["**Maintiens** la touche pour aller à la portée maximale.", "Lance-la **après que les boucliers et bulles** adverses sont tombés, sinon elle est absorbée.", "Utilise-la **en rage** pour profiter du vol de vie.", "Bon usage : **forcer les ults de soin** adverses, que ton équipe pourra contrer ensuite.", "Tu peux la lancer **instantanément** (courte distance) ou la **maintenir** pour aller plus loin : même dégâts, mais plus facile de toucher.", "On peut te **sortir de l'ult** avec un contrôle : lance-la quand l'ennemi n'en a plus, ou depuis le côté.", "Idéale **après une ult de Groot** ; seule, vise plutôt **un tank**, les supports s'échappent facilement.", "Tu ressors dans la forme où tu étais : **active ta forme de rage avant** pour enchaîner à l'épée."], "title": "Ultime", "ability": "Thousandfold Slash"}, {"kind": "mistakes", "items": ["Jouer le fusil **au corps à corps**.", "Sortir l'épée **hors de la rage**.", "Parer des **dégâts insignifiants**.", "Lancer l'ult **dans un bouclier**.", "Foncer **sans charges** de rage."], "title": "Erreurs fréquentes"}], "synergies": [{"hero": "magneto", "note": "Un tank de ligne qui te laisse jouer à mi-distance derrière lui."}, {"hero": "emma-frost", "note": "Même logique : elle tient le front pendant que tu grignotes."}, {"hero": "groot", "note": "Ses murs regroupent les ennemis pour ton ult."}, {"hero": "mantis", "note": "Son bonus de dégâts accélère tes kills."}, {"hero": "cloak-and-dagger", "note": "Soins constants qui te permettent de rester dans le brawl."}], "difficulty": 2, "patch_note": "Guide tiré d'une vidéo de Paz (padswagger), reformulé en français. Les chiffres du kit ont été retirés car ils changent à chaque saison ; team-ups et derniers changements sont à jour (saison 10.5) dans la section dédiée.", "kit": {"season": "Saison 10.5", "health": "", "abilities": [], "teamups": [{"name": "Blade of Khonshu", "partners": ["moon-knight"], "key": "", "text": "Chaque Whirlwind Slash lance une lame lunaire en plus."}, {"name": "Bleed for Battle", "partners": ["captain-america"], "key": "", "text": "Donne des cumuls de Bloodline Awakening à Blade. **Amélioré :** Se déclenche aussi sur les dégâts critiques."}, {"name": "Blood Leech", "partners": ["venom"], "key": "", "text": "Cellular Corrosion vole de la vie. **Amélioré :** Ajoute un soin ponctuel."}, {"name": "Vampiric Kin", "partners": ["jubilee"], "key": "", "text": "Champ vampirique qui soigne et donne du vol de vie (soin de 15/s autour pendant 6 s en 10.5). **Amélioré :** Soin supplémentaire."}], "changes": [{"season": "Saison 10", "text": "Team-up avec Captain America : 4 cumuls max en plus au lieu de 2."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · changements : patch notes des saisons 10 et 10.5", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'blade' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"tags": ["Dive", "Pression", "Peel", "Mobilité"], "tldr": ["Ton job : **forcer les cooldowns** adverses par la pression, puis engager pour de vrai.", "Garde ton **bouclier et ta charge** pour esquiver les contrôles, pas pour bloquer chaque balle.", "Ton ult est une **mini-ult de support** : engager, contrer une menace moyenne ou tenir le point."], "combos": [{"note": "Attends le **son d'impact** du bouclier avant d'enchaîner, sinon tu annules ton attaque.", "steps": [{"key": "Maj", "label": "sprint"}, {"key": "Espace", "label": "saut"}, {"key": "E", "label": "lancer bouclier"}, {"key": "", "label": "Slam"}, {"key": "F", "label": "charge"}, {"key": "Clic G", "label": "coups"}], "title": "Combo complet"}], "sources": [{"url": "https://www.youtube.com/watch?v=HZrBVN4tuik", "title": "Captain America Guide", "author": "Paz (padswagger)"}], "summary": "Captain America est un tank de pression et de déplacement : il encercle l'équipe adverse pour préparer un dive, ou intercepte un flanker avant qu'il n'atteigne tes supports. Il ne se joue jamais en restant devant à frapper les tanks.", "counters": [{"hero": "ultron", "note": "Il fait des dégâts bonus contre ton ult et vole hors de portée."}, {"hero": "winter-soldier", "note": "Il te rattrape et tu peines à fuir sans mobilité."}, {"hero": "the-punisher", "note": "S'il vise bien, ton bouclier disparaît en un instant."}, {"hero": "iron-man", "note": "Tu ne peux presque jamais l'atteindre."}, {"hero": "loki", "note": "Ses runes annulent ton engage d'un bouton."}, {"hero": "adam-warlock", "note": "Même chose avec son lien : force-le d'abord."}], "sections": [{"kind": "tips", "lead": "Cap porte plusieurs casquettes selon ce dont ton équipe a besoin : préparer le dive ou éteindre les incendies chez toi.", "items": ["Avec une **Psylocke ou un Daredevil**, aide-les à diver sur les supports adverses.", "Si tes supports souffrent, **intercepte le diver** (Black Panther…) avant qu'il n'arrive.", "Prends un angle pour **dessiner un cercle** autour de l'ennemi, engage quand tu es prêt, force les ressources, puis fight.", "En fight à trois supports, ton rôle est d'**éteindre les incendies** : traite les menaces, force les ults adverses, et trouve des picks sur les DPS.", "Le but n'est pas de **tuer tout de suite** : c'est de forcer les cooldowns défensifs pour l'engage suivant."], "title": "Philosophie de jeu", "diagram": "dive"}, {"key": "Clic G", "lead": "Deux coups de poing débloquent des petits lancers de bouclier qui visent automatiquement autour de ton viseur.", "items": ["Après **deux coups de poing**, tu passes aux lancers de bouclier à distance.", "Le guidage est plus généreux si tu **vises à droite** de ta cible.", "Les charges se gagnent aussi sur les **murs de Groot** ou les **clones de Loki**, mais pas sur les boucliers inanimés.", "Ne spamme pas sprint et lancer : **attends le son d'impact** du bouclier, sinon tu annules ton attaque."], "title": "Coups et boucliers lancés", "ability": "Sentinel Strike"}, {"key": "Maj", "lead": "Le sprint n'a ni cooldown ni jauge. En sautant pendant le sprint, tu peux t'écraser au sol et projeter les ennemis en l'air.", "items": ["Sprinte **entre deux lancers** pour ne jamais lâcher une cible qui fuit.", "Le sprint est **bruyant** : pour un flank discret, marche.", "Le saut écrasé **projette en l'air** : idéal pour lancer un combo ou rejoindre un diver allié.", "Il a un long cooldown : si tu l'utilises pour entrer, **tu ne pourras pas t'en servir pour sortir**."], "title": "Sprint et saut écrasé", "ability": "Leading Dash · Super-Soldier Slam"}, {"key": "Clic D", "lead": "Le bouclier renvoie les projectiles dans une direction aléatoire. Il se régénère quand il est rangé, mais met du temps à revenir s'il casse.", "items": ["Il sert surtout à **esquiver les contrôles** : boule de neige de Luna, étourdissement de Hela.", "Il peut **protéger tes supports** : dagues de Hela, ults d'Iron Man ou de Magneto.", "Les coups de mêlée et les rayons **ne sont pas renvoyés**.", "Ne le lève pas juste parce que tu peux : la plupart des dégâts se soignent ou s'évitent avec un **meilleur placement**."], "title": "Bouclier", "ability": "Living Legend"}, {"key": "F · E", "lead": "La charge te rend insensible aux contrôles. Le gros lancer de bouclier ricoche entre les cibles.", "items": ["Pendant la charge, tu es **insensible aux contrôles** : elle esquive boules de neige, ult de Doctor Strange, même l'ult de Jeff.", "Elle **s'arrête au contact** d'une cible : c'est soit pour finir, soit pour fuir, rarement les deux.", "Vise les **pieds** avec le gros lancer : même raté, il ricoche vers la cible.", "Combo complet : **sprint, saut, lancer de bouclier, slam, charge, coups**.", "En engage léger, **garde la charge pour sortir** et esquiver les contrôles."], "title": "Charge et lancer de bouclier", "ability": "Liberty Rush · Vibranium Energy Saw"}, {"key": "Q", "lead": "Tu laisses un sillage qui donne vie bonus et vitesse à toi et tes alliés. Ça vaut presque une ult de support, en un bouton.", "items": ["**Engager** : ton équipe fonce sur la backline sans gaspiller une ult de support.", "**Contrer une menace moyenne** : une ult de Star-Lord, un diver arrivé sur tes supports, un Punisher en ult.", "**Tenir le point** : bouclier levé pendant l'ult, tu bouscules les ennemis et deviens très dur à toucher.", "Lance-la **près de ton équipe** pour que tous profitent de la vie bonus.", "Laisse parfois tes supports utiliser leurs ults et **garde la tienne pour un moment décisif**. Préviens-les de ton plan.", "Astuce : active les **barres de vie alliées** pour sauver tes coéquipiers plus souvent."], "title": "Ultime", "ability": "Freedom Charge"}, {"kind": "mistakes", "items": ["Rester **devant à frapper les tanks** toute la partie.", "Spammer sprint et lancers et **annuler ses attaques**.", "Lever le bouclier **pour rien** au lieu de le garder contre un contrôle.", "Diver **sans moyen de sortir**.", "Chercher le kill tout de suite au lieu de **forcer les cooldowns**."], "title": "Erreurs fréquentes"}], "synergies": [{"hero": "venom", "note": "Deux angles qui convergent sur la même cible : quasi impossible à gérer."}, {"hero": "psylocke", "note": "La pression combinée écrase la backline."}, {"hero": "black-panther", "note": "Même plan de jeu : encercler et diver."}, {"hero": "human-torch", "note": "Tes coups forcent l'ennemi à reculer dans ses zones de feu."}, {"hero": "luna-snow", "note": "Un support qui marche dans toutes les compos de dive."}, {"hero": "mantis", "note": "Son bonus de dégâts rend tes engages mortels."}], "difficulty": 2, "patch_note": "Guide tiré d'une vidéo de Paz (padswagger), reformulé en français. Les chiffres du kit ont été retirés car ils changent à chaque saison ; team-ups et derniers changements sont à jour (saison 10.5) dans la section dédiée.", "kit": {"season": "Saison 10.5", "health": "", "abilities": [], "teamups": [{"name": "Bleed for Battle", "partners": ["blade"], "key": "", "text": "Donne des cumuls de Bloodline Awakening à Blade. **Amélioré :** Se déclenche aussi sur les dégâts critiques."}, {"name": "Savage Slam", "partners": ["hulk"], "key": "", "text": "Un saut écrasé réduit les cooldowns. **Amélioré :** Ajoute la vulnérabilité."}, {"name": "Stars Aligned", "partners": ["winter-soldier"], "key": "", "text": "Saut vers l'allié qui partage de la vie bonus. **Amélioré :** Ralliement mutuel."}, {"name": "Voltaic Union", "partners": ["thor"], "key": "", "text": "Projectile-bouclier de foudre (10 s depuis la saison 10). **Amélioré :** Explosion de zone à chaque touche."}], "changes": [{"season": "Saison 10", "text": "Vie de base 300 → 350."}, {"season": "Saison 10", "text": "Le lancer de bouclier ne perd plus de dégâts en rebondissant."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · changements : patch notes des saisons 10 et 10.5", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'captain-america' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"tags": ["Soins de zone", "Utilitaire", "Anti-ult", "Accessible"], "tldr": ["Ta priorité : **charger ton ult plus vite** que les supports d'en face.", "Change de forme pour **recharger Dagger** et glisser des dégâts avec Cloak.", "Garde l'**intangibilité de Cloak** pour contrer une vraie ult adverse."], "sources": [{"url": "https://www.youtube.com/watch?v=E9lKTfRFJ6s", "title": "Cloak and Dagger Guide", "author": "Paz (padswagger)"}], "summary": "Cloak & Dagger est un duo facile à prendre en main mais qui récompense énormément la maîtrise : on gagne en chargeant son ult plus vite que les supports adverses, en alternant soins de Dagger, dégâts de Cloak et cooldowns bien placés.", "counters": [{"hero": "magneto", "note": "Son ult peut te tuer pendant la tienne."}, {"hero": "hawkeye", "note": "Un headshot suffit à couper ton ult."}, {"hero": "iron-man", "note": "Même risque, trace ton ult à couvert."}, {"hero": "luna-snow", "note": "Plus agressive à distance avec une ult plus forte."}], "sections": [{"kind": "tips", "lead": "Soigner ne suffit pas : ceux qui portent la partie sur C&D sont efficaces avec chaque cooldown et glissent des dégâts dès que possible.", "items": ["Plus tu montes en rang, plus **l'avance en ult** fait la différence.", "Éliminer une cible tôt dans le fight, c'est **autant de dégâts que ton équipe ne prendra pas**.", "Ne meurs pas pour un mauvais placement : **joue près des packs de soin, à couvert**, et charge ton ult.", "Avec deux ults de support prêtes, tu peux **ouvrir un fight agressivement** pour prendre l'avantage."], "title": "Philosophie de jeu", "diagram": "heal"}, {"key": "Clic G", "lead": "Des projectiles à tête chercheuse qui soignent la cible, puis éclatent pour soigner tous les alliés autour.", "items": ["Le projectile cherche la cible **la plus proche de ton viseur**, seulement si elle a perdu de la vie.", "À l'impact, il **éclate et soigne en zone** : vise les groupes d'alliés pour maximiser tes soins et ta charge d'ult.", "Le projectile est lent : envoie tes soins **juste avant** qu'un diver allié entre en duel, pas après les dégâts.", "Tirer sur l'ennemi fait des dégâts et soigne autour, mais **moitié moins** de soin au total."], "title": "Soins de Dagger"}, {"key": "Maj", "lead": "Passer d'une forme à l'autre est quasi instantané et recharge les projectiles de Dagger plus vite qu'un rechargement normal.", "items": ["**Double changement de forme** = rechargement plus rapide de Dagger.", "Anticipe le passage en Cloak quand tu sens venir une ult adverse : la courte animation peut te coûter cher.", "Le rayon de Cloak traque sa cible : utilise-le pour **finir une cible qui fuit** ou charger ton ult quand tout le monde est soigné."], "title": "Changer de forme"}, {"key": "E", "lead": "Dagger lance un voile qui soigne et booste les soins reçus. Cloak lance un voile qui aveugle et rend les ennemis plus vulnérables.", "items": ["Le voile de **Dagger** sert quand ton équipe **pousse groupée** ou doit reculer sous la pression.", "Il disparaît s'il touche **un mur ou un bouclier** ennemi : attention aux angles.", "Ne le gâche pas pour un seul allié mal placé, sauf s'il a **une ult décisive** prête.", "Le voile de **Cloak** aveugle : une ult de Star-Lord ou de Scarlet Witch aveuglée **ne verrouille plus** ses cibles.", "Il augmente fortement les **dégâts subis** : c'est l'une des capacités les plus fortes de ton kit. Lance-le à chaque rechargement."], "title": "Les voiles", "ability": "Veil of Lightforce · Terror Cape"}, {"lead": "Une salve de dagues crée une zone de soin continu à l'impact.", "items": ["Vise **les pieds** de ton équipe : leurs corps ne bloquent pas la capacité.", "Pose-la, puis **passe en Cloak** pour faire des dégâts pendant qu'elle soigne.", "C&D n'a presque pas d'auto-soin : garde-la pour **survivre aux divers** si tu sais qu'ils vont venir."], "title": "Dôme de soin", "ability": "Dagger Storm"}, {"key": "Clic D", "lead": "Tous les alliés autour de Cloak deviennent invulnérables et plus rapides quelques instants, tant qu'ils n'agissent pas.", "items": ["Elle **annule les ults** de Psylocke, Magneto ou Jeff : les ennemis malins chercheront à la forcer avant.", "Si ton équipe écoute, **annonce le décompte** pour qu'elle n'en sorte pas par erreur en tirant.", "Tu voles pendant l'effet : profites-en pour **te replacer en hauteur** après un dive."], "title": "Intangibilité", "ability": "Dark Teleportation"}, {"key": "Q", "lead": "Quatre dashes rapides qui laissent des traînées de soin pour les alliés et de dégâts pour les ennemis.", "items": ["Après l'ult, **ne soigne plus** : passe en Cloak et fais des dégâts pour finir le fight.", "Tu restes **immobile un instant** après chaque dash : attention à Hawkeye, Punisher, Magneto ou Iron Man en ult.", "Trace l'ult **autour du point** pour que ton équipe puisse se battre là où ça compte.", "Si l'ennemi n'a qu'une ult à contrer et que ton autre support peut s'en charger, utilise la tienne **pour pousser**.", "Tu ne peux pas monter en l'air pendant l'ult : **attention aux chutes**."], "title": "Ultime", "ability": "Eternal Bond"}, {"kind": "mistakes", "items": ["Ne **jamais passer en Cloak**.", "Oublier le **voile de Cloak**, l'un de tes meilleurs outils.", "Gaspiller l'intangibilité avant **l'ult qu'elle devait contrer**.", "Continuer à soigner **pendant sa propre ult**.", "Tracer l'ult **à découvert** face à un Hawkeye ou un Magneto."], "title": "Erreurs fréquentes"}], "synergies": [{"hero": "the-thing", "note": "En brawl groupé, tes soins de zone font des merveilles."}, {"hero": "emma-frost", "note": "Même logique de compo serrée autour du point."}, {"hero": "black-widow", "note": "Ton voile de Cloak donne un bonus de dégâts à ses tirs."}, {"hero": "iron-fist", "note": "Tes soins à tête chercheuse suivent facilement les divers."}], "difficulty": 1, "patch_note": "Guide tiré d'une vidéo de Paz (padswagger), reformulé en français. Les chiffres du kit ont été retirés car ils changent à chaque saison ; team-ups et derniers changements sont à jour (saison 10.5) dans la section dédiée.", "kit": {"season": "Saison 10.5", "health": "", "abilities": [], "teamups": [{"name": "Frozen Haven", "partners": ["luna-snow"], "key": "", "text": "L'état gelé émet une aura de soin (bouclier de 2 s depuis la saison 10). **Amélioré :** Aura renforcée."}, {"name": "Light & Dark Darts", "partners": ["psylocke"], "key": "", "text": "Fléchettes de lumière et domaine d'ombre. **Amélioré :** Domaine plus grand, fléchettes relancées."}, {"name": "Luminous Moon", "partners": ["moon-knight"], "key": "", "text": "Dash intangible avec une vague de soin. **Amélioré :** Plus long, avec un soin continu."}, {"name": "Moonlit Slash", "partners": ["hawkeye"], "key": "", "text": "Entaille lumineuse qui soigne les alliés, et Hawkeye se soigne d'autant (10.5). **Amélioré :** Combo en trois coups."}, {"name": "Oblivion Shroud", "partners": ["the-hood"], "key": "", "text": "Les voiles affaiblissent dégâts et soins ennemis. **Amélioré :** Plus larges, avec un boost de dégâts."}], "changes": [{"season": "Saison 10", "text": "Terror Cape : vulnérabilité 28 % → 20 % ; dague de lumière 25 → 20 de soin."}, {"season": "Saison 10", "text": "Tous les Strategists : l'ult se charge un peu moins vite (65 % du soin et 50 % des dégâts convertis en énergie, au lieu de 70 % et 55 %)."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · changements : patch notes des saisons 10 et 10.5", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'cloak-and-dagger' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"tags": ["Mêlée", "Dive", "Combos", "Renvoi"], "tldr": ["**Isole une cible, tue-la, puis gagne le 6 contre 5** avec ton équipe.", "Ton dash est **à haut risque** : sans reset, tu es hors du fight pendant un long moment.", "Ton grappin est d'abord un **outil de fuite**, pas d'engage."], "combos": [{"note": "Le lancer ricoche et ralentit : c'est ton ouvreur de loin.", "steps": [{"key": "F", "label": "marque"}, {"key": "", "label": "Lancer"}, {"key": "F", "label": "dash"}, {"key": "", "label": "Attaque bondissante"}, {"key": "", "label": "Frappe au sol"}, {"key": "", "label": "Attaque bondissante"}], "title": "Combo principal"}], "sources": [{"url": "https://www.youtube.com/watch?v=HRXsRdVXMVo", "title": "Daredevil Guide", "author": "Paz (padswagger)"}, {"title": "Ultimate Daredevil Guide (Beginner/Advanced)", "author": "Tephra98", "url": "https://www.youtube.com/watch?v=w0jA0OauzfA"}], "summary": "Daredevil est un duelliste de mêlée polyvalent, capable de diver sur une cible isolée comme de brawler avec son équipe. Il voit à travers les murs, marque une cible et la traque, et chaque élimination relance son dash.", "counters": [{"hero": "emma-frost", "note": "Son étranglement te sort du fight. Tu peux le renvoyer si tu l'anticipes."}, {"hero": "the-thing", "note": "Son impact au sol te bloque sans que tu puisses renvoyer."}, {"hero": "peni-parker", "note": "Son nid coupe tes dives."}, {"hero": "phoenix", "note": "Étourdissement ciblé, dash et régénération : elle te gagne."}, {"hero": "star-lord", "note": "Il te marque et esquive tes combos."}, {"hero": "ultron", "note": "Il vole hors de portée et soigne à distance."}], "sections": [{"kind": "tips", "lead": "Selon ta compo, tu attends dans l'ombre qu'un support s'isole, ou tu joues un angle à mi-distance pour charger ton ult en attendant ton moment.", "items": ["Repère les **cibles isolées** grâce à ta vision à travers les murs, puis frappe.", "Si c'est trop risqué d'entrer, reste sur un **angle décalé** et fais pression de loin.", "La **patience** est la clé : c'est très facile d'en faire trop et de mourir.", "Contre lui : si tu es marqué, **regroupe-toi**. S'il ne trouve pas de reset, il ne peut plus rien faire.", "Entre deux dives, tu as assez de vie pour **brawler les tanks** (Strange, Hulk, Captain America) en attendant tes cooldowns.", "Contre une compo **anti-dive** (Emma Frost, Winter Soldier), mets la pression sur les tanks ou chasse les flankers adverses que tu vois à travers les murs."], "title": "Philosophie de jeu", "diagram": "dive"}, {"lead": "Daredevil voit moins loin, mais il perçoit les ennemis à travers les murs, même immobiles ou invisibles.", "items": ["La vision à travers les murs révèle aussi **Invisible Woman et Loki** quand ils sont invisibles.", "Astuce : active l'option d'**effet de balayage** dans les paramètres d'accessibilité pour distinguer alliés et ennemis.", "Il peut **courir sur les murs** à l'infini : passe au-dessus de l'ennemi pour le surprendre.", "Baisse la **luminosité de fond du radar** dans les réglages du héros : tu vois mieux les murs quand tu dois fuir au grappin."], "title": "Passifs"}, {"key": "Clic G", "lead": "Une série de quatre coups qui remplit ta jauge de fureur. Après chaque capacité, tu gagnes une attaque bondissante plus puissante pendant quelques secondes.", "items": ["Glisse un **coup de mêlée** à la fin de la série : le premier frappe deux fois.", "L'attaque bondissante (**Righteous Cross**) te propulse en avant : parfaite pour **rattraper une cible mobile** ou fuir.", "Apprends à glisser une attaque bondissante **après chaque capacité** : c'est le cœur de son style.", "Alterner coups et **mêlée** recharge ta fureur plus vite : fais-le pendant tes temps morts pour revenir plein."], "title": "Matraques et fureur"}, {"key": "F", "lead": "Marque une cible à grande distance pour courir plus vite et encaisser moins. Réappuie pour foncer sur elle, l'aveugler et remplir ta fureur.", "items": ["Garde **toujours une marque** sur quelqu'un : bonus de vitesse et de résistance gratuits.", "Le dash a un **long cooldown**, mais il se relance si **n'importe quel ennemi meurt** juste après, même tué par un allié.", "Si tu n'es pas sûr d'obtenir le reset, **sois patient** et attends ton moment.", "L'aveuglement est utile : une **ult de Star-Lord** aveuglée ne peut plus tirer."], "title": "Marque et dash", "ability": "Sonic Pursuit"}, {"key": "E · Clic G / Clic D", "lead": "La fureur débloque deux attaques : une frappe au sol en X qui te donne de la vie bonus, et un lancer qui ricoche entre les ennemis.", "items": ["La **frappe au sol** fait plus de dégâts si tu vises **les pieds** : c'est ton outil pour finir et récupérer ton dash.", "Le **lancer** ricoche et ralentit : ton ouvreur de combo de loin, et une bonne source de charge d'ult.", "Combo principal : **marque, lancer, dash, attaque bondissante, frappe au sol**, puis une dernière attaque bondissante pour finir.", "Deux supports collés l'un à l'autre prennent **beaucoup plus** de dégâts avec le lancer."], "title": "Attaques de fureur", "ability": "Devil's Chain · Devil's Throw"}, {"lead": "Un grappin qui te tire vers un mur ou un ennemi. Son cooldown ne démarre qu'au contact : rater ne coûte rien.", "items": ["C'est surtout ton **outil de fuite**, comme le balancement de Venom.", "Pour engager, ne l'utilise que si tu peux **ressortir avec l'attaque bondissante** qu'il te donne.", "Agripper un ennemi vous place **tous les deux** au milieu des équipes : tu es solide, mais réfléchis.", "Avec un partenaire prêt, tu peux **tirer un support hors de son ult** (Invisible Woman, Cloak & Dagger) pour le tuer.", "Raté, il **ne part pas en cooldown** : retente tout de suite.", "Ce n'est **pas un stun** : contrairement à Bucky ou Spider-Man, il ne coupe pas les ults."], "title": "Grappin", "ability": "Devil's Latch"}, {"key": "Clic D", "lead": "Tu fais tournoyer tes matraques et renvoies tous les projectiles venant de face. Les rayons et coups de mêlée passent quand même.", "items": ["Il renvoie les **boules de neige de Luna, sommeils de Mantis, ults de Groot, Magneto ou Iron Man**.", "Il bloque aussi les ults de **Doctor Strange, Scarlet Witch ou The Thing**, sans les renvoyer.", "Les matraques **font des dégâts** pendant le renvoi : parfait pour finir une Luna qui tente de te geler.", "Les bons joueurs vont **chercher à le forcer** : ne l'utilise que si nécessaire.", "Option : désactive le mode **maintenir pour renvoyer**, le cooldown est fixe de toute façon.", "Il renvoie aussi les **soins en projectile** (dagues de Cloak & Dagger, orbes de Rocket) : tu te soignes avec."], "title": "Renvoi", "ability": "Objection"}, {"key": "Q", "lead": "Une aura de dégâts qui aveugle les ennemis qui te regardent. Sa vraie force : une fureur quasi infinie pour enchaîner les combos.", "items": ["Profite de la **fureur illimitée** pour enchaîner combos et resets de dash.", "Combine-la avec ton **renvoi** pour forcer l'ennemi à te regarder sans mourir.", "Elle peut **reprendre le tempo** : l'ennemi doit choisir entre te gérer ou continuer son plan.", "Comme toute ult de DPS, lance-la **avec le soutien** de ton équipe."], "title": "Ultime", "ability": "Let the Devil Out"}, {"kind": "mistakes", "items": ["Dasher **sans espoir de reset**.", "Engager **au grappin** sans porte de sortie.", "Renvoyer **trop tôt** et ne plus l'avoir pour l'ult adverse.", "Appuyer sur **clic droit par erreur** en plein combo.", "En faire trop et **mourir seul**."], "title": "Erreurs fréquentes"}], "synergies": [{"hero": "venom", "note": "En dive, il fait fondre la cible que tu marques."}, {"hero": "captain-america", "note": "Autre tank de dive pour converger sur la backline."}, {"hero": "emma-frost", "note": "En brawl, tu finis la cible qu'elle vient de frapper."}, {"hero": "hela", "note": "Elle couvre les volants que tu ne peux pas atteindre."}, {"hero": "phoenix", "note": "Même rôle, et vous gagnez les 2 contre 1."}, {"hero": "luna-snow", "note": "Le support qui marche avec lui dans toutes les compos."}], "difficulty": 3, "patch_note": "Guide tiré d'une vidéo de Paz (padswagger), reformulé en français. Les chiffres du kit ont été retirés car ils changent à chaque saison ; team-ups et derniers changements sont à jour (saison 10.5) dans la section dédiée.", "kit": {"season": "Saison 10.5", "health": "", "abilities": [], "teamups": [{"name": "Bestial Hunt", "partners": ["the-punisher"], "key": "", "text": "Balles perforantes avec bonus de dégâts. **Amélioré :** Détruit les murs plus vite."}, {"name": "Comprehensive Defense", "partners": ["iron-fist"], "key": "", "text": "Objection! touche tous les ennemis et renvoie les projectiles. **Amélioré :** Ajoute un soin passif."}, {"name": "Devilish Affair", "partners": ["black-widow"], "key": "", "text": "Devil's Chain frappe en croix et ralentit. **Amélioré :** Plus large, et rend de la Fureur."}], "changes": [], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · changements : patch notes des saisons 10 et 10.5", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'daredevil' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"tags": ["Trois rôles", "Montée en niveau", "Polyvalent", "Rebonds"], "tldr": ["**Gagner le fight passe avant monter de niveau** : prends tes selfies quand tes cooldowns sont à plat.", "Utilise ton premier dash **sur un ennemi** pour gagner les dashes bonus, jamais pour te déplacer.", "Lance ton ult **tôt** : si tu meurs avec, tu perds toute la charge."], "sources": [{"url": "https://www.youtube.com/watch?v=JfrdVuQ5mn0", "title": "Deadpool Guide", "author": "Paz (padswagger)"}, {"title": "Ultimate Deadpool Guide (Beginner/Advanced)", "author": "Tephra98", "url": "https://www.youtube.com/watch?v=Lb-cnglbx3w"}], "summary": "Deadpool se joue dans les trois rôles avec un kit presque identique : deux pistolets, deux katanas, une aura et un rebond sur les têtes. Il monte en niveau au fil de la partie et charge son ult avec des points de style. Chaque version a son propre plan de jeu.", "counters": [{"hero": "the-thing", "note": "Il gagne au corps à corps et bloque les rebonds."}, {"hero": "hela", "note": "Elle punit à distance avant que tu sois amélioré."}, {"hero": "phoenix", "note": "Son burst passe à travers ta régénération si elle est déjà utilisée."}], "sections": [{"kind": "tips", "lead": "Deadpool progresse en jeu : chaque kill te permet de prendre un selfie pour gagner de l'expérience et améliorer une capacité. L'expérience est partagée entre les rôles.", "items": ["Après un coup de grâce, **appuie sur la touche de selfie** près de la victime : tu es invulnérable pendant l'animation et tu gagnes beaucoup d'expérience.", "Pense comme dans un MOBA : **achète tes améliorations quand tes cooldowns sont à plat**, pas en plein fight.", "Son ult ne se charge pas comme les autres : il gagne des **points de style** selon ses actions.", "Ton **passif de régénération** se déclenche si tu prends un gros burst : il te fait survivre à des dégâts qui tueraient d'autres héros.", "Astuce rebond : saute quand **tes pieds sont dans la tête** de la cible, pas au-dessus, pour ne pas rater la relance.", "Deadpool **gagne de l'XP** avec le temps et en touchant : chaque niveau débloque une amélioration à choisir dans son menu, différente selon le rôle.", "Prendre un **selfie avec un corps** rapporte de l'XP et te rend invulnérable pendant la pose.", "Sa jauge d'ult monte comme dans un jeu de combat (de E à S) en touchant, mais **tu perds tout en mourant**.", "Un dash sur une cible **sous bulle** compte comme raté : il part en cooldown."], "title": "Philosophie de jeu", "diagram": "brawl"}, {"kind": "tips", "lead": "Un tank harceleur, proche d'un gros DPS : il tient l'espace en étant tellement pénible que l'ennemi doit le respecter.", "items": ["Joue **près de l'ennemi** : les pistolets perdent vite leurs dégâts à distance.", "Le **dôme** (clic droit aux pistolets) coupe les soins d'un tank isolé, gagne les duels contre un Hela, ou protège d'une ult (Magneto, Namor, Iron Man).", "L'**aura** fait tirer beaucoup plus vite : allume-la quand c'est ton tour de fight, ou pour sécuriser un duel.", "L'ult aux katanas est un **joker de survie** : elle te laisse aller plus loin pour forcer les ults adverses.", "Ordre d'amélioration conseillé : **pistolets, dash, aura**, puis katanas et dôme. Monte le dôme plus tôt si tu es seul tank.", "Améliorations conseillées : **la zone de provocation** d'abord, puis le dash, puis l'ult que tu utilises le plus (celle des katanas, plus facile à monter en bonus).", "Avant tes améliorations, joue surtout **au pistolet** et planifie ton avancée avec ta **bulle** de peluche."], "title": "Version Vanguard"}, {"kind": "tips", "lead": "Il use l'ennemi à distance, puis passe aux katanas pour finir. Patience, puis tout-en-un.", "items": ["Reste **un peu plus loin** qu'en tank : ses pistolets portent plus loin dans cette version.", "Lance le **boomerang** comme une grenade : vise les **pieds**, la zone tourne avant de revenir.", "Améliorés, les dashes se relancent **à chaque ennemi touché** : garde-en un pour le mini-jeu de ton ult.", "Les **rebonds sur les têtes** chargent ton ult très vite et donnent de la vie bonus.", "L'ult aux **pistolets** est utile contre un support prêt à ult : elle le rend vulnérable pour ton équipe.", "Améliorations : orientées **pistolets** si l'ennemi est plus fort que toi au corps à corps (The Thing), sinon **dash, aura et katanas**.", "Améliore d'abord **la tête lancée** (trois lancers puis explosion) : synchronise ton dash avec le troisième lancer pour un gros burst.", "Ensuite, les **dashes infinis** tant que tu touches : tu deviens presque intouchable au contact.", "Joue à distance jusqu'au moment d'engager avec ta **réduction de dégâts**."], "title": "Version Duelist"}, {"kind": "tips", "lead": "La plus forte des trois : énormément de soins, une aura qui booste les dégâts alliés et une ult qui se charge à une vitesse folle.", "items": ["Ses pistolets soignent **sans perte à distance** : un très bon soin ciblé.", "Le **boomerang** soigne tes alliés et blesse les ennemis : lance-le entre les deux, et dans le spawn adverse dès le début.", "Les **katanas et le dash** soignent en zone : parfaits en brawl serré et pour défendre ta backline contre un diver.", "L'**aura améliorée** donne un bonus de dégâts aux alliés : très fort avec Phoenix ou Black Widow.", "Les **rebonds sur les alliés blessés** chargent ton ult.", "Ult : avance **avec ton équipe dans l'aura** et lance-la **en début de fight**, de façon proactive. Finis le mini-jeu pour qu'elle dure plus longtemps que celle d'en face.", "Ordre conseillé : **boomerang puis ult aux katanas** en premier, le reste selon la partie.", "Soigne surtout **au pistolet** ; garde les katanas pour fuir ou **peel ton autre support** (tes coups soignent autour de toi).", "Améliore d'abord **la tête lancée** (soins), puis la zone de provocation pour la sécurité.", "L'ult des katanas, montée en bonus en **rebondissant sur la tête de tes alliés**, devient une longue ult défensive."], "title": "Version Strategist"}, {"key": "Maj · Clic D", "lead": "Maj passe des pistolets aux katanas. Avec les katanas, le clic droit lance un dash qui donne des dashes bonus s'il touche un ennemi.", "items": ["**Premier dash sur un ennemi** pour débloquer les dashes bonus, puis utilise-les pour bouger.", "Brûler tous ses dashes avant l'ult, c'est ne plus pouvoir **finir le mini-jeu**.", "Changer d'arme **remet à zéro** le compteur du tir explosif des pistolets améliorés."], "title": "Les katanas et le dash"}, {"key": "Q", "lead": "Une ult différente selon l'arme en main. Celle des katanas lance un mini-jeu : enchaîne rebonds, dashes ou boomerangs pour la renforcer.", "items": ["Le **mini-jeu** se suit en bas à droite de l'écran : chaque action réussie te rapproche du bonus.", "L'ult des katanas est presque toujours la bonne en **Vanguard et Strategist**.", "En **Duelist**, l'ult des pistolets peut servir à **isoler un support clé**.", "Mourir avec l'ult chargée **la fait perdre** : utilise-la plutôt trop tôt que trop tard."], "title": "Les ultimes"}, {"kind": "mistakes", "items": ["Prendre des selfies **en plein fight** alors que tes cooldowns sont dispos.", "Utiliser le **premier dash pour se déplacer**.", "**Mourir avec l'ult** chargée.", "En Strategist, foncer seul dans l'ult **sans ton équipe** dans l'aura.", "Jouer la version Vanguard **trop loin** de l'ennemi."], "title": "Erreurs fréquentes"}], "synergies": [{"hero": "phoenix", "note": "Ton aura de Strategist lui permet d'éliminer d'un coup."}, {"hero": "black-widow", "note": "Même effet : l'aura rend ses headshots mortels."}, {"hero": "winter-soldier", "note": "En Vanguard, un brawler qui profite de ton aura."}, {"hero": "wolverine", "note": "Autre brawler à accompagner avec ta réduction de dégâts."}, {"hero": "groot", "note": "Combattez dans les couloirs serrés où tes soins de zone brillent."}], "difficulty": 2, "patch_note": "Guide tiré d'une vidéo de Paz (padswagger), reformulé en français. Les chiffres du kit ont été retirés car ils changent à chaque saison ; team-ups et derniers changements sont à jour (saison 10.5) dans la section dédiée.", "kit": {"season": "Saison 10.5", "health": "", "abilities": [], "teamups": [{"name": "Hel-Yeah, Honey", "partners": ["hela"], "key": "", "text": "Deadpool débloque une amélioration en plus pour ses Desert Eagles et ses katanas."}, {"name": "Gumbo Chimichangas", "partners": ["gambit"], "key": "", "text": "Saut cinétique avec un anneau de chimichangas. **Amélioré :** Étourdit à l'atterrissage."}, {"name": "Loudmouth Mercs", "partners": ["elsa-bloodstone"], "key": "", "text": "Munitions spéciales qui provoquent et ralentissent. **Amélioré :** Plus de gain d'instinct."}, {"name": "Mr. Pool's Interdimensional Toy Box", "partners": ["jeff-the-land-shark"], "key": "", "text": "Une peluche provoque les ennemis et soigne. **Amélioré :** Provocation et dégâts renforcés."}], "changes": [{"season": "Saison 10", "text": "Vanguard : Desert Eagles moins pénalisées à distance (75 % des dégâts à 30 m au lieu de 50 %), Ban Hammer soigne 35/s au lieu de 25/s, améliorations moins chères en XP."}, {"season": "Saison 10", "text": "Duelist : tir des Desert Eagles 38 → 42."}, {"season": "Saison 10", "text": "Strategist : vie de base 250 → 275, cooldown 12 s → 10 s."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · changements : patch notes des saisons 10 et 10.5", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'deadpool' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"tags": ["Bouclier", "Portail", "Combos", "Contrôle de zone"], "tldr": ["**Économise ton bouclier** : passe de couvert en couvert et garde-le pour les grosses menaces.", "Construis ta **jauge de ténèbres**, puis relâche-la pour finir une cible avant qu'elle ne déborde.", "Ne te retourne pas pour **peel** : ta place est de tenir le front."], "combos": [{"note": "Avec **au moins la moitié de la jauge**.", "steps": [{"key": "Clic G", "label": "tir"}, {"key": "Mêlée", "label": ""}, {"key": "Clic G", "label": "tir"}, {"key": "", "label": "Explosion des ténèbres"}], "title": "Éliminer un fragile"}], "sources": [{"url": "https://www.youtube.com/watch?v=8ZyNSU1fBAk", "title": "Doctor Strange Guide", "author": "Paz (padswagger)"}, {"title": "The Only Dr Strange Guide You'll Ever Need", "author": "Kingsman", "url": "https://www.youtube.com/watch?v=sUEq8_2xjI0"}], "summary": "Doctor Strange est un tank flexible : il protège son équipe avec un grand bouclier, fait de vrais dégâts de loin, téléporte l'équipe avec ses portails et étourdit tout un groupe avec son ult. Il s'adapte au brawl comme au poke, un peu moins au dive.", "counters": [{"hero": "emma-frost", "note": "Elle charge sur ton bouclier et t'étrangle avant ton ult."}, {"hero": "hulk", "note": "Il frappe à travers ton bouclier."}, {"hero": "the-thing", "note": "Même chose, en brawl il te met beaucoup de pression."}, {"hero": "invisible-woman", "note": "Ses poussées annulent ton ult."}, {"hero": "wolverine", "note": "Il ignore ton bouclier au corps à corps."}], "sections": [{"kind": "tips", "lead": "Strange fait ce que ta compo demande : protéger un brawl, couvrir des tireurs à distance ou prendre la hauteur avec les DPS.", "items": ["Erreur classique : **tenir le bouclier tout le temps** et oublier de faire des dégâts. Sois actif.", "Alterne **tir et petits coups de bouclier** pour bloquer le burst sans vider sa vie.", "Si tes alliés se font diver, **ce n'est pas ton rôle** de te retourner : l'autre tank, un DPS ou un support s'en charge. Toi, tiens la ligne.", "Strange brille **contre les compos sans mêlée** et en miroir contre un autre Strange ; contre une bonne Emma Frost ou un Wolverine, son bouclier ne sert presque à rien : passe sur The Thing ou Emma.", "Contre trop de spam sur un choke, **Magneto** passe souvent mieux.", "En solo queue, la valeur de ton bouclier et de ton portail dépend de ton équipe : il rend beaucoup plus en groupe qui communique."], "title": "Philosophie de jeu", "diagram": "space"}, {"key": "Clic G", "lead": "Tes salves de dagues remplissent une jauge de ténèbres que tu relâches en explosion autour de toi. Plus la jauge est pleine, plus elle fait mal.", "items": ["Glisse un **coup de mêlée** entre deux salves : plus de dégâts et un rechargement plus rapide.", "Les dagues tournoient : vise **un peu à droite** de ta cible à distance. Au-delà d'une certaine portée, elles disparaissent.", "**Jauge pleine trop longtemps = anti-soin sur toi** : relâche-la à temps ou arrête de tirer.", "Combo : **tir, mêlée, tir, explosion** avec au moins la moitié de la jauge pour éliminer un personnage fragile.", "Parfois, mieux vaut **ne rien faire** et garder la jauge sous contrôle.", "Chaque dégât charge la jauge de ténèbres, la **mêlée aussi** (et elle touche plusieurs ennemis) : enchaîne tir, mêlée, tir, mêlée, puis explosion.", "Le rechargement est terminé **à la moitié de la barre** : annule-le avec une mêlée ou en levant ton bouclier.", "Jauge pleine trop longtemps = **anti-soin sur toi** pendant quelques secondes : décharge-la avant, surtout si tu es bas en vie."], "title": "Dagues et ténèbres", "ability": "Daggers of Denak · Maelstrom of Madness"}, {"key": "Clic D", "lead": "Un grand bouclier qui encaisse beaucoup et se régénère lentement une fois rangé. Celui qui garde le sien plus longtemps gagne le fight.", "items": ["Toujours bloquer : les ults qui visent tes supports (**Iron Man, Magneto**). Ne le lève pas trop tôt, sinon ils le cassent avant.", "Contre l'ult de **Hela**, monte en l'air et bloque face à elle.", "Bloque le **burst** (Hawkeye, Hela, Phoenix) : ils cassent mal le bouclier.", "Contre un **Punisher**, encaisse plutôt avec ta vie : il casse vite le bouclier mais te tue lentement.", "En attaque : coupe les **soins d'une ult de Luna** ou d'un tank trop avancé.", "Il se lève et se baisse **instantanément** : joue-le comme un bouclier de Reinhardt, pas comme un mur fixe.", "Sers-t'en pour **couper les soins** d'une cible isolée, ou bloquer une partie d'une ult de soin (Luna) et isoler un kill."], "title": "Bouclier", "ability": "Shield of the Seraphim"}, {"key": "F", "lead": "Deux portails reliés qui restent ouverts un court moment, avec un très long cooldown. Trois usages principaux.", "items": ["**Revenir du spawn** pour contester. En hauteur pour tes tireurs, face au point pour tes brawlers.", "Passe **toujours en premier** : les supports qui traversent avant toi se font piéger.", "**Bloquer un passage** : une boucle de portails entre deux portes empêche l'ennemi de contester.", "**Préparer une ult** (la tienne ou celle d'un allié), mais les bons joueurs s'y attendent.", "En défense, **garde-le** pour revenir. En attaque, tu peux l'utiliser tôt : il reviendra avant la fin du round.", "C'est **le meilleur outil du jeu pour recontester un point** : ferme les sorties du spawn adverse, ou ramène toute ton équipe en overtime.", "Tu peux **placer les deux extrémités** où tu veux après la première : c'est comme ça qu'on mure un passage.", "En overtime sur le point d'être perdu, **n'importe qui** (sauf un support qui a son ult) devrait passer Strange juste pour le portail."], "title": "Portail", "ability": "Pentagram of Farallah"}, {"lead": "Un vol de quelques secondes. Le cooldown ne démarre qu'à la fin du vol.", "items": ["**Mettre la pression** sur un DPS en hauteur.", "**Feinter ton ult** : monte, puis redescends bouclier levé pour faire sortir l'étourdissement de Luna.", "**Te faire soigner** hors de portée d'un brawler comme The Thing."], "title": "Lévitation", "ability": "Cloak of Levitation"}, {"key": "Q", "lead": "Après une longue incantation, tu étourdis tous les ennemis autour de toi et sépares leur âme de leur corps.", "items": ["Pendant l'incantation, tu peux être **étourdi, poussé, attiré** : prépare-la bien.", "Entre avec **une bonne jauge de ténèbres** : tir, mêlée, explosion pour éliminer les fragiles.", "Toucher **âme et corps** en même temps double les dégâts de l'explosion.", "Plutôt que sauter en plein milieu, **tombe d'un flank ou d'une hauteur** sur l'ennemi.", "Astuce : n'ult pas contre la première ult de soin : **vise la suivante** pour qu'elle ne puisse pas être contrée.", "Combo dans l'ult : **tir, mêlée, explosion de ténèbres** : elle touche le corps ET l'âme, donc dégâts doublés.", "**Fais sortir les contrôles** adverses avant (bulle de Magneto, gel de Luna, sommeil) : tu es très vulnérable pendant l'incantation.", "Lance-la depuis une **position cachée** (en l'air, dans un coin) quand l'ennemi n'a plus de quoi l'interrompre.", "Elle se recharge vite si tu enchaînes tirs, mêlées et explosions."], "title": "Ultime", "ability": "Eye of Agamotto"}, {"kind": "mistakes", "items": ["**Casser son bouclier** sur des dégâts sans importance.", "Laisser la jauge **déborder** et s'infliger l'anti-soin.", "Se retourner pour **peel** et laisser passer toute l'équipe adverse.", "Laisser les supports **traverser le portail en premier**.", "Ult **en sautant au milieu** de l'ennemi, de façon prévisible."], "title": "Erreurs fréquentes"}], "synergies": [{"hero": "magneto", "note": "Il bloque le soutenu, toi le burst. Un classique."}, {"hero": "winter-soldier", "note": "Un DPS qui avance derrière ton bouclier."}, {"hero": "the-punisher", "note": "Même logique de jeu front contre front."}, {"hero": "phoenix", "note": "Ton ult regroupe des cibles pour son explosion."}, {"hero": "luna-snow", "note": "Le duo de supports idéal derrière ton bouclier."}, {"hero": "loki", "note": "Même chose, très fort en ranked."}], "difficulty": 2, "patch_note": "Guide tiré d'une vidéo de Paz (padswagger), reformulé en français. Les chiffres du kit ont été retirés car ils changent à chaque saison ; team-ups et derniers changements sont à jour (saison 10.5) dans la section dédiée.", "kit": {"season": "Saison 10.5", "health": "", "abilities": [], "teamups": [{"name": "Chain of Cyttorak", "partners": ["magik"], "key": "", "text": "Une chaîne relie deux ennemis. **Amélioré :** Relie des groupes entiers."}, {"name": "Gamma Maelstrom", "partners": ["hulk"], "key": "", "text": "Le Maelstrom gamma accélère la charge (plus de perte de dégâts à distance depuis la saison 10). **Amélioré :** Garde et stocke l'énergie."}, {"name": "Psionic Vortex", "partners": ["invisible-woman"], "key": "", "text": "Projette les ennemis et renforce le bouclier. **Amélioré :** Vie bonus selon les dégâts."}, {"name": "Sorcerers Supreme", "partners": ["scarlet-witch"], "key": "", "text": "Salve de missiles mystiques. **Amélioré :** Devient activable à volonté."}], "changes": [{"season": "Saison 10", "text": "Daggers of Denak plus rapides (60 → 80 m/s) et cadence améliorée (0,9 s → 0,8 s)."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · changements : patch notes des saisons 10 et 10.5", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'doctor-strange' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"tags": ["Ligne de front", "Combos", "Anti-tank", "Mobilité"], "tldr": ["Commence **avec ton équipe** pour charger ton passif et ton ult, puis prends un léger angle.", "Glisse un **tir de fusil à éléphant** après chaque capacité : c'est là que sont tes dégâts.", "**Recharge souvent** : quatre tirs seulement avant d'être à sec."], "combos": [{"note": "Garde assez de munitions pour le lancer en entier.", "steps": [{"key": "Clic G", "label": "tir"}, {"key": "E", "label": "charge"}, {"key": "Clic G", "label": "tir"}, {"key": "E", "label": "détonation"}, {"key": "Clic G", "label": "tir"}], "title": "Combo de base"}, {"note": "Élimine une cible et te laisse ta fuite.", "steps": [{"key": "Clic G", "label": "tir"}, {"key": "E", "label": "charge"}, {"key": "Clic D", "label": "balle vivante"}, {"key": "Clic G", "label": "tir"}], "title": "Avec la balle vivante"}], "sources": [{"url": "https://www.youtube.com/watch?v=XTUTGUIFfUY", "title": "Elsa Bloodstone Guide", "author": "Paz (padswagger)"}, {"title": "Ultimate Elsa Bloodstone Guide (Beginner/Advanced)", "author": "Tephra98", "url": "https://www.youtube.com/watch?v=dQjvW-u1Mbs"}], "summary": "Elsa Bloodstone est une DPS de ligne de front avec une touche d'angle décalé, un mélange de Winter Soldier et de Psylocke. Son fusil à éléphant fait des dégâts en pourcentage qui font fondre les tanks, et son passif réduit le cooldown de son dash au fil de la partie.", "counters": [{"hero": "the-thing", "note": "Il bloque ta mobilité. Use-le à distance."}, {"hero": "hela", "note": "Elle te domine à distance selon la carte."}, {"hero": "phoenix", "note": "Même problème sur les cartes ouvertes."}, {"hero": "luna-snow", "note": "Son ult suit sa lanceuse : plus dure à attraper."}, {"hero": "gambit", "note": "Il peut sortir ses alliés de ton ult."}], "sections": [{"kind": "tips", "lead": "Elsa joue comme beaucoup de DPS méta : elle commence au centre, met la pression sur le front, puis passe sur un angle décalé pour finir le fight.", "items": ["Tire sur **les tanks** d'abord : ils reculent, et tu peux ensuite chercher un pick dans la backline.", "Une fois ton **passif plein**, tu deviens très difficile à ralentir : ne meurs pas pour le garder.", "Après un pick sur le **front adverse**, tu peux aller plus loin dans la backline : tes tanks n'ont plus besoin de toi.", "**Gère tes munitions** : recharge entre les échanges pour avoir de quoi faire un combo au bon moment.", "Tu n'es **pas une sniper** : ta portée efficace est courte (environ 15 m). Joue comme Psylocke, sur des **off-angles** avec des tentatives d'assassinat sur la backline.", "Contre beaucoup d'anti-dive (Winter Soldier), joue **avec ton équipe** et sers-toi de ton piège sur leurs flankers."], "title": "Philosophie de jeu", "diagram": "angle"}, {"key": "Clic G", "lead": "Ton arme de base tire en rafales instantanées. Après chaque capacité, tu passes quelques secondes au fusil à éléphant, qui transperce et fait des dégâts en pourcentage de la vie.", "items": ["Le fusil de base s'éparpille vite : reste **à mi-distance**, pas trop loin.", "Sur un flank discret, **approche avant de tirer** pour ne pas te dévoiler.", "Le fusil à éléphant **transperce les ennemis** (pas les boucliers) et s'étale à l'horizontale : aligne plusieurs cibles pour charger ton ult.", "Les capacités **ne rechargent pas** ton arme de base : surveille tes munitions."], "title": "Les deux fusils", "ability": "Double-Barrel Blaster · Monster Piercer"}, {"lead": "Ta jauge de passif se remplit avec les dégâts et les kills. Chaque palier réduit le cooldown de ton dash, qui te donne de la vie bonus et le fusil à éléphant.", "items": ["Jauge pleine = un dash **presque toujours disponible** : tu peux enchaîner les tirs de fusil à éléphant.", "La jauge ne baisse qu'**à ta mort** (d'un palier) ou en fin de round.", "Le dash est **uniquement horizontal** et coupe ton élan.", "Avant un engage : **dash, tir, dash, tir** pour ouvrir avec beaucoup de dégâts.", "Le dash part **dans la direction de ton déplacement**, pas de ta caméra : tu peux reculer ou esquiver de côté **en gardant ta visée** sur la cible.", "Les **kills** remplissent ta jauge d'instinct d'un coup ; en mourant, tu en perds une partie."], "title": "Passif et dash", "ability": "Inherited Instinct · Helix Advance"}, {"key": "E", "lead": "Une charge vers l'avant qui projette les ennemis en l'air, puis une détonation qui te propulse en arrière. Chaque partie te donne un tir de fusil à éléphant.", "items": ["Combo de base : **tir, E, tir, E, tir** pour éliminer un personnage fragile.", "Utilise la charge pour **tenter un pick risqué**, puis la détonation pour fuir.", "Pense à **te retourner** : la seconde partie te pousse vers l'arrière.", "Attention aux ennemis qui t'attendent : **The Thing, Invisible Woman, Winter Soldier** peuvent bloquer ta fuite."], "title": "Charge et recul", "ability": "Ruthless Pursuit"}, {"key": "Clic D", "lead": "Une balle qui ricoche entre les ennemis après son premier impact et les marque à travers les murs.", "items": ["Elle ne traque **qu'après avoir touché** un ennemi ou le décor : vise près de ta cible.", "Les marques révèlent les **ennemis invisibles** (Psylocke, Invisible Woman) et vérifient un coin suspect.", "Tirer sur une cible marquée te donne un **bref boost de vitesse**.", "Glisse-la dans tes combos : **tir, E, balle, tir** élimine une cible et te laisse ta fuite.", "Elle fait **plus de dégâts aux boucliers et à la vie bonus** : garde-la pour la bulle de Magneto, Cloak & Dagger ou le bouclier d'Invisible Woman sur elle-même.", "La marque se **voit à travers les murs** : tu suis une cible qui se cache.", "Tirer sur une cible marquée te donne **un petit boost de vitesse** pour fuir."], "title": "Balle vivante", "ability": "Living Bullet"}, {"lead": "Un piège qui devient invisible et indestructible après une seconde. L'ennemi qui marche dessus est immobilisé.", "items": ["Contre le **dive** (Daredevil…), pose-le près de tes supports.", "Contre ceux qui te sautent dessus sur ton angle (**Star-Lord, Psylocke**), pose-le à tes pieds.", "Contre un front lourd, pose-le **devant tes tanks** ou dans la backline adverse.", "Quand quelqu'un est pris, **dash sur lui** pour un kill facile.", "Pose-le **près d'un pack de soin** : une cible basse en vie vient s'y prendre toute seule."], "title": "Piège", "ability": "Smoky Snare"}, {"key": "Q", "lead": "Une créature charge droit devant, saisit les ennemis et les mord. Réappuie pour la faire revenir vers toi.", "items": ["Lance-la **à un dash de ton front**, de l'arrière vers l'avant : bien plus facile d'attraper plusieurs ennemis que depuis un angle bizarre.", "Tu peux **sortir un support de son ult** (Invisible Woman, Cloak & Dagger), mais ne la garde pas trois fights pour ça.", "Sur certaines cartes, elle peut **éjecter des ennemis** dans le vide, mais c'est risqué.", "Elle se charge vite : **utilise-la souvent**.", "C'est un **contre aux ults statiques** : sors Invisible Woman de son ult, ou attrape Cloak & Dagger à la fin de la sienne.", "Elle **coupe aussi une ult de DPS** en approche (Winter Soldier qui saute, Spider-Man) en l'emportant à l'autre bout.", "Le monstre a peu de vie : l'ult de Phoenix le détruit presque d'un coup."], "title": "Ultime", "ability": "Apex Predator"}, {"kind": "mistakes", "items": ["Être **à sec de munitions** au moment du combo.", "Tirer **de trop loin** avec l'arme de base.", "Oublier de **tirer au fusil à éléphant** après une capacité.", "Garder l'ult **plusieurs fights** pour un contre parfait.", "Lancer l'ult **depuis un flank lointain**."], "title": "Erreurs fréquentes"}], "synergies": [{"hero": "magneto", "note": "Un tank qui avance et te laisse jouer au front."}, {"hero": "emma-frost", "note": "Même chose, en brawl rapproché."}, {"hero": "groot", "note": "Ses murs regroupent les ennemis pour ton ult."}, {"hero": "winter-soldier", "note": "Duo qui fait fondre le front adverse."}, {"hero": "wolverine", "note": "Même logique de pression sur les tanks."}, {"hero": "deadpool", "note": "Un tank harceleur qui joue au contact avec toi."}], "difficulty": 2, "patch_note": "Guide tiré d'une vidéo de Paz (padswagger), reformulé en français. Les chiffres du kit ont été retirés car ils changent à chaque saison ; team-ups et derniers changements sont à jour (saison 10.5) dans la section dédiée.", "kit": {"season": "Saison 10.5", "health": "", "abilities": [], "teamups": [{"name": "Blood Moon", "partners": ["moon-knight"], "key": "", "text": "L'ankh piège invoque des serres. **Amélioré :** En invoque plusieurs."}, {"name": "Expert Instinct", "partners": ["winter-soldier"], "key": "", "text": "Les kills donnent des cumuls d'instinct. **Amélioré :** Augmente la vie bonus de Ceaseless Charge (55 en saison 10)."}, {"name": "Loudmouth Mercs", "partners": ["deadpool"], "key": "", "text": "Munitions spéciales qui provoquent et ralentissent. **Amélioré :** Plus de gain d'instinct."}, {"name": "Prehistoric Trap", "partners": ["devil-dinosaur"], "key": "", "text": "Smoky Snare immobilise et gaze (cooldown 15 s depuis la saison 10). **Amélioré :** Deux pièges."}], "changes": [{"season": "Saison 10", "text": "Monster-Piercer 13 → 12 de dégâts de base, Helix Advance 30 → 25 de vie bonus."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · changements : patch notes des saisons 10 et 10.5", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'elsa-bloodstone' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"tags": ["Rayon", "Brawl", "Contrôle", "Polyvalente"], "tldr": ["Priorité absolue : **charger ton rayon** à fond, puis le garder chargé.", "Ton bouclier est **utilitaire** : bloque un angle décalé ou une grosse menace, pas tout le flux de dégâts.", "En forme de diamant : **étranglement, coups, coup de pied contre un mur**."], "combos": [{"note": "Ajoute un coup de plus pour plus de sécurité.", "steps": [{"key": "Maj", "label": "forme diamant"}, {"key": "", "label": "Étranglement"}, {"key": "", "label": "Coup"}, {"key": "", "label": "Coup"}, {"key": "", "label": "Coup de pied au mur"}], "title": "Combo de base"}], "sources": [{"url": "https://www.youtube.com/watch?v=geqHn_q6k7w", "title": "Emma Frost Guide", "author": "Paz (padswagger)"}], "summary": "Emma Frost est le tank le plus polyvalent du jeu : elle charge son rayon pendant les longs fights, puis passe en forme de diamant pour finir les cibles au corps à corps avec étranglements et coups de pied. Si tu ne charges pas ton rayon au plus vite, tu perds.", "counters": [{"hero": "groot", "note": "Ses murs ne chargent pas ton rayon."}, {"hero": "iron-man", "note": "Il vole hors de portée de ton rayon."}, {"hero": "human-torch", "note": "Même problème avec les volants."}], "sections": [{"kind": "tips", "lead": "Le début d'un fight ne sert pas à tuer : il sert à charger ton rayon, comme un support charge son ult.", "items": ["Joue **à portée de rayon**, charge à fond, puis colle l'ennemi en forme de diamant.", "Après un fight gagné, va **intercepter l'ennemi à la sortie du spawn** pour garder ta charge.", "Ton rayon se vide si tu ne touches personne pendant quelques secondes : **reste actif**."], "title": "Philosophie de jeu", "diagram": "brawl"}, {"key": "Clic G", "lead": "Un rayon dont les dégâts augmentent avec sa charge. Tu le charges en touchant des ennemis, des boucliers, des clones ou tes cristaux.", "items": ["En duel contre une autre Emma, **ne pose pas ton bouclier** trop tôt : tu lui offrirais de la charge.", "Tu charges sur les **bulles de Magneto** et le **bouclier de Captain America**, mais pas sur le grand bouclier de Magneto ni les **murs de Groot**.", "Passer en diamant ou utiliser ton ult **met en pause** la perte de charge."], "title": "Rayon télépathique", "ability": "Telepathic Pulse"}, {"key": "E", "lead": "Un projectile qui extrait un cristal de la cible. Le briser lui inflige une partie de sa vie restante.", "items": ["Tirer sur le cristal **charge ton rayon plus vite** que sur un ennemi : c'est surtout un outil de charge.", "Ton rayon **traverse le cristal** pour toucher deux cibles à la fois.", "Si la cible s'éloigne trop du cristal, il **disparaît sans dégâts** : utilise-le à portée raisonnable.", "Astuce : tu peux extraire l'âme de **Venom ou Jeff** même quand ils sont sous terre."], "title": "Cristal d'âme", "ability": "Psychic Spear"}, {"key": "Clic D", "lead": "Un bouclier qui ne bloque qu'une fois posé. Il n'est pas très solide : c'est un outil pour avancer, pas un mur.", "items": ["Bloque un **DPS sur un angle décalé** pour l'obliger à changer de place pendant que tu gagnes le front.", "Prends le relais quand le **bouclier de ton Magneto** tombe.", "Il bloque bien les grosses menaces : **ult de Hela ou Iron Man, flèches de Hawkeye**.", "**Coupe les soins** d'un tank, puis étrangle-le et renvoie-le dans ton équipe.", "Pose-le toujours **avant de passer en diamant** ou de lancer ton ult."], "title": "Bouclier", "ability": "Mind's Aegis"}, {"key": "Maj", "lead": "Tu encaisses moins de dégâts pendant quelques secondes et tu passes aux coups de poing, avec un étranglement et un coup de pied.", "items": ["L'**étranglement** étourdit sa cible : il annule de nombreuses ults (Doctor Strange, Scarlet Witch, Loki…).", "Le **coup de pied** fait beaucoup plus mal si la cible percute un mur (les murs de Groot comptent, pas les corps).", "Combo de base : **étranglement, deux coups, coup de pied contre un mur**. Ajoute un coup pour plus de sécurité.", "Pousse les fragiles dans les **espaces fermés** avec ton rayon avant d'entrer.", "Dans un couloir étroit, un **coup de pied de zone en premier** peut couper les soins avant l'étranglement."], "title": "Forme de diamant", "ability": "Diamond Form"}, {"key": "Q", "lead": "Un cône qui fait des dégâts et prend le contrôle des ennemis, qui marchent vers toi quelques instants.", "items": ["Tu ne peux pas passer en diamant avant : **pose un bouclier** ou attends que ton équipe te couvre.", "**Casse les boucliers** adverses avant de lancer, sinon ils s'abritent derrière.", "Bon usage : contre une **ult de support statique** (Invisible Woman), pour **contrer un dive** sur tes supports, ou pour **désynchroniser un combo d'ults** adverse.", "Pas besoin d'attendre que toute l'équipe soit groupée : **une valeur précise** au bon moment suffit."], "title": "Ultime", "ability": "Psionic Seduction"}, {"kind": "mistakes", "items": ["Laisser son rayon **se décharger** entre deux fights.", "Utiliser le bouclier comme un **mur à encaisser**.", "Passer en diamant **sans bouclier** de couverture.", "Lancer l'ult **à découvert** ou face à des boucliers intacts.", "Coup de pied **sans mur** derrière la cible."], "title": "Erreurs fréquentes"}], "synergies": [{"hero": "magneto", "note": "Il tient le grand bouclier, tu prends le relais quand il tombe."}, {"hero": "winter-soldier", "note": "Vous enchaînez les contrôles sur une même cible."}, {"hero": "psylocke", "note": "Elle profite de l'espace que tu crées en brawl."}, {"hero": "luna-snow", "note": "Des soins solides pour te laisser charger."}, {"hero": "rocket-raccoon", "note": "Même logique, très fort quand il n'est pas banni."}], "difficulty": 2, "patch_note": "Guide tiré d'une vidéo de Paz (padswagger), reformulé en français. Les chiffres du kit ont été retirés car ils changent à chaque saison ; team-ups et derniers changements sont à jour (saison 10.5) dans la section dédiée.", "kit": {"season": "Saison 10.5", "health": "", "abilities": [], "teamups": [{"name": "Iced Out Diamond", "partners": ["luna-snow"], "key": "", "text": "Projectile de glace et barrière de diamant. **Amélioré :** Ajoute des ralentissements."}, {"name": "Magnetic Resonance", "partners": ["magneto"], "key": "", "text": "Une projection imite Magneto (50 % des dégâts, 6 s en 10.5). **Amélioré :** Beaucoup plus de vie, la projection dure."}, {"name": "Mental Projection", "partners": ["psylocke"], "key": "", "text": "Une illusion dashe et imite les frappes. **Amélioré :** Permet d'échanger de place avec l'illusion."}, {"name": "Spirit Breaker", "partners": ["mantis"], "key": "", "text": "Les dégâts de Sentience deviennent de la vie bonus. **Amélioré :** Vie bonus ponctuelle et cooldown de Psychic Spear réduit."}], "changes": [{"season": "Saison 10", "text": "Vie de base 650 → 675, portée de Telepathic Pulse 18 m → 20 m, Carbon Crush porte à 8,5 m au lieu de 7 m."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · changements : patch notes des saisons 10 et 10.5", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'emma-frost' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"tags": ["Purification", "Dégâts", "Duels", "Économie d'ult"], "tldr": ["Sors ton **paquet de dégâts** entre les fights et en début de combat : c'est ta charge d'ult.", "Anticipe l'ult adverse et **garde le paquet de soin prêt** pour la purifier.", "Lance ton ult **une fois collé à l'ennemi**, pas de loin."], "combos": [{"note": "", "steps": [{"key": "", "label": "Paquet dégâts"}, {"key": "Clic G", "label": "tir"}, {"key": "", "label": "Dash renforcé"}, {"key": "Clic G", "label": "tir"}, {"key": "", "label": "Carte anti-soin"}], "title": "Combo pick"}], "sources": [{"url": "https://www.youtube.com/watch?v=WIHDdJujzUs", "title": "Gambit Guide", "author": "Paz (padswagger)"}, {"title": "Ultimate Gambit Guide (Beginner/Advanced)", "author": "Tephra98", "url": "https://www.youtube.com/watch?v=mYUUUKAQplM"}], "summary": "Gambit est un support agressif et autonome : il fait des dégâts dès le début du fight pour charger son ult avant tout le monde, purifie ses alliés des contrôles et des ults, et transforme son équipe en rouleau compresseur avec son ultime.", "counters": [{"hero": "daredevil", "note": "Son burst te tue avant que tu te soignes."}, {"hero": "hela", "note": "Même problème à distance."}, {"hero": "elsa-bloodstone", "note": "Elle saisit tes alliés en boucle avec son ult."}], "sections": [{"kind": "tips", "lead": "Comme Luna Snow, Gambit gagne en chargeant son ult plus vite que les autres supports. Mais il joue plus près de son équipe et cherche des picks.", "items": ["Prends un **léger angle décalé** pour poker là où les boucliers ne te bloquent pas, avec la possibilité de revenir en dash vers ton équipe.", "Il est excellent pour **marquer les divers** (Psylocke, Iron Fist) : duel-les avant qu'ils atteignent ton équipe.", "Détruis les **objets adverses** (clones, tourelles) quand tu peux.", "En **double support**, soigne un peu plus. En **triple support**, lâche-toi sur les dégâts et l'anti-soin.", "Joue **assez près de ton équipe** pour que tes trois cartes touchent : ton tir principal est un fusil à pompe, il soigne mal de loin.", "Gambit soigne énormément : en duo de supports classique, tu soigneras plus que tu ne feras de dégâts ; en **triple support**, lâche-toi sur les cartes de dégâts.", "Quand l'ennemi a une **ult qui gagne un fight** (Groot, Strange, Winter Soldier), recule un peu : tu ne la prends pas, et tu peux dash dans ton équipe pour **la nettoyer**."], "title": "Philosophie de jeu", "diagram": "pocket"}, {"key": "Clic G", "lead": "Des salves de trois cartes qui soignent les alliés et blessent les ennemis. Elles s'écartent avec la distance.", "items": ["Pas de perte de dégâts avec la distance, mais **l'écart entre les cartes** grandit : reste à distance moyenne.", "Très facile de toucher : utilise-les pour **poker** autant que pour soigner."], "title": "Cartes cinétiques"}, {"lead": "Un dash qui traverse les cibles et une frappe au sol qui soigne les alliés (toi compris) et blesse les ennemis. Combinés, ils deviennent un dash tournoyant.", "items": ["Contre des flankers (**Daredevil, Psylocke, Captain America**), garde la frappe pour te défendre.", "Contre un **brawl lourd**, utilise-la plus agressivement avec ton équipe.", "Le **dash renforcé** (frappe pendant le dash) va plus loin et soigne ou blesse en chemin. Fais un **demi-tour** en plein dash pour tout toucher.", "Utilise-le pour **revenir soigner** ton équipe après un duel, ou pour aller finir une cible au front.", "Frappe au sol **pendant le dash** : tu tournoies vers l'avant en soignant les alliés traversés. Pour faire mal, commence **collé à l'ennemi** : la première frappe part tout de suite.", "Le dash va dans toutes les directions : **monte en hauteur** avec."], "title": "Dash et frappe au sol", "ability": "Cajun Charge · Bayou Bash"}, {"kind": "tips", "lead": "Tu as quatre charges partagées. Sortir un paquet coûte une charge, jouer une carte en coûte une autre : anticipe ce dont tu auras besoin.", "items": ["Le **paquet de soin** ne fait que te régénérer : ne le sors que si tu comptes jouer une carte de soin.", "Le **paquet de dégâts** booste tous tes dégâts quelques secondes : sors-le dès que possible pour charger ton ult.", "Une carte gâchée, c'est **deux charges perdues** : l'autre Gambit gagne l'échange.", "Règle de base : pour un **burst de soin**, le paquet de soin en ligne (Flush) ; pour un **burst de dégâts**, la salve (Raise). Les autres options sont pour des cas précis.", "Une carte pour activer, une autre pour lancer : avec quatre cartes, tu n'as que **deux lancers**. Ne les spamme pas.", "Avec une seule carte, tu peux quand même **activer** le bonus (soin ou dégâts) sans lancer.", "Garde **deux cartes** en réserve quand une ult adverse arrive : la purge de soin (Raise) **annule les contrôles et les débuffs**, même l'ult de Strange ou la marque de Winter Soldier. Contrer une ult, c'est la meilleure valeur du jeu."], "title": "Les paquets de cartes"}, {"lead": "Une carte qui rebondit entre les alliés et booste leurs soins reçus, et une volée de cartes qui soigne et purifie.", "items": ["La **carte rebondissante** est la carte « enabler » : lance-la sur un allié qui lance son ult (Punisher, Star-Lord).", "Elle peut **rebondir sur le sol** pour soigner un allié hors de vue.", "La **purification** efface les contrôles : ult de Winter Soldier, de Doctor Strange, attrapes d'Angela ou de Wolverine, anti-soin…", "Elle ne protège pas à l'avance : **sors le paquet avant l'ult**, puis purifie au bon moment.", "Purifier une ult **gagne des parties**. Plus tu montes, plus ça vaut le coup de la guetter."], "title": "Cartes de soin", "ability": "Bridge Boost · Purifying Pickup"}, {"lead": "Une carte explosive qui applique l'anti-soin, et une volée qui projette les ennemis en l'air.", "items": ["L'**anti-soin** aide à tuer à travers une ult de soin, si ton équipe suit.", "En ranked, elle sert surtout à **finir une cible**. Avec des combos comme les ults de Groot ou d'Angela, n'hésite pas.", "La **projection** coupe les attrapes d'Angela ou Wolverine, les sauts de Hulk, les balancements de Venom.", "Combo pick : **paquet de dégâts, tir, dash renforcé, tir, carte anti-soin**."], "title": "Cartes de dégâts", "ability": "Explosive Trick · Bidding Barrage"}, {"key": "Q", "lead": "Tous les alliés dans un grand cône sont purifiés, soignés, accélérés, chargent leur ult plus vite et infligent des dégâts bonus. Une des ults les plus fortes du jeu.", "items": ["**Engager** : charge-la avant tout le monde, puis lance-la **quand ton équipe est déjà sur l'ennemi**.", "**Contre-ult** : quand l'ennemi lance une grosse ult (Doctor Strange…), réponds avec la tienne, même à travers un mur.", "Tu peux aussi l'utiliser pour **tuer un support juste avant qu'il ait son ult**.", "Lance-la **depuis l'arrière** de ton équipe pour toucher tout le monde, puis passe aux dégâts.", "Si tu es en retard sur l'autre support, sois la **deuxième ult** du fight.", "Elle se lance **à travers les murs** et nettoie tous les effets négatifs : parfaite pour **lancer un fight** ou retourner un fight perdu."], "title": "Ultime", "ability": "Ragin' Royal Flush"}, {"kind": "mistakes", "items": ["Rester derrière à **soigner tout le fight**.", "Sortir un paquet **sans plan** et gâcher deux charges.", "Ne pas avoir le **paquet de soin prêt** quand l'ult adverse arrive.", "Lancer l'ult **de trop loin** : l'ennemi a le temps de fuir.", "Duel un **Daredevil** sans soutien."], "title": "Erreurs fréquentes"}], "synergies": [{"hero": "magneto", "note": "Un tank de brawl qui avance avec toi."}, {"hero": "psylocke", "note": "Ton anti-soin sur la backline lui offre des kills."}, {"hero": "captain-america", "note": "En dive, tu suis facilement grâce à ta mobilité."}, {"hero": "venom", "note": "Même logique de dive."}, {"hero": "luna-snow", "note": "Un duo de supports qui rend la backline presque immortelle."}], "difficulty": 3, "patch_note": "Guide tiré d'une vidéo de Paz (padswagger), reformulé en français. Les chiffres du kit ont été retirés car ils changent à chaque saison ; team-ups et derniers changements sont à jour (saison 10.5) dans la section dédiée.", "kit": {"season": "Saison 10.5", "health": "", "abilities": [], "teamups": [{"name": "Favorable Odds", "partners": ["magneto"], "key": "", "text": "Cartes magnétiques qui soignent et projettent (une seule fois, à l'explosion, depuis la saison 10). **Amélioré :** Explosion finale en plus."}, {"name": "Gumbo Chimichangas", "partners": ["deadpool"], "key": "", "text": "Saut cinétique avec un anneau de chimichangas. **Amélioré :** Étourdit à l'atterrissage."}, {"name": "Kinetic Kin", "partners": ["cyclops"], "key": "", "text": "Boost de vitesse et de saut (8 s en 10.5). **Amélioré :** Augmente la vitesse d'attaque."}, {"name": "Mr. & Mrs. X", "partners": ["rogue"], "key": "", "text": "Explosions cinétiques sur les attaques. **Amélioré :** Verrouille Hearts as One."}, {"name": "Pair of Threes", "partners": ["wolverine"], "key": "", "text": "Amélioration cinétique avec des particules qui explosent. **Amélioré :** Ajoute un soin continu."}, {"name": "Sparkling Staff", "partners": ["jubilee"], "key": "", "text": "Un bâton qui soigne et bloque les projectiles (2 s en 10.5). **Amélioré :** Ajoute des auras de soin continu."}], "changes": [{"season": "Saison 10", "text": "Team-up avec Magneto : la projection ne se déclenche plus qu'une fois, à l'explosion."}, {"season": "Saison 10.5", "text": "Paquets de soin et de dégâts : 7 s par charge au lieu de 8 s."}, {"season": "Saison 10.5", "text": "Ult : portée de recherche 40 m → 30 m, boost de saut 500 → 300."}, {"season": "Saison 10", "text": "Tous les Strategists : l'ult se charge un peu moins vite (65 % du soin et 50 % des dégâts convertis en énergie, au lieu de 70 % et 55 %)."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · changements : patch notes des saisons 10 et 10.5", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'gambit' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"tags": ["Murs", "Combos d'ult", "Couloirs", "Ligne de front"], "tldr": ["**Isole un tank de ses heals** avec tes murs, puis focus-le avec ton équipe.", "Garde ton **mur de bois de fer** pour un vrai engage, pas pour décorer.", "Avant ton ult, vérifie que **ton partenaire de combo** est prêt."], "sources": [{"url": "https://www.youtube.com/watch?v=l6xG6WAsYMU", "title": "Groot Guide", "author": "Paz (padswagger)"}], "summary": "Groot est un tank de ligne de front qui découpe le champ de bataille avec ses murs : il isole une cible de ses heals pour que son équipe la tue, et son ult regroupe les ennemis pour lancer des combos dévastateurs.", "counters": [{"hero": "wolverine", "note": "Le pire matchup : il t'attrape dans les couloirs. Garde un grand mur."}, {"hero": "iron-man", "note": "Il reste hors de portée et casse tes murs."}, {"hero": "winter-soldier", "note": "Son grappin te tire hors de ta position."}, {"hero": "emma-frost", "note": "Elle charge son rayon sur tes murs."}, {"hero": "captain-america", "note": "Il ignore tes murs en divant."}, {"hero": "loki", "note": "Il casse tes murs sans trop de risque."}], "sections": [{"kind": "tips", "lead": "Groot a peu d'options sans ses capacités. Tout son jeu repose sur le bon mur au bon moment.", "items": ["Arrive en position **à couvert** sans gaspiller tes murs, puis coupe les tanks de leurs heals.", "Sois **patient** : force d'abord les capacités de fuite (le saut de Strange…), puis isole la cible pour de bon.", "Joue les **couloirs étroits** : un grand mur et un petit au-dessus suffisent à renvoyer l'équipe adverse au spawn.", "Contre le **dive**, place tes murs devant le front adverse pour laisser à ton équipe le temps de gérer le diver.", "Tu peux aussi **protéger une ult alliée** (l'amplificateur de Rocket, un support face à Hawkeye) derrière un mur."], "title": "Philosophie de jeu", "diagram": "choke"}, {"key": "Clic G", "lead": "De gros projectiles faciles à toucher, une série de trois coups de mêlée et une bombe de spores à lancer comme une grenade.", "items": ["Pas de headshot : vise **les jambes**, la hitbox est plus large.", "Glisse des **coups de mêlée** entre les tirs : le troisième repousse et projette en l'air.", "La **bombe** fait mal aux groupes et aux pieds des tanks.", "Une bombe sur les **supports adverses** les empêche de soigner tranquillement."], "title": "Dégâts", "ability": "Vine Strike · Spore Bomb"}, {"key": "Maj", "lead": "Deux murs en stock, rechargés rapidement. Chaque appui change l'orientation : vertical, diagonal (escalier) ou horizontal (plafond).", "items": ["**Vertical** pour couper les ennemis entre eux, **diagonal** pour créer un escalier vers une hauteur, **horizontal** pour piéger un passage.", "Les murs **blessent les ennemis proches** quand ton équipe leur inflige des dégâts.", "Ils sont fragiles face à **Punisher, Loki ou Iron Man**.", "Leur cooldown démarre à la pose : **laisse-les en place**."], "title": "Murs d'épines", "ability": "Thornlash Wall"}, {"lead": "Un grand mur très solide, posé plus près de toi. À côté, les dégâts de ton équipe te donnent de la vie bonus.", "items": ["C'est ton outil d'**engage** : utilise-le pour un vrai pick ou pour forcer un gros cooldown (lampes, lien d'Adam).", "Ne le lance pas **n'importe comment** : sans lui, tu es vulnérable un long moment.", "Une fois l'engage fait, **récupère-le** avec F : son cooldown est plus court s'il a peu souffert.", "Ne laisse pas de mur hors de portée : une **Emma** adverse s'en servirait pour charger son rayon."], "title": "Mur de bois de fer", "ability": "Ironwood Wall"}, {"key": "Q", "lead": "Un projectile qui attire et retient les ennemis au centre. Sa force : les combos avec d'autres ults pour tuer à travers une ult de soin.", "items": ["Elle se charge **très vite** : au premier fight, lance-la si l'ennemi n'a pas d'ult de support.", "Combos classiques : **Moon Knight, Namor, Winter Soldier, Human Torch**, avec le voile de Cloak en bonus.", "Regarde le **tableau des scores** entre les fights pour savoir avec qui combiner.", "Sans combo face à une ult de support : **force-la d'abord**, ou coupe la Luna de son équipe avec un mur.", "Méfie-toi d'**Adam Warlock** (sa résurrection annule ton combo) et du **bouclier de Magneto**, qui bloque le projectile.", "Pendant l'ult, **isole avec un mur** les supports qui ne sont pas pris dedans."], "title": "Ultime", "ability": "Strangling Prison"}, {"kind": "mistakes", "items": ["**Jeter ses murs** sans plan.", "Laisser le grand mur en place **après l'engage**.", "Ult **sans partenaire** prêt à suivre.", "Lancer l'ult **dans un bouclier** de Magneto.", "Laisser un mur **à portée d'une Emma** adverse."], "title": "Erreurs fréquentes"}], "synergies": [{"hero": "magneto", "note": "Un tank flexible pour peel ou avancer."}, {"hero": "emma-frost", "note": "Même chose, quand Magneto est pris."}, {"hero": "moon-knight", "note": "Le combo d'ult classique."}, {"hero": "namor", "note": "Son ult achève les ennemis que tu regroupes."}, {"hero": "human-torch", "note": "Ses zones de feu font fondre ta prison."}, {"hero": "cloak-and-dagger", "note": "Son voile booste les dégâts sur tes cibles isolées."}], "difficulty": 2, "patch_note": "Guide tiré d'une vidéo de Paz (padswagger), reformulé en français. Les chiffres du kit ont été retirés car ils changent à chaque saison ; team-ups et derniers changements sont à jour (saison 10.5) dans la section dédiée.", "kit": {"season": "Saison 10.5", "health": "", "abilities": [], "teamups": [{"name": "Bubble Buddies", "partners": ["jeff-the-land-shark"], "key": "", "text": "Une bulle-bouclier rend invincible et soigne. **Amélioré :** Ajoute de la vie bonus."}, {"name": "Flora Munitions", "partners": ["star-lord"], "key": "", "text": "Pièges d'épines qui immobilisent. **Amélioré :** Plus de pièges et de dégâts."}, {"name": "Planet X Pals", "partners": ["rocket-raccoon"], "key": "", "text": "Spores épineuses qui blessent et soignent. **Amélioré :** Rocket peut monter sur Groot."}, {"name": "Wild Wall", "partners": ["mantis"], "key": "", "text": "Le Wild Wall soigne et donne de la vie bonus. **Amélioré :** Le mur évolue après avoir soigné."}], "changes": [{"season": "Saison 10", "text": "Ironwood Wall : vie bonus 40 → 50."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · changements : patch notes des saisons 10 et 10.5", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'groot' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"tags": ["Sniper", "One-shot", "Anti-ult", "Parade"], "tldr": ["**Garde ta visée sur une cible** pour charger tes flèches : deux tirs au corps suffisent souvent.", "Installe-toi **en marchant** et garde ton saut pour survivre aux divers.", "En duel, **arrête de bouger** au moment du tir : tu simplifies ta visée."], "combos": [{"note": "La flèche chargée au corps suffit.", "steps": [{"key": "", "label": "Flèche hypersonique"}, {"key": "Clic G", "label": "flèche chargée"}], "title": "Tuer un fragile"}, {"note": "", "steps": [{"key": "Mêlée", "label": ""}, {"key": "Mêlée", "label": ""}, {"key": "", "label": "Coup de zone"}, {"key": "Clic G", "label": "flèche chargée"}], "title": "Au contact"}], "sources": [{"url": "https://www.youtube.com/watch?v=L10v3F9r5Hs", "title": "Hawkeye Guide", "author": "Paz (padswagger)"}], "summary": "Hawkeye est un tireur à très haut risque et très haute récompense : ses flèches chargées tuent d'un headshot, ce qui lui permet de couper une ult de support tout seul. En échange, il a peu de mobilité et souffre face au dive.", "counters": [{"hero": "venom", "note": "Il te dive et t'oblige à te replacer sans cesse."}, {"hero": "captain-america", "note": "Même problème, il ignore ton angle."}, {"hero": "iron-fist", "note": "Il pare tes flèches et coupe tes capacités."}, {"hero": "psylocke", "note": "Invisible, elle comble la distance facilement."}, {"hero": "moon-knight", "note": "Tu ne peux pas charger sur ses ankhs."}, {"hero": "magneto", "note": "Son bouclier te prive de tes cibles."}], "sections": [{"kind": "tips", "lead": "Hawkeye vit ou meurt par sa visée. Mais tu n'as pas besoin de ne faire que des headshots : des tirs au corps réguliers suffisent à peser.", "items": ["Son point fort unique : **tuer un support à travers son ult** sans aide, très fort contre le triple support.", "Charge tes flèches **à couvert**, en ne montrant qu'un bout de ton corps : l'ennemi ne peut presque pas te toucher.", "Si tu as l'avantage, **deux tirs au corps** valent mieux qu'un headshot raté.", "Charger une flèche **te ralentit** : ne reste pas armé face à un diver."], "title": "Philosophie de jeu", "diagram": "highground"}, {"key": "Clic G", "lead": "Plus une flèche est chargée, plus elle fait mal. Ton passif ajoute des dégâts quand ton viseur reste sur un ennemi.", "items": ["Les flèches sont **très rapides** : tu dois à peine anticiper.", "Tu peux charger ton passif **sur les tanks** au front avant de viser une cible lointaine.", "Les **flèches explosives** servent à casser le décor, les clones de Loki, ou à mettre la pression sur une cible que tu ne peux pas viser longtemps."], "title": "Flèches"}, {"lead": "Une flèche qui transperce les ennemis, les ralentit et fait tomber les volants. Une excellente source de charge d'ult.", "items": ["Tire-la dans un **groupe** : chaque cible touchée charge beaucoup ton ult.", "Elle **fait tomber** Iron Man, Angela ou Ultron.", "Combo : **flèche hypersonique puis flèche chargée** au corps pour tuer un personnage fragile.", "Ne l'oublie pas : beaucoup de joueurs la laissent de côté."], "title": "Flèche hypersonique", "ability": "Hypersonic Arrow"}, {"lead": "Un coup d'épée de zone qui repousse les ennemis, et un coup de mêlée qui pare les projectiles s'il est bien synchronisé.", "items": ["Le coup de zone est ta **survie contre les divers** : utilise-le **après** le saut de Captain America ou de Venom.", "Un bon **Iron Fist** le parera : sois malin.", "Combo : **deux coups de mêlée, coup de zone, flèche chargée au corps**.", "La **parade** bloque les projectiles non explosifs : coups de poing, flèches, boules de neige de Luna.", "Les meilleurs Hawkeye **parent, attendent le rechargement adverse**, puis placent leur flèche."], "title": "Coup d'épée et parade", "ability": "Crescent Slash · Ronin Slash"}, {"lead": "Un double saut dans la direction choisie. C'est ta seule vraie porte de sortie.", "items": ["Ne l'utilise pas pour **monter sur ton angle** en début de fight : les divers te verront arriver.", "Installe-toi **en marchant** ou après un fight gagné.", "Quand ils divent, **descends vers ton équipe**, puis remonte en sautant quand ils te suivent."], "title": "Saut", "ability": "Skyward Leap"}, {"key": "Q", "lead": "Tes flèches se chargent quasi instantanément et les ennemis laissent des images rémanentes que tu peux toucher.", "items": ["C'est une ult **aussi redoutée que celles de Star-Lord ou Punisher** : attends-toi à être focus.", "Lance-la dans un **espace ouvert**, quand l'ennemi n'a pas de quoi y répondre.", "Face à l'ult de **Magneto**, saute : tu ne peux pas la parer.", "Même un seul pick ou une ult adverse forcée, c'est **suffisant** : survis pour la suite.", "Elle se charge **vite** : tu l'auras presque à chaque fight."], "title": "Ultime", "ability": "Hunter's Sight"}, {"kind": "mistakes", "items": ["Garder une flèche **chargée face à un diver**.", "Utiliser le **saut pour s'installer**.", "Chercher la **tête à tout prix** au lieu de deux tirs au corps.", "Oublier la **flèche hypersonique**.", "Lancer l'ult **sans couverture** d'équipe."], "title": "Erreurs fréquentes"}], "synergies": [{"hero": "luna-snow", "note": "Le support idéal à côté duquel jouer ton angle."}, {"hero": "invisible-woman", "note": "Son bouclier te protège pendant que tu tires."}, {"hero": "venom", "note": "Un tir au corps et il finit la cible."}, {"hero": "captain-america", "note": "Même logique en dive."}], "difficulty": 3, "patch_note": "Guide tiré d'une vidéo de Paz (padswagger), reformulé en français. Les chiffres du kit ont été retirés car ils changent à chaque saison ; team-ups et derniers changements sont à jour (saison 10.5) dans la section dédiée.", "kit": {"season": "Saison 10.5", "health": "", "abilities": [], "teamups": [{"name": "Allied Agents", "partners": ["black-widow"], "key": "", "text": "Les cumuls de concentration donnent des balles renforcées ; les critiques gardent la concentration active."}, {"name": "Moonlit Slash", "partners": ["cloak-and-dagger"], "key": "", "text": "Entaille lumineuse qui soigne les alliés, et Hawkeye se soigne d'autant (10.5). **Amélioré :** Combo en trois coups."}, {"name": "Senbonzakura Strike", "partners": ["psylocke"], "key": "", "text": "Hawkeye stocke des flèches psioniques (33 dégâts en 10.5) et les tire ensemble. **Amélioré :** Encochage plus rapide et explosions."}], "changes": [{"season": "Saison 10.5", "text": "Piercing Arrow plus rapide (140 à 210 m/s), Hypersonic Arrow plus large (3 m → 5 m), Crescent Slash récupère un peu plus vite."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · changements : patch notes des saisons 10 et 10.5", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'hawkeye' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"tags": ["Hitscan", "Angles décalés", "Burst", "Invulnérabilité"], "tldr": ["Prends des **angles décalés** où l'ennemi ne te voit pas : tes tirs deviennent bien plus faciles.", "Ton **corbeau est une fuite**, pas un engage : rejoins ton angle à pied.", "Lance ton ult **là où l'ennemi ne peut pas fuir**, après avoir forcé ses réponses."], "combos": [{"note": "L'étourdissement en plein déplacement **annule aussi leur capacité**.", "steps": [{"key": "Clic G", "label": "tête"}, {"key": "E", "label": "étourdir"}, {"key": "Clic G", "label": "tête"}], "title": "Combo de base"}], "sources": [{"url": "https://www.youtube.com/watch?v=KD6ORSun0ZE", "title": "Hela Guide", "author": "Paz (padswagger)"}], "summary": "Hela est une tireuse instantanée qui élimine les personnages fragiles en deux headshots. Sa vraie force n'est pas que la visée : c'est de se placer sur des angles décalés où les tirs deviennent faciles, et de fuir invulnérable en corbeau.", "counters": [{"hero": "hulk", "note": "Il te colle et te prive de ton angle."}, {"hero": "venom", "note": "Même problème, surtout avec un DPS diver."}, {"hero": "captain-america", "note": "Il te rejoint très vite."}, {"hero": "doctor-strange", "note": "Son bouclier te bloque sur les cartes sans angle."}, {"hero": "invisible-woman", "note": "Son bouclier protège ceux qui te duellent."}, {"hero": "rocket-raccoon", "note": "Ses packs d'armure cassent ton tue-en-deux."}], "sections": [{"kind": "tips", "lead": "Les meilleures Hela ne sont pas celles qui touchent tout : ce sont celles qui se rendent la tâche facile.", "items": ["Prends un angle, **fais des dégâts rapides**, puis passe à autre chose.", "Un DPS sert d'abord à **chasser l'ennemi des positions fortes**, pas seulement à tuer.", "**Ne sacrifie pas ton placement** pour un kill : un headshot suffit souvent à sortir une cible du fight.", "Entraîne-toi à la visée **par clics** (statique et dynamique)."], "title": "Philosophie de jeu", "diagram": "angle"}, {"key": "Clic G · Clic D", "lead": "Des dagues instantanées qui tuent en deux headshots, et une volée de dagues explosives qui collent aux cibles.", "items": ["Au-delà d'une certaine distance, les dégâts baissent : il faut alors **un tir de plus**.", "La **volée explosive** sert sur les groupes, les boucliers, ou pour finir une cible blessée par le corbeau de ton passif.", "Les dagues **collent** : la cible ramène l'explosion au milieu de son équipe."], "title": "Dagues", "ability": "Nightsword Thorn · Piercing Night"}, {"key": "E", "lead": "Un projectile qui attire et étourdit brièvement. Assez pour placer un headshot facile.", "items": ["**Headshot, étourdissement, headshot** : le combo de base.", "Il **coupe l'incantation** d'ults comme celle de Doctor Strange.", "Garde-le contre les divers (**Black Panther, Iron Fist, Magik**) : ils guettent ton étourdissement pour te sauter dessus.", "Les étourdir en plein déplacement **annule aussi leur capacité**."], "title": "Étourdissement", "ability": "Soul Drainer"}, {"lead": "Tu te transformes en nuée de corbeaux, invulnérable, et tu fonces dans la direction visée.", "items": ["Erreur classique : l'utiliser **pour engager**. Sans lui, tu es très vulnérable.", "Ne t'envole pas pour **planer au-dessus des boucliers** sans raison : tu deviens une cible facile.", "Il **esquive les ults** : Doctor Strange, Magneto, Storm, Winter Soldier…", "Il y a un **petit délai** avant la transformation : anticipe.", "Si tu en sors à bas PV, **ping-le** pour que tes supports le sachent."], "title": "Corbeau", "ability": "Astral Flock"}, {"lead": "Chaque kill fait apparaître un corbeau qui explose peu après. Hela peut aussi planer en l'air.", "items": ["Le corbeau **affaiblit les ennemis proches** : un headshot et un au corps suffisent ensuite.", "Combo : tue une cible, puis **attire la seconde dans l'explosion** avec ton étourdissement.", "Planer après un kill sur un angle permet d'**enchaîner**, mais attention aux autres tireurs."], "title": "Passifs", "ability": "Nastrond Crowstorm · Hel's Descent"}, {"key": "Q", "lead": "Tu t'envoles et tires des corbeaux explosifs. Tu vois les ennemis à travers les murs, et seul un gros burst te fait redescendre.", "items": ["Contre des brawlers (**Magik, Invisible Woman, The Thing**), envole-toi et lâche-toi : ils ne peuvent pas te descendre.", "Contre des tireurs, **élimine-les ou force-les** d'abord.", "Force les **ults de support et cooldowns défensifs** avant de lancer.", "Contre un **Doctor Strange**, abîme son bouclier avant : il viendra te bloquer.", "Lance-la **là où l'ennemi ne peut pas fuir** : sur le point ou en prolongation."], "title": "Ultime", "ability": "Goddess of Death"}, {"kind": "mistakes", "items": ["**S'acharner** après quelques tirs ratés.", "Utiliser le **corbeau pour engager**.", "Lancer l'étourdissement **n'importe comment** face à des divers.", "Ult **quand l'ennemi peut s'abriter**.", "Oublier l'**explosion du corbeau** après un kill."], "title": "Erreurs fréquentes"}], "synergies": [{"hero": "thor", "note": "Un tank qui te protège des divers."}, {"hero": "loki", "note": "Un support qui t'accompagne sur ton angle."}, {"hero": "namor", "note": "Ses tourelles repoussent les divers."}, {"hero": "mantis", "note": "Elle peut se battre sur l'angle avec toi."}, {"hero": "adam-warlock", "note": "Même chose, et ses dégâts suivent les tiens."}], "difficulty": 2, "patch_note": "Guide tiré d'une vidéo de Paz (padswagger), reformulé en français. Les chiffres du kit ont été retirés car ils changent à chaque saison ; team-ups et derniers changements sont à jour (saison 10.5) dans la section dédiée.", "kit": {"season": "Saison 10.5", "health": "", "abilities": [], "teamups": [{"name": "Hel-Yeah, Honey", "partners": ["deadpool"], "key": "", "text": "Deadpool débloque une amélioration en plus pour ses Desert Eagles et ses katanas."}, {"name": "Circle of Life", "partners": ["phoenix"], "key": "", "text": "Les tirs de Netherfire posent des étincelles et étourdissent. **Amélioré :** Plus d'étincelles."}, {"name": "Deep Wrath", "partners": ["namor"], "key": "", "text": "Les kills de Hela font apparaître des monstros morts-vivants. **Amélioré :** Ils apparaissent à chaque attaque."}, {"name": "Hel Tendrils", "partners": ["venom"], "key": "", "text": "Des tentacules attirent et ralentissent les ennemis. **Amélioré :** Les Nightsword Thorns soignent en plus."}, {"name": "Ragnarok Rebirth", "partners": ["thor"], "key": "", "text": "Une vie bonus empêche la mort et permet de revenir sur un kill. **Amélioré :** Résurrection instantanée."}, {"name": "Ragnarök", "partners": ["gorr-the-god-butcher"], "key": "", "text": "Coup de faux qui cloue les ennemis au sol. **Amélioré :** Plus de portée et vie bonus."}, {"name": "Villain's Illusion", "partners": ["loki"], "key": "", "text": "Prend la forme d'un héros tombé. **Amélioré :** Dure plus longtemps et empêche la mort."}], "changes": [], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · changements : patch notes des saisons 10 et 10.5", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'hela' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"tags": ["Dive", "Bulles", "Contrôle", "Exigeant"], "tldr": ["**Charge ton saut en permanence**, même en frappant : c'est ton outil principal.", "Utilise tes **bulles pour tes alliés**, pas seulement pour toi.", "Réfléchis à ton **exil** avant chaque fight : il doit sortir une ult adverse du jeu."], "combos": [{"note": "", "steps": [{"key": "Clic G", "label": "coup de poing"}, {"key": "", "label": "Clap"}], "title": "Finir une cible"}], "sources": [{"url": "https://www.youtube.com/watch?v=YZf3psRKPmE", "title": "Hulk Guide", "author": "Paz (padswagger)"}], "summary": "Hulk est l'un des tanks les plus exigeants : il brawle au front, dive sur les tireurs perchés et protège ses alliés avec des bulles au bon moment. Savoir quand engager légèrement et quand engager pour de vrai fait toute la différence.", "counters": [{"hero": "emma-frost", "note": "Elle charge sur toi : saute quand elle te cristallise."}, {"hero": "groot", "note": "Ses murs t'isolent : saute, casse-les."}, {"hero": "the-punisher", "note": "Il te farme de loin."}, {"hero": "squirrel-girl", "note": "Même chose avec ses dégâts de zone."}, {"hero": "iron-man", "note": "Il reste en l'air et te fait fondre."}, {"hero": "invisible-woman", "note": "Elle te ramène quand tu tentes de fuir."}], "sections": [{"kind": "tips", "lead": "Hulk s'adapte : brawl au front contre une compo serrée, dive sur les angles contre une compo à distance. La souplesse mentale est la clé.", "items": ["**Engage léger** : saute sur un angle sans investir ta bulle ni ton ult, attire l'attention, force leurs cooldowns (corbeau de Hela, clap de Luna), puis reviens.", "**Engage total** : une fois leurs cooldowns brûlés, reviens pour confirmer le pick ou prendre la position.", "Ne passe pas **trop de temps** sur une cible que tu ne peux pas tuer, mais **engage-toi à fond** quand le kill est possible.", "Après un pick, profite de l'avantage numérique pour aller sur la backline."], "title": "Philosophie de jeu", "diagram": "dive"}, {"key": "Clic G", "lead": "Des coups de poing à bonne portée et un clap qui envoie un projectile traversant.", "items": ["Le **clap** en début de fight charge ton ult et chasse une cible isolée de sa position.", "**Coup de poing puis clap** enchaînés pour finir une cible.", "Aligne le clap sur **plusieurs ennemis**, puis saute sur le retardataire.", "Clappe **pendant ton saut** pour frapper dès l'atterrissage."], "title": "Coups et clap", "ability": "Heavy Blow · Gamma Burst"}, {"lead": "Des bulles qui protègent tous les alliés proches quelques instants. Les dégâts absorbés sur ta propre bulle chargent ton ult.", "items": ["**Activer un allié** : saute sur ta Hela qui se fait flanquer et bulle-la.", "**Protéger un brawl** : bulle tout ton groupe quand il pousse.", "**Contrer une ult** : Doctor Strange, Magneto, Psylocke. Contre Iron Man, saute, bulle-toi et intercepte le projectile.", "Contre un **diver** sur ta backline, bulle tes supports puis saute sur lui.", "L'erreur : **ne bulle que toi** en permanence."], "title": "Bulles", "ability": "Indestructible Guard"}, {"lead": "Maintiens le saut pour le charger, puis relâche. Tu peux t'accrocher aux murs et attraper les volants.", "items": ["**Charge-le tout le temps**, même en frappant ou en bullant.", "Les contrôles (repoussement, étourdissement) **annulent la charge** : esquive les poussées d'Invisible Woman, les repoussements de Magneto.", "Toucher un **volant** (Star-Lord, Iron Man, Human Torch) l'attrape et le ramène au sol, ce qui gâche son ult.", "En **brawl miroir**, saute en l'air pour te faire soigner à l'abri.", "Contre une compo **à distance**, saute pour chasser les tireurs de leurs angles."], "title": "Saut prodigieux", "ability": "Incredible Leap"}, {"lead": "Un projectile lent qui sort une cible du jeu deux secondes : elle ne peut ni agir, ni prendre de dégâts, ni contester l'objectif.", "items": ["Il sert à **retirer une menace** : la Psylocke en ult que tes supports ne peuvent pas contrer, l'Iron Man qui vise ta Luna.", "Attention : une cible exilée **survit aux ults de ton équipe**. Seul Hulk peut la libérer en la frappant.", "Exile le **Doctor Strange qui revient du spawn** en portail.", "Ne le gâche pas pour un **clip spectaculaire** sur un volant."], "title": "Exil", "ability": "Radioactive Lockdown"}, {"key": "Q", "lead": "Tu deviens Monster Hulk avec énormément de vie, des coups qui repoussent, un clap très rapide et un exil rechargé plus vite. Tu perds tes bulles.", "items": ["**Jongle** : projette un ennemi en l'air, puis saute dessus pour l'étourdir. Plus facile contre un mur, et plus utile sur les tanks.", "**Coup, clap, coup** élimine vite un personnage fragile.", "World Breaker t'immobilise avec une cible : utilise-le pour **couper une ult** (un Loki en pleine copie).", "Ton ult sert à **prolonger un engage** ou à **tenir le point**. Fais contester un allié pendant ta transformation.", "Si tu meurs, tu redeviens **Bruce Banner** : tire et lance des grenades sur toi pour recharger vite ton ult."], "title": "Ultime", "ability": "Hulk Smash · World Breaker"}, {"kind": "mistakes", "items": ["**Ne pas charger** son saut entre deux actions.", "Se **bulle-r soi-même** systématiquement.", "Lancer l'exil **sans plan**, ou sauver un ennemi des ults alliées.", "Engager **à fond** quand l'ennemi a encore tous ses cooldowns.", "Rester **trop longtemps** sur une cible inaccessible."], "title": "Erreurs fréquentes"}], "synergies": [{"hero": "magneto", "note": "Un tank qui gère ce qui te contre."}, {"hero": "psylocke", "note": "Elle dive avec toi, puis brawle au centre."}, {"hero": "namor", "note": "Ses tourelles et tes bulles rendent le dive adverse très dur."}, {"hero": "wolverine", "note": "Tu peux le lancer pour qu'il attrape une cible."}, {"hero": "luna-snow", "note": "Elle te soutient pour aller plus loin."}], "difficulty": 3, "patch_note": "Guide tiré d'une vidéo de Paz (padswagger), reformulé en français. Les chiffres du kit ont été retirés car ils changent à chaque saison ; team-ups et derniers changements sont à jour (saison 10.5) dans la section dédiée.", "kit": {"season": "Saison 10.5", "health": "", "abilities": [], "teamups": [{"name": "Gamma Charge", "partners": ["iron-man"], "key": "", "text": "Gamma Overdrive avec un bouclier. **Amélioré :** Crée un canon à impulsion gamma."}, {"name": "Gamma Fastball", "partners": ["wolverine"], "key": "", "text": "État furieux et Scars of Rage (+25 % vitesse d'attaque et de déplacement en 10.5). **Amélioré :** Débloque le Fastball Special (Unstoppable : seuil 400, cooldown 45 s en 10.5)."}, {"name": "Gamma Maelstrom", "partners": ["doctor-strange"], "key": "", "text": "Le Maelstrom gamma accélère la charge (plus de perte de dégâts à distance depuis la saison 10). **Amélioré :** Garde et stocke l'énergie."}, {"name": "Gamma Monstro", "partners": ["namor"], "key": "", "text": "Un monstro gamma en plus (cooldown 25 s depuis la saison 10). **Amélioré :** Ajoute une barrière d'eau gamma."}, {"name": "Savage Slam", "partners": ["captain-america"], "key": "", "text": "Un saut écrasé réduit les cooldowns. **Amélioré :** Ajoute la vulnérabilité."}], "changes": [{"season": "Saison 10.5", "text": "Banner : Gamma Ray Gun plus rapide (80 → 120 m/s), Gamma Grenade rend 100 d'énergie gamma au lieu de 50."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · changements : patch notes des saisons 10 et 10.5", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'hulk' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"tags": ["Contrôle de zone", "Vol", "Dégâts sur la durée", "Combos d'ult"], "tldr": ["**Crée de la pression** avec tes zones de feu, ne cherche pas le kill tout de suite.", "Garde ton **fusil et ton plongeon** pour finir le fight, pas pour l'ouvrir.", "Prépare ton ult : **boules de feu déjà posées**, à couvert et dans la vue de tes supports."], "sources": [{"url": "https://www.youtube.com/watch?v=P9NvGuL_cho", "title": "Human Torch Guide", "author": "Paz (padswagger)"}, {"title": "Ultimate Human Torch Guide (Beginner/Advanced)", "author": "Tephra98", "url": "https://www.youtube.com/watch?v=p_2z3BujAyQ"}], "summary": "Human Torch n'est pas un chasseur de picks : c'est un contrôleur de zone volant. Il pose des boules de feu et des murs pour découper l'équipe adverse, empêcher les supports de soigner tranquillement, puis finit les cibles affaiblies au fusil.", "counters": [{"hero": "hulk", "note": "Il saute pour te ramener au sol."}, {"hero": "star-lord", "note": "Il te met la pression et t'empêche de t'installer."}, {"hero": "iron-man", "note": "Il te bat à distance. Ne le duel qu'à courte portée."}, {"hero": "magneto", "note": "Son ult avale tes tornades."}, {"hero": "ultron", "note": "Un duelliste à longue portée qui ne meurt jamais."}, {"hero": "luna-snow", "note": "Elle te met la pression en l'air et te gèle après ton dive."}], "sections": [{"kind": "tips", "lead": "Contrairement à Iron Man qui pèse par les dégâts bruts, Johnny dicte où l'ennemi peut ou ne peut pas jouer.", "items": ["Pose tes zones pour **séparer les ennemis** depuis le ciel, puis frappe les cibles affaiblies.", "Passe **de couvert en couvert** : en début de fight, diver sur les supports, c'est perdre.", "Avant de diver, garde **au moins une charge de fusil** et un peu de vol pour repartir.", "Avant ton ult ou ton plongeon, **jette un œil à tes supports** : sois dans leur ligne de vue.", "Vole **toujours près du décor** : à découvert, tes heals ne te voient pas et les hitscan te descendent.", "Joue à **moyenne portée** : loin pour poser ta prison, près pour tes rafales (fusil à pompe).", "Méthode en trois temps : **grande prison** depuis la hauteur ou un flank, repère la cible négligée par les heals, puis **double ou triple zone et plongeon**, et ressors.", "Tu as accès à tout le terrain : **punis celui qui est mal placé**, tank compris.", "Avec **Luna Snow** (flocon) ou **Invisible Woman** (bouclier), tu peux prendre beaucoup plus de risques."], "title": "Philosophie de jeu", "diagram": "highground"}, {"key": "Clic G", "lead": "Un fusil à projectiles qui ne se recharge pas : ses munitions reviennent toutes seules quand tu ne tires pas.", "items": ["Au-delà de la mi-distance, il **s'éparpille et perd des dégâts** : reste proche.", "Un **coup de mêlée** accélère la recharge des munitions : enchaîne tir et mêlée.", "C'est ton **outil de fin de fight** pour confirmer les kills.", "Alterne **rafales et boules de feu** : c'est ce qui garde tes munitions pleines tout en faisant le plus de dégâts.", "Contre les cibles rapides (Spider-Man, Storm), les **boules de feu** sont plus faciles à toucher."], "title": "Fusil de feu", "ability": "Fire Cluster"}, {"key": "Clic D", "lead": "Trois charges de boules de feu qui laissent une zone brûlante. C'est ton vrai outil de poke à distance.", "items": ["Utilise-les sur **les tanks et les supports** pour leur interdire des zones.", "Débusque les **supports cachés sous un toit** pour les forcer à découvert.", "Avant de diver sur un support : **une boule derrière lui, une sur lui**.", "**Jamais en duel contre un volant** : ton fusil fait bien mieux.", "Évite de les lancer en terrain ouvert, où l'ennemi n'a qu'à faire un pas de côté."], "title": "Boules de feu", "ability": "Blazing Blast"}, {"lead": "Relie au moins trois boules de feu au sol pour créer des murs de flammes qui enferment et brûlent les ennemis.", "items": ["Un rectangle visible de loin est **facile à éviter** : les bons joueurs partent avant.", "En défense ou après un fight gagné, **pose tes boules à l'avance** et active les murs quand l'ennemi arrive sur le point.", "Utilise aussi les murs pour **prolonger une bonne zone** dans un couloir, ou pour **couper les supports** l'un de l'autre.", "Teste en entraînement la **distance maximale** entre deux points.", "Les murs ne se relient que s'il n'y a **aucun obstacle** entre deux zones au moment où tu la lances (payload, mur de Groot, marche trop haute).", "Elle peut monter ou descendre **une petite marche** et relier des zones jusqu'à 40 m : tu peux enflammer un point entier.", "En attaque, enferme **le point** ; en défense, enferme **les chokes** par où ils arrivent."], "title": "Prison de flammes", "ability": "Pyro-Prison"}, {"lead": "Tu plonges au sol, repousses les ennemis et gagnes de la vie bonus. Sur une boule de feu, tu la fais exploser.", "items": ["Repousse les ennemis **dans une autre zone de feu** ou un tank **vers ton équipe**.", "Il peut **sortir Cloak & Dagger ou Invisible Woman de leur ult**.", "Pas besoin de boule de feu pour diver : supports, ne vous croyez pas à l'abri.", "Long cooldown : c'est une **action de fin de fight**, avec ton équipe prête à suivre.", "Il repousse les ennemis **dans la direction opposée** à ton arrivée : il peut sortir quelqu'un de la carte, ou **sauver un allié** pris par l'ult de Strange.", "Chaque zone de feu à proximité **explose** : deux zones + plongeon tuent un fragile, trois tuent même plus solide, y compris dans une ult de soin.", "Il **coupe aussi un engage** de Spider-Man sur toi."], "title": "Plongeon", "ability": "Flaming Meteor"}, {"key": "Maj", "lead": "Maintiens pour voler beaucoup plus vite, tant que ta jauge le permet.", "items": ["Ne tombe **jamais à sec** en terrain découvert.", "Avant ton ult, utilise-le pour **te placer** plutôt que de chercher ta position en pleine ult."], "title": "Vol rapide", "ability": "Plasma Body"}, {"key": "Q", "lead": "Une onde de choc autour de toi, puis tes boules de feu deviennent des tornades enflammées qui s'empilent. Tu encaisses moins de dégâts.", "items": ["Deux ou trois tornades au même endroit **traversent n'importe quelle ult de soin**.", "Avec une **ult de Groot**, lance la tienne un peu avant pour être prêt quand les ennemis sont regroupés.", "Astuce : lance une boule de feu **juste avant** l'ult, elle devient une tornade. Les boules déjà au sol ne se transforment pas.", "**Tire au fusil** entre deux tornades pour ajouter des dégâts.", "Place les tornades sur les **entrées du point** pour bloquer l'ennemi.", "Évite de plonger pendant l'ult : tu **repousses les ennemis hors de tes tornades**.", "Ordre conseillé : **prison, plongeon sur double zone, puis ult** pour finir les cibles affaiblies.", "Une boule de feu lancée juste avant l'ult **devient une tornade**."], "title": "Ultime", "ability": "Supernova"}, {"kind": "mistakes", "items": ["Diver sur les supports **en début de fight**.", "Lancer des boules de feu **en duel** contre un volant.", "Tomber **à court de vol** à découvert.", "Ult **hors de la vue** de ses supports, puis blâmer les soins.", "Prison en rectangle **trop visible**.", "Rester **en plein ciel à découvert**."], "title": "Erreurs fréquentes"}], "synergies": [{"hero": "groot", "note": "Le combo d'ult le plus satisfaisant du jeu."}, {"hero": "captain-america", "note": "Il repousse les ennemis dans tes zones."}, {"hero": "psylocke", "note": "Elle finit les cibles que tu as affaiblies."}, {"hero": "spider-man", "note": "Un diver qui suit tes zones."}, {"hero": "invisible-woman", "note": "Ses soins et ses outils t'aident à survivre en l'air."}, {"hero": "luna-snow", "note": "Le meilleur support pour te garder en vie."}], "difficulty": 2, "patch_note": "Guide tiré d'une vidéo de Paz (padswagger), reformulé en français. Les chiffres du kit ont été retirés car ils changent à chaque saison ; team-ups et derniers changements sont à jour (saison 10.5) dans la section dédiée.", "kit": {"season": "Saison 10.5", "health": "", "abilities": [], "teamups": [{"name": "Fiery Sparks", "partners": ["jubilee"], "key": "", "text": "Étincelles de feu d'artifice à tête chercheuse. **Amélioré :** Vie bonus à l'atterrissage."}, {"name": "Storming Ignition", "partners": ["storm"], "key": "", "text": "Un vortex de feu attire les ennemis. **Amélioré :** Allume des ouragans enflammés."}, {"name": "Two-in-One", "partners": ["the-thing"], "key": "", "text": "Poings enflammés (cooldown 18 s, 8 s de durée depuis la saison 10). **Amélioré :** Soulève et écrase avec étourdissement."}, {"name": "United Siblings", "partners": ["invisible-woman"], "key": "", "text": "Bouclier de flammes avec une aura de soin. **Amélioré :** Plus grand, bouclier renforcé."}], "changes": [], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · changements : patch notes des saisons 10 et 10.5", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'human-torch' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"tags": ["Brawl", "Déplacement d'ennemis", "Bouclier", "Charge d'ult"], "tldr": ["**Aligne un maximum de cibles** avec tes orbes : chaque tir charge énormément ton ult.", "Ta **poussée-attraction** est ce qui te fait porter les parties : un pick ou un sauvetage à chaque utilisation.", "Ton ult ne bouge pas : place-la **sur le point**, de préférence en seconde ult."], "sources": [{"url": "https://www.youtube.com/watch?v=mRt2zFGqrws", "title": "Invisible Woman Guide", "author": "Paz (padswagger)"}], "summary": "Invisible Woman brille dans les compos groupées : elle aligne alliés et ennemis pour charger son ult très vite, attire les cibles importantes dans la portée de son équipe et protège les menaces clés avec son bouclier personnel.", "counters": [{"hero": "spider-man", "note": "Les compos éclatées de dive te privent de valeur."}, {"hero": "venom", "note": "Même problème, il dive sur toi."}, {"hero": "iron-man", "note": "Il te surclasse à distance, hors d'atteinte."}, {"hero": "hela", "note": "Elle te gagne à distance si tu ne peux pas l'attirer."}, {"hero": "hawkeye", "note": "Même chose, et il peut te tuer dans ton ult."}], "sections": [{"kind": "tips", "lead": "Tu n'as pas les dégâts pour tuer seule : ton rôle est d'amener les bonnes cibles devant ton équipe et de charger ton ult au plus vite.", "items": ["Elle est forte quand **tout le monde joue groupé**, faible contre les compos éclatées sur plusieurs angles.", "Si ton équipe joue **dive**, préfère Luna ou Cloak & Dagger.", "Joue **près de ton autre support** pour pouvoir être aidée, et garde ton saut pour les urgences."], "title": "Philosophie de jeu", "diagram": "peel"}, {"key": "Clic G", "lead": "Des orbes qui partent en ligne droite puis reviennent comme un boomerang. Ils touchent alliés et ennemis à l'aller et au retour.", "items": ["Aligne **un maximum d'alliés et d'ennemis** : c'est ta meilleure source de charge d'ult.", "Vise **le sol au niveau de la dernière cible** pour déclencher le retour plus tôt.", "Reste **un peu en retrait** : le retour touche plus facilement."], "title": "Orbes"}, {"key": "Clic D", "lead": "Un petit bouclier personnel posé sur un allié, qui le soigne aussi. C'est un sauve-qui-peut ciblé, pas un mur.", "items": ["Bloque le **burst** qui va tuer : ult de Magneto ou de Doctor Strange, dagues de Hela, flèches de Hawkeye. Pas les dégâts continus d'un Punisher.", "**Rends un DPS invincible** sur son angle : un Star-Lord ou Punisher en ult, un Hela repéré.", "Il **ralentit** l'ennemi qui le traverse.", "**Rappelle-le avec F** avant qu'il casse : il revient bien plus vite.", "Avec un autre support en difficulté, pose-le sur ton équipe en marchant pour avoir **couvert et soins** pour toi aussi."], "title": "Bouclier gardien", "ability": "Guardian Shield"}, {"key": "E · Clic G / Clic D", "lead": "Tu repousses ou attires les ennemis dans la zone visée. Maîtriser cette capacité, c'est maîtriser Invisible Woman.", "items": ["**Attire** un DPS perché ou un tank trop avancé dans ton équipe : pick gratuit.", "**Repousse** un diver (Spider-Man, Magik, Black Panther, Iron Fist), mais seulement **quand il n'a plus de mobilité**.", "Sur certaines cartes, la poussée **éjecte** les ennemis du terrain.", "Garde la poussée quand le **Doctor Strange adverse a son ult** : tu l'envoies hors de portée.", "Le meilleur contre à **Wolverine** : attire-le hors de son agrippement.", "Ne ramène pas un ennemi **dans ton équipe blessée**, et ne sauve pas une cible qui allait mourir."], "title": "Poussée et attraction", "ability": "Force Physics"}, {"key": "Maj", "lead": "Une boule qui crée une zone de ralentissement et d'attraction. Réappuie pour la faire éclater où tu veux.", "items": ["En **brawl contre brawl**, mets-la sur les tanks quand ils poussent.", "Elle peut **piéger un DPS** sur son angle pour ton DPS.", "Contre un diver, pose-la **à tes pieds**, saute, puis pousse-le dedans.", "Elle n'éclate pas sur le bouclier de Magneto : **déclenche-la toi-même**."], "title": "Vortex", "ability": "Psionic Vortex"}, {"lead": "Sans agir ni prendre de dégâts, tu deviens invisible et te soignes. Le double saut te rend invisible immédiatement.", "items": ["Le saut est un **outil de survie**, pas de déplacement.", "Dive sur toi ? **Saute**. Ult de Magneto ? **Saute**, puis protège ton autre support.", "Tes **pas sont bruyants** même invisible."], "title": "Saut et invisibilité", "ability": "Veiled Step · Covert Advance"}, {"key": "Q", "lead": "Une zone fixe qui soigne et rend invisibles tes alliés à l'intérieur. Les ennemis qui entrent ou sortent sont fortement ralentis.", "items": ["Place-la **sur le point** : l'ennemi doit se battre ou abandonner l'objectif.", "Coupe l'équipe adverse **en deux** pour que leurs supports ne voient plus leurs tanks.", "Elle ne bouge pas : ne l'utilise **pas pour engager**, sers-t'en plutôt en **seconde ult**.", "Si tu meurs, elle disparaît : **reste en vie** face aux ults de Magneto, Punisher ou un Hawkeye."], "title": "Ultime", "ability": "Invisible Boundary"}, {"kind": "mistakes", "items": ["Tirer sans **aligner les cibles**.", "Laisser casser le bouclier au lieu de le **rappeler**.", "Repousser un diver **pendant son déplacement**.", "Utiliser le saut **pour se déplacer**.", "Lancer l'ult **loin du point**."], "title": "Erreurs fréquentes"}], "synergies": [{"hero": "the-thing", "note": "Tu attires les cibles dans sa portée."}, {"hero": "doctor-strange", "note": "Un tank de brawl derrière lequel tu brilles."}, {"hero": "groot", "note": "Attire une cible, il l'isole avec un mur."}, {"hero": "winter-soldier", "note": "Un DPS qui veut le contact."}, {"hero": "magik", "note": "Même logique de brawl rapproché."}, {"hero": "wolverine", "note": "Tu lui amènes ses cibles."}, {"hero": "human-torch", "note": "Tu l'aides à survivre pendant ses dives."}], "difficulty": 2, "patch_note": "Guide tiré d'une vidéo de Paz (padswagger), reformulé en français. Les chiffres du kit ont été retirés car ils changent à chaque saison ; team-ups et derniers changements sont à jour (saison 10.5) dans la section dédiée.", "kit": {"season": "Saison 10.5", "health": "", "abilities": [], "teamups": [{"name": "First Family", "partners": ["mister-fantastic"], "key": "", "text": "Invisibilité avec soin et vitesse. **Amélioré :** Version renforcée."}, {"name": "Psionic Vortex", "partners": ["doctor-strange"], "key": "", "text": "Projette les ennemis et renforce le bouclier. **Amélioré :** Vie bonus selon les dégâts."}, {"name": "Unbreakable Forces", "partners": ["the-thing"], "key": "", "text": "Armure psionique qui donne de la vie bonus (cooldown 15 s en 10.5). **Amélioré :** Impulsions de soin de zone (seuil de 125 dégâts en 10.5)."}, {"name": "United Siblings", "partners": ["human-torch"], "key": "", "text": "Bouclier de flammes avec une aura de soin. **Amélioré :** Plus grand, bouclier renforcé."}], "changes": [{"season": "Saison 10", "text": "Retour de l'orbe : 45 → 40 de soin ; l'invisibilité tient 1 s après avoir pris des dégâts."}, {"season": "Saison 10", "text": "Tous les Strategists : l'ult se charge un peu moins vite (65 % du soin et 50 % des dégâts convertis en énergie, au lieu de 70 % et 55 %)."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · changements : patch notes des saisons 10 et 10.5", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'invisible-woman' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"tags": ["Mêlée", "Parade", "Anti-volant", "Anti-tank"], "tldr": ["**Harcèle, pare, puis frappe** : ta parade débloque tes vrais dégâts.", "Les coups renforcés font **plus mal aux tanks** : excellent pour charger ton ult.", "Garde de la **hauteur** avec murs et triple saut pour repérer la cible isolée."], "sources": [{"url": "https://www.youtube.com/watch?v=xfZl57O8_OQ", "title": "Iron Fist Guide", "author": "Paz (padswagger)"}], "summary": "Iron Fist est un combattant de mêlée polyvalent, capable de diver comme de brawler. Il harcèle avec ses coups de base pour forcer les contrôles adverses, pare, puis déchaîne des coups renforcés qui font fondre les tanks.", "counters": [{"hero": "magneto", "note": "Sa bulle protège la cible que tu engages."}, {"hero": "emma-frost", "note": "En forme de diamant, elle te sort de ton combo."}, {"hero": "peni-parker", "note": "Ses nids et toiles gênent tes dives."}, {"hero": "namor", "note": "Tu ne verrouilles pas ses tourelles."}, {"hero": "winter-soldier", "note": "Un matchup très difficile."}, {"hero": "adam-warlock", "note": "Son lien rend ton burst inutile."}], "sections": [{"kind": "tips", "lead": "Iron Fist ressemble à Daredevil : il dive ou brawle selon les besoins. Dans le doute, médite, force des cooldowns, pare, puis brawle avec ton équipe.", "items": ["Sois **patient** : la parade est ta ressource, tu vis et meurs avec elle.", "Dans un fight serré à 6 contre 6, **force d'abord leurs contrôles** avec les coups de base, puis riposte.", "Avec un pick d'avance, tu peux **parer tout de suite** et faire boule de neige.", "Astuce : pare, **ressors avec ta vie bonus**, puis reviens sur un support quand l'équipe adverse se disperse."], "title": "Philosophie de jeu", "diagram": "reset"}, {"lead": "Trois sauts consécutifs et la course sur les murs. Iron Fist peut presque voler.", "items": ["Les sauts ne se rechargent qu'**en touchant une surface** : enchaîne sauts et course sur les murs pour rester en hauteur.", "Garde **une vue d'ensemble** pour repérer le support isolé.", "Les sauts **esquivent** les dégâts de zone (Iron Man) et l'ult de The Thing."], "title": "Mobilité", "ability": "Crane Leap · Wall Runner"}, {"key": "Clic G", "lead": "Une série de six coups dont le dernier projette en l'air. Ils te propulsent vers une cible proche et réduisent le cooldown de ta parade.", "items": ["Leur rôle : **harceler** et forcer les contrôles (boule de neige de Luna…), pas tuer.", "Le dernier coup **fait tomber les volants** : prépare-le sur un mur, puis garde-le pour une cible en l'air.", "Frapper l'air **ralentit ta chute**.", "Le verrouillage fonctionne même **sans visibilité**, mais pas à travers les boucliers."], "title": "Coups de base"}, {"key": "Clic D", "lead": "Tu bloques tout pendant un instant et convertis les dégâts en vie bonus. Ensuite, tu gagnes des coups très rapides qui infligent des dégâts en pourcentage de la vie.", "items": ["La parade bloque **tout** : boules de neige, capacités de Magneto ou Iron Man, ult de Jeff.", "Les coups renforcés font **plus de dégâts aux tanks**, mais restent très forts sur les fragiles.", "**Suis ta cible** avec tes déplacements, sinon tu te détaches et perds des coups.", "Force d'abord la **fuite d'un tank** (le saut de Strange, le balancement de Venom), puis pare et frappe.", "Contre Iron Fist : **ne tire pas sur lui pendant sa parade**."], "title": "Parade et coups renforcés", "ability": "Dragon's Defense"}, {"key": "Maj", "lead": "Un coup de pied tournoyant qui te propulse en avant. Le second impact fait double dégâts sur une cible à moins de la moitié de sa vie.", "items": ["Excellent **outil pour finir** : anticipe si le premier impact fera passer la cible sous la moitié.", "Sert aussi à **rejoindre un volant** ou à fuir.", "Il **s'arrête au contact** : pour fuir, éloigne-toi des ennemis.", "Utilise **un saut avant** pour aller plus loin."], "title": "Coup de pied"}, {"lead": "Tu te soignes rapidement et gagnes de la vie bonus, mais tu es immobile et bruyant.", "items": ["Médite **avant le fight**, à couvert ou au-dessus d'un passage.", "Cycle : **dive, force des cooldowns, ressors, médite, recommence**.", "Tu flottes en méditant : tu peux t'installer dans des **positions inattendues**."], "title": "Méditation", "ability": "Harmony Recovery"}, {"key": "Q", "lead": "Bonus de dégâts et de vitesse, portée doublée, coups renforcés permanents et parade presque toujours disponible.", "items": ["Plus besoin de parer pour frapper fort : la parade sert à **bloquer et te soigner**.", "Tu deviens la priorité adverse : **pare au bon moment**.", "Utilise-la pour **forcer les ults de support**, puis recharge la suivante.", "Elle se charge vite en frappant les tanks.", "Après ton premier pick, **respire** : n'en fais pas trop."], "title": "Ultime", "ability": "Living Chi"}, {"kind": "mistakes", "items": ["Parer **dès le début** contre une équipe qui garde ses contrôles.", "Mal **suivre sa cible** et perdre ses coups renforcés.", "Méditer **à découvert**.", "Gâcher le **coup de pied** alors qu'il fallait fuir.", "Rester trop longtemps après son pick."], "title": "Erreurs fréquentes"}], "synergies": [{"hero": "luna-snow", "note": "Le support idéal, qui se débrouille seule."}, {"hero": "venom", "note": "En dive, vous éliminez vite les supports."}, {"hero": "captain-america", "note": "Même logique de dive."}, {"hero": "psylocke", "note": "Pression combinée sur la backline."}, {"hero": "cloak-and-dagger", "note": "Autre support autonome qui te laisse un slot DPS."}], "difficulty": 3, "patch_note": "Guide tiré d'une vidéo de Paz (padswagger), reformulé en français. Les chiffres du kit ont été retirés car ils changent à chaque saison ; team-ups et derniers changements sont à jour (saison 10.5) dans la section dédiée.", "kit": {"season": "Saison 10.5", "health": "", "abilities": [], "teamups": [{"name": "Comprehensive Defense", "partners": ["daredevil"], "key": "", "text": "Objection! touche tous les ennemis et renvoie les projectiles. **Amélioré :** Ajoute un soin passif."}, {"name": "Iron & Stone", "partners": ["the-thing"], "key": "", "text": "Uppercut qui projette en l'air puis coup de pied (fonctionne même sans The Thing, cooldown 12 s depuis la saison 10). **Amélioré :** Enchaînements et dégâts en plus."}, {"name": "Kumiho Palm", "partners": ["white-fox"], "key": "", "text": "Yat Jee Chung Kuen soigne les alliés. **Amélioré :** Portée de verrouillage augmentée."}], "changes": [{"season": "Saison 10", "text": "Jeet Kune Do 35 → 38 par coup (cinquième coup 55 → 60), ult moins chère (3400 → 3100)."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · changements : patch notes des saisons 10 et 10.5", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'iron-fist' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"tags": ["Vol", "Charge d'ult", "Anti-ult", "Poke"], "tldr": ["Sur un **groupe**, tire aux répulseurs ; sur une **cible isolée**, passe au rayon.", "Active la **surcharge derrière un mur**, jamais à découvert.", "Ton ult sert à **punir une ult de support** : place-toi à l'abri avant de tirer."], "sources": [{"url": "https://www.youtube.com/watch?v=3hV4kz3Repc", "title": "Iron Man Guide", "author": "Paz (padswagger)"}, {"title": "The Best Iron Man Guide (Season 2.5)", "author": "Kingsman", "url": "https://www.youtube.com/watch?v=Rg-etuOgUNY"}], "summary": "Iron Man n'est pas un DPS classique : son ult se charge très vite et peut annuler les ults adverses. Il poke les groupes avec ses répulseurs pour charger, puis passe en surcharge pour faire fondre une cible isolée avec son rayon.", "counters": [{"hero": "hela", "note": "Elle te descend du ciel. Joue à couvert."}, {"hero": "hawkeye", "note": "Même chose, et il peut couper ton rayon."}, {"hero": "spider-man", "note": "Il te rejoint partout dans les airs."}, {"hero": "star-lord", "note": "Pousse-le à trop te poursuivre."}, {"hero": "psylocke", "note": "Même idée : fais-la sortir de position."}, {"hero": "magneto", "note": "Son ult avale ton canon."}, {"hero": "adam-warlock", "note": "Ses tirs instantanés te punissent en l'air."}, {"hero": "the-punisher", "note": "Il te tire dessus en continu dès que tu sors du décor."}], "sections": [{"kind": "tips", "lead": "Iron Man demande de la patience : il charge son ult à toute vitesse et attend le moment précis où elle change le fight.", "items": ["Garde ton **temps de tir au maximum** : il y a presque toujours quelqu'un à toucher.", "Reste à **bonne distance**, environ à la portée maximale du rayon : la cible est plus facile à suivre.", "Évite de **flanquer en volant** : c'est la capacité la plus bruyante du jeu.", "Sur les tanks soutenus par deux heals, tu nourris surtout **l'ult adverse**.", "Ne reste pas **perché à 200 m** : redescends devant tes heals pour être soigné, et tourne autour d'eux pour rester dur à toucher.", "Joue près des **piliers et du décor** : contre des hitscan (Hela, The Punisher), c'est ce qui te garde en vie. Si tu peux, bannis-les.", "Avec **Ultron** (drone sur toi, team-up commun), vous pouvez rester en l'air presque indéfiniment."], "title": "Philosophie de jeu", "diagram": "highground"}, {"key": "Clic G", "lead": "Des projectiles explosifs en série de trois. Une bonne partie des dégâts vient de l'explosion.", "items": ["Vise **les pieds** en duel : même raté, tu infliges des dégâts de zone.", "Ils servent surtout à **charger ton ult** sur des ennemis groupés.", "Tire dans une **ult de support** adverse pour charger la tienne et la contrer ensuite.", "Le troisième tir part **plus vite** : ajuste ta visée.", "Les explosions servent **contre les groupes** et les cibles juste sous toi : vise le sol sous ta cible.", "Le rayon (Uni-Beam en tir) fait plus de dégâts **sur une seule cible** et consomme moins de munitions."], "title": "Répulseurs", "ability": "Repulsor Blast"}, {"key": "Clic D", "lead": "Un rayon instantané qui partage les munitions de tes répulseurs. C'est ton vrai outil pour éliminer une cible.", "items": ["**Recharge avant** d'aller chercher une cible : garde de la marge de munitions.", "Sa portée **dépasse celle d'Emma Frost**.", "Poke aux répulseurs, puis **finis au rayon**."], "title": "Uni-Beam"}, {"key": "E", "lead": "Après une courte animation, tes attaques sont renforcées, tes munitions illimitées, et tu gagnes de la vie bonus.", "items": ["**Toujours derrière un mur** : l'animation te rend vulnérable.", "Elle **ne recharge pas** ton arme à la fin : prévois un endroit sûr pour recharger.", "Avant de l'activer, demande-toi si tu peux **vraiment mettre la pression** sur une cible sans te faire punir.", "Les **micro-missiles** en surcharge sont un bonus de dégâts, pas une priorité.", "Elle ne **recharge pas** tes munitions à la fin, et la sortie te rend vulnérable : mets-toi **derrière un mur** juste avant qu'elle se termine."], "title": "Surcharge", "ability": "Armor Overdrive"}, {"key": "Maj", "lead": "Un vol très rapide qui consomme de l'énergie. La surcharge te la remplit.", "items": ["Sert à **rejoindre un angle** pour passer en surcharge, ou à **fuir** une menace.", "Utilise-le pour te **placer en sécurité** avant ton ult.", "Le vol rapide est **très bruyant** : l'ennemi t'entend arriver de loin."], "title": "Vol rapide", "ability": "Hyper-Velocity"}, {"key": "Q", "lead": "Un gros projectile lent qui explose et élimine presque tout dans sa zone. Une des ults les plus rapides à charger.", "items": ["Tu seras visé : demande un **bouclier d'Emma** ou une **bulle de Magneto**, ou force d'abord les menaces (fais fuir la Hela).", "Ne vole pas en flank pour ult **tout de suite** : attends quelques secondes qu'on t'oublie.", "Cible prioritaire : **les ults de support**, surtout celle de Luna. Ne sois pas trop loin, sinon ils fuient.", "Même sans kill, elle **force des cooldowns** (runes, bulles, murs) qui gagnent le fight.", "Un **Magneto** en ult peut l'absorber : force la sienne avant.", "Le centre de l'explosion **tue presque tout**, même à travers les ults de soin ; le bord fait beaucoup moins : tire **au sol** près de la cible.", "Tu restes **immobile 1 à 2 secondes** : fais sortir la bulle ou l'ult de Magneto avant, sinon il absorbe ton ult.", "Avec une bulle, un bouclier d'Invisible Woman ou un Magneto qui te protège, c'est presque un **fight gagné**.", "Anticipe **où le support va fuir** (Cloak & Dagger qui dash vers sa bulle de Magneto) et vise ailleurs si besoin."], "title": "Ultime", "ability": "Invincible Pulse Cannon"}, {"kind": "mistakes", "items": ["Activer la surcharge **à découvert**.", "Viser au rayon un **tank soutenu** par deux heals.", "Partir au rayon **sans munitions**.", "Ult **juste après un vol bruyant** en flank.", "Garder l'ult trop longtemps alors qu'elle revient vite."], "title": "Erreurs fréquentes"}], "synergies": [{"hero": "ultron", "note": "Un autre volant qui te soigne en l'air."}, {"hero": "magneto", "note": "Sa bulle te protège pendant ton ult."}, {"hero": "emma-frost", "note": "Son bouclier te couvre pendant ton ult."}, {"hero": "hela", "note": "Elle gère les tireurs qui te visent."}, {"hero": "psylocke", "note": "Elle s'occupe de Hela et Hawkeye."}, {"hero": "invisible-woman", "note": "Son bouclier sécurise ton ult."}], "difficulty": 2, "patch_note": "Guide tiré d'une vidéo de Paz (padswagger), reformulé en français. Les chiffres du kit ont été retirés car ils changent à chaque saison ; team-ups et derniers changements sont à jour (saison 10.5) dans la section dédiée.", "kit": {"season": "Saison 10.5", "health": "", "abilities": [], "teamups": [{"name": "Gamma Charge", "partners": ["hulk"], "key": "", "text": "Gamma Overdrive avec un bouclier. **Amélioré :** Crée un canon à impulsion gamma."}, {"name": "Squirrel Missile", "partners": ["squirrel-girl"], "key": "", "text": "Un missile-écureuil à tête chercheuse. **Amélioré :** En tire un avec Squirrel Blockade."}, {"name": "Stark Protocol", "partners": ["ultron"], "key": "", "text": "Nano-rayon qui soigne et blesse. **Amélioré :** Tire des missiles à tête chercheuse."}, {"name": "Thunder Overdrive", "partners": ["thor"], "key": "", "text": "Armor Overdrive gagne en dégâts (anneau de l'Unibeam à 80/s en 10.5). **Amélioré :** Anneau à 90/s en 10.5."}], "changes": [{"season": "Saison 10.5", "text": "Micro-Missile Barrage : les missiles suivent les ennemis proches (5 max par cible), 60 m/s au lieu de 15, mais 10 de dégâts par missile au lieu de 20 (15 en Armor Overdrive)."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · changements : patch notes des saisons 10 et 10.5", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'iron-man' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"tags": ["Flanc", "Pression", "Mobilité", "Ult de pick"], "tldr": ["Prends un **angle de flank** et vise les **supports et DPS**, jamais les tanks.", "**Gère tes bulles** : garde-en toujours une ou deux pour fuir.", "Une ult qui retire **un ou deux ennemis clés** suffit largement."], "combos": [{"note": "", "steps": [{"key": "E", "label": "bulle"}, {"key": "", "label": "Passe dedans"}, {"key": "Maj", "label": "plonge"}], "title": "Filer à ton angle"}], "sources": [{"url": "https://www.youtube.com/watch?v=bEtshLmrVyw", "title": "Jeff the Land Shark Guide", "author": "Paz (padswagger)"}], "summary": "Jeff se joue comme un flanker qui met la pression sur la backline adverse : il attire l'attention loin de son équipe, survit grâce à la nage et à ses bulles, et peut retirer des ennemis du terrain avec son ult. Le jouer en simple heal, c'est le jouer mal.", "counters": [{"hero": "captain-america", "note": "Il te suit partout et annule ton flank."}, {"hero": "star-lord", "note": "Mobile, il vide son chargeur sur ta grosse hitbox."}, {"hero": "iron-man", "note": "Ses dégâts de zone te touchent toujours."}, {"hero": "loki", "note": "Ses projectiles explosifs et ses runes te compliquent la vie."}, {"hero": "magneto", "note": "Son ult te punit pendant la tienne."}], "sections": [{"kind": "tips", "lead": "Ton vrai soin, c'est d'attirer les dégâts et l'attention sur toi plutôt que sur ton équipe. Ça ne se voit pas au tableau des scores, mais ça se voit au résultat.", "items": ["Nage jusqu'à un **angle décalé**, mets la pression sur la backline, puis repars quand ils réagissent.", "Avant de partir, **laisse deux ou trois bulles** à ton autre support.", "Casse les **objets adverses** (tourelles, amplificateurs) depuis ton flank.", "Ne sois pas **trop gourmand** : reste sur des positions difficiles d'accès.", "En **triple support**, tu peux te concentrer encore plus sur les dégâts."], "title": "Philosophie de jeu", "diagram": "pocket"}, {"key": "Clic G · Clic D", "lead": "Un jet d'eau qui soigne et traverse les alliés, et des projectiles d'eau qui explosent à l'impact.", "items": ["Le jet est un projectile : **anticipe un peu** et soigne avant les dégâts.", "Reviens soigner quand **un allié lance son ult** ou quand ta Luna, presque prête, se fait dive.", "Vise **les pieds** avec les projectiles : l'explosion compense un tir raté.", "Contre un volant, vise **le mur derrière lui**. Sinon, change de cible.", "Ne tire **jamais sur les tanks** : tu ne fais que les énerver."], "title": "Soin et dégâts", "ability": "Joyful Splash · Aqua Burst"}, {"key": "Maj", "lead": "Sous terre, tu vas plus vite, tu te soignes, tu ne peux pas être touché à la tête et tu peux nager sur les murs.", "items": ["Combo de base : **pose une bulle, passe dedans, plonge** pour filer à ton angle.", "Tu peux **attendre sur un mur** et surprendre un ennemi qui passe.", "Option : passe la nage murale en mode **appui simple** dans les paramètres si c'est plus confortable.", "Sous terre, tu **ne contestes pas** l'objectif."], "title": "Nage", "ability": "Hide and Seek"}, {"key": "E", "lead": "Des bulles posées au sol qui soignent, accélèrent et boostent les soins reçus. Elles restent longtemps en place.", "items": ["Ne les **empile pas** : l'accélération ne se cumule pas.", "Avec une bonne gestion des bulles, **un bon Jeff ne meurt presque jamais**.", "Avant un fight, trace un **chemin de bulles** vers le bord de la carte pour sortir les ennemis avec ton ult.", "Pense à **ton hitbox** : un mouvement en huit rend Jeff très dur à toucher."], "title": "Bulles", "ability": "Healing Bubble"}, {"key": "Q", "lead": "Tu plonges et avales tous les ennemis (et alliés) dans la zone, puis tu les recraches, idéalement hors de la carte.", "items": ["Les héros mobiles (**Invisible Woman, Doctor Strange, Wolverine, Psylocke**) peuvent revenir si tu les recraches mal : vise un angle franc.", "Attention à **ne pas sortir tes alliés** de la carte ou du point en prolongation.", "Un **Magneto** garde souvent son ult pour toi : force-la ou attends qu'elle soit utilisée.", "Lance-la **quand les supports adverses lancent leur ult** : tu en attraperas souvent un.", "En défense : **avale ton équipe** juste avant un combo d'ults adverse pour l'esquiver."], "title": "Ultime", "ability": "It's Jeff!"}, {"kind": "mistakes", "items": ["Rester derrière à **ne faire que soigner**.", "Tirer **sur les tanks**.", "Gaspiller toutes ses bulles et **ne plus pouvoir fuir**.", "Avaler **ses alliés** et les sortir du point.", "Ult **dans un Magneto** qui garde la sienne."], "title": "Erreurs fréquentes"}], "synergies": [{"hero": "captain-america", "note": "Ensemble vous fermez le cercle derrière l'ennemi."}, {"hero": "venom", "note": "Autre tank de dive qui suit ta pression."}, {"hero": "human-torch", "note": "Il bloque les supports, toi tu les empêches de fuir."}, {"hero": "black-panther", "note": "Un diver qui finit les cibles que tu harcèles."}, {"hero": "luna-snow", "note": "Elle soigne l'équipe pendant que tu flanques."}], "difficulty": 2, "patch_note": "Guide tiré d'une vidéo de Paz enregistrée en saison 2 : le kit de Jeff a été retouché depuis et ses team-ups ont changé. On a gardé le plan de jeu et retiré les chiffres, les team-ups et les astuces de carte périmées. Vérifie en jeu.", "kit": {"season": "Saison 10.5", "health": "", "abilities": [], "teamups": [{"name": "Bubble Buddies", "partners": ["groot"], "key": "", "text": "Une bulle-bouclier rend invincible et soigne. **Amélioré :** Ajoute de la vie bonus."}, {"name": "Guardian of the Deep", "partners": ["venom"], "key": "", "text": "Tentacules de soin qui donnent de la vie bonus. **Amélioré :** Ajoute des coups de fouet qui blessent."}, {"name": "Jaws of Fate", "partners": ["storm"], "key": "", "text": "Averse qui soigne. **Amélioré :** Jeff peut nager dans une tornade (Jeff-nado)."}, {"name": "Mr. Pool's Interdimensional Toy Box", "partners": ["deadpool"], "key": "", "text": "Une peluche provoque les ennemis et soigne. **Amélioré :** Provocation et dégâts renforcés."}, {"name": "Surf & Turf", "partners": ["devil-dinosaur"], "key": "", "text": "Jet d'eau qui blesse et soigne. **Amélioré :** Jeff chevauche Devil Dinosaur, et les deux se soignent."}], "changes": [{"season": "Saison 10", "text": "Joyful Splash 130/s → 140/s de soin, Aqua Burst 25 → 30 de dégâts, zone de soin de l'ult 100/s → 130/s."}, {"season": "Saison 10", "text": "Tous les Strategists : l'ult se charge un peu moins vite (65 % du soin et 50 % des dégâts convertis en énergie, au lieu de 70 % et 55 %)."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · changements : patch notes des saisons 10 et 10.5", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'jeff-the-land-shark' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"tags": ["Soins", "Charge d'ult", "Anti-ult", "Polyvalente"], "tldr": ["Ta mission : **rester en vie et charger ton ult** plus vite que l'autre Luna.", "Glisse des **dégâts entre les fights** : casse les objets adverses, finis les cibles basses.", "Fais **tourner ta marque** sur l'allié qui va en avoir besoin."], "sources": [{"url": "https://www.youtube.com/watch?v=jzICK22y7Is", "title": "Luna Snow Guide", "author": "Paz (padswagger)"}, {"title": "Ultimate Luna Snow Guide (Beginner/Advanced)", "author": "Tephra98", "url": "https://www.youtube.com/watch?v=MbmlCd9u18M"}], "summary": "Luna Snow est facile à prendre en main, mais ce qui distingue une vraie joueuse de Luna, c'est la vitesse à laquelle elle charge son ult et sa capacité à rester en vie. Son ult rend l'équipe presque immortelle pendant de longues secondes.", "counters": [{"hero": "hela", "note": "Elle te punit si tu es mal placée."}, {"hero": "star-lord", "note": "Il vole, esquive ta boule et force tes cooldowns."}, {"hero": "black-panther", "note": "Il dive après ta boule ratée."}, {"hero": "magik", "note": "Même logique de dive."}, {"hero": "doctor-strange", "note": "Son bouclier peut bloquer tes soins d'ult."}], "sections": [{"kind": "tips", "lead": "Soigner ne suffit pas : les vraies Luna glissent des dégâts utiles et chargent leur ult à une vitesse folle.", "items": ["Entre deux fights, **poke l'ennemi** pour charger ton ult, mais sans t'exposer à un Hawkeye.", "Ne poke **plus une fois l'ult prête** : tu ne fais que charger celle des supports adverses.", "Tu as souvent la meilleure vue : **casse les ankhs de Moon Knight, les tourelles de Namor**.", "**Finis les cibles** que ton DPS a laissées à un fil, et repousse les flankers avant qu'ils engagent.", "Entraîne ta visée en **suivi de cible** (tracking).", "Luna est une **strategist, pas une heal bot** : poke les flyers et les flankers, enlever de la pression à ton équipe vaut parfois plus qu'une barre de vie pleine.", "Ses capacités **te soignent** (passif) : en duel, utilise-les au lieu de spammer ton tir."], "title": "Philosophie de jeu", "diagram": "heal"}, {"key": "Clic G", "lead": "Des rafales instantanées qui soignent les alliés et blessent les ennemis. La perte de dégâts à distance ne touche pas les soins.", "items": ["Soigner de loin n'est pas un problème : **reste en retrait** si besoin.", "Pour tuer un fragile, il faut **viser la tête**.", "C'est un **hitscan** : vise directement, et vise la tête en dégâts (les soins n'ont ni headshot ni perte à distance).", "En patinant, dirige-toi **avec la caméra** pour garder la vitesse ; sauter ne la coupe pas."], "title": "Tir principal"}, {"key": "Maj", "lead": "Pendant quelques secondes, tu lances des stalactites qui traversent alliés et ennemis, soignant les uns et blessant les autres. Tu te soignes aussi un peu.", "items": ["Aligne **un maximum de cibles** : c'est ta meilleure source de charge d'ult.", "Ne l'utilise pas **trop tôt** (personne n'en a besoin) ni **trop tard** (ton équipe meurt pendant l'animation).", "Moment idéal : tes tanks à **mi-vie**, ou ton équipe qui **engage**.", "Contre le dive, il peut **protéger ton autre support** tout en blessant le diver.", "Lance-le **au moment de recharger** : tu continues à soigner sans temps mort."], "title": "Clap", "ability": "Ice Arts"}, {"lead": "Un projectile qui gèle la cible quelques secondes. Tu peux tirer une rafale juste après sans la dégeler.", "items": ["Elle **coupe les ults à incantation** (Doctor Strange, Storm).", "Contre un diver, lance-la **juste avant qu'il fonce sur toi** en ligne droite.", "Elle peut aussi **créer un pick** : un Punisher en train de faire fondre tes tanks, gelé.", "Si un diver peut te sauter dessus après, **garde-la**.", "Beaucoup de Luna **l'oublient** : regarde le tableau des scores pour savoir sur qui la garder.", "Contre une compo **dive** (Spider-Man, Magik, Venom), garde-la pour **le diver qui te saute dessus** : gel, puis rafale à la tête.", "Elle **coupe certaines ults** en incantation, surtout celle de Doctor Strange : suis qui a son ult.", "Gèle un **tank à bouclier** en le contournant : il lâche son bouclier et prend tout."], "title": "Boule de neige", "ability": "Absolute Zero"}, {"lead": "Une marque sur un allié qui augmente tes soins sur lui et le soigne quand tu soignes quelqu'un d'autre.", "items": ["Ne la laisse pas simplement sur ton DPS de flank : **fais-la tourner**.", "Pose-la sur l'allié **qui s'apprête à agir** : ton Hulk qui saute sur un angle, puis ton DPS qui s'active.", "Sur un **tank agressif** (Hulk, The Thing, Captain America, Venom), elle charge beaucoup ton ult.", "Si ton DPS part loin tôt dans le fight, **marque-le avant**.", "Garde-la **toujours sur quelqu'un** : un flanker, un off-angle (Hela), un flyer, ou le tank qui part loin (Venom).", "Sur quelqu'un qui prend énormément, **pose la marque avant de le soigner** : il cumule les deux."], "title": "Marque", "ability": "Share the Stage"}, {"key": "Q", "lead": "Une grosse zone de soin qui dure longtemps. Réappuie pour passer en aura de bonus de dégâts.", "items": ["**Annonce-le** en vocal : on perd facilement le compte de sa durée.", "Passe en **bonus de dégâts** pour une ult alliée clé (Venom, Namor) ou pour tuer vite une cible. Pendant ce temps, tu ne soignes plus.", "Tu **n'es pas invincible** : flèche de Hawkeye, ult de Magneto, ult de Punisher boostée peuvent te tuer.", "Les **boucliers et le décor** bloquent tes soins.", "Vérifie que ton ult est **vraiment nécessaire** : un bouclier de Strange ou des clones de Loki peuvent suffire.", "Ne l'utilise pas **pour engager** pendant que l'équipe marche : attends qu'elle soit en position.", "Règle perso de Paz : vers **100 PV avec l'ult prête**, lance-la.", "On ne peut pas te **stun** pendant l'ult, mais on peut t'enraciner : **continue de bouger**.", "Ce n'est **pas une invulnérabilité** : elle ne sauve pas d'une ult d'Iron Man ou de Scarlet Witch, mais tient contre beaucoup d'autres.", "Mets le **changement de mode sur la molette** pour alterner soin et bonus de dégâts très vite."], "title": "Ultime", "ability": "Fate of Both Worlds"}, {"kind": "mistakes", "items": ["Ne faire **que soigner** et charger son ult trop lentement.", "Oublier la **boule de neige**.", "Laisser la marque **sur le même allié** toute la partie.", "**Mourir avec l'ult** prête.", "Rester trop longtemps en **bonus de dégâts**."], "title": "Erreurs fréquentes"}], "synergies": [{"hero": "loki", "note": "Il copie ton ult : de très longues secondes d'immortalité."}, {"hero": "namor", "note": "Ton bonus de dégâts rend son ult mortelle."}, {"hero": "venom", "note": "Même effet avec son ult."}, {"hero": "jeff-the-land-shark", "note": "Il flanque pendant que tu tiens l'équipe."}, {"hero": "iron-fist", "note": "Un diver que tes soins suivent facilement."}], "difficulty": 1, "patch_note": "Guide tiré d'une vidéo de Paz (padswagger), reformulé en français. Les chiffres du kit ont été retirés car ils changent à chaque saison ; team-ups et derniers changements sont à jour (saison 10.5) dans la section dédiée.", "kit": {"season": "Saison 10.5", "health": "", "abilities": [], "teamups": [{"name": "Atlas Bond", "partners": ["white-fox"], "key": "", "text": "Un renard spirituel charme les ennemis et soigne les alliés. **Amélioré :** Le renard revient tout seul."}, {"name": "Chilling Charisma", "partners": ["namor"], "key": "", "text": "Frost Tide ralentit les ennemis. **Amélioré :** Une charge en plus et un impact au bout de la course."}, {"name": "Duality Dance", "partners": ["adam-warlock"], "key": "", "text": "Soul Bond relie et soigne. **Amélioré :** Les critiques réduisent les cooldowns."}, {"name": "Frozen Haven", "partners": ["cloak-and-dagger"], "key": "", "text": "L'état gelé émet une aura de soin (bouclier de 2 s depuis la saison 10). **Amélioré :** Aura renforcée."}, {"name": "Iced Out Diamond", "partners": ["emma-frost"], "key": "", "text": "Projectile de glace et barrière de diamant. **Amélioré :** Ajoute des ralentissements."}], "changes": [{"season": "Saison 10", "text": "Cryo Heart : auto-soin 30/s → 35/s."}, {"season": "Saison 10", "text": "Tous les Strategists : l'ult se charge un peu moins vite (65 % du soin et 50 % des dégâts convertis en énergie, au lieu de 70 % et 55 %)."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · changements : patch notes des saisons 10 et 10.5", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'luna-snow' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"tags": ["Mêlée", "Combos", "Dive", "Vie bonus"], "tldr": ["**Ne fonce pas** : attends que ton équipe puisse suivre avant de dasher.", "Apprends **un combo à la fois** en entraînement, puis enchaîne-les.", "Tes **portails sont ta survie** : garde-en toujours un pour sortir."], "combos": [{"note": "Ne dash **jamais avant** le projectile.", "steps": [{"key": "Clic D", "label": "projectile chargé"}, {"key": "E", "label": "dash"}, {"key": "Clic G", "label": "épée"}], "title": "Simple"}, {"note": "Plus imprévisible, et esquive une boule de neige.", "steps": [{"key": "Clic D", "label": "projectile"}, {"key": "", "label": "Portail"}, {"key": "E", "label": "dash"}, {"key": "Clic G", "label": "épée"}], "title": "Avec portail"}, {"note": "", "steps": [{"key": "", "label": "Portail"}, {"key": "", "label": "Tourbillon"}, {"key": "E", "label": "dash"}, {"key": "Clic G", "label": "épée"}, {"key": "Mêlée", "label": ""}, {"key": "Clic D", "label": "projectile"}], "title": "Élimination"}], "sources": [{"url": "https://www.youtube.com/watch?v=4vilAy9tSwY", "title": "Magik Guide", "author": "Paz (padswagger)"}, {"title": "The Ultimate Magik Guide (From the #1 Magik)", "author": "Kingsman", "url": "https://www.youtube.com/watch?v=WPe_Fce3k8w"}, {"title": "How to Dominate Top 500 as Magik", "author": "Kingsman", "url": "https://www.youtube.com/watch?v=uy-heXjN8nA"}, {"title": "The Ultimate Magik Game Sense Guide", "author": "Kingsman", "url": "https://www.youtube.com/watch?v=2jwUDTGkzyY"}, {"title": "The Best Magik Guide for Season 10", "author": "Kingsman", "url": "https://www.youtube.com/watch?v=8ipk_Ggdj3I"}, {"title": "I VOD Reviewed Your Magik Games", "author": "Kingsman", "url": "https://www.youtube.com/watch?v=JVK6xsG4vAY"}], "summary": "Magik est une combattante de mêlée à combos, capable de diver sur une cible isolée comme de brawler au centre. Ses portails la rendent intouchable, sa vie bonus la garde en vie, et son ult la transforme en version surpuissante d'elle-même.", "counters": [{"hero": "emma-frost", "note": "En diamant, elle bloque tes entrées et sorties."}, {"hero": "peni-parker", "note": "Tu n'as pas de moyen fiable de détruire ses nids."}, {"hero": "the-thing", "note": "Son impact au sol coupe tes combos."}, {"hero": "human-torch", "note": "Un volant rapide, dur à combo."}, {"hero": "namor", "note": "Ses tourelles t'usent avant que tu engages."}, {"hero": "winter-soldier", "note": "Avec son dash, ne t'approche pas."}, {"hero": "loki", "note": "Ses runes : force-les avant ton combo."}, {"hero": "ultron", "note": "Son drone casse tes seuils de kill."}], "sections": [{"kind": "tips", "lead": "Selon ta compo, tu isoles une cible avec une bulle de ton Magneto, ou tu brawles au centre avec tes tanks.", "items": ["En **dive**, commence sur ton angle, combo une cible, puis **reviens vers ton équipe** récupérer tes cooldowns.", "En **brawl**, ton projectile traversant charge vite ton ult et réduit le cooldown de tes portails.", "Les Magik **patientes** tuent plus en faisant moins.", "Magik **teste l'ennemi** : s'il change de compo juste pour te contrer, tes alliés respirent.", "Magik est la meilleure **brawleuse** des DPS : frapper pendant une ult de soin adverse recharge ton ult très vite, alors que leurs heals ne gagnent rien.", "Joue en **corner defender** : coin de la backline adverse, coin du brawl, jamais en frontline pure sur les tanks.", "Sur ton angle, reste **dans la ligne de vue de ton heal** : tu gagneras presque tous les 1v1.", "Annonce ton engage **juste avant** (« 3, 2, 1 ») : pendant que leurs heals te regardent, ton équipe collapse.", "Une mort qui force une **ult de soin** ou un gros cooldown n'est pas une erreur : c'est un échange gagnant.", "Ne laisse **personne te prendre ta hauteur** gratuitement : dash dessus dès que ton cooldown le permet, au lieu d'attendre en main.", "Quand le payload avance, **prépare ta position** à l'avance (high ground, coin) pour reprendre le fight au bon endroit."], "title": "Philosophie de jeu", "diagram": "reset"}, {"key": "Clic G · Clic D", "lead": "Des coups d'épée lents mais puissants, et un projectile chargé qui traverse les ennemis.", "items": ["L'épée perd des dégâts **en bout de portée** : frappe de près.", "Glisse un **coup de mêlée** après chaque coup d'épée.", "Chaque ennemi touché par le projectile **réduit le cooldown** de tes portails.", "Le projectile est **gros** : il se fait bloquer par les boucliers et le décor. Anticipe un peu à distance.", "Astuce : chargé mais pas tiré, il **reste disponible** après un portail.", "L'épée perd jusqu'aux **deux tiers** de ses dégâts à distance : il faut environ 4 coups de près contre 8 de loin.", "En brawl contre un groupe, **spamme l'épée sans mêlée** : tu touches plus de monde, donc plus de bouclier et d'ult. La mêlée après chaque coup, c'est pour le 1v1.", "La mêlée a **moins de portée** que l'épée : si la cible est un peu loin, elle rate et te fait perdre du temps."], "title": "Épée et projectile", "ability": "Soul Sword · Magik Slash"}, {"lead": "Deux charges de portail. Tu es invulnérable pendant le passage, et chaque portail débloque soit un tourbillon, soit un démon.", "items": ["Le **tourbillon** (Eldritch Whirl) fait des dégâts autour de toi : idéal en début de combo ou en brawl.", "Le **démon** (clic droit après un portail) frappe devant lui et empêche les ennemis de te poursuivre. Excellent contre la **tourelle du Punisher**.", "Ne gâche pas les deux charges **pour te rapprocher** : marche ou dash pour entrer, portail pour prolonger ou sortir.", "Le portail te donne un **petit gain de hauteur** : il permet d'atteindre certains high grounds sans utiliser ton dash.", "Pas besoin de poser le démon tout de suite : tu as quelques secondes pour **passer derrière les supports** et le placer là où ils devront reculer.", "Tu n'es invulnérable qu'**une fois dans le portail**, pas pendant que tu y entres.", "Après un engage raté, **portal en arrière pour garder l'espace**, pas vers ton équipe : à haut niveau, revenir dans les tiens se fait punir.", "En sortie de portail, **le démon vaut presque toujours mieux que le tourbillon** : plus de bouclier, plus de dégâts sur une cible qui ne peut pas reculer."], "title": "Portails", "ability": "Stepping Discs"}, {"key": "E", "lead": "Un dash rapide qui projette la cible et toi en l'air. C'est ton ouvreur de combo.", "items": ["Vise **à droite** de ta cible pour le rendre plus fiable.", "**Trop tôt**, ton équipe ne suit pas. **Trop tard**, elle a déjà perdu le 5 contre 6.", "Tu peux dasher **pendant le tourbillon** pour frapper tout le monde en chemin."], "title": "Dash", "ability": "Umbral Incursion"}, {"kind": "tips", "lead": "Du plus simple au plus fort. Apprends-les un par un, puis choisis selon la distance et la cible.", "items": ["**Simple** : projectile chargé, dash, coup d'épée. Évident, mais force les cooldowns. Ne dash jamais avant le projectile.", "**Avec portail** : projectile, portail, dash, épée. Plus imprévisible, et esquive une boule de neige.", "**Discret** : dash, épée, projectile non chargé, épée, coup de mêlée.", "**Au contact** : épée, mêlée, projectile, épée, puis dash pour finir.", "**Élimination** : portail, tourbillon, dash, épée, mêlée, projectile.", "**Tuer un support dans son ult** : projectile chargé et dash qui touchent **en même temps**. La fenêtre est minuscule : demande à ton équipe de focus la même cible, ou pose un démon dessus pour l'agrandir.", "Le combo **tourbillon puis dash** est le moins rentable : garde-le pour une cible sans défense (Hela sans corbeau, Loki sans soin).", "**Ouvre avec le projectile chargé, puis le portail** : chaque ennemi touché réduit le cooldown des portails avant même d'entrer.", "Mets la **mêlée sur un bouton latéral de souris** pour l'enchaîner sans lâcher tes déplacements."], "title": "Combos"}, {"key": "Q", "lead": "Tu deviens Darkchild : toutes tes capacités font beaucoup plus mal, tes portails reviennent bien plus vite et tes capacités sont réinitialisées à la sortie.", "items": ["Spamme le **tourbillon** : énormes dégâts de zone.", "Combo : **portail, tourbillon, dash**, plus un coup d'épée si besoin.", "**Projectile chargé puis dash** élimine un fragile, même à travers une ult de soin avec un bonus de dégâts.", "Tu restes **fragile** et deviens la cible prioritaire : n'en fais pas trop.", "Son vrai rôle : **forcer l'ult de soin adverse**. Tu la récupères vite en brawl, et l'équipe qui gagne le cycle d'ults gagne le fight suivant.", "Dans l'ult, le dash se lance **même à la dernière seconde** : un dernier uppercut peut finir une cible.", "Démon pour **zoner** un passage, tourbillon pour les **dégâts de zone**."], "title": "Ultime", "ability": "Darkchild"}, {"title": "Team-up avec The Hood", "ability": "Void Pentagram", "lead": "Chaque portail fait apparaître un démon en plus du tien : c'est l'un des meilleurs outils de zone du jeu quand il est bien placé (cooldown de 20 s depuis la saison 10).", "items": ["Place-le **entre le support et le tank** adverses : ils doivent avancer dans ton équipe ou reculer dans les démons.", "Trois ou quatre démons sur un passage **bloquent la lane**, même pendant une ult de soin.", "La position du team-up compte **plus que la tienne** : pense zone avant de penser kill.", "Débutant sur Magik ? **Apprends-la d'abord sans** ce team-up : il ne remplace pas les combos."], "kind": "default"}, {"kind": "mistakes", "items": ["Dasher **avant** le projectile chargé.", "Brûler ses **deux portails** pour entrer.", "Oublier le **démon**.", "Engager **avant que l'équipe suive**.", "Diver **jusque dans le spawn** adverse.", "Jouer en **frontline pure** sur les tanks au lieu des coins.", "Mettre une mêlée après chaque coup **contre un groupe**.", "Lancer l'ult **avant que ton équipe soit là** (un 1v6 pour l'espace)."], "title": "Erreurs fréquentes"}], "synergies": [{"hero": "doctor-strange", "note": "Un tank polyvalent qui suit ta flexibilité."}, {"hero": "magneto", "note": "Sa bulle te laisse confirmer ton kill."}, {"hero": "hela", "note": "Elle gère les menaces que tu ne peux pas atteindre."}, {"hero": "phoenix", "note": "Même rôle de soutien à distance."}, {"hero": "psylocke", "note": "Pression combinée sur la backline."}, {"hero": "luna-snow", "note": "Son bonus de dégâts rend tes combos mortels."}], "difficulty": 3, "patch_note": "Guide tiré des vidéos de Paz et de Kingsman (jusqu'à la saison 10). En saison 10 : démon du Limbo moins solide et team-up avec The Hood à 20 s de cooldown. Vérifie les chiffres en jeu.", "kit": {"season": "Saison 10.5", "health": "", "abilities": [], "teamups": [{"name": "Chain of Cyttorak", "partners": ["doctor-strange"], "key": "", "text": "Une chaîne relie deux ennemis. **Amélioré :** Relie des groupes entiers."}, {"name": "Dimensional Shortcut", "partners": ["black-panther"], "key": "", "text": "Un disque de Limbo ramène Black Panther à sa position précédente. **Amélioré :** Retour déclenchable à la main."}, {"name": "Void Pentagram", "partners": ["the-hood"], "key": "", "text": "Les Stepping Discs rendent de l'énergie et invoquent des démons du Limbo (cooldown 20 s depuis la saison 10). **Amélioré :** Démons plus solides, plus de portée."}], "changes": [{"season": "Saison 10", "text": "Démon du Limbo : bonus de vie 100 → 25."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · changements : patch notes des saisons 10 et 10.5", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'magik' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"tags": ["Bulles", "Bouclier", "Anti-ult", "Flexible"], "tldr": ["**Ouvre le tableau des scores** entre chaque fight : c'est à toi de savoir qui bulle-r.", "Contre des divers, ta bulle va **sur tes supports**. Sinon, **sur toi** pour plus de dégâts.", "Ton ult vise en priorité **les ults de support** adverses."], "combos": [{"note": "Mets la mêlée sur un bouton de souris.", "steps": [{"key": "Clic G", "label": "tir"}, {"key": "Mêlée", "label": ""}, {"key": "Clic D", "label": "canon"}, {"key": "Mêlée", "label": ""}], "title": "Combo rapide"}], "sources": [{"url": "https://www.youtube.com/watch?v=7qG9KH9UkNc", "title": "Magneto Guide", "author": "Paz (padswagger)"}], "summary": "Magneto est probablement le tank le plus flexible du jeu : contre le dive, il protège sa backline avec ses bulles ; contre le brawl, il se bulle lui-même pour frapper fort. Son ult, l'une des plus décisives du jeu, sert surtout à punir les ults de support.", "counters": [{"hero": "emma-frost", "note": "Bloque ses cristaux, sinon elle te roule dessus."}, {"hero": "groot", "note": "Ses murs te coupent de ton équipe."}, {"hero": "loki", "note": "Ses runes annulent ton ult."}, {"hero": "adam-warlock", "note": "Son lien d'âmes annule ton ult."}], "sections": [{"kind": "tips", "lead": "Magneto s'adapte à tout, mais il faut savoir ce que les deux équipes jouent pour bien utiliser son kit.", "items": ["Joue **à couvert** pour économiser ton bouclier.", "Poker au centre pour **charger ton ult** est souvent plus utile que chercher un kill.", "Ne compte pas sur tes supports pour **demander une bulle** : en ranked, c'est à toi de surveiller les divers."], "title": "Philosophie de jeu", "diagram": "space"}, {"key": "Clic G · Clic D", "lead": "Un projectile qui explose à l'impact, et un canon qui se charge par paliers. Au dernier palier, il repousse fortement.", "items": ["Combo rapide : **tir, coup de mêlée, canon, coup de mêlée**. Mets la mêlée sur un bouton de souris.", "De loin, l'explosion est **plus large**, mais pas plus forte.", "Évite le canon au **premier palier**, trop faible.", "Le repoussement envoie un tank **dans son équipe** pour toucher plus d'ennemis, ou chasse un diver (Spider-Man, Iron Fist, **Wolverine**) de ta backline."], "title": "Tir et canon", "ability": "Iron Volley · Mag-Cannon"}, {"key": "E · F", "lead": "E bulle un allié, F te bulle toi-même. Les deux partagent le même cooldown. Une bulle cassée remplit d'un coup ton canon.", "items": ["**Règle 1** : contre des divers (Black Panther, Psylocke, Iron Fist, Spider-Man), garde la bulle pour **ta backline**.", "**Règle 2** : sinon, **bulle-toi** pour frapper plus fort et avancer.", "**Règle 3** : garde-la pour **les ults**, celles qui menacent tes supports (Magneto, Iron Man, Winter Soldier) comme celles de tes alliés (Iron Man, Punisher en ult).", "Tire au canon **pendant la bulle** : si elle casse, tu en as un autre prêt."], "title": "Bulles", "ability": "Metallic Chaos"}, {"key": "Maj", "lead": "Un bouclier à énergie qui ne tient qu'un instant mais avale tout ce qui le touche, y compris des capacités et des ults.", "items": ["Il sert à bloquer un **gros burst** ou une **capacité précise** : dagues de Hela, vortex d'Invisible Woman, étourdissements.", "Face à une **ult de Punisher**, il le rend inoffensif le temps que ton équipe le tue.", "Il avale les ults d'**Iron Man** et des autres **Magneto**.", "Ce n'est pas un bouclier pour avancer longtemps : **anticipe** ce que tu veux bloquer."], "title": "Rideau magnétique", "ability": "Magnetic Curtain"}, {"key": "Q", "lead": "Tu flottes et absorbes les projectiles ennemis autour de toi pendant quelques secondes, puis tu lances un météore dévastateur.", "items": ["Cible prioritaire : **les supports en ult**. Les éliminer suffit à porter les parties.", "Méfie-toi des **runes de Loki** et des **bulles de Magneto** adverses : force-les avant.", "Contre une **ult de Luna**, fais d'abord tomber son bouclier.", "Il **contre** les ults de Star-Lord, Punisher, Iron Man ou Ultron, mais parfois ton bouclier suffit et tu gardes l'ult pour plus tard.", "Les **rayons** passent à travers l'absorption.", "Contre Cloak & Dagger en ult, n'attends pas le dernier dash : **lance au troisième**."], "title": "Ultime", "ability": "Meteor M"}, {"kind": "mistakes", "items": ["Ne **jamais regarder** la compo adverse.", "Se bulle-r alors qu'un **diver** est sur ses supports.", "Tirer le canon **au premier palier**.", "Gâcher son ult sur une ult **déjà contrée** par autre chose.", "Lancer son ult dans des **runes** ou une **bulle**."], "title": "Erreurs fréquentes"}], "synergies": [{"hero": "emma-frost", "note": "Le duo de tanks idéal."}, {"hero": "magik", "note": "Ta bulle lui permet de confirmer ses kills."}, {"hero": "star-lord", "note": "Bulle-le pour qu'il tourne au milieu de l'ennemi."}, {"hero": "the-punisher", "note": "Protège-le pendant son ult."}, {"hero": "luna-snow", "note": "La meilleure paire de supports derrière toi."}, {"hero": "loki", "note": "Même chose."}], "difficulty": 2, "patch_note": "Guide tiré d'une vidéo de Paz (padswagger), reformulé en français. Les chiffres du kit ont été retirés car ils changent à chaque saison ; team-ups et derniers changements sont à jour (saison 10.5) dans la section dédiée.", "kit": {"season": "Saison 10.5", "health": "", "abilities": [], "teamups": [{"name": "Explosive Entanglement", "partners": ["rogue"], "key": "", "text": "Un champ magnétique renforce la posture défensive de Rogue. **Amélioré :** Ajoute un recul et des dégâts aux murs."}, {"name": "Favorable Odds", "partners": ["gambit"], "key": "", "text": "Cartes magnétiques qui soignent et projettent (une seule fois, à l'explosion, depuis la saison 10). **Amélioré :** Explosion finale en plus."}, {"name": "Magnetic Resonance", "partners": ["emma-frost"], "key": "", "text": "Une projection imite Magneto (50 % des dégâts, 6 s en 10.5). **Amélioré :** Beaucoup plus de vie, la projection dure."}, {"name": "Metallic Chaos", "partners": ["scarlet-witch"], "key": "", "text": "Coup d'épée du chaos (cooldown 18 s depuis la saison 10). **Amélioré :** Le Mag-Cannon devient des épées chargées."}], "changes": [{"season": "Saison 10", "text": "Vie de base 650 → 600, bouclier 250 → 200, tir du Mag-Cannon 20 → 10."}, {"season": "Saison 10.5", "text": "Team-up avec Emma Frost : la projection fait 50 % des dégâts et dure 6 s."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · changements : patch notes des saisons 10 et 10.5", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'magneto' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"tags": ["Dégâts", "Bonus de dégâts", "Sommeil", "Angles"], "tldr": ["**Tire à la tête** : chaque tir réussi recharge une feuille.", "Garde le **bonus de dégâts actif** sur tes DPS qui s'engagent, puis sur toi.", "Lance ton ult **en premier** pour pousser, pas pour contrer."], "sources": [{"url": "https://www.youtube.com/watch?v=Fifg2W8-PO4", "title": "Mantis Guide", "author": "Paz (padswagger)"}], "summary": "Mantis est une DPS déguisée en support : ses headshots rechargent ses feuilles, qui servent à soigner ou à donner un bonus de dégâts. Elle porte en trouvant des kills et en gardant son bonus de dégâts actif en permanence sur les bonnes cibles.", "counters": [{"hero": "black-panther", "note": "Avec un tank qui dive aussi, ton sommeil ne suffit plus."}, {"hero": "venom", "note": "Même problème quand ils arrivent à deux."}, {"hero": "the-thing", "note": "Les compos de brawl collé te privent d'angles."}, {"hero": "magik", "note": "Même chose en double support."}], "sections": [{"kind": "tips", "lead": "Faire des dégâts, c'est soigner : un ennemi éliminé ne blesse plus personne. Si tu ne fais que soigner, prends un autre support.", "items": ["Prends des **angles** et mets la pression : ton efficacité dépend de tes headshots.", "Les headshots **sur les tanks** comptentnt aussi : de quoi recharger tes feuilles.", "**Gère tes ressources** : surveille en bas à droite qui a déjà tes soins et ton bonus.", "Elle brille en **triple support**, où elle joue presque comme un DPS."], "title": "Philosophie de jeu", "diagram": "pocket"}, {"key": "Clic G", "lead": "Des projectiles rapides : deux headshots et un au corps éliminent un personnage fragile.", "items": ["Les tirs partent de ton personnage, pas de ton viseur : **de près, vise au-dessus à droite** de la tête.", "Ce sont des projectiles : **anticipe un peu** à distance plutôt que de te rapprocher.", "Entraîne la visée **par clics** (statique et dynamique)."], "title": "Tirs"}, {"key": "Clic D", "lead": "Un soin immédiat suivi d'un soin sur la durée. Il ne soigne pas beaucoup, mais il continue même hors de vue.", "items": ["Donne-le à un **flanker qui va quitter ta vue** pour un duel, avec un bonus de dégâts.", "Priorité : **ton autre support**, puis tes DPS. Les tanks seulement si tu as des ressources en trop.", "Attends qu'un allié ait **perdu une partie de sa vie** pour ne pas gâcher la feuille.", "Astuce : baisse la **sensibilité de visée** des soins dans les paramètres si tu rates tes cibles."], "title": "Fleur de soin", "ability": "Healing Flower"}, {"key": "E", "lead": "Un bonus de dégâts pour un allié (ou pour toi) qui dure longtemps. Il s'applique au moment du tir, pas à l'impact.", "items": ["C'est **la capacité la plus importante** : garde-le actif le plus possible.", "Booste les DPS **qui s'engagent** : un Star-Lord en duel, un Punisher qui arrose, une Storm.", "Il **accélère aussi la charge d'ult** : utile pour qu'un allié obtienne la sienne à temps.", "Booste **avant** l'ult d'un Namor, pas après.", "Ne relance pas sur un allié **déjà boosté** : attends la dernière seconde.", "Sur toi, il permet d'**éliminer une Luna** avec ton combo et te soigne un peu."], "title": "Bonus de dégâts", "ability": "Allied Inspiration · Natural Anger"}, {"lead": "Une bombe qui endort l'ennemi le plus proche de l'impact. Il se réveille s'il est touché.", "items": ["Contre des flankers (**Star-Lord, Psylocke, Black Panther, Spider-Man**), garde-le pour toi.", "Il **coupe les ults** à incantation : Doctor Strange, Scarlet Witch, Storm.", "Cible endormie : **maintiens le tir** pour placer deux projectiles d'un coup. Booste-toi avant.", "Toucher l'**illusion violette** derrière la cible la réveille aussi."], "title": "Sommeil", "ability": "Spore Slumber"}, {"key": "Q", "lead": "Une zone qui soigne, donne de la vie bonus au-delà du maximum et accélère ton équipe.", "items": ["Utilise-la **pour pousser**, idéalement en première ult, puis laisse l'autre support contrer.", "Si tu es le **seul** support avec ult, garde-la pour ton équipe.", "Ne laisse pas ton équipe derrière : **avance avec elle**.", "Pendant l'ult, **ne soigne plus** : booste toute ton équipe et élimine l'ennemi.", "Les **boucliers** et le décor bloquent tes soins."], "title": "Ultime", "ability": "Soul Resurgence"}, {"kind": "mistakes", "items": ["Jouer Mantis **en simple soigneuse**.", "Relancer un bonus de dégâts **déjà actif**.", "Utiliser le sommeil **trop tôt** face à un flanker.", "Soigner **pendant sa propre ult**.", "Courir trop vite et **laisser son équipe** derrière."], "title": "Erreurs fréquentes"}], "synergies": [{"hero": "black-widow", "note": "Ton bonus rend ses headshots mortels."}, {"hero": "star-lord", "note": "Ton bonus rend son ult bien plus meurtrière."}, {"hero": "venom", "note": "Un tank de dive qui profite de ton bonus."}, {"hero": "captain-america", "note": "Même logique."}, {"hero": "psylocke", "note": "Une héroïne de dive facile à soigner et à booster."}, {"hero": "luna-snow", "note": "Elle soigne assez pour te laisser faire des dégâts."}], "difficulty": 2, "patch_note": "Guide tiré d'une vidéo de Paz (padswagger), reformulé en français. Les chiffres du kit ont été retirés car ils changent à chaque saison ; team-ups et derniers changements sont à jour (saison 10.5) dans la section dédiée.", "kit": {"season": "Saison 10.5", "health": "", "abilities": [], "teamups": [{"name": "Spirit Breaker", "partners": ["emma-frost"], "key": "", "text": "Les dégâts de Sentience deviennent de la vie bonus. **Amélioré :** Vie bonus ponctuelle et cooldown de Psychic Spear réduit."}, {"name": "Star Blossom", "partners": ["star-lord"], "key": "", "text": "Relancer la fleur de soin propage le soin (10 + 3 %/s depuis la saison 10). **Amélioré :** Déclenchement immédiat."}, {"name": "Vibrant Vitality", "partners": ["loki"], "key": "", "text": "Domaine de régénération qui renforce les alliés. **Amélioré :** Onde de choc qui projette en blessant."}, {"name": "Vitality Pact", "partners": ["adam-warlock"], "key": "", "text": "L'état d'âme soigne et reforge (fleur à 12 + 3 %/s depuis la saison 10). **Amélioré :** Soul Bond avec soin sur la durée."}, {"name": "Wild Wall", "partners": ["groot"], "key": "", "text": "Le Wild Wall soigne et donne de la vie bonus. **Amélioré :** Le mur évolue après avoir soigné."}], "changes": [{"season": "Saison 10", "text": "Life Orb se charge en 4 s au lieu de 3 s, soin de zone en forme d'âme 5/s → 30/s, fleur renforcée 15 + 3,5 % → 10 + 3,5 %."}, {"season": "Saison 10", "text": "Tous les Strategists : l'ult se charge un peu moins vite (65 % du soin et 50 % des dégâts convertis en énergie, au lieu de 70 % et 55 %)."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · changements : patch notes des saisons 10 et 10.5", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'mantis' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"tags": ["Brawl", "Peel", "Contrôle", "Hybride"], "tldr": ["Contre le **dive**, utilise tes capacités pour protéger tes supports : ça charge aussi ta forme gonflée.", "Contre un **brawl**, synchronise ta forme gonflée avec une ult alliée.", "Reste **à portée de poing**, pas collé à l'ennemi : ton allonge est ton avantage."], "sources": [{"url": "https://www.youtube.com/watch?v=V4DFywKwdFk", "title": "Mister Fantastic Guide", "author": "Paz (padswagger)"}, {"title": "This Guide Is Fantastic!", "author": "Kingsman", "url": "https://www.youtube.com/watch?v=ZwH1aVlfGyw"}], "summary": "Mister Fantastic est un brawler hybride, entre DPS et tank : il protège sa backline des divers, puis gonfle pour écraser le front adverse. Tout l'art consiste à savoir quand avancer, quand protéger, et quand gonfler.", "counters": [{"hero": "emma-frost", "note": "Elle charge son rayon sur toi."}, {"hero": "groot", "note": "Son grand mur te bloque."}, {"hero": "the-punisher", "note": "Il te fait fondre à distance."}, {"hero": "moon-knight", "note": "Même problème avec ses dégâts à distance."}, {"hero": "hela", "note": "Elle te force en réfrigérateur et te laisse sans options."}, {"hero": "phoenix", "note": "Même chose."}], "sections": [{"kind": "tips", "lead": "Il peut à la fois protéger sa backline et faire fondre le front adverse. Les meilleurs choisissent le bon rôle au bon moment.", "items": ["Contre des divers, **force leurs cooldowns** en protégeant tes alliés, puis gonfle et avance au centre.", "Contre une compo serrée, **gonfle en même temps** qu'une ult alliée (Gambit…).", "Choisis **où te battre** : prends les couloirs et les passages étroits avant l'ennemi.", "Avant de gonfler, **vérifie que tes supports te suivent**.", "Mister Fantastic a **la meilleure survie** du jeu : il enchaîne forme normale et forme gonflée, et peut rester le dernier debout fight après fight.", "Vois-le comme un **hybride tank/DPS** : parfait en second tank dans une compo à un seul tank, et le meilleur DPS pour **protéger ses heals**.", "Ce n'est **pas un carry** : sans burst, il faut des DPS à côté pour finir les fights."], "title": "Philosophie de jeu", "diagram": "brawl"}, {"lead": "Tes coups, tes attractions et tes grappins remplissent une jauge. Pleine, tu gonfles : vie supplémentaire, coups plus rapides et plus forts, déplacement plus rapide.", "items": ["Cette vie supplémentaire **se soigne** : tu deviens un vrai tank temporaire.", "Tes coups gonflés **traversent les boucliers** : idéal pour atteindre la backline.", "La jauge **redescend** si tu n'agis pas : utilise l'attraction pour la maintenir.", "Pendant la forme gonflée, tu **ne peux pas protéger** tes alliés avec tes capacités.", "La jauge se remplit en touchant et en utilisant tes capacités : **fais tourner tout ton kit** pour la remplir vite.", "En forme gonflée, ta vie bonus ne se soigne pas et tu **peux toujours être contrôlé** (attrape, stun, coup de pied)."], "title": "Forme gonflée", "ability": "Elastic Strength"}, {"key": "Clic G", "lead": "Des coups à longue portée qui touchent plusieurs ennemis si tu balaies ton viseur.", "items": ["Balaie dans la direction du bras pour **toucher tout un groupe**.", "Erreur courante : **coller l'ennemi** alors que tu as de l'allonge. Frappe depuis un couvert.", "C'est ta principale source de **charge** en début de fight.", "Tes bras balaient comme un marteau : **arrose plusieurs ennemis** à chaque coup, mais un groupe ne remplit pas plus vite la jauge qu'une seule cible."], "title": "Coups allongés", "ability": "Stretch Punch"}, {"key": "Clic D", "lead": "Un projectile lent qui agrippe une cible pour l'attirer vers toi ou la projeter contre un autre ennemi. La cible ne peut plus utiliser ses déplacements un instant.", "items": ["Le vrai intérêt : **bloquer la fuite** d'une cible. Agrippe Venom après ses boucliers, ou Gambit après son premier dash.", "Rapproche-toi : il est **lent et de courte portée**.", "Projeter deux ennemis l'un contre l'autre les **immobilise tous les deux**.", "Il peut aussi **éjecter** un ennemi du terrain.", "Sers-t'en surtout pour **remplir ta jauge**, ou ramener une cible qui fuit pour un pick.", "Tu peux annuler l'agrippement en **saut sur un allié/ennemi** pour charger ta jauge encore plus vite."], "title": "Agrippement", "ability": "Distended Grip"}, {"lead": "Tu t'étires vers un allié ou un ennemi proche et gagnes de la vie bonus. Sur un ennemi, tu le ralentis, et tu peux même faire tomber un volant.", "items": ["Après avoir agrippé une cible, **fonce dessus** pour la ralentir et confirmer le pick.", "Si tu rates un diver, **étire-toi vers ton support** pour lui donner de la vie bonus et le défendre.", "Proche de la jauge pleine, une élongation suffit à **gonfler en arrivant** sur la cible.", "Deux charges : **ne laisse jamais les deux** inutilisées."], "title": "Élongation", "ability": "Flexible Elongation"}, {"lead": "Tu deviens invulnérable et absorbes les dégâts, puis tu en renvoies une partie en projectile. Tu es lent et sans capacités pendant ce temps.", "items": ["Tu peux **contester le point** en restant invulnérable.", "Utilise-la pour **survivre** ou pour **couvrir un allié** sur le point d'avoir son ult.", "Combine **élongation puis réfrigérateur** pour bloquer une ult (Magneto, Iron Man, Punisher) sur un support.", "Erreur : la lancer **trop tôt** alors qu'un couvert suffisait.", "Insensible aux contrôles, tu absorbes les dégâts (et les ults) puis tu les renvoies ; tu peux **annuler tôt** pour riposter vite.", "Elle ne remplit pas ta jauge, mais **te fait gagner du temps** pendant que tes autres capacités reviennent."], "title": "Forme réfrigérateur", "ability": "Reflexive Rubber"}, {"key": "Q", "lead": "Tu gonfles instantanément et rebondis plusieurs fois. Chaque rebond qui touche fait plus mal et ralentit plus.", "items": ["Idéal **juste après** ta forme gonflée, pour récupérer la vie perdue et maintenir la pression.", "Utilise-la pour **protéger ta backline**, puis retourner le fight.", "Sous un **plafond bas**, les rebonds s'accélèrent.", "Elle peut **contrer une ult de Jeff** ou de Gambit avec ton équipe.", "Rater un rebond **coupe la série** : vise bien.", "Chaque rebond qui touche relance un rebond (jusqu'à six) : vise **un groupe**, sinon tu retombes après un ou deux bonds.", "Lancée **sous un pont ou un plafond**, elle rebondit beaucoup plus vite : burst énorme.", "Elle sert aussi à **forcer l'ult de soin** adverse : avec toute ta vie bonus, on ne te tue presque jamais pendant."], "title": "Ultime", "ability": "Brainiac Bounce"}, {"kind": "mistakes", "items": ["Gonfler alors que des **divers** attaquent ta backline.", "Coller l'ennemi au lieu d'utiliser **ton allonge**.", "Agripper une cible **avant** qu'elle ait utilisé sa capacité.", "Forme réfrigérateur **trop tôt**.", "Engager sans que ses **supports suivent**."], "title": "Erreurs fréquentes"}], "synergies": [{"hero": "magneto", "note": "Tu lui permets d'être beaucoup plus agressif."}, {"hero": "the-thing", "note": "Il veut faire la même chose que toi : protéger et frapper."}, {"hero": "winter-soldier", "note": "Tu lui crées l'espace pour faire des dégâts."}, {"hero": "gambit", "note": "Son ult te laisse rouler sur l'équipe adverse."}, {"hero": "invisible-woman", "note": "Elle t'aide à tenir pendant tes engages."}], "difficulty": 2, "patch_note": "Guide tiré d'une vidéo de Paz (padswagger), reformulé en français. Les chiffres du kit ont été retirés car ils changent à chaque saison ; team-ups et derniers changements sont à jour (saison 10.5) dans la section dédiée.", "kit": {"season": "Saison 10.5", "health": "", "abilities": [], "teamups": [{"name": "Clobberin' Research Dept.", "partners": ["the-thing"], "key": "", "text": "Posture de bagarre avec un coup de poing chargé (activable à volonté depuis la saison 10). **Amélioré :** Ajoute un coup de marteau chargé."}, {"name": "Fantastic Amplifier", "partners": ["rocket-raccoon"], "key": "", "text": "Un amplificateur augmente l'élasticité et le gonflement. **Amélioré :** Les coups projettent les ennemis."}, {"name": "First Family", "partners": ["invisible-woman"], "key": "", "text": "Invisibilité avec soin et vitesse. **Amélioré :** Version renforcée."}], "changes": [{"season": "Saison 10", "text": "Brawling Punch se charge en 0,75 s au lieu de 1 s, 65 de dégâts sans charge au lieu de 55."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · changements : patch notes des saisons 10 et 10.5", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'mister-fantastic' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"tags": ["Dégâts de zone", "Ricochets", "Charge d'ult", "Combos d'ult"], "tldr": ["Vise les **groupes** : chaque ricochet charge ton ult.", "Ne tire **pas sur l'ankh** directement, tire sur les ennemis à côté.", "Prévois ton **placement avant le fight** : tu es lent, ta mobilité sert à fuir."], "combos": [{"note": "Vise la cible, pas l'ankh : tu perdrais les dégâts du premier impact.", "steps": [{"key": "", "label": "Ankh"}, {"key": "Clic G", "label": "rafale au corps"}, {"key": "Clic D", "label": "lame lunaire"}], "title": "Le combo"}], "sources": [{"url": "https://www.youtube.com/watch?v=yHH6KBvciPg", "title": "Moon Knight Guide", "author": "Paz (padswagger)"}], "summary": "Moon Knight est une machine à dégâts : ses tirs ricochent entre les ennemis groupés et chargent son ult à une vitesse folle. Contre des équipes sans bouclier, il peut lancer une ult à presque chaque fight. En échange, il manque de mobilité.", "counters": [{"hero": "magneto", "note": "Son bouclier coupe tes ricochets et son ult avale la tienne."}, {"hero": "doctor-strange", "note": "Même chose, en un peu moins fort."}, {"hero": "captain-america", "note": "Il te colle et tu ne peux pas fuir."}, {"hero": "iron-man", "note": "Les volants ne te laissent pas ricocher."}, {"hero": "psylocke", "note": "Elle esquive ton ankh et punit ton manque de mobilité."}, {"hero": "ultron", "note": "Un autre volant difficile à toucher."}], "sections": [{"kind": "tips", "lead": "Fais des dégâts, charge ton ult, élimine l'équipe adverse, recommence. Mais attention à ne pas nourrir les ults de soin adverses.", "items": ["Une fois ton ult prête, **ne spamme plus** des dégâts inutiles : tu charges les ults de support adverses.", "Avec ton ankh, tu gagnes **les duels** : prends un léger angle, puis reviens vers ton équipe.", "Reste à **bonne distance** de l'ennemi : ne sacrifie pas ton placement pour des tirs plus faciles.", "Comme un canon de verre, **choisis ton angle avant le fight** et utilise tes déplacements de base pour y aller."], "title": "Philosophie de jeu", "diagram": "poke"}, {"key": "Clic G", "lead": "Des rafales de trois projectiles qui ricochent sur les ennemis proches les uns des autres, avec des dégâts réduits à chaque rebond.", "items": ["Les ennemis doivent être **assez proches** les uns des autres pour que les tirs rebondissent.", "Pour finir une cible isolée et basse, **vise-la directement** : le premier impact fait le plus mal.", "Même vitesse de projectile que **Storm et Namor** : tu peux transférer ta visée."], "title": "Fléchettes", "ability": "Crescent Dart"}, {"key": "Clic D", "lead": "Une grosse lame qui ricoche aussi et te donne de la vie bonus à chaque rebond. Tu en as deux charges.", "items": ["Ouvre un fight avec une lame pour la **vie bonus**, garde la seconde pour **finir**.", "De près, vise **au-dessus de la tête** pour un headshot.", "Elle est un peu **plus lente** que tes fléchettes."], "title": "Lame lunaire", "ability": "Moon Blade"}, {"lead": "Un ankh qui s'accroche au décor, attire les ennemis proches et sert de point de rebond pour tes tirs.", "items": ["L'attraction est **sa vraie force** : elle t'aide à gagner un duel contre un Star-Lord.", "Tirer sur l'ankh **te prive des dégâts du premier impact** : tire sur l'ennemi à côté.", "Il **ramène les ennemis** dans ton ult, même ceux qui fuient.", "Tu peux en avoir **deux** : pré-place-les sur les passages en défense."], "title": "Ankh", "ability": "Ancient Ankh"}, {"kind": "tips", "lead": "Le seul combo dont tu as vraiment besoin pour éliminer un personnage fragile.", "items": ["**Ankh, une rafale au corps, lame lunaire**.", "Avec un headshot dans la rafale, la cible tombe presque à coup sûr.", "Attention à **ne pas viser trop bas** et toucher l'ankh au lieu de la cible."], "title": "Combo"}, {"key": "Maj · F", "lead": "Double saut, planeur et grappin. Le grappin est lent à lancer mais rapide une fois accroché.", "items": ["Le grappin est ton **outil de fuite** : ne l'utilise pas si un saut suffit.", "Le planeur sert à **passer d'une hauteur à l'autre**, pas à esquiver les tireurs.", "Astuce : vise **le côté d'un mur** au grappin, puis saute pour monter plus haut.", "Bien utilisé, le grappin **esquive une ult de Magneto**."], "title": "Mobilité", "ability": "Night Glider · Moon Knight Hook"}, {"key": "Q", "lead": "Des mains explosives tombent du ciel en triangle autour de ta cible pendant plusieurs secondes.", "items": ["Le centre de la zone fait le plus mal : vise **un peu à droite, devant ou derrière** l'ennemi selon sa direction.", "Combos mortels avec l'**ult de Groot** ou celle d'**Angela**.", "Sans combo, **lance-la quand même** : elle revient très vite.", "Astuce : sortir l'ult (l'ankh au-dessus de ta tête) peut **pousser un support adverse à utiliser la sienne**. Ne le fais pas à chaque fois."], "title": "Ultime", "ability": "Hand of Khonshu"}, {"kind": "mistakes", "items": ["Tirer **sur l'ankh** au lieu des ennemis.", "Utiliser le **grappin pour se déplacer**.", "S'approcher trop pour **toucher plus facilement**.", "Spammer des dégâts **avec l'ult déjà prête**.", "Sortir l'ult **toujours de la même façon**."], "title": "Erreurs fréquentes"}], "synergies": [{"hero": "groot", "note": "Son ult regroupe tout le monde pour la tienne."}, {"hero": "angela", "note": "Même combo d'ult, moins fort en neutre."}, {"hero": "magneto", "note": "Il te protège pour que tu tires plus longtemps."}, {"hero": "hela", "note": "Elle s'occupe des volants à ta place."}, {"hero": "mantis", "note": "Son bonus de dégâts te fait charger ton ult encore plus vite."}, {"hero": "luna-snow", "note": "Toujours un bon choix."}], "difficulty": 1, "patch_note": "Guide tiré d'une vidéo de Paz (padswagger), reformulé en français. Les chiffres du kit ont été retirés car ils changent à chaque saison ; team-ups et derniers changements sont à jour (saison 10.5) dans la section dédiée.", "kit": {"season": "Saison 10.5", "health": "", "abilities": [], "teamups": [{"name": "Blade of Khonshu", "partners": ["blade"], "key": "", "text": "Chaque Whirlwind Slash lance une lame lunaire en plus."}, {"name": "Blood Moon", "partners": ["elsa-bloodstone"], "key": "", "text": "L'ankh piège invoque des serres. **Amélioré :** En invoque plusieurs."}, {"name": "Luminous Moon", "partners": ["cloak-and-dagger"], "key": "", "text": "Dash intangible avec une vague de soin. **Amélioré :** Plus long, avec un soin continu."}, {"name": "New Moon's Shadow", "partners": ["the-hood"], "key": "", "text": "Une barrière lunaire explose (détection des rebonds à 6 m depuis la saison 10). **Amélioré :** Les attaques rebondissent."}], "changes": [], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · changements : patch notes des saisons 10 et 10.5", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'moon-knight' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"tags": ["Tourelles", "Anti-dive", "Angles décalés", "Combos d'ult"], "tldr": ["D'abord **repérer et gérer les divers**, ensuite seulement prendre un angle.", "Pose **une tourelle avant de poker** : tes tridents rechargent tes tourelles.", "Ton trident secondaire n'a pas besoin de toucher : **vise les pieds**."], "combos": [{"note": "Annule l'animation du premier tir avec le trident.", "steps": [{"key": "E", "label": "tourelles"}, {"key": "Clic G", "label": "tête"}, {"key": "Clic D", "label": "trident"}], "title": "Tête et trident"}], "sources": [{"url": "https://www.youtube.com/watch?v=FPPs-i1ee-g", "title": "Namor Guide", "author": "Paz (padswagger)"}, {"title": "The King of the Seas", "author": "Kingsman", "url": "https://www.youtube.com/watch?v=l_51Gk4iULk"}], "summary": "Namor est un DPS à tourelles : il protège sa backline des divers, puis devient une menace sur les angles décalés grâce à ses combos tridents et tourelles. Sans ses tourelles bien placées, il ne sert à rien.", "counters": [{"hero": "emma-frost", "note": "Elle garde sa charge en tapant tes tourelles."}, {"hero": "hela", "note": "Elle te domine à distance et casse tes tourelles."}, {"hero": "luna-snow", "note": "Elle détruit tes tourelles en deux rafales."}, {"hero": "magneto", "note": "Les compos à bouclier qui jouent au centre t'obligent à flanquer."}], "sections": [{"kind": "tips", "lead": "Procède par étapes : y a-t-il un flanker dans ta backline ? Si oui, gère-le. Sinon, prends un angle agressif.", "items": ["Contre des divers (**Black Panther, Magik, Psylocke**), garde tes tourelles pour eux.", "Une fois la menace gérée, prends un **angle décalé** pour attaquer les supports.", "N'engage pas **tes deux tourelles** si tu n'es pas sûr du kill.", "Tes **pas sont bruyants** : les bons joueurs t'entendront arriver en flank.", "Namor demande **beaucoup de précision** : chaque touche réduit le cooldown des tourelles. Sans aim, il ne rapporte presque rien.", "Tu peux jouer front, spam sur un choke ou flank ; à haut niveau, le flank est risqué car tu n'as **aucune fuite** hors de la bulle.", "Apprends-le en **partie rapide** avant de le sortir en ranked."], "title": "Philosophie de jeu", "diagram": "choke"}, {"key": "Clic G · Clic D", "lead": "Des tridents qui tuent en deux headshots, et un trident explosif qui déclenche une attaque renforcée de toutes tes tourelles.", "items": ["Joue à **mi-distance**, pas besoin de coller.", "Chaque trident qui touche **réduit le cooldown** de tes tourelles. Un headshot les rend **frénétiques**.", "Le trident explosif a une **zone d'impact** : vise les pieds, même raté il déclenche tes tourelles.", "Combo : **headshot puis trident explosif**, en annulant l'animation du premier, avec tes tourelles posées."], "title": "Tridents", "ability": "Trident of Neptune · Wrath of the Seven Seas"}, {"key": "E", "lead": "Des petites tourelles qui s'accrochent au décor et verrouillent la première cible visible. Deux maximum à la fois.", "items": ["**Poker** : pose-les sur des angles difficiles d'accès en début de fight.", "**Repérer le dive** : une tourelle sur un flank courant révèle le diver avant qu'il engage.", "**Attaquer** : lance-les sur un mur juste avant de te montrer, pour qu'elles tirent en même temps que toi.", "Ne les place pas **trop loin** : elles verrouillent la mauvaise cible et laissent tes supports seuls.", "Pose-les **là où l'ennemi a du mal à les viser** : sur un mur, en hauteur, dans un angle.", "Contre un diver, place-les dans **un coin de ta backline** : elles peel toutes seules pendant que tu tires devant.", "Après un trident lourd qui touche, elles passent en **mode berserker** : pose-les d'abord, lance le trident ensuite."], "title": "Tourelles", "ability": "Aquatic Dominion"}, {"lead": "Tu montes dans une bulle invulnérable et insensible aux contrôles, avec un long cooldown.", "items": ["Les bons joueurs vont **chercher à la forcer** avant leur ult.", "Ne l'utilise pas **juste pour monter** en hauteur, sauf si personne ne peut te punir.", "Tes **tourelles tirent** pendant que tu es dans la bulle.", "Astuce : elle peut **esquiver une ult de Magneto**.", "Elle te rend **intouchable deux secondes**, même sous un effet de contrôle léger, et tes heals peuvent te soigner à travers.", "Elle bloque aussi **l'ult de Magneto** : sers-t'en pour protéger tes heals."], "title": "Bulle", "ability": "Blessing of the Deep"}, {"key": "Q", "lead": "Une baleine géante s'écrase dans une zone. Les ennemis dedans ne peuvent plus utiliser leurs capacités de déplacement.", "items": ["Le **cercle central** fait énormément de dégâts. Avec un bonus de dégâts, le cercle extérieur tue aussi les fragiles.", "Avec l'**ult de Groot**, aucune ult de soin ne sauve l'ennemi : lance vite après lui.", "Elle **bloque les déplacements** : portails de Magik, patinage de Luna, intangibilité de Cloak…", "Elle coupe l'ult de **Cloak & Dagger** à la fin du quatrième dash.", "Elle se charge vite : **utilise-la souvent**.", "Elle cloue les ennemis au sol : ils ne peuvent plus utiliser leurs déplacements. Un trident suffit souvent à finir ceux qui étaient au bord.", "C'est un **excellent ult de combo** (Emma, Groot) et elle sort une Cloak & Dagger de son ult si ton équipe la focus.", "Elle est bloquée par **les lampes de Loki, les bulles et les boucliers** : fais-les sortir avant."], "title": "Ultime", "ability": "Horn of Proteus"}, {"kind": "mistakes", "items": ["Partir en flank alors qu'un **diver** menace ta backline.", "Placer ses tourelles **trop loin** ou à découvert.", "Chercher à **toucher** le trident explosif au lieu de viser les pieds.", "Gâcher sa **bulle** pour un déplacement.", "Poser **deux tourelles** sans être sûr du kill."], "title": "Erreurs fréquentes"}], "synergies": [{"hero": "hulk", "note": "Ses bulles et tes tourelles rendent le dive adverse impossible."}, {"hero": "groot", "note": "Le combo d'ult parfait."}, {"hero": "winter-soldier", "note": "Il ramène des cibles dans la portée de tes tourelles."}, {"hero": "luna-snow", "note": "Son bonus de dégâts rend ton ult mortelle."}, {"hero": "mantis", "note": "Même chose : booste au lancement."}], "difficulty": 1, "patch_note": "Guide tiré d'une vidéo de Paz (padswagger), reformulé en français. Les chiffres du kit ont été retirés car ils changent à chaque saison ; team-ups et derniers changements sont à jour (saison 10.5) dans la section dédiée.", "kit": {"season": "Saison 10.5", "health": "", "abilities": [], "teamups": [{"name": "Chilling Charisma", "partners": ["luna-snow"], "key": "", "text": "Frost Tide ralentit les ennemis. **Amélioré :** Une charge en plus et un impact au bout de la course."}, {"name": "Deep Wrath", "partners": ["hela"], "key": "", "text": "Les kills de Hela font apparaître des monstros morts-vivants. **Amélioré :** Ils apparaissent à chaque attaque."}, {"name": "Gamma Monstro", "partners": ["hulk"], "key": "", "text": "Un monstro gamma en plus (cooldown 25 s depuis la saison 10). **Amélioré :** Ajoute une barrière d'eau gamma."}], "changes": [{"season": "Saison 10", "text": "Trident of Neptune 75 → 80 par tir."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · changements : patch notes des saisons 10 et 10.5", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'namor' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"tags": ["Contrôle de zone", "Anti-dive", "Pièges", "Défense"], "tldr": ["**Adapte tes nids** : en backline contre le dive, près du front contre le brawl, sur un angle en attaque.", "Garde **toujours une mine** en rechargement et pose-les par groupes.", "Ton snare peut **couper une ult** en pleine incantation."], "sources": [{"url": "https://www.youtube.com/watch?v=fHwTq8w2FVU", "title": "Peni Parker Guide", "author": "Paz (padswagger)"}], "summary": "Peni Parker contrôle le terrain avec ses nids, ses toiles et ses mines. Elle protège ses supports des divers en défense, et peut aussi s'installer sur un angle agressif pour aider un DPS à trouver des kills. C'est d'abord un contre, ensuite un soutien.", "counters": [{"hero": "emma-frost", "note": "Elle charge sur toi et casse tes nids."}, {"hero": "groot", "note": "Un mur sur ton nid le détruit."}, {"hero": "the-punisher", "note": "Ses dégâts continus te dévorent."}, {"hero": "moon-knight", "note": "Même chose, ta grosse hitbox est facile à toucher."}, {"hero": "phoenix", "note": "Elle te farme et son ult détruit tout."}, {"hero": "ultron", "note": "Il casse tes nids depuis les airs."}], "sections": [{"kind": "tips", "lead": "En défense comme en attaque, ton rôle est de donner à tes supports et DPS les positions dont ils ont besoin.", "items": ["En **défense**, sois le gardien de ta backline : attends les flankers et fais-leur perdre leur temps.", "En **attaque**, pose un nid sur un angle décalé : l'ennemi doit envoyer deux joueurs pour te déloger, et ton équipe gagne au centre.", "Quand l'ennemi recule, **avance** et pose un nid sur sa position pour lui retirer ses coins sûrs.", "Ton seul abri face aux gros DPS est ton **grappin** : maîtrise-le."], "title": "Philosophie de jeu", "diagram": "choke"}, {"key": "Clic G · Clic D", "lead": "Des projectiles explosifs sans rechargement, et une toile lente qui étourdit si elle touche, ou laisse une toile au sol si elle rate.", "items": ["Vise **les pieds** pour plus de régularité, ou la tête si tu as confiance en ta visée.", "Le snare **coupe une incantation** : ult de Doctor Strange, d'Iron Man ou de Scarlet Witch.", "Les **toiles au sol** soignent, donnent de la vie bonus et de la vitesse à toi et tes alliés.", "Tu ne peux avoir que **trois toiles** à la fois : surveille le compteur en bas à gauche."], "title": "Tir et snare", "ability": "Cyber-Web Cluster · Cyber-Web Snare"}, {"lead": "Tu te tires vers le décor et restes attachée. Relâche ton déplacement pour revenir en fronde vers le point d'accroche.", "items": ["Sers-t'en pour **mettre la pression** sur la backline puis revenir vers ton équipe.", "Détache-toi pour **traverser la carte** : pose un nid, grappin, récupère le nid, recommence.", "Astuce : baisse la **sensibilité de ciblage** dans les paramètres pour garder le contrôle."], "title": "Grappin", "ability": "Cyber-Bond"}, {"lead": "Des mines qui explosent quand un ennemi passe. Posées dans une toile, elles deviennent invisibles.", "items": ["Pose-les **par trois ou quatre** pour éliminer un personnage fragile.", "Contre une **Hela**, mine ses hauteurs habituelles. Contre un **Black Panther**, mine ta backline.", "Mine **les murs et les coins derrière ton équipe** pour couper l'ult de Cloak & Dagger.", "En attaque, **lance-les sur les supports** quand ton équipe les presse."], "title": "Mines", "ability": "Arachno-Mine"}, {"lead": "Un nid qui crée une grande toile et envoie des araignées qui blessent et ralentissent. Tu peux le récupérer à tout moment.", "items": ["Contre le **dive**, en backline. Contre le **brawl**, près du front pour accélérer ton équipe.", "Place-le **derrière un coin** : l'ennemi doit s'exposer pour le casser.", "Un nid intact **revient tout de suite** : utilise-le pour te déplacer.", "Face à une ult (Gambit), **récupère un nid avancé** et repose-le derrière ton équipe.", "Prolonge sa toile avec tes **snares**."], "title": "Nid d'araignées", "ability": "Bionic Spider-Nest"}, {"key": "Q", "lead": "Tu gagnes beaucoup de vie bonus et de vitesse, des coups qui projettent, des mines à lancer et des araignées en continu.", "items": ["Ne **commence pas** le fight avec : tu deviens la cible prioritaire.", "En plein fight, elle **étend tes toiles sur le point** pour toute l'équipe.", "Avance **avec ton équipe**, pas seule par une fenêtre.", "Si l'ennemi a une ult à couper (Doctor Strange, Iron Man), **garde ton snare** avant de lancer la tienne."], "title": "Ultime", "ability": "Spider-Sweeper"}, {"kind": "mistakes", "items": ["**Oublier ses mines** pendant tout le fight.", "Placer son nid **à découvert**.", "Lancer l'ult **en ouverture** du fight.", "Rester attachée au grappin **au milieu des ennemis**.", "Garder un nid **au même endroit** alors que la menace a changé."], "title": "Erreurs fréquentes"}], "synergies": [{"hero": "rocket-raccoon", "note": "Un support qui joue la défense de zone avec toi."}, {"hero": "doctor-strange", "note": "Son bouclier gère les DPS qui te contrent."}, {"hero": "magneto", "note": "Même chose."}, {"hero": "hela", "note": "Un nid sur son angle la protège des divers."}, {"hero": "the-punisher", "note": "Même logique."}], "difficulty": 2, "patch_note": "Guide tiré d'une vidéo de Paz (padswagger), reformulé en français. Les chiffres du kit ont été retirés car ils changent à chaque saison ; team-ups et derniers changements sont à jour (saison 10.5) dans la section dédiée.", "kit": {"season": "Saison 10.5", "health": "", "abilities": [], "teamups": [{"name": "Parker Power-Up", "partners": ["spider-man"], "key": "", "text": "Bombe-araignée collante qui marque les ennemis (cooldown 10 s depuis la saison 10). **Amélioré :** Vie bonus à la détonation."}, {"name": "Rocket Network", "partners": ["rocket-raccoon"], "key": "", "text": "Le nid d'araignées largue des drones et des kits d'armure. **Amélioré :** Régénération et plus d'unités."}, {"name": "SP//DR Sync", "partners": ["ultron"], "key": "", "text": "Imperative: Patch s'applique aux alliés. **Amélioré :** Les drones cumulent les effets de Firewall."}, {"name": "Vibranium Mech", "partners": ["black-panther"], "key": "", "text": "Bouclier de vibranium frontal et vitesse d'attaque (cooldown 15 s depuis la saison 10). **Amélioré :** Bouclier plus grand."}], "changes": [{"season": "Saison 10", "text": "Cyber-Web plus rapide (0,3 s → 0,25 s entre deux tirs), plus de ralentissement quand elle tire."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · changements : patch notes des saisons 10 et 10.5", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'peni-parker' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"tags": ["Hitscan", "Marques", "Brawl", "Anti-bouclier"], "tldr": ["Commence **au centre** pour poser des marques, puis vole vers un angle en plein fight.", "Reste **à mi-distance** : ses dégâts chutent fortement de loin.", "Avant ton ult, pose **deux marques** sur les fragiles : l'impact les achève."], "combos": [{"note": "Le dash final annule l'animation.", "steps": [{"key": "Clic D", "label": "explosion"}, {"key": "Clic G", "label": "tir"}, {"key": "Mêlée", "label": ""}, {"key": "", "label": "Dash"}], "title": "Presque un kill"}], "sources": [{"url": "https://www.youtube.com/watch?v=OoQyu_WzbBY", "title": "Phoenix Guide", "author": "Paz (padswagger)"}, {"title": "The Ultimate Phoenix Guide", "author": "Kingsman", "url": "https://www.youtube.com/watch?v=j2OSEOO0RUU"}], "summary": "Phoenix est une tireuse instantanée qui marque les ennemis et déclenche des réactions en chaîne d'explosions. Contrairement à Hela, elle ne gagne pas à longue distance : elle brille en brawl et en dive, quand les ennemis sont groupés.", "counters": [{"hero": "captain-america", "note": "Petite cible, rarement collé à son équipe : tes marques ne prennent pas."}, {"hero": "hela", "note": "Elle te bat à distance."}, {"hero": "psylocke", "note": "Elle force ta mobilité et te saute dessus après ton vol."}, {"hero": "winter-soldier", "note": "Trop de vie pour être brûlé vite."}, {"hero": "rocket-raccoon", "note": "Ses soins et packs cassent tes combos."}, {"hero": "the-thing", "note": "Il peut intercepter ton ult."}, {"hero": "the-punisher", "note": "Ses tirs constants abattent ton oiseau d'ult."}], "sections": [{"kind": "tips", "lead": "Phoenix demande un peu plus de réflexion qu'un tireur classique : ses dégâts viennent des explosions en chaîne sur des ennemis groupés.", "items": ["Avec des tanks de brawl (**Magneto, The Thing**), joue au centre, lance des chaînes, puis vole vers un angle décalé.", "Avec des tanks de dive (**Captain America**), guette le moment où les supports adverses se regroupent avec leur front et fais-les exploser.", "Contre **Hela** à longue distance, tu perds le duel : force-la à se battre de près.", "Charge ton ult **avec tes tanks** au début : pas besoin d'angle fou tout de suite.", "Phoenix est une **anti-dive** qui fait de la zone : joue avec ta backline et punis chaque diver qui entre.", "Pendant une ult de soin adverse sans ton ult, **tire sur les tanks** : les explosions rebondissent sur les autres et chargent ton ult.", "Face à un diver, ne grille pas ton dash dès sa première approche : il cherche justement à **te le faire sortir**."], "title": "Philosophie de jeu", "diagram": "angle"}, {"key": "Clic G", "lead": "Des tirs instantanés qui posent des marques. À trois marques, la cible explose et marque les ennemis autour d'elle.", "items": ["Un headshot pose **deux marques** d'un coup.", "Chaîne type : **corps sur A, tête sur B, tête sur A**, et tout explose.", "Les marques **disparaissent** au bout de quelques secondes.", "Chaque explosion te **soigne** un peu sur la durée.", "Les **clones de Loki** permettent des chaînes faciles.", "Trois marques font exploser la cible et **marquent ceux autour** : une réaction en chaîne sur un groupe.", "Un headshot pose **deux marques** : trois headshots d'affilée provoquent deux explosions.", "Ta mêlée pose aussi une marque, mais ton tir fait mieux : garde-la pour un **groupe collé** (sous une ult de Groot)."], "title": "Flammes et marques", "ability": "Cosmic Flames"}, {"lead": "Un dash qui laisse une illusion explosive derrière toi. Tu es insensible aux dégâts pendant le mouvement.", "items": ["Combo : **tir, coup de mêlée, dash** pour annuler l'animation. Ajoute ton explosion en ouverture pour presque tuer un fragile.", "Il **esquive** les ults d'Iron Man ou de Magneto.", "Dash dans tous les sens : l'ennemi croit que **tu te téléportes**.", "Ne l'utilise **jamais pour monter** en hauteur : c'est le rôle du vol.", "Il t'envoie **dans la direction de ton déplacement** sans tourner la caméra : le meilleur outil du jeu pour te repositionner contre le dive.", "Il laisse une **explosion** là où tu étais et peut aussi te faire monter."], "title": "Dash", "ability": "Telepathic Illusion"}, {"lead": "Quelques secondes de vol rapide qui rechargent aussi tes munitions. Très bruyant.", "items": ["Sers-t'en pour **passer sur un angle** en plein fight, après avoir lancé tes chaînes au centre.", "Tirer ou utiliser une capacité **coupe le vol** : attention au-dessus du vide.", "On t'entend arriver : ne t'**isole pas**, une Psylocke te guette."], "title": "Vol", "ability": "Dark Ascent"}, {"key": "Clic D", "lead": "Trois explosions en ligne. La première étourdit brièvement, les deux suivantes ralentissent. Toutes posent une marque.", "items": ["L'étourdissement **coupe les ults** de Doctor Strange ou de Scarlet Witch (anticipe l'animation).", "Contre un **diver**, lance-la à tes pieds : il se fait étourdir ou ralentir en arrivant.", "Combinée à un coup de **Winter Soldier**, elle prolonge le contrôle de sa cible.", "C'est un **contrôle dur** : il coupe les déplacements (grappin de Spider-Man, dash de Black Panther) et les ults en cours de lancement.", "Long cooldown : garde-la pour **un coin** ou pour **une ult adverse** sur un groupe."], "title": "Explosion télékinétique", "ability": "Telekinesis Burst"}, {"key": "Q", "lead": "Tu t'élèves puis t'écrases sur une zone, puis une onde de choc détruit boucliers, invocations et vie bonus adverses, même à travers les murs.", "items": ["Deux marques sur une cible fragile, et **l'impact l'achève**.", "L'onde de choc **casse** les boucliers de Strange et Magneto, la vie bonus de Venom, les clones de Loki, l'ult de Rocket.", "Avec un **bonus de dégâts** (Luna, Rocket, Cloak & Dagger), vise **la zone d'impact**, pas ton point de départ.", "Tu sors de l'ult avec ta vie d'avant : ne la lance pas **trop près du front**, où l'ennemi peut te piéger.", "Ta forme en l'air peut **être abattue** : contre une équipe prête, écrase-toi derrière un mur pour l'onde de choc seule.", "**The Thing** peut sauter pour l'intercepter.", "L'onde de choc **détruit boucliers, bulles, invocations et vie bonus**, même les lampes de Loki et le gros bouclier de l'ult de Storm.", "C'est **le meilleur ult à combiner** : lance-le en premier pour casser les protections, puis les autres ults finissent le travail.", "Après l'atterrissage, tu es **brièvement invulnérable** ; en l'air, l'oiseau peut être abattu par des tirs précis (Punisher, hitscan)."], "title": "Ultime", "ability": "Endsong Inferno"}, {"kind": "mistakes", "items": ["Jouer comme une **Hela** à longue distance.", "Gâcher le dash **pour monter** en hauteur.", "Voler et **s'isoler** bruyamment.", "Ult **trop près du front** adverse.", "Laisser les marques **expirer** sans les faire exploser."], "title": "Erreurs fréquentes"}], "synergies": [{"hero": "magneto", "note": "Un brawl au centre où tu poses tes marques."}, {"hero": "black-panther", "note": "Les supports qu'il dive se regroupent : tu les fais exploser."}, {"hero": "captain-america", "note": "Même logique de dive."}, {"hero": "winter-soldier", "note": "Tu prolonges le contrôle de sa cible."}, {"hero": "wolverine", "note": "Un brawler qui profite de tes explosions."}, {"hero": "invisible-woman", "note": "Elle regroupe les ennemis et te protège sur ton angle."}], "difficulty": 2, "patch_note": "Guide tiré d'une vidéo de Paz (padswagger), reformulé en français. Les chiffres du kit ont été retirés car ils changent à chaque saison ; team-ups et derniers changements sont à jour (saison 10.5) dans la section dédiée.", "kit": {"season": "Saison 10.5", "health": "", "abilities": [], "teamups": [{"name": "Abyssal Flames", "partners": ["venom"], "key": "", "text": "Les griffes de Venom posent des étincelles de Phoenix, qui explosent à 3 cumuls."}, {"name": "Burning Bullets", "partners": ["black-widow"], "key": "", "text": "Le Plasma Cannon devient un tir instantané (hitscan). **Amélioré :** Une charge en plus."}, {"name": "Circle of Life", "partners": ["hela"], "key": "", "text": "Les tirs de Netherfire posent des étincelles et étourdissent. **Amélioré :** Plus d'étincelles."}, {"name": "Slim and Red", "partners": ["cyclops"], "key": "", "text": "Embrasement qui brûle et déclenche les étincelles (cooldown 10 s en 10.5). **Amélioré :** Les étincelles réduisent le cooldown de Ricochet Force."}, {"name": "Telekinetic Beatdown", "partners": ["rogue"], "key": "", "text": "Coups télékinétiques qui sautent d'une cible à l'autre. **Amélioré :** Étincelles et frappes en plus."}], "changes": [{"season": "Saison 10.5", "text": "Cosmic Flames 60 → 65, étincelles : 45 de dégâts directs et 20 d'explosion."}, {"season": "Saison 10.5", "text": "L'explosion des étincelles ne soigne plus : elle donne 5 de vie bonus pendant 4 s (25 max)."}, {"season": "Saison 10.5", "text": "Ult : 2 étincelles par touche au lieu de 1."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · changements : patch notes des saisons 10 et 10.5", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'phoenix' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"tags": ["Assassin", "Invisibilité", "Combos", "Flanc"], "tldr": ["Prends **un flank à l'écart** du centre et isole les cibles en duel.", "Active ton **invisibilité à la bonne distance** pour arriver pile à portée.", "**Farme les tanks** entre deux dives pour récupérer tes capacités."], "combos": [{"note": "Puis **dash vers ton équipe** et recommence.", "steps": [{"key": "Clic G", "label": "tir"}, {"key": "Clic D", "label": "shurikens"}, {"key": "", "label": "Rappel"}, {"key": "Clic G", "label": "tir"}, {"key": "Clic G", "label": "tir"}], "title": "Éliminer un fragile"}], "sources": [{"url": "https://www.youtube.com/watch?v=Vsua14VUmGg", "title": "Psylocke Guide", "author": "Paz (padswagger)"}], "summary": "Psylocke est une assassine de flank : elle évite le couloir principal, s'approche invisible d'une cible isolée, l'élimine d'un combo, puis repart vers son équipe. Ses tirs réduisent le cooldown de toutes ses capacités.", "counters": [{"hero": "peni-parker", "note": "Ses nids te révèlent et bloquent ton flank."}, {"hero": "hulk", "note": "Ses bulles bloquent ton ult."}, {"hero": "namor", "note": "Ses tourelles te repèrent."}, {"hero": "star-lord", "note": "Il te marque et te force à sortir de l'invisibilité."}, {"hero": "rocket-raccoon", "note": "Ses packs d'armure cassent tes seuils de kill."}, {"hero": "loki", "note": "Ses clones annulent ton ult."}], "sections": [{"kind": "tips", "lead": "Patience, timing et confiance : force les bonnes cibles au bon moment, puis exécute.", "items": ["Cycle de base : **dive par derrière, combo un fragile, dash vers ton équipe**, puis recommence.", "La visée compte, mais c'est surtout ton **approche** : si la cible ne te voit pas, tu touches tout.", "Excellente contre les **tireurs oppressants** (Hela, Hawkeye) : rejoins-les invisible.", "N'engage pas **hors de ta portée efficace**, même si tu meurs d'envie."], "title": "Philosophie de jeu", "diagram": "reset"}, {"key": "Clic G", "lead": "Des rafales instantanées en triangle autour de ton viseur. Chaque projectile qui touche réduit le cooldown de toutes tes capacités.", "items": ["Au-delà de la mi-distance, la dispersion rend **la tête inutile** : approche-toi.", "En difficulté, **tire sur un tank**, même de loin, pour récupérer ton dash.", "Un **coup de mêlée** en fin de rechargement raccourcit l'animation."], "title": "Arbalète", "ability": "Psionic Crossbow"}, {"key": "Clic D", "lead": "Cinq shurikens lancés en carré, puis rappelés vers toi. Ils te donnent un peu de vie bonus.", "items": ["Pas de dégâts à la tête : vise **le torse**.", "Au rappel, ils passent par **l'endroit que tu vises** avant de revenir.", "Combo : **tir, shurikens, rappel, deux tirs** pour éliminer un fragile.", "Variante : **tir, shurikens, dash à travers la cible** (le dash rappelle les shurikens)."], "title": "Shurikens", "ability": "Wing Shurikens"}, {"lead": "Deux charges de dash qui blessent les ennemis traversés. Une pour entrer, une pour sortir.", "items": ["Vise **le sol en angle** pour raccourcir le dash et finir face à ta cible, sans te retourner.", "Garde **toujours un dash** pour fuir.", "Tes tirs **réduisent** le cooldown du dash déjà utilisé."], "title": "Dash", "ability": "Psi-Blade Dash"}, {"lead": "Quelques secondes d'invisibilité et de vitesse. Le début et la fin sont bruyants.", "items": ["**Cacher ton flank** : traverse le centre invisible pour que l'ennemi ne sache pas d'où tu viens.", "**Engager** : ni trop tôt (tu réapparais avant d'arriver), ni trop tard (on t'a déjà vue).", "**Fuir** : dash derrière un mur, puis invisibilité. L'ennemi perd toute info sur toi.", "L'utiliser **sous les yeux de l'ennemi** ne sert à rien.", "Tu peux **recharger** et ramasser des packs de soin en étant invisible."], "title": "Invisibilité", "ability": "Psychic Stealth"}, {"key": "Q", "lead": "Tu tranches les ennemis autour de toi pendant quelques secondes, en priorité ceux qui ont été le moins touchés.", "items": ["Vise **un ou deux ennemis isolés**, pas le centre de l'équipe : ils se répartissent les coups.", "Les **clones de Loki** absorbent les coups, et un ennemi invisible ne peut pas être ciblé.", "**Force d'abord** les ults de support et les cooldowns défensifs.", "Après l'ult, tu ne peux **pas dasher tout de suite** : finis-la près d'une sortie.", "Sers-t'en pour **charger** quand deux ults de support s'affrontent, puis frappe après."], "title": "Ultime", "ability": "Dance of the Butterfly"}, {"kind": "mistakes", "items": ["Jouer **au centre** comme un DPS classique.", "Activer l'invisibilité **trop tôt ou devant l'ennemi**.", "Utiliser **les deux dashes** pour entrer.", "Ult **au milieu** de toute l'équipe adverse.", "Dasher **à travers** la cible et perdre son angle."], "title": "Erreurs fréquentes"}], "synergies": [{"hero": "captain-america", "note": "Il dive par l'autre côté pendant que tu arrives."}, {"hero": "venom", "note": "Même idée."}, {"hero": "emma-frost", "note": "Elle tient le front pendant tes flancs."}, {"hero": "jeff-the-land-shark", "note": "Il attire l'attention et affaiblit tes cibles."}, {"hero": "luna-snow", "note": "Elle te permet d'aller plus loin en flank."}], "difficulty": 3, "patch_note": "Guide tiré d'une vidéo de Paz (padswagger), reformulé en français. Les chiffres du kit ont été retirés car ils changent à chaque saison ; team-ups et derniers changements sont à jour (saison 10.5) dans la section dédiée.", "kit": {"season": "Saison 10.5", "health": "", "abilities": [], "teamups": [{"name": "Light & Dark Darts", "partners": ["cloak-and-dagger"], "key": "", "text": "Fléchettes de lumière et domaine d'ombre. **Amélioré :** Domaine plus grand, fléchettes relancées."}, {"name": "Mental Projection", "partners": ["emma-frost"], "key": "", "text": "Une illusion dashe et imite les frappes. **Amélioré :** Permet d'échanger de place avec l'illusion."}, {"name": "Psionic Fox", "partners": ["white-fox"], "key": "", "text": "La forme de renard ne coûte plus d'énergie. **Amélioré :** Cooldown fortement réduit."}, {"name": "Senbonzakura Strike", "partners": ["hawkeye"], "key": "", "text": "Hawkeye stocke des flèches psioniques (33 dégâts en 10.5) et les tire ensemble. **Amélioré :** Encochage plus rapide et explosions."}], "changes": [{"season": "Saison 10", "text": "Wing Shurikens plus rapides (120 → 150 m/s), 10 dégâts par shuriken au lieu de 9."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · changements : patch notes des saisons 10 et 10.5", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'psylocke' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"tags": ["Soins de zone", "Résurrection", "Mobilité", "Bonus de dégâts"], "tldr": ["**Rester en vie et charger ton ult** : le reste vient après.", "Place ta **balise de résurrection à l'abri** et déplace-la si un diver s'en approche.", "Pose ton ult **derrière un coin** où l'ennemi doit s'exposer pour la casser."], "sources": [{"url": "https://www.youtube.com/watch?v=CGw4ZlAMAF4", "title": "Rocket Raccoon Guide", "author": "Paz (padswagger)"}], "summary": "Rocket Raccoon est un support de soins de zone qui fait rebondir ses orbes sur le décor, ressuscite ses alliés avec sa balise et donne un gros bonus de dégâts avec son ult. Sa survie repose entièrement sur sa mobilité.", "counters": [{"hero": "captain-america", "note": "Il te colle et trouve ta balise."}, {"hero": "venom", "note": "Même chose avec ses dives."}, {"hero": "iron-fist", "note": "Une fois sur toi, c'est fini sans aide."}, {"hero": "hela", "note": "Elle force tes dashes de loin."}], "sections": [{"kind": "tips", "lead": "Comme tous les supports, Rocket gagne en chargeant son ult plus vite que l'adversaire, sans mourir.", "items": ["**Avant le fight**, glisse des dégâts pour charger ton ult.", "**Pendant le fight**, concentre-toi sur les soins et la survie.", "Ne garde pas tes dashes de côté pour rien, mais **ne les gaspille pas** avant que les divers arrivent."], "title": "Philosophie de jeu", "diagram": "pocket"}, {"key": "Clic D", "lead": "Des orbes qui soignent en passant près des alliés et en les touchant directement. Ils rebondissent sur les murs et restent un moment sur place.", "items": ["Fais **rebondir les orbes** sur le sol et les murs pour toucher plusieurs alliés.", "Vise **les pieds** de tes alliés.", "Les orbes **ralentissent près des alliés** : les soins collent mieux.", "Ne vide pas ton chargeur **juste avant que ton équipe engage**."], "title": "Orbes de soin"}, {"key": "Clic G", "lead": "Une rafale rapide qui fait beaucoup de dégâts de près, mais perd vite en puissance avec la distance.", "items": ["Sers-t'en pour **casser les objets** adverses (tourelles de Namor, ults posées).", "Si deux Rocket lancent leur ult en même temps, **casse la sienne** en premier.", "Pendant une **ult de support alliée**, tu peux passer aux dégâts."], "title": "Tir laser"}, {"lead": "Une balise qui distribue des packs d'armure et de super-saut, et ressuscite un allié tombé à portée.", "items": ["Place-la **à l'abri**, tout en restant à portée du fight.", "Récupérée intacte, elle **revient vite**. Cassée, elle met très longtemps.", "Contre des flankers (**Captain America, Iron Fist**), surveille-la et **déplace-la** avant qu'ils la cassent.", "Pose-la **avant** que tes alliés soient en danger : un petit recul, la balise, puis retour aux soins."], "title": "Balise de résurrection", "ability": "Battle Rebirth Beacon"}, {"key": "Maj", "lead": "Deux charges de dash, la course sur les murs et un vol plané. Ta survie dépend de comment tu bouges.", "items": ["Contre **Hela, Hawkeye, Black Widow** : dash derrière un couvert.", "Contre **Iron Fist, Spider-Man, Venom** : dash vers ton équipe pour qu'elle s'occupe du diver.", "Contre **The Thing, Emma Frost** : dash à l'opposé pour les forcer à te poursuivre.", "Accroche-toi à un mur puis **dash vers le haut** : tu disparais de l'écran adverse.", "Passe **d'un couvert à l'autre** pour que Hela ne puisse pas forcer tes dashes."], "title": "Jetpack et murs", "ability": "Jetpack Dash · Wild Crawl"}, {"key": "Q", "lead": "Un amplificateur posé au sol qui donne bonus de dégâts et vie bonus à tous les alliés en vue. Il peut être détruit.", "items": ["Place-le **derrière un coin** : l'ennemi doit s'exposer pour le casser.", "Le bonus dépend de la **ligne de vue** : ne le cache pas complètement si tu comptes avancer.", "Ne l'utilise pas **trop tôt** : l'ennemi n'a qu'à reculer.", "C'est une ult de **retournement** : quand l'ennemi pousse en croyant gagner, pose-la et renverse le fight.", "Pour contrer une grosse ult de DPS, l'**autre support** est souvent mieux placé."], "title": "Ultime", "ability": "C.Y.A."}, {"kind": "mistakes", "items": ["Gaspiller **ses dashes** avant que les divers arrivent.", "Laisser la balise **se faire casser** au lieu de la déplacer.", "Poser l'ult **à découvert** ou trop tôt.", "Tirer au laser **en plein fight** au lieu de soigner.", "Vider son chargeur **juste avant l'engage**."], "title": "Erreurs fréquentes"}], "synergies": [{"hero": "magneto", "note": "Une compo groupée où tes soins de zone brillent."}, {"hero": "emma-frost", "note": "Même logique."}, {"hero": "groot", "note": "Ses murs font rebondir tes orbes."}, {"hero": "the-punisher", "note": "Ton ult booste ses dégâts constants."}, {"hero": "winter-soldier", "note": "Un brawler qui profite de tes soins."}, {"hero": "luna-snow", "note": "Un duo de supports solide."}], "difficulty": 1, "patch_note": "Guide tiré d'une vidéo de Paz (padswagger), reformulé en français. Les chiffres du kit ont été retirés car ils changent à chaque saison ; team-ups et derniers changements sont à jour (saison 10.5) dans la section dédiée.", "kit": {"season": "Saison 10.5", "health": "", "abilities": [], "teamups": [{"name": "Ammo Overload", "partners": ["the-punisher"], "key": "", "text": "Rocket pose un appareil qui accélère la cadence des alliés. **Amélioré :** Munitions infinies en plus."}, {"name": "Fantastic Amplifier", "partners": ["mister-fantastic"], "key": "", "text": "Un amplificateur augmente l'élasticité et le gonflement. **Amélioré :** Les coups projettent les ennemis."}, {"name": "Mammalian Bond", "partners": ["squirrel-girl"], "key": "", "text": "Glands de vitalité qui soignent et réduisent les cooldowns. **Amélioré :** Plus de charges."}, {"name": "Planet X Pals", "partners": ["groot"], "key": "", "text": "Spores épineuses qui blessent et soignent. **Amélioré :** Rocket peut monter sur Groot."}, {"name": "Rocket Network", "partners": ["peni-parker"], "key": "", "text": "Le nid d'araignées largue des drones et des kits d'armure. **Amélioré :** Régénération et plus d'unités."}], "changes": [{"season": "Saison 10", "text": "Tous les Strategists : l'ult se charge un peu moins vite (65 % du soin et 50 % des dégâts convertis en énergie, au lieu de 70 % et 55 %)."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · changements : patch notes des saisons 10 et 10.5", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'rocket-raccoon' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"tags": ["Combos", "Absorption", "Contrôle", "Anti-ult"], "tldr": ["**Passe derrière les murs et les obstacles** pour arriver au contact avec un maximum de vie.", "Le coup de pied doit **toucher** pour garantir ton absorption, qui coûte cher si tu la rates.", "Lance ton ult **en premier**, jamais après deux ults adverses."], "combos": [{"note": "Envoie une cible au milieu de son équipe.", "steps": [{"key": "", "label": "Dash"}, {"key": "", "label": "Zone d'attraction"}, {"key": "E", "label": "coup de pied"}], "title": "Regroupement"}], "sources": [{"url": "https://www.youtube.com/watch?v=LGAj_h43m5A", "title": "Rogue Guide", "author": "Paz (padswagger)"}], "summary": "Rogue est un tank exigeant, basé sur les combos : elle bloque les dégâts, projette et regroupe les ennemis, et absorbe les capacités de ses adversaires. Son ult empêche l'ennemi de lancer ses propres ults.", "counters": [{"hero": "the-thing", "note": "Son impact au sol t'immobilise."}, {"hero": "hela", "note": "Elle te punit si tu ne joues pas à couvert."}, {"hero": "phoenix", "note": "Même chose."}, {"hero": "winter-soldier", "note": "Son dash coupe ta mobilité."}, {"hero": "wolverine", "note": "Il t'oblige à jouer lentement."}, {"hero": "invisible-woman", "note": "Ses poussées cassent tes combos."}], "sections": [{"kind": "tips", "lead": "Rogue demande de l'initiative et de l'efficacité. Ton plan change selon la force de ton front.", "items": ["Avec un **front plus fort** que l'adversaire, avance au centre et écrase-le.", "Avec un **front plus faible**, verrouille un **couloir latéral** pour offrir de bons angles à tes DPS.", "Sans cooldowns disponibles, **ne t'engage pas à fond**.", "Ne bloque pas tout : certains dégâts peuvent être encaissés et **chargent l'ult** de tes supports."], "title": "Philosophie de jeu", "diagram": "brawl"}, {"key": "Clic D · Clic G", "lead": "Une garde frontale qui réduit fortement les dégâts reçus. Pendant la garde, tu peux charger une ruée qui projette une onde d'énergie.", "items": ["Elle encaisse l'**ult de Magneto** ou même celle d'**Iron Man** si tu es pleine de vie.", "Pour protéger un allié d'Iron Man, **fonce intercepter** le projectile : l'explosion touche quand même autour de toi.", "L'onde part **après** la ruée : tu peux fuir, te retourner, et toucher quand même.", "Plus tu as bloqué de dégâts, **plus la ruée fait mal**."], "title": "Garde et ruée", "ability": "Southern Brawl"}, {"key": "E", "lead": "Une charge suivie d'un coup de pied qui projette en l'air. Tu peux ensuite voler un instant, lancer deux coups de pied à distance, puis t'écraser au sol.", "items": ["Enchaîne un **coup de pied à distance juste après la projection** : il touche à coup sûr.", "Au front, utilise-le pour **écarter un tank** et ouvrir le fight.", "Sur un angle, **renvoie une cible vers ton équipe**.", "En dive, **isole un support** ou un peeler (Mister Fantastic).", "Contre **Groot**, reste en l'air pour éviter ses murs.", "Combo : **deux coups de poing, coup de pied, tir de pied, slam, tir de pied**."], "title": "Coup de pied", "ability": "Kinetic Kick"}, {"lead": "Une charge, puis une zone qui attire tous les ennemis vers toi au moment où tu le décides.", "items": ["L'attraction **interrompt les déplacements** (dash de Black Panther, de Winter Soldier…), mais c'est dur à synchroniser.", "Elle **ramène les ennemis** dans une ult alliée (Moon Knight, Namor, Daredevil).", "Combo de regroupement : **dash, zone d'attraction, coup de pied** pour envoyer une cible au milieu de son équipe."], "title": "Attraction", "ability": "Fatal Attraction"}, {"lead": "Tu fonces sur une cible et absorbes son énergie : un bonus selon son rôle, et souvent l'une de ses capacités.", "items": ["Rater coûte **très cher** : garantis-la avec le coup de pied.", "**Tank** : vie maximale bonus. **DPS** : gros bonus de dégâts, idéal pour tes combos. **Support** : régénération.", "Certains héros te donnent une **capacité** (icône au-dessus de leur tête), les autres rechargent ton dash.", "Voler une **boule de neige de Luna** ou une **poussée d'Invisible Woman** peut contrer une ult de Doctor Strange.", "Pendant l'absorption, la cible est au sol : tu **retires son bouclier** un instant."], "title": "Absorption", "ability": "Ability Absorption"}, {"key": "Q", "lead": "Une aura qui vide la charge d'ult des ennemis proches de l'avoir, et te donne des bonus selon les rôles touchés.", "items": ["**Prends l'initiative** : lance-la et dive sur le support qui allait utiliser son ult.", "Sans ult de support adverse prête, vise le **Star-Lord ou le Punisher** avant qu'il lance la sienne.", "La lancer **après deux ults adverses**, c'est la gâcher.", "Tu peux être **étourdie** pendant l'incantation (étranglement d'Emma) : lance-la à couvert.", "Elle permet aussi de **tenir le point** très longtemps."], "title": "Ultime", "ability": "Heartbreaker"}, {"kind": "mistakes", "items": ["Rater l'**absorption** sans l'avoir préparée.", "Bloquer **tous** les dégâts au lieu des plus dangereux.", "S'engager **sans cooldowns**.", "Lancer l'ult **trop tard** dans le fight.", "Incanter l'ult **à découvert** face à une Emma."], "title": "Erreurs fréquentes"}], "synergies": [{"hero": "gambit", "note": "Son ult te laisse traverser l'équipe adverse."}, {"hero": "magneto", "note": "Sa bulle te laisse arriver au contact."}, {"hero": "moon-knight", "note": "Tu envoies les ennemis dans ses ankhs et son ult."}, {"hero": "phoenix", "note": "Tu regroupes les ennemis pour ses explosions."}, {"hero": "winter-soldier", "note": "Un brawler qui suit tes combos."}], "difficulty": 3, "patch_note": "Guide tiré d'une vidéo de Paz (padswagger), reformulé en français. Les chiffres du kit ont été retirés car ils changent à chaque saison ; team-ups et derniers changements sont à jour (saison 10.5) dans la section dédiée.", "kit": {"season": "Saison 10.5", "health": "", "abilities": [], "teamups": [{"name": "Explosive Entanglement", "partners": ["magneto"], "key": "", "text": "Un champ magnétique renforce la posture défensive de Rogue. **Amélioré :** Ajoute un recul et des dégâts aux murs."}, {"name": "Mr. & Mrs. X", "partners": ["gambit"], "key": "", "text": "Explosions cinétiques sur les attaques. **Amélioré :** Verrouille Hearts as One."}, {"name": "Telekinetic Beatdown", "partners": ["phoenix"], "key": "", "text": "Coups télékinétiques qui sautent d'une cible à l'autre. **Amélioré :** Étincelles et frappes en plus."}], "changes": [{"season": "Saison 10", "text": "Bouclier régénérant 250 → 275, absorption de Vanguard 125 → 150, énergie 15/s → 25/s."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · changements : patch notes des saisons 10 et 10.5", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'rogue' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, role, status, content) values ('role', 'Strategist', 'published', $j${"tags": ["Placement", "Gestion d'ult", "Lecture du fight"], "tldr": ["Ton vrai objectif : **charger ton ult** le plus vite possible.", "**Ne meurs pas en plein fight** : sans toi, ton équipe tombe presque toujours.", "**Fais plus que soigner** : dégâts et utilitaire gagnent les fights."], "sources": [{"title": "Guide général du support", "author": "Paz (padswagger)"}, {"title": "Useless Strategists", "author": "Auteur à préciser"}], "summary": "Soigner, c'est le minimum. Ce qui sépare un bon Strategist d'un mauvais, c'est de rester en vie, de bien gérer son ult et d'apporter plus que du soin.", "counters": [], "sections": [{"kind": "tips", "lead": "Soins, dégâts et survie servent tous le même but. Penser « ult » t'indique comment jouer chaque héros.", "items": ["Tout ce que tu fais doit servir à **charger ton ult le plus vite possible**.", "**Adam Warlock** prend des angles et fait des dégâts. **Rocket** reste derrière son équipe et soigne en continu.", "Un héros joué à contre-emploi (Adam qui soigne en retrait, Rocket qui flanque) **charge lentement et apporte peu**."], "title": "Ton vrai objectif : charger ton ult", "diagram": "heal"}, {"lead": "Ta mort en plein fight, surtout avec ton ult chargée, fait presque toujours perdre le fight.", "items": ["Ne te place **jamais devant tes tanks**, et à peine à côté. Exceptions : pendant ton ult, ou quand le fight est déjà gagné.", "Joue **près d'une couverture**. Test : si une Scarlet Witch lançait son ult à côté de toi, aurais-tu un mur pour te cacher ?", "Exercice : pendant une partie rapide entière, **reste collé à un mur ou à un obstacle**. Tu sentiras vite la différence.", "Survivre ne suffit pas : **trop en retrait, tu n'apportes plus rien**."], "title": "Rester en vie"}, {"lead": "Il n'y a pas de bon placement universel : tout dépend de ce que l'ennemi veut te faire.", "items": ["Contre un **bagarreur au corps à corps** (The Thing) : garde tes distances, tes tanks ne te protègent pas de lui.", "Contre le **dive** (Venom, Captain America) : au contraire, **reste près de ton équipe** pour qu'elle te défende.", "Contre le **poke à distance** (Hawkeye, Hela) : joue **à couvert**, derrière les murs et les boucliers."], "title": "Se placer selon l'adversaire"}, {"lead": "Une ult de support peut gagner ou perdre un fight à elle seule. Le timing compte plus que tout.", "items": ["Seulement **pendant un vrai fight** : ni avant (l'ennemi recule), ni après (trop tard).", "Regarde le **tableau (Tab)** : si personne n'avance ni ne recule, le fight est serré et ton ult peut le faire basculer.", "**Deux morts ou plus** d'un côté ? Le fight est décidé : garde ton ult pour le suivant.", "Ne réponds pas **automatiquement** à l'ult d'un support adverse : attends le dernier moment utile. Certaines ults durent plus longtemps que d'autres.", "Avec l'autre support, **annoncez qui ult en premier**.", "Bonnes raisons d'ult : **contrer** une ult dangereuse, **sauver** une cible clé, **retourner** un fight important (le dernier avant un checkpoint en Convoi)."], "title": "Bien utiliser ton ult"}, {"kind": "tips", "lead": "Si les deux équipes soignent, c'est celle qui fait le plus en plus du soin qui gagne.", "items": ["Ajoute des **dégâts dès que tu peux** : ce sont les dégâts qui gagnent les fights.", "Essai : une partie où **tes dégâts dépassent tes soins**. Ton équipe tiendra quand même.", "**Luna Snow, Invisible Woman** : place-toi pour que tes tirs touchent à la fois tes tanks et les ennemis.", "**Rocket** : tire sur quiconque s'approche trop. **Cloak & Dagger** : passe en Cloak de temps en temps.", "**Adam Warlock, Mantis** : tire en continu.", "Pense à ton **utilitaire** : attraction d'Invisible Woman, stuns de Luna Snow et de Mantis, bonus de dégâts de Mantis."], "title": "Faire plus que soigner"}, {"lead": "Parfois, tu ne peux sauver qu'une personne. Choisis celle qui pèse le plus sur la suite.", "items": ["Un **Punisher en ult** vaut le coup si l'ennemi n'a pas de tank pour l'encaisser.", "Un **Groot proche de son ult** vaut le coup si tu as un combo prêt derrière.", "**Éliminer une menace** (une Hela isolée) revient à soigner toute ton équipe à l'avance."], "title": "Choisir qui soigner"}, {"lead": "Savoir quelle ult arrive en face, c'est garder la bonne réponse au bon moment.", "items": ["Repère : chacun récupère son ult **environ tous les deux fights**. Plus lent en triple support, plus rapide si quelqu'un meurt tôt.", "Exercice : regarde **en replay** une partie d'un ami où tu n'étais pas, **masque les ults**, devine qui l'a après chaque fight, puis vérifie.", "**Annonce ces infos** à ton équipe."], "title": "Suivre les ults adverses"}, {"kind": "mistakes", "items": ["Jouer **devant ou à côté** de ses tanks.", "Lancer son ult **hors d'un vrai fight**.", "Ult **en même temps** que l'autre support.", "**Ne faire que soigner.**", "Rester **si loin** qu'on n'apporte plus rien."], "title": "Erreurs fréquentes"}], "synergies": [], "difficulty": 1, "patch_note": "Principes valables quelle que soit la saison. Les exemples de héros dépendent de la méta du moment."}$j$::jsonb) on conflict (role) where kind = 'role' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"tags": ["Pression", "Anti-dive", "Contrôle", "Accessible"], "tldr": ["Ne reste pas au centre à tirer sur les tanks : prends des **angles** et force les cooldowns.", "Cherche les **2 contre 1** : avec un heal derrière toi, tu gagnes presque tous les duels.", "Ton ult n'a pas besoin de tuer : elle sert à **contrôler le tempo** du fight."], "sources": [{"url": "https://www.youtube.com/watch?v=cPujUz0S7nQ", "title": "Scarlet Witch Guide", "author": "Paz (padswagger)"}], "summary": "Scarlet Witch est une DPS de pression constante : elle use les cibles fragiles depuis des angles décalés pour forcer les cooldowns adverses, protège sa backline des divers et contrôle le fight avec une ult qui oblige l'ennemi à reculer.", "counters": [{"hero": "groot", "note": "Les compos groupées ne te laissent pas de cible isolée."}, {"hero": "magneto", "note": "Même chose, et sa bulle protège ses alliés."}, {"hero": "emma-frost", "note": "Elle peut t'étrangler pendant ton ult."}, {"hero": "star-lord", "note": "Avec des soins, il fait plus de dégâts que toi."}, {"hero": "hela", "note": "Même chose."}], "sections": [{"kind": "tips", "lead": "Tu ne gagneras pas tous tes duels, mais tu peux forcer les bulles de Cloak, les poussées d'Invisible Woman, les boules de neige de Luna ou les runes de Loki.", "items": ["Prends une **hauteur qui donne accès aux deux côtés** du fight : tu peux poker au centre et défendre ta backline.", "Joue en **duo** avec un autre DPS sur son angle : ta présence le rend beaucoup plus dur à déloger.", "Va chercher les **traînards** isolés de leur équipe.", "Sur un angle offensif, empêche les divers d'atteindre **ton tireur** (Hawkeye…)."], "title": "Philosophie de jeu", "diagram": "angle"}, {"kind": "tips", "lead": "Avant la refonte, elle combinait un rayon à verrouillage généreux et des projectiles explosifs. L'idée reste la même : rester active en permanence.", "items": ["Garde **toujours une capacité de dégâts en rechargement** : tes dégâts de base sont faibles, chaque cycle compte.", "Ouvre un duel avec tes **projectiles**, puis finis la cible.", "Entraîne ta visée sur les **cibles fragiles** plutôt que de te rabattre sur les tanks."], "title": "Dégâts"}, {"kind": "tips", "lead": "Son étourdissement de zone était son outil le plus polyvalent.", "items": ["Il pouvait **couper les ults** à incantation : Doctor Strange, Storm, Cloak & Dagger.", "Pose-le **sur tes supports** contre le dive : les divers hésitent à entrer.", "Étourdis le **support qui soigne** ta cible en duel.", "Pendant une ult adverse, il **immobilise une cible** pour qu'un allié la tue."], "title": "Contrôle"}, {"kind": "tips", "lead": "Elle pouvait devenir intangible et se déplacer très vite, tout en ramassant les packs de soin et en recevant les soins alliés.", "items": ["Erreur courante : utiliser sa mobilité **pour monter** en hauteur avant le fight. Marche plutôt.", "Joue **près des packs de soin** : frappe, repars te soigner, reviens."], "title": "Mobilité"}, {"key": "Q", "lead": "Une ult qu'on incante quelques secondes avant une énorme explosion autour de toi. Tout le monde va te viser.", "items": ["Ne la garde pas **trop longtemps**, et n'essaie pas d'en faire **trop** : elle sert à forcer l'ennemi à reculer.", "Si l'ennemi lance une grosse ult offensive avant vous, utilise la tienne pour **bloquer son avancée** et gagner du temps.", "Incante **derrière un mur** et ne sors qu'au dernier moment.", "Force les **bulles de Magneto** et méfie-toi d'une **Emma** en diamant.", "Ne vole pas **trop haut** : tu couvres moins de terrain au sol."], "title": "Ultime", "ability": "Reality Erasure"}, {"kind": "mistakes", "items": ["Rester **au centre** sur les tanks.", "Gâcher sa **mobilité** avant le fight.", "Laisser ses capacités **inutilisées**.", "Incanter l'ult **à découvert**.", "Garder l'ult **plusieurs fights**."], "title": "Erreurs fréquentes"}], "synergies": [{"hero": "venom", "note": "Tu suis facilement un tank de dive."}, {"hero": "captain-america", "note": "Même chose."}, {"hero": "phoenix", "note": "Votre duo sur un angle est très dur à déloger."}, {"hero": "hawkeye", "note": "Tu protèges son angle des divers."}, {"hero": "rocket-raccoon", "note": "Son ult te donne assez de vie pour survivre à la tienne."}], "difficulty": 1, "patch_note": "Attention : Scarlet Witch a été retravaillée en saison 10, et cette vidéo de Paz date d'avant. Le plan de jeu reste valable, mais le détail des capacités a pu changer. Les chiffres et team-ups ont été retirés : vérifie en jeu.", "kit": {"season": "Saison 10.5", "health": "", "abilities": [], "teamups": [{"name": "Chaos Collision", "partners": ["the-hood"], "key": "", "text": "Zone arcanique et téléportation. **Amélioré :** Ajoute une onde de choc."}, {"name": "Hex Fireworks", "partners": ["jubilee"], "key": "", "text": "Détonation de sceau plasmoïde. **Amélioré :** Ajoute un soin continu."}, {"name": "Metallic Chaos", "partners": ["magneto"], "key": "", "text": "Coup d'épée du chaos (cooldown 18 s depuis la saison 10). **Amélioré :** Le Mag-Cannon devient des épées chargées."}, {"name": "Sorcerers Supreme", "partners": ["doctor-strange"], "key": "", "text": "Salve de missiles mystiques. **Amélioré :** Devient activable à volonté."}], "changes": [{"season": "Saison 10", "text": "Refonte : nouveau Scarlet Hex (40 de dégâts, pose une marque du chaos), Chaos Control 85/s → 75/s, vitesse de Mystic Projection +35 % au lieu de +50 %."}, {"season": "Saison 10.5", "text": "Chthonian Burst 40 → 35 de dégâts de zone."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · changements : patch notes des saisons 10 et 10.5", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'scarlet-witch' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"tags": ["Spam", "Anti-dive", "Couloirs", "Charge d'ult"], "tldr": ["**Spamme au centre** : boucliers, tanks, puis backline exposée.", "Utilise **Mammal Bond avant** ton gland étourdissant pour ne pas bloquer tes cooldown.", "Lance ton ult **dès que tu l'as**, en la faisant rebondir sur un mur."], "sources": [{"url": "https://www.youtube.com/watch?v=hfHY0afkEUg", "title": "Squirrel Girl Guide", "author": "Paz (padswagger)"}], "summary": "Squirrel Girl a un plan de jeu simple : elle arrose le couloir principal de glands explosifs pour mettre la pression sur les tanks et les fragiles, puis lance son ult dès qu'elle l'a. Ses glands étourdissants en font aussi une excellente gardienne contre le dive.", "counters": [{"hero": "magneto", "note": "Son bouclier bloque tes glands importants."}, {"hero": "iron-man", "note": "Difficile à toucher dans les airs."}, {"hero": "ultron", "note": "Même problème."}, {"hero": "human-torch", "note": "Même problème."}, {"hero": "hela", "note": "Elle te surclasse sur les longues lignes de vue."}, {"hero": "hawkeye", "note": "Même chose."}, {"hero": "black-widow", "note": "Avec un bonus de dégâts, elle te tue de loin."}], "sections": [{"kind": "tips", "lead": "Reste simple : pression constante, et tu apporteras beaucoup dans la plupart des parties. En faire trop, c'est mourir souvent.", "items": ["Elle brille sur les cartes à **passages étroits**.", "Joue en **gardienne de ta backline** : quand un diver entre, il devient ta priorité.", "Vise d'abord **le tank à portée**, puis les fragiles bas en vie."], "title": "Philosophie de jeu", "diagram": "choke"}, {"key": "Clic G", "lead": "Des glands qui explosent au sol. Un tir direct fait plus mal, mais l'explosion compense les ratés.", "items": ["Ce sont des projectiles qui **retombent** : vise plus haut à longue distance.", "Ils **rebondissent sur les murs** et n'explosent qu'en touchant le sol.", "Tire **vers le sol en angle** pour les faire rebondir par-dessus un bouclier.", "Vise **la moitié basse** des cibles.", "Teste des **trajectoires** en partie personnalisée pour toucher les positions habituelles des supports."], "title": "Glands explosifs", "ability": "Burst Acorn"}, {"key": "Clic D", "lead": "Un gros gland qu'on charge pour aller plus vite, qui étourdit si il touche directement et rebondit plusieurs fois.", "items": ["**Étourdis un tank** mal placé pour offrir un pick à ton équipe.", "Il **immobilise une ult mobile** (Magik, Scarlet Witch, Spider-Man) sans l'annuler, et fait tomber les volants.", "Contre un **diver** (Black Panther), garde-en un pour protéger tes supports.", "Les bons divers attendent que tu l'aies lancé : **garde-le** quand un dive ou une ult arrive.", "Astuce : un **coup de mêlée** annule la charge sans le lancer."], "title": "Gland étourdissant", "ability": "Squirrel Blockade"}, {"lead": "Un saut vertical, plus haut si tu sautes avant.", "items": ["Contre des **tireurs** (Hela, Hawkeye, Phoenix, Punisher), ne saute pas devant eux : tu deviens prévisible.", "Contre le **dive** (Venom, Captain America, Psylocke), garde-le toujours pour fuir.", "Contre un **brawl**, il te permet de reculer et d'esquiver l'ult de The Thing ou de Moon Knight.", "Sur un **plafond en pente**, il te propulse à l'horizontale, bien moins prévisible."], "title": "Saut à la queue", "ability": "Tail Bounce"}, {"lead": "Recharge instantanément ton arme et te donne une charge bonus d'une capacité pendant quelques secondes.", "items": ["Presque toujours pour **un gland étourdissant de plus**.", "Active-le **avant** d'utiliser tes capacités de base : pendant l'effet, leurs cooldown sont gelés.", "Contre le dive, ça te garde **un gland et un saut** en réserve."], "title": "Mammal Bond"}, {"key": "Q", "lead": "Une horde d'écureuils qui fonce, rebondit vers l'ennemi le plus proche à chaque mur et fait mal à chaque passage. Elle peut être détruite.", "items": ["Elle se charge **très vite** : ne la garde jamais.", "Fais-la **rebondir sur un mur** : elle survit bien plus longtemps.", "Lance-la **à mi-distance** et ajoute un gland sur un fragile pour l'achever.", "Forcer une ult de support, c'est **bien** : tu auras la suivante avant eux.", "Le **payload** compte comme un mur."], "title": "Ultime", "ability": "Unbeatable Squirrel Tsunami"}, {"kind": "mistakes", "items": ["Sauter **face aux tireurs** en début de fight.", "Lancer le gland étourdissant **avant** Mammal Bond.", "**Garder l'ult** pour le moment parfait.", "Partir en **flank** au lieu de tenir la backline.", "Lancer l'ult **en ligne droite**, facile à détruire."], "title": "Erreurs fréquentes"}], "synergies": [{"hero": "emma-frost", "note": "Un front qui te laisse arroser au centre."}, {"hero": "doctor-strange", "note": "Même chose."}, {"hero": "the-punisher", "note": "Deux DPS de dégâts constants au centre."}, {"hero": "hela", "note": "Elle gère les volants et les tireurs."}, {"hero": "psylocke", "note": "Elle finit les supports que tu as affaiblis."}, {"hero": "mantis", "note": "Son bonus de dégâts réduit le nombre de glands nécessaires."}], "difficulty": 1, "patch_note": "Guide tiré d'une vidéo de Paz (padswagger), reformulé en français. Les chiffres du kit ont été retirés car ils changent à chaque saison ; team-ups et derniers changements sont à jour (saison 10.5) dans la section dédiée.", "kit": {"season": "Saison 10.5", "health": "", "abilities": [], "teamups": [{"name": "ESU Alumnus", "partners": ["spider-man"], "key": "", "text": "Bombe de toile qui explose et laisse une zone de toile. **Amélioré :** La toile collante reste au sol."}, {"name": "Mammalian Bond", "partners": ["rocket-raccoon"], "key": "", "text": "Glands de vitalité qui soignent et réduisent les cooldowns. **Amélioré :** Plus de charges."}, {"name": "Squirrel Missile", "partners": ["iron-man"], "key": "", "text": "Un missile-écureuil à tête chercheuse. **Amélioré :** En tire un avec Squirrel Blockade."}], "changes": [], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · changements : patch notes des saisons 10 et 10.5", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'squirrel-girl' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"tags": ["Polyvalent", "Anti-volant", "Mobilité", "Esquive"], "tldr": ["Au début de chaque partie, **identifie qui tu dois marquer** : flanker, sniper ou volant.", "Tes **roulades** servent à esquiver et recharger, jamais à te déplacer.", "Garde **tes deux roulades** et place-toi avant de lancer ton ult."], "sources": [{"url": "https://www.youtube.com/watch?v=71rolJfkehc", "title": "Star-Lord Guide", "author": "Paz (padswagger)"}], "summary": "Star-Lord change de rôle à chaque partie : flanker qui tue les supports, chasseur de volants ou farmeur de tanks qui charge son ult à toute vitesse. Ses roulades le rendent intouchable un instant et rechargent ses pistolets.", "counters": [{"hero": "hela", "note": "Un headshot et tu es presque mort."}, {"hero": "namor", "note": "Ses tourelles t'usent si ton équipe ne les casse pas."}, {"hero": "magneto", "note": "Son ult gâche la tienne."}, {"hero": "iron-fist", "note": "Très dur à tuer, il te ramène au sol."}], "sections": [{"kind": "tips", "lead": "Star-Lord s'adapte à ce dont l'équipe a besoin. Il n'a pas besoin de tuer à chaque fight : chasser les ennemis de leurs positions suffit souvent.", "items": ["Contre un **flanker, un sniper ou un volant** : marque-le en priorité.", "Contre une compo **brawl/poke** (Strange, Magneto) : mets la pression sur la backline.", "Contre une compo **avec Namor ou sans ult défensive** : farme les tanks pour ton ult, en attendant que les tourelles soient gérées.", "Après un fight gagné, utilise ta mobilité pour **te placer** immédiatement pour le suivant."], "title": "Philosophie de jeu", "diagram": "flank"}, {"key": "Clic G", "lead": "Deux pistolets qui crachent une rafale rapide. La dispersion augmente vite pendant le tir.", "items": ["Commence la rafale **sur la tête**, puis descends vers le **cou** : la dispersion touche plus de la hitbox.", "Les dégâts baissent vite avec la distance, mais **poivrer de loin** suffit à chasser un ennemi.", "Chasse un Hela ou un Namor d'une **hauteur**, puis prends-la toi-même.", "Contre une **Storm**, c'est ta cible numéro un."], "title": "Pistolets", "ability": "Element Guns"}, {"lead": "Deux charges de roulade qui te rendent intouchable, rechargent tes pistolets et te déplacent un peu.", "items": ["Elle **esquive les ults** : Doctor Strange, Magneto, The Thing, Groot…", "En duel contre **Hela** ou **Namor**, roule au bon moment pour esquiver leurs tirs clés.", "Sur un tank isolé, tu peux t'en servir pour **recharger et finir** le kill.", "Ne l'utilise **jamais juste pour te déplacer** : tes bottes sont faites pour ça."], "title": "Roulade", "ability": "Stellar Shift"}, {"key": "Maj", "lead": "Tes bottes te font voler deux fois plus vite, mais tu ne peux pas tirer. La jauge se recharge lentement.", "items": ["Rejoins ton flank, attends que la jauge **se recharge**, puis duel : tu auras de quoi fuir.", "Pour **gagner du temps** (tenir un point), vole dans tous les sens.", "Astuce : démarre le vol et **coupe-le aussitôt** dans la même direction pour un petit élan économique.", "Garde du carburant pour **te placer avant ton ult**."], "title": "Bottes", "ability": "Rocket Propulsion"}, {"lead": "Tu tournoies quelques secondes en tirant sur tout ce qui est autour de toi.", "items": ["Elle sert à **finir** une cible ou à faire sortir **Psylocke ou Loki** de l'invisibilité.", "Quand deux ults de soin s'affrontent, **tourne au milieu** pour charger ton ult.", "Tu n'es pas invulnérable : fais-le **avec ton équipe** ou une bulle de Magneto.", "Une cible devant une autre prend **double dégâts**."], "title": "Toupie", "ability": "Blaster Barrage"}, {"key": "Q", "lead": "Tu t'envoles et vises automatiquement pendant quelques secondes. Tu ne peux plus utiliser tes bottes.", "items": ["Tu deviens la cible n°1 : place-toi **dans la vue de tes supports** et près d'un couvert.", "Contre des divers au sol (**Magik, Black Panther**), tu peux monter haut. Contre **Hela ou Namor**, reste à couvert.", "Si possible, **élimine d'abord ton contre** (la Hela) avec l'ult.", "Entre dans l'ult **avec tes deux roulades** : esquive et rechargement.", "Face à une ult de soin, tu as souvent **un court moment** pour tuer un traînard."], "title": "Ultime", "ability": "Galactic Legend"}, {"kind": "mistakes", "items": ["**Rouler pour se déplacer**.", "Brûler tout le **carburant** avant le duel.", "Ult **sans roulade** disponible.", "Monter **trop haut** en ult et rater les premières balles.", "Ignorer la **Storm ou le flanker** adverse."], "title": "Erreurs fréquentes"}], "synergies": [{"hero": "venom", "note": "Il dive avec toi et tu finis la cible."}, {"hero": "captain-america", "note": "Même idée."}, {"hero": "psylocke", "note": "Pression combinée sur la backline."}, {"hero": "hela", "note": "Elle gère l'autre Hela pendant que tu flanques."}, {"hero": "adam-warlock", "note": "Un support qui joue les angles avec toi."}, {"hero": "mantis", "note": "Son bonus de dégâts fiabilise ton ult."}], "difficulty": 2, "patch_note": "Guide tiré d'une vidéo de Paz (padswagger), reformulé en français. Les chiffres du kit ont été retirés car ils changent à chaque saison ; team-ups et derniers changements sont à jour (saison 10.5) dans la section dédiée.", "kit": {"season": "Saison 10.5", "health": "", "abilities": [], "teamups": [{"name": "Asgardians of the Galaxy", "partners": ["angela"], "key": "", "text": "Révèle une zone et cloue les ennemis au sol avec un impact. **Amélioré :** Ajoute de la vie bonus."}, {"name": "Flora Munitions", "partners": ["groot"], "key": "", "text": "Pièges d'épines qui immobilisent. **Amélioré :** Plus de pièges et de dégâts."}, {"name": "Star Blossom", "partners": ["mantis"], "key": "", "text": "Relancer la fleur de soin propage le soin (10 + 3 %/s depuis la saison 10). **Amélioré :** Déclenchement immédiat."}, {"name": "Star-Soul", "partners": ["adam-warlock"], "key": "", "text": "Téléportation sur une balise et réapparition en cocon. **Amélioré :** Les kills réduisent le cooldown de la balise."}], "changes": [{"season": "Saison 10", "text": "Bouclier régénérant 100 → 125, Blaster Barrage 75/s → 80/s."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · changements : patch notes des saisons 10 et 10.5", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'star-lord' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"tags": ["Auras", "Soutien offensif", "Vol", "Charge d'ult"], "tldr": ["Reste **au milieu de ton équipe**, assez bas pour que ton aura touche tout le monde.", "**Aura de vent** pour activer ou ramener tes alliés, **aura de foudre** quand ils sont en position.", "Incante ton ult **à l'abri** : l'animation peut être interrompue."], "combos": [{"note": "L'éclair juste après une lame annule l'animation.", "steps": [{"key": "Clic G", "label": "lame"}, {"key": "", "label": "Boost divin"}, {"key": "Clic G", "label": "lame"}, {"key": "Clic D", "label": "éclair"}], "title": "Fragile sans soins"}], "sources": [{"url": "https://www.youtube.com/watch?v=mlewjqlw91c", "title": "Storm Guide", "author": "Paz (padswagger)"}], "summary": "Storm est une DPS de soutien : elle joue au milieu de son équipe et lui donne une aura de vitesse ou de dégâts, tout en tirant des lames traversantes qui chargent vite son ult. Ce n'est pas une héroïne d'angle décalé.", "counters": [{"hero": "hulk", "note": "Il peut t'exiler hors de ton ult."}, {"hero": "the-thing", "note": "Il te fait tomber du ciel si tu t'avances."}, {"hero": "iron-man", "note": "Son ult te contre et il te bat en duel."}, {"hero": "spider-man", "note": "Tu n'as pas de fuite rapide contre lui."}, {"hero": "ultron", "note": "Il te harcèle par-dessus les boucliers."}, {"hero": "luna-snow", "note": "Ses dégâts te chassent et son ult résiste à la tienne."}], "sections": [{"kind": "tips", "lead": "Storm fait pression de façon constante, à travers ses propres dégâts et ceux qu'elle donne à son équipe. La patience est la clé.", "items": ["Joue dans un **endroit sûr au milieu de ton équipe**, proche du sol.", "Si tu veux jouer les angles décalés, prends **Psylocke ou Hela** à la place.", "Elle brille avec et contre les compos **poke et brawl**, beaucoup moins contre le **dive**."], "title": "Philosophie de jeu", "diagram": "highground"}, {"key": "Clic G · Clic D", "lead": "Des lames traversantes, et un éclair instantané qui frappe en ligne verticale.", "items": ["Les lames **traversent les ennemis** : excellente charge d'ult en tirant dans un groupe.", "Pas de headshot, et une **perte de dégâts** à distance.", "Lance l'éclair **juste après une lame** pour annuler l'animation.", "L'éclair sert surtout à **finir une cible**."], "title": "Lames de vent et éclair", "ability": "Wind Blade · Bolt Rush"}, {"lead": "Une aura sphérique autour de toi : vent pour la vitesse, foudre pour les dégâts. Monte trop haut et tes alliés en sortent.", "items": ["**Vent** : active plus vite un allié qui doit se placer (The Thing qui veut le contact, Hela qui rejoint son angle).", "**Vent** aussi pour **sauver un allié trop avancé** ou **ramener ton équipe** du spawn après un fight gagné.", "**Foudre** dès que tes alliés sont **en position** : un Punisher en ult, une Black Widow sur son angle.", "Début de fight typique : **vent pour se placer, puis foudre**."], "title": "Auras", "ability": "Weather Control"}, {"lead": "Renforce temporairement ton aura active. Son cooldown ne démarre qu'à la fin de l'effet.", "items": ["**Vent renforcé** : ton équipe va plus vite et l'ennemi est ralenti, idéal pour un brawl.", "**Foudre renforcée** : gros bonus de dégâts et dégâts de zone sur les ennemis proches.", "Combo : **lame, boost, lame, éclair** pour éliminer un fragile sans soins."], "title": "Boost divin", "ability": "Goddess Boost"}, {"key": "Q", "lead": "Tu choisis où commencer, puis tu deviens un ouragan qui blesse et aspire les ennemis. Tu gagnes beaucoup de vie bonus.", "items": ["L'**incantation** peut être interrompue : lance-la depuis ton équipe.", "Attends-toi à une **ult de soin** en réponse : cherche le traînard hors de la zone.", "À la fin, tu réapparais **au centre de l'ouragan** : ne va pas trop loin dans l'équipe adverse.", "Attention à **Iron Man** (son ult te tue) et **Phoenix** (elle retire ta vie bonus).", "Astuce : tu peux la lancer **en revenant du spawn** pour retourner un fight encore en cours.", "Elle peut **contrer une ult mobile** adverse (Winter Soldier, Magik)."], "title": "Ultime", "ability": "Omega Hurricane"}, {"kind": "mistakes", "items": ["Jouer **sur un angle isolé** loin de l'équipe.", "Voler **trop haut** : l'aura ne touche plus personne.", "Rester en **foudre** quand l'équipe doit se placer ou revenir.", "Incanter l'ult **à découvert**.", "Finir l'ult **au milieu de l'ennemi**."], "title": "Erreurs fréquentes"}], "synergies": [{"hero": "magneto", "note": "Ses boucliers te gardent en sécurité au centre."}, {"hero": "emma-frost", "note": "Même chose."}, {"hero": "the-punisher", "note": "Ton aura de foudre le rend terrifiant."}, {"hero": "winter-soldier", "note": "Un DPS qui reste avec l'équipe et profite de l'aura."}, {"hero": "black-widow", "note": "Ton aura rend ses headshots mortels."}, {"hero": "luna-snow", "note": "Le support le plus sûr à côté de toi."}], "difficulty": 1, "patch_note": "Guide tiré d'une vidéo de Paz (padswagger), reformulé en français. Les chiffres du kit ont été retirés car ils changent à chaque saison ; team-ups et derniers changements sont à jour (saison 10.5) dans la section dédiée.", "kit": {"season": "Saison 10.5", "health": "", "abilities": [], "teamups": [{"name": "Cosmic Cyclone", "partners": ["adam-warlock"], "key": "", "text": "Soul Bond donne un boost de vitesse. **Amélioré :** Ajoute un boost de dégâts."}, {"name": "Damisa-Yao", "partners": ["black-panther"], "key": "", "text": "Explosion élémentaire de l'armure qui ralentit et marque. **Amélioré :** Projette les ennemis vers Black Panther."}, {"name": "Gods of Thunder", "partners": ["thor"], "key": "", "text": "Rayon de foudre. **Amélioré :** Bolt Rush devient un éclair en chaîne qui rebondit."}, {"name": "Jaws of Fate", "partners": ["jeff-the-land-shark"], "key": "", "text": "Averse qui soigne. **Amélioré :** Jeff peut nager dans une tornade (Jeff-nado)."}, {"name": "Storming Ignition", "partners": ["human-torch"], "key": "", "text": "Un vortex de feu attire les ennemis. **Amélioré :** Allume des ouragans enflammés."}], "changes": [], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · changements : patch notes des saisons 10 et 10.5", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'storm' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"tags": ["Dégâts constants", "Anti-volant", "Tourelle", "Accessible"], "tldr": ["**Mets la pression** sur les bonnes cibles au lieu de vider ton chargeur sur un tank soigné.", "**Change d'arme avant** de te montrer : le changement n'est pas instantané.", "Prépare une **tyrolienne de sortie** avant de poser ta tourelle en position risquée."], "sources": [{"url": "https://www.youtube.com/watch?v=T0d2S3gRW-M", "title": "Punisher Guide", "author": "Paz (padswagger)"}], "summary": "Le Punisher est un DPS de dégâts constants plutôt que de picks rapides. Il met la pression sur les tanks trop avancés, les volants à découvert et les supports trop tranquilles, pour que l'ennemi soit affaibli quand le vrai fight éclate.", "counters": [{"hero": "magneto", "note": "Son bouclier ignore tes dégâts et son ult annule la tienne."}, {"hero": "psylocke", "note": "Elle te déborde par sa mobilité."}, {"hero": "hela", "note": "Elle te tue en deux tirs avant que tu sois installé."}, {"hero": "rocket-raccoon", "note": "Ses soins compliquent tes kills."}], "sections": [{"kind": "tips", "lead": "Le Punisher demande de la patience et une bonne visée en suivi : il use l'ennemi pendant tout le fight.", "items": ["Attention à ne pas **nourrir les ults de support** adverses en tirant sur un tank que tu ne peux pas tuer.", "Avec ton ult déjà prête, prends un **angle en tyrolienne** et vise la backline.", "Fais **douter les volants** qui restent à découvert.", "Si personne ne te regarde, **ne bouge pas** : tu vises mieux."], "title": "Philosophie de jeu", "diagram": "poke"}, {"key": "Clic G", "lead": "Un fusil instantané à cadence élevée, qui fait très mal en visant la tête, même de loin.", "items": ["Tire par **rafales** pour limiter la dispersion.", "C'est ton outil pour **mettre la pression** et charger ton ult en début de fight.", "Entraîne ta visée en **suivi de cible** (tracking)."], "title": "Fusil d'assaut", "ability": "Adjudication"}, {"lead": "Un fusil à pompe qui peut éliminer d'un tir à bout portant, mais qui perd vite ses dégâts avec la distance.", "items": ["Ne l'utilise **que de près**. Un peu plus loin, vise le torse.", "C'est ton outil pour **finir une cible** basse en fin de fight.", "Changer d'arme **ne recharge pas** : recharge les deux après chaque fight."], "title": "Fusil à pompe", "ability": "Deliverance"}, {"key": "E", "lead": "Tu t'installes derrière une tourelle protégée de face, qui tire des projectiles explosifs. Elle te rend insensible aux contrôles.", "items": ["Excellente sur un **groupe** d'ennemis, moins sur une seule cible.", "Place-la **hors de vue directe**, au-dessus d'un passage, pour charger ton ult en sécurité.", "L'installation est **lente et bruyante** : prépare une sortie en tyrolienne.", "Elle peut **protéger un support** derrière toi d'une ult de Magneto."], "title": "Tourelle", "ability": "Culling Turret"}, {"key": "Maj · Clic D", "lead": "Une tyrolienne très rapide (trois maximum en place) et une grenade fumigène qui te propulse en arrière.", "items": ["**Pré-place des tyroliennes** pour revenir vite du spawn.", "Le fumigène est d'abord un **outil de survie** contre les divers ou un Hela qui te vise.", "Combine tyrolienne et fumigène pour **atteindre des hauteurs** et des flancs inattendus.", "Ton passif te laisse **voir quelques secondes à travers les murs** les ennemis que tu viens de voir (toi seul)."], "title": "Tyrolienne et fumigène", "ability": "Vantage Connection · Scourge Grenade"}, {"key": "Q", "lead": "Deux mitrailleuses et des missiles autoguidés pendant quelques secondes. Assez pour tuer une Luna à travers son ult si tu vises la tête.", "items": ["Lance-la **derrière un mur** : il y a une animation avant de tirer.", "Le **Magneto** adverse t'attend : joue près de ton tank à bouclier, ou demande une bulle ou un bouclier d'Invisible Woman.", "Avec deux ults de Luna qui s'échangent, lance la tienne et **cherche le traînard** hors de la zone.", "Elle se charge vite en tirant sur les tanks."], "title": "Ultime", "ability": "Final Judgment"}, {"kind": "mistakes", "items": ["Vider ses chargeurs sur un **tank bien soigné**.", "Changer d'arme **à découvert**.", "Poser la tourelle **sans porte de sortie**.", "Ult **à découvert** face à un Magneto prêt.", "Utiliser le fumigène **en attaque** et ne plus pouvoir fuir."], "title": "Erreurs fréquentes"}], "synergies": [{"hero": "emma-frost", "note": "Un front solide qui te laisse tirer."}, {"hero": "groot", "note": "Même chose, et tu brises les fights qu'il découpe."}, {"hero": "doctor-strange", "note": "Son bouclier et son portail te protègent."}, {"hero": "black-widow", "note": "Duo redoutable contre les volants."}, {"hero": "winter-soldier", "note": "Tu achèves au fusil à pompe ce qu'il attrape."}, {"hero": "luna-snow", "note": "Son bonus de dégâts pendant ton ult détruit l'équipe adverse."}], "difficulty": 1, "patch_note": "Guide tiré d'une vidéo de Paz (padswagger), reformulé en français. Les chiffres du kit ont été retirés car ils changent à chaque saison ; team-ups et derniers changements sont à jour (saison 10.5) dans la section dédiée.", "kit": {"season": "Saison 10.5", "health": "", "abilities": [], "teamups": [{"name": "Ammo Overload", "partners": ["rocket-raccoon"], "key": "", "text": "Rocket pose un appareil qui accélère la cadence des alliés. **Amélioré :** Munitions infinies en plus."}, {"name": "Bestial Hunt", "partners": ["daredevil"], "key": "", "text": "Balles perforantes avec bonus de dégâts. **Amélioré :** Détruit les murs plus vite."}, {"name": "Primal Punishment", "partners": ["devil-dinosaur"], "key": "", "text": "Canons magnétiques qui font saigner (projectiles à 150 m/s depuis la saison 10). **Amélioré :** The Punisher chevauche Devil Dinosaur et partage les dégâts."}, {"name": "Timeless Veterans", "partners": ["winter-soldier"], "key": "", "text": "Pointe d'électricité qui repousse. **Amélioré :** Cloue au sol en plus."}], "changes": [], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · changements : patch notes des saisons 10 et 10.5", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'the-punisher' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"tags": ["Brawl", "Anti-dive", "Contrôle", "Couloirs"], "tldr": ["Force les combats **dans les espaces serrés** : en terrain ouvert, tu perds.", "Ta **charge** est ta capacité clé : elle coupe les déplacements adverses.", "Pendant les échanges d'ults de soin, **frappe sans arrêt** : ton ult se charge très vite."], "combos": [{"note": "", "steps": [{"key": "Clic G", "label": "coup"}, {"key": "Clic G", "label": "coup"}, {"key": "Clic D", "label": "crochet"}], "title": "Éliminer un fragile"}], "sources": [{"url": "https://www.youtube.com/watch?v=8IJGdtB9s2s", "title": "The Thing Guide", "author": "Paz (padswagger)"}], "summary": "The Thing est un tank qui excelle dans les espaces étroits où il force l'ennemi au corps à corps. Il protège sa backline des divers grâce à sa charge, saute vers alliés ou ennemis, et son ult étourdit tout ce qui est devant lui.", "counters": [{"hero": "emma-frost", "note": "Tu es une batterie à rayon pour elle."}, {"hero": "groot", "note": "Il t'isole après ton engage : attends son grand mur."}, {"hero": "the-punisher", "note": "Il te farme de loin."}, {"hero": "squirrel-girl", "note": "Même chose."}, {"hero": "iron-man", "note": "Hors de portée et beaucoup de dégâts."}, {"hero": "phoenix", "note": "Elle te farme avec ses marques."}, {"hero": "moon-knight", "note": "Ses ricochets te dévorent."}], "sections": [{"kind": "tips", "lead": "Si l'ennemi ne peut pas fuir, il perd contre The Thing. Après un fight gagné, tiens des positions précises où il devra venir à toi.", "items": ["Place-toi **à couvert près des passages** que l'ennemi doit traverser.", "En défense, il est souvent **meilleur qu'une Peni** sur certaines cartes.", "Ne t'engage pas **trop loin** : ta grosse hitbox nourrit l'ult des DPS adverses."], "title": "Philosophie de jeu", "diagram": "brawl"}, {"key": "Clic G · Clic D", "lead": "Des coups de poing en cône qui touchent plusieurs ennemis, et un gros crochet à longue portée qui te donne de la vie bonus.", "items": ["Les ennemis à portée de coup sont **surlignés** : tu sais exactement quand frapper.", "Le **crochet** est ton outil de poke : utilise-le presque en continu.", "Combo : **deux coups, crochet** pour éliminer un fragile.", "Charge le crochet **avant de sauter** sur un volant pour le faire tomber."], "title": "Coups et crochet", "ability": "Rocky Jabs · Stone Haymaker"}, {"key": "Maj", "lead": "Tu fonces, puis frappes le sol : les ennemis sont projetés et une zone les empêche d'utiliser leurs déplacements. Tu gagnes de la vie bonus pendant la charge.", "items": ["Option recommandée : passe-la en **mode maintenu** pour frapper le sol instantanément.", "**Protéger ta backline** : quand Black Panther dive, frappe le sol sur tes supports.", "**Confirmer un pick** : un Magneto qui vient d'utiliser sa bulle, un support qui veut fuir.", "La zone peut même empêcher **Phoenix de lancer son ult**.", "Pendant la charge, tu es **insensible à la boule de neige** de Luna.", "Si tu dives, garde **un saut** pour revenir."], "title": "Charge", "ability": "Yancy Street Charge"}, {"lead": "Deux charges partagées pour sauter vers un allié (réduction de dégâts pour vous deux) ou vers un ennemi (réduction pour toi seul).", "items": ["**Charge dans la backline**, force l'ennemi à se retourner, puis **saute vers ton équipe** (qui doit te voir).", "Saute sur un **DPS allié en ult** (Star-Lord, Punisher) pour le protéger.", "Saute sur ton **support visé par un Magneto** en ult.", "Pour aider un allié en duel, saute **vers l'allié** : même position, plus de protection.", "Pour attraper un volant, sois patient : **attaque-le en rotation**, pas en début de fight.", "Tu peux **intercepter l'ult de Phoenix**. Par contre, **ne saute jamais** sur un Punisher en ult."], "title": "Sauts", "ability": "Embattled Leap · Battle Blitz"}, {"lead": "Tu ne peux être ni repoussé, ni attiré, ni projeté. Les étourdissements fonctionnent toujours.", "items": ["Les poussées d'**Invisible Woman** ne te font rien : fonce sur elle.", "Le grappin de **Winter Soldier** ne te tire pas, mais t'étourdit."], "title": "Passif", "ability": "Unyielding Will"}, {"key": "Q", "lead": "Tu frappes le sol et une onde se propage devant toi, étourdissant tous les ennemis touchés. Elle traverse les boucliers.", "items": ["Elle se charge **très vite** : lance-la souvent, tu peux en avoir deux dans un long fight.", "**Contre-attaque** juste après une ult étourdissable adverse (Doctor Strange, Hawkeye).", "Sans ult de soin chez vous, cherche à **étourdir la Luna** avant qu'elle lance la sienne.", "Avec un **Punisher** en ult, étourdis l'équipe adverse pour qu'il ne tire pas dans un bouclier."], "title": "Ultime", "ability": "It's Clobberin' Time!"}, {"kind": "mistakes", "items": ["Se battre **en terrain ouvert**.", "Garder la charge en mode **par défaut** au lieu de maintenu.", "Diver **sans saut** pour revenir.", "Sauter **sur un Punisher en ult**.", "Garder son ult au lieu de **l'utiliser en ouverture**."], "title": "Erreurs fréquentes"}], "synergies": [{"hero": "magneto", "note": "Un tank capable de tenir le front avec toi."}, {"hero": "emma-frost", "note": "Même chose."}, {"hero": "magik", "note": "Une brawleuse qui aime le contact."}, {"hero": "phoenix", "note": "Tu regroupes les ennemis pour ses marques."}, {"hero": "human-torch", "note": "Tu repousses l'ennemi dans ses zones."}, {"hero": "invisible-woman", "note": "Elle te soutient en brawl."}, {"hero": "wolverine", "note": "Un brawler qui suit tes engages."}], "difficulty": 1, "patch_note": "Guide tiré d'une vidéo de Paz (padswagger), reformulé en français. Les chiffres du kit ont été retirés car ils changent à chaque saison ; team-ups et derniers changements sont à jour (saison 10.5) dans la section dédiée.", "kit": {"season": "Saison 10.5", "health": "", "abilities": [], "teamups": [{"name": "Clobberin' Research Dept.", "partners": ["mister-fantastic"], "key": "", "text": "Posture de bagarre avec un coup de poing chargé (activable à volonté depuis la saison 10). **Amélioré :** Ajoute un coup de marteau chargé."}, {"name": "Iron & Stone", "partners": ["iron-fist"], "key": "", "text": "Uppercut qui projette en l'air puis coup de pied (fonctionne même sans The Thing, cooldown 12 s depuis la saison 10). **Amélioré :** Enchaînements et dégâts en plus."}, {"name": "Two-in-One", "partners": ["human-torch"], "key": "", "text": "Poings enflammés (cooldown 18 s, 8 s de durée depuis la saison 10). **Amélioré :** Soulève et écrase avec étourdissement."}, {"name": "Unbreakable Forces", "partners": ["invisible-woman"], "key": "", "text": "Armure psionique qui donne de la vie bonus (cooldown 15 s en 10.5). **Amélioré :** Impulsions de soin de zone (seuil de 125 dégâts en 10.5)."}], "changes": [{"season": "Saison 10", "text": "Vie de base 750 → 725, Stone Haymaker 10 % → 8 % de la vie max, Yancy Street Charge 10 s → 12 s de cooldown."}, {"season": "Saison 10.5", "text": "Team-up avec Invisible Woman : cooldown 20 s → 15 s."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · changements : patch notes des saisons 10 et 10.5", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'the-thing' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"tags": ["Ressource", "Déplacement d'ennemis", "Flexible", "Duels"], "tldr": ["**Gère ta Thorforce** : frappe entre deux capacités pour la recharger.", "**Conteste les hauteurs** tenues par les DPS adverses, puis ramène un tank chez toi.", "N'active l'**Éveil** que si tu peux vraiment toucher tes cibles, sans bouclier devant."], "combos": [{"note": "Lance l'Éveil pendant que le marteau vole.", "steps": [{"key": "Clic D", "label": "lancer marteau"}, {"key": "", "label": "Éveil"}], "title": "Éveil en vol"}], "sources": [{"url": "https://www.youtube.com/watch?v=_F5nOfRLy8A", "title": "Thor Guide", "author": "Paz (padswagger)"}], "summary": "Thor est un tank très flexible qui joue sur une ressource, la Thorforce : il conteste les positions fortes pour empêcher les DPS adverses d'entrer, puis ouvre les flancs pour ramener des tanks ennemis dans son équipe avec son dash.", "counters": [{"hero": "emma-frost", "note": "Elle charge sur toi et te chasse des positions."}, {"hero": "rogue", "note": "Elle te plaque au sol et vole ton Éveil."}, {"hero": "the-thing", "note": "Son impact au sol t'empêche de dasher."}, {"hero": "moon-knight", "note": "Les DPS à dégâts constants te font fondre."}, {"hero": "the-punisher", "note": "Même chose."}, {"hero": "invisible-woman", "note": "Ses poussées et attractions te rendent injouable."}], "sections": [{"kind": "tips", "lead": "Pense en permanence : qui dois-je mettre sous pression, et quand ? Thor peut tout faire, selon le matchup.", "items": ["Avec un **front fort** (Winter Soldier, Wolverine), brawle au centre.", "Si le **front adverse est plus fort**, prends les angles et les duels.", "Monte sur les **hauteurs tenues par les DPS** adverses : tu les forces à reculer, et le tank adverse avec.", "En défense, reste **un peu en retrait** du front, prêt à ramener un tank trop avancé."], "title": "Philosophie de jeu", "diagram": "pull"}, {"lead": "La plupart de tes capacités consomment de la Thorforce et te donnent de la vie bonus. Elle se recharge avec le temps ou en touchant un ennemi.", "items": ["Après chaque capacité, il y a un **court délai** avant la suivante : frappe pendant ce temps pour recharger.", "Ton efficacité dépend de **comment tu gères** cette ressource."], "title": "Thorforce", "ability": "Thorforce"}, {"key": "Clic G · Clic D", "lead": "Des coups de marteau sans série fixe, et un lancer de marteau qui revient comme un boomerang.", "items": ["Chaque **premier impact** recharge une Thorforce.", "Le lancer **revient plus vite** s'il touche une cible proche.", "Pendant le lancer, tu ne peux pas dasher, mais tu peux **activer l'Éveil**."], "title": "Marteau", "ability": "Mjolnir Bash · Hammer Throw"}, {"key": "Maj", "lead": "Maintiens pour charger le dash, puis fonce. Tu peux emporter un ennemi et tourner pendant le dash pour le ramener chez toi.", "items": ["**Ramène un tank** derrière son équipe vers la tienne, puis enchaîne.", "La charge est **bruyante** : un étourdissement (Hela, Phoenix, Luna) ou une attraction (Invisible Woman) peut t'arrêter.", "Pour sortir du spawn, un **dash non chargé** suffit.", "Si tu n'as rien d'autre, dash vers un **Iron Man ou Magneto en ult** pour encaisser à la place de tes supports."], "title": "Dash", "ability": "Storm Surge"}, {"lead": "Une sphère autour de toi qui blesse et ralentit les ennemis qui la traversent et bloque leurs déplacements. Elle recharge ta Thorforce selon le nombre d'ennemis dedans.", "items": ["Après un dash sur une cible, **pose le dôme** pour qu'elle ne s'échappe pas.", "Fais **entrer et sortir** l'ennemi du dôme avec ton dash pour multiplier les dégâts.", "Contre **Angela**, pose-le sur tes supports pour couper ses attrapes."], "title": "Dôme de foudre", "ability": "Lightning Realm"}, {"lead": "Consomme toute ta Thorforce : tes coups deviennent des projectiles puissants en série de quatre et une petite aura blesse autour de toi.", "items": ["Gros investissement : sois **sûr de toucher** avant de l'activer.", "Contre des boucliers (**Magneto, Strange**), bouscule-les d'abord.", "Contre **Peni**, active-le directement pour nettoyer ses nids.", "Contre **Rogue ou Emma**, garde tes distances ou attends qu'elles aient utilisé leurs attrapes.", "Combo : **lancer de marteau, puis Éveil** pendant qu'il vole.", "Tu peux le **couper tôt** pour récupérer une Thorforce et dasher."], "title": "Éveil", "ability": "Awakening Rune"}, {"key": "Q", "lead": "Tu t'élèves, insensible aux contrôles, avec une zone qui blesse au sol, puis tu t'écrases en étourdissant tout le monde.", "items": ["Avec un **bonus de dégâts** (Luna, Rocket), l'impact tue à travers une ult de soin.", "Idéal dans un **passage étroit** que l'ennemi doit traverser.", "Pas d'ult face à un **Punisher ou Hawkeye en ult** : tu es une énorme cible.", "Dépense de la **Thorforce avant** pour la vie bonus."], "title": "Ultime", "ability": "God of Thunder"}, {"kind": "mistakes", "items": ["Enchaîner les capacités **sans frapper** entre deux.", "Charger le dash **en vue d'un étourdissement**.", "Activer l'Éveil **dans un bouclier**.", "Ult **face à une ult de DPS** adverse.", "Duel un **The Thing** au centre."], "title": "Erreurs fréquentes"}], "synergies": [{"hero": "angela", "note": "Une autre tank qui joue les flancs avec toi."}, {"hero": "hela", "note": "Tu la protèges sur son angle et chasses l'autre tireur."}, {"hero": "phoenix", "note": "Même chose."}, {"hero": "luna-snow", "note": "Son bonus de dégâts rend ton ult mortelle."}, {"hero": "rocket-raccoon", "note": "Même chose."}], "difficulty": 2, "patch_note": "Guide tiré d'une vidéo de Paz (padswagger), reformulé en français. Les chiffres du kit ont été retirés car ils changent à chaque saison ; team-ups et derniers changements sont à jour (saison 10.5) dans la section dédiée.", "kit": {"season": "Saison 10.5", "health": "", "abilities": [], "teamups": [{"name": "Divine Armory", "partners": ["angela"], "key": "", "text": "La lance de foudre rend de la Thorforce. **Amélioré :** Vie bonus sur le saut."}, {"name": "Gods of Thunder", "partners": ["storm"], "key": "", "text": "Rayon de foudre. **Amélioré :** Bolt Rush devient un éclair en chaîne qui rebondit."}, {"name": "Ragnarok Rebirth", "partners": ["hela"], "key": "", "text": "Une vie bonus empêche la mort et permet de revenir sur un kill. **Amélioré :** Résurrection instantanée."}, {"name": "Thunder Overdrive", "partners": ["iron-man"], "key": "", "text": "Armor Overdrive gagne en dégâts (anneau de l'Unibeam à 80/s en 10.5). **Amélioré :** Anneau à 90/s en 10.5."}, {"name": "Voltaic Union", "partners": ["captain-america"], "key": "", "text": "Projectile-bouclier de foudre (10 s depuis la saison 10). **Amélioré :** Explosion de zone à chaque touche."}], "changes": [{"season": "Saison 10", "text": "Vie de base 300 → 325, Lightning Realm 40 → 50 de dégâts."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · changements : patch notes des saisons 10 et 10.5", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'thor' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"tags": ["Vol", "Duels", "Vie bonus", "Anti-dive"], "tldr": ["Prends des **angles** et cherche des picks : rester derrière à soigner, c'est mal le jouer.", "Ton **drone** doit toujours être sur un allié, et changer de cible selon qui est actif.", "Après ton **pare-feu**, deviens agressif : la vie bonus disparaît vite."], "sources": [{"url": "https://www.youtube.com/watch?v=YKcxUGf25Es", "title": "Ultron Guide", "author": "Paz (padswagger)"}, {"title": "The Only Ultron Guide You'll Ever Need", "author": "Kingsman", "url": "https://www.youtube.com/watch?v=YXCTyF__Y0c"}], "summary": "Ultron ne soutient pas son équipe en soignant beaucoup : il distribue de la vie bonus de n'importe où sur la carte, gagne ses duels grâce à son laser et sa mobilité, et charge très vite une ult polyvalente.", "counters": [{"hero": "hela", "note": "Elle te descend du ciel."}, {"hero": "hawkeye", "note": "Même chose."}, {"hero": "star-lord", "note": "Il te poursuit dans les airs."}, {"hero": "adam-warlock", "note": "Ses tirs instantanés te punissent."}, {"hero": "black-widow", "note": "Elle te tue de loin."}, {"hero": "iron-man", "note": "Il te sort de ton plan de jeu."}], "sections": [{"kind": "tips", "lead": "La plupart des joueurs voient Ultron comme un heal. C'est l'erreur : ses forces sont les duels, les picks et la vie bonus au bon moment.", "items": ["Joue **à couvert**, même en volant : le ciel ne te protège pas des tireurs.", "Pas besoin de flanquer **très loin** : un angle sûr suffit.", "Ne tire pas sur les tanks **toute la partie**, sauf s'ils sont les seules cibles visibles.", "Le duo **Ultron + Hela sur un angle** est très dur à gérer pour l'adversaire.", "Ultron n'est **pas un heal principal** : c'est un troisième support, spécialiste de l'**anti-dive** et du poke depuis le ciel.", "Joue-le avec des **flyers** (Iron Man, Human Torch, Storm) ou une compo **dive/anti-dive**. Jamais dans une compo **brawl** au sol : il ne soigne pas assez.", "Les **hitscan** (Hela, The Punisher) sont ton gros problème : tu es fragile une fois tes cooldowns utilisés.", "Contre un diver, préviens ton autre support, **recule vers tes tanks** et retournez-vous ensemble sur lui."], "title": "Philosophie de jeu", "diagram": "pocket"}, {"key": "Clic G", "lead": "Un rayon instantané suivi d'une petite explosion. Une seule pression suffit, pas besoin de maintenir.", "items": ["Deux tirs complets tuent un fragile, **trois** à longue distance.", "L'explosion ne touche **qu'une seule cible**, mais elle rend le tir plus facile.", "Astuce : **commence à charger** contre un mur, puis sors juste avant l'explosion.", "Annule l'animation de rechargement avec un **coup de mêlée** à mi-chemin."], "title": "Laser"}, {"key": "Maj", "lead": "Un dash dans toutes les directions suivi d'un bonus de vitesse, et un peu de vie bonus. Le cooldown ne démarre qu'à la fin de l'accélération.", "items": ["Le haut et le bas se contrôlent avec **ton viseur**.", "Utile pour **revenir du spawn**, **fuir** après un pick trop profond, ou **confirmer un duel**.", "Combo duel : charge le laser derrière un couvert, **dash et tire** sur un Hela basse.", "C'est la **seule capacité utilisable pendant ton ult** : garde-la pour te sauver."], "title": "Vol rapide", "ability": "Dynamic Flight"}, {"lead": "Un drone qui soigne son porteur et les alliés autour, toi compris. Pas de cooldown : il doit toujours être actif.", "items": ["Il revient si tu es **trop loin** ou **hors de vue** trop longtemps : repasse dans la zone régulièrement.", "Début de fight : **sur tes tanks**. Quand un DPS duel : **sur lui**. Si tes supports se font dive : **sur eux**.", "Avec une **Luna** qui marque déjà ton diver, mets plutôt le drone sur les tanks.", "Il soigne en zone autour de l'allié, un peu plus l'allié lui-même, et **toi aussi** si tu restes près de lui : colle-le sur un flyer et volez ensemble."], "title": "Drone", "ability": "Imperative: Patch"}, {"key": "Clic D", "lead": "De la vie bonus pour toi et les alliés proches de toi ou de ton drone. Elle s'estompe vite.", "items": ["Juste après, **sois agressif** : recule, protège, puis fonce sur la backline.", "Elle **empêche un one-shot** : une flèche de Hawkeye ou l'ult de Namor.", "La zone est **sphérique** : si ton drone est en l'air, les alliés au sol ne reçoivent rien.", "Garde-le pour **le moment où l'ennemi engage** (ult de Venom, burst de zone) : bien timé, il retourne l'échange."], "title": "Pare-feu", "ability": "Imperative: Firewall"}, {"key": "Q", "lead": "Quatre drones apparaissent et tirent des salves qui soignent tes alliés et blessent les ennemis. Tu ne peux pas être étourdi et tu peux dasher.", "items": ["Lance-la **derrière un couvert**, puis sors pendant que les drones tirent.", "C'est une ult de **retournement** : quand l'ennemi écrase ton front, soigne tes tanks et blesse les siens.", "Elle contre les menaces ciblées : **Magik, Iron Fist, Winter Soldier**.", "Elle se charge **vite** : n'hésite pas à la lancer pour tuer un support isolé.", "Ses rayons soignent énormément mais **il faut viser** : ce n'est pas une zone automatique.", "Elle revient **très vite** si tu touches tes tirs : tu peux l'avoir avant les heals adverses et gagner le cycle d'ults."], "title": "Ultime", "ability": "Rage of Ultron"}, {"kind": "mistakes", "items": ["Rester **en retrait à soigner**.", "Oublier son **drone** ou le laisser expirer.", "Utiliser le pare-feu **sans agresser** ensuite.", "Voler **à découvert** face à Hela ou Hawkeye.", "Insister quand ton équipe **prend trop de dégâts** : change de support."], "title": "Erreurs fréquentes"}], "synergies": [{"hero": "iron-man", "note": "Un autre volant à soutenir."}, {"hero": "captain-america", "note": "Ton drone le garde en vie en dive."}, {"hero": "psylocke", "note": "Même chose."}, {"hero": "hela", "note": "Votre duo sur un angle est presque intouchable."}, {"hero": "storm", "note": "Son aura booste ton laser et elle joue près de toi."}, {"hero": "luna-snow", "note": "Elle soigne assez pour te laisser jouer offensif."}, {"hero": "rocket-raccoon", "note": "Même chose."}], "difficulty": 2, "patch_note": "Guide tiré d'une vidéo de Paz (padswagger), reformulé en français. Les chiffres du kit ont été retirés car ils changent à chaque saison ; team-ups et derniers changements sont à jour (saison 10.5) dans la section dédiée.", "kit": {"season": "Saison 10.5", "health": "", "abilities": [], "teamups": [{"name": "Flawless Design", "partners": ["adam-warlock"], "key": "", "text": "Les Cosmic Cluster d'Adam soignent les alliés (18 par projectile en 10.5). **Amélioré :** Explosion de soin à l'impact (7 en 10.5)."}, {"name": "SP//DR Sync", "partners": ["peni-parker"], "key": "", "text": "Imperative: Patch s'applique aux alliés. **Amélioré :** Les drones cumulent les effets de Firewall."}, {"name": "Stark Protocol", "partners": ["iron-man"], "key": "", "text": "Nano-rayon qui soigne et blesse. **Amélioré :** Tire des missiles à tête chercheuse."}], "changes": [{"season": "Saison 10", "text": "Firewall : vie bonus 65 → 40 pour Ultron, 50 → 40 pour les alliés ; nouvel auto-soin de 20/s pendant 3 s."}, {"season": "Saison 10", "text": "Tous les Strategists : l'ult se charge un peu moins vite (65 % du soin et 50 % des dégâts convertis en énergie, au lieu de 70 % et 55 %)."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · changements : patch notes des saisons 10 et 10.5", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'ultron' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"tags": ["Dive", "Pression", "Vie bonus", "Mobilité"], "tldr": ["**Engage depuis un mur** avec le saut écrasé, et garde le balancement pour **fuir**.", "Lance ta **vie bonus vers 150-200 PV**, pas trop tôt, pas trop tard.", "Ne saute pas partout : **un simple pas de côté** suffit, ta hitbox est énorme de toute façon."], "combos": [{"note": "", "steps": [{"key": "", "label": "Mur"}, {"key": "", "label": "Saut écrasé"}, {"key": "Clic D", "label": "tentacules"}, {"key": "Clic G", "label": "tirs"}], "title": "Engage"}], "sources": [{"url": "https://www.youtube.com/watch?v=3HMlrN1UxIc", "title": "Venom Guide", "author": "Paz (padswagger)"}], "summary": "Venom est un tank de dive qui encercle l'ennemi, force ses cooldowns, puis attend que son équipe soit prête pour l'élimination. Il n'a pas besoin de tuer : sa pression suffit à ouvrir le fight pour ses alliés.", "counters": [{"hero": "emma-frost", "note": "Elle charge sur toi si ton équipe ne la gère pas."}, {"hero": "the-thing", "note": "Il t'immobilise à l'entrée ou à la sortie."}, {"hero": "thor", "note": "Même chose."}, {"hero": "the-punisher", "note": "Ses dégâts constants te font fondre."}, {"hero": "phoenix", "note": "Elle retire ta vie bonus."}, {"hero": "luna-snow", "note": "Elle te gèle à l'atterrissage."}, {"hero": "ultron", "note": "Intouchable, et son drone casse tes seuils."}], "sections": [{"kind": "tips", "lead": "Venom force les cooldowns au plus vite pour garder sa vie bonus pour le moment où son équipe peut suivre.", "items": ["Après un fight gagné, monte **au-dessus d'un passage**, laisse passer les tanks, puis tombe sur les supports.", "Sache **toujours où est ton équipe** pour qu'elle puisse suivre ton engage.", "Pas de kill ? Pas grave : tu **bloques l'ennemi** et tu offres un pick à ton équipe.", "Astuce : sortie du spawn rapide en **balancement puis sauts enchaînés** (saut sur la molette)."], "title": "Philosophie de jeu", "diagram": "dive"}, {"key": "Clic G", "lead": "Des salves de tentacules à bonne portée qui peuvent toucher la tête. Elles font plus mal que la plupart des tanks.", "items": ["Ne te colle pas : à **mi-distance**, tu touches plus facilement la tête.", "Évite les **sauts inutiles** qui ruinent ta visée.", "Glisse des **coups de mêlée** entre les salves sur une cible unique."], "title": "Tentacules"}, {"key": "Clic D", "lead": "Tous les ennemis proches sont attachés et ralentis. S'ils ne s'éloignent pas à temps, ils subissent un gros pic de dégâts.", "items": ["Utilise-la **à chaque engage** : elle force les cooldowns et éloigne les cibles de leur équipe.", "Déplace-toi pour qu'ils aient **du mal à s'éloigner**.", "Elle **suit les cibles invisibles** (Cloak & Dagger, Invisible Woman)."], "title": "Tentacules corrosives", "ability": "Cellular Corrosion"}, {"key": "Maj", "lead": "Un balancement très rapide accroché au décor, et la capacité de grimper et courir sur les murs et plafonds.", "items": ["Le balancement sert surtout à **sortir**. Accroche-toi **bas sur un mur** pour partir à l'horizontale, hors de vue des tireurs.", "Engage plutôt en **grimpant sur un mur** puis en sautant écrasé.", "Courir sur les murs est **bruyant** : les supports t'entendent arriver.", "En duel près d'un mur, **monte et écrase-toi** sur la cible pour des dégâts bonus."], "title": "Balancement et murs", "ability": "Venom Swing · Alien Biology"}, {"lead": "Tu bondis et t'écrases au sol, projetant les ennemis en l'air. Les dégâts baissent si tu tombes à côté.", "items": ["Vise **directement** la cible.", "Tu ne peux pas être gelé en vol, mais un bon support **attendra ton atterrissage**.", "Combo : **mur, saut écrasé, tentacules corrosives, tirs**."], "title": "Saut écrasé", "ability": "Frenzied Arrival"}, {"lead": "Tu gagnes de la vie bonus en fonction de la vie qui te manque. Plus tu es blessé, plus tu en reçois.", "items": ["Lance-la vers **150-200 PV** : assez tard pour en profiter, assez tôt pour ne pas mourir avant.", "Elle **ne charge pas** l'ult adverse : collé à une Luna presque prête, tu la bloques.", "**Survis** après l'avoir lancée : mourir avec, c'est offrir de l'ult à l'ennemi.", "Attention à **Phoenix** (elle la retire) et **Ultron** (son ult la fait fondre)."], "title": "Vie bonus", "ability": "Symbiotic Resilience"}, {"key": "Q", "lead": "Tu t'enfouis et te déplaces très vite, puis tu ressurgis en dévorant un pourcentage de la vie des ennemis autour, converti en vie bonus pour toi.", "items": ["Elle **prolonge un engage** sur les supports ou force leurs ults.", "Avec un **bonus de dégâts** (Luna, Rocket) : tentacules corrosives, puis ressurgis au moment où leurs dégâts tombent, pour tuer à travers une ult de soin.", "Bon timing : **ressurgis sous le Jeff** au moment où il sort pour avaler ton équipe.", "Sous terre, ta **tête peut être touchée**, et l'ennemi peut te bloquer le passage."], "title": "Ultime", "ability": "Feast of the Abyss"}, {"kind": "mistakes", "items": ["**Engager au balancement** et ne plus pouvoir fuir.", "Sauter partout et **rater ses tirs**.", "Lancer la vie bonus **trop tôt**.", "Diver **sans équipe** prête à suivre.", "Écraser **à côté** de la cible."], "title": "Erreurs fréquentes"}], "synergies": [{"hero": "captain-america", "note": "Il dégage le couloir opposé : un partenaire de dive idéal."}, {"hero": "psylocke", "note": "Dive combiné sur la backline."}, {"hero": "black-widow", "note": "Elle achève au corps les cibles que tu dives."}, {"hero": "jeff-the-land-shark", "note": "Il suit tes dives et attire l'attention."}, {"hero": "luna-snow", "note": "Son bonus de dégâts rend ton ult mortelle."}, {"hero": "mantis", "note": "Elle booste les divers qui t'accompagnent."}], "difficulty": 2, "patch_note": "Guide tiré d'une vidéo de Paz (padswagger), reformulé en français. Les chiffres du kit ont été retirés car ils changent à chaque saison ; team-ups et derniers changements sont à jour (saison 10.5) dans la section dédiée.", "kit": {"season": "Saison 10.5", "health": "", "abilities": [], "teamups": [{"name": "Abyssal Flames", "partners": ["phoenix"], "key": "", "text": "Les griffes de Venom posent des étincelles de Phoenix, qui explosent à 3 cumuls."}, {"name": "Blood Leech", "partners": ["blade"], "key": "", "text": "Cellular Corrosion vole de la vie. **Amélioré :** Ajoute un soin ponctuel."}, {"name": "Guardian of the Deep", "partners": ["jeff-the-land-shark"], "key": "", "text": "Tentacules de soin qui donnent de la vie bonus. **Amélioré :** Ajoute des coups de fouet qui blessent."}, {"name": "Hel Tendrils", "partners": ["hela"], "key": "", "text": "Des tentacules attirent et ralentissent les ennemis. **Amélioré :** Les Nightsword Thorns soignent en plus."}, {"name": "Hive Mind", "partners": ["gorr-the-god-butcher"], "key": "", "text": "Une griffe de symbiote attire les ennemis. **Amélioré :** Ajoute un boost de dégâts et un ralentissement."}, {"name": "Symbiote Bond", "partners": ["spider-man"], "key": "", "text": "Pointes de symbiote qui repoussent les ennemis. **Amélioré :** Ajoute des tentacules qui relient."}], "changes": [], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · changements : patch notes des saisons 10 et 10.5", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'venom' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"tags": ["Utilitaire", "Anti-ult", "Téléportation", "Brawl"], "tldr": ["**Touche directement** tes cibles : un tir raté, c'est beaucoup de soin et de charge d'ult perdus.", "Garde des **queues spirituelles** pour contrer les ults et les dives adverses.", "Passe en **forme de renard** quand ton équipe engage ou qu'un diver te tombe dessus."], "sources": [{"url": "https://www.youtube.com/watch?v=agc2g5G7fwM", "title": "White Fox Guide", "author": "Paz (padswagger)"}, {"title": "Ultimate White Fox Guide (Beginner/Advanced)", "author": "Tephra98", "url": "https://www.youtube.com/watch?v=H9G10NfC2TI"}], "summary": "White Fox est une support pleine d'utilitaires : elle contrôle le fight avec ses renards spectraux et sa téléportation, puis passe en forme de renard au corps à corps quand c'est le tour de son équipe d'engager. Son ult rend un allié presque imbattable quelques secondes.", "counters": [{"hero": "hela", "note": "Elle te domine sur les longues lignes de vue."}, {"hero": "phoenix", "note": "Même chose."}, {"hero": "the-thing", "note": "Il bloque tes déplacements et ta téléportation."}, {"hero": "the-punisher", "note": "Il te déchire pendant ton ult."}, {"hero": "wolverine", "note": "Même chose."}, {"hero": "angela", "note": "Elle peut t'emporter hors de la carte."}], "sections": [{"kind": "tips", "lead": "Analyse ce que l'ennemi joue et prévoit, puis adapte tes utilitaires. Charger ton ult reste l'objectif, mais la façon de le faire change selon la compo.", "items": ["En **brawl**, utilise téléportation et bouclier pour couper les soins d'une cible clé.", "En **poke**, téléporte-toi vers ta **Hela** quand elle duel ou se fait dive.", "Sois **proactive** : ne reste pas derrière à soigner.", "Boucle de jeu : **accumule deux queues**, flank ou duel un flanker, fais ton combo, puis **téléporte-toi** vers ton équipe.", "Elle s'entend surtout avec les **divers** (Spider-Man, Magik, Daredevil, Deadpool) : suis-les et soigne-les à distance de téléportation.", "Si l'ennemi a des **ults que tu peux contrer**, calme les flanks et garde tes capacités pour elles."], "title": "Philosophie de jeu", "diagram": "heal"}, {"key": "Clic G", "lead": "Des projectiles qui soignent ou blessent, puis rebondissent une seule fois vers une cible proche.", "items": ["Le premier impact fait l'essentiel : **vise directement** la cible.", "Pour une cible lointaine ou très mobile, vise **ses pieds** ou le mur derrière elle pour profiter du rebond.", "Elles chargent aussi tes **queues spirituelles**.", "Vise **juste** : un coup direct rebondit sur un deuxième allié ou ennemi, un raté rebondit moins bien."], "title": "Billes de renard", "ability": "Fox Marbles"}, {"key": "Clic D", "lead": "Un renard qui traverse les cibles, soigne et blesse, et coûte une queue. S'il touche directement, il rend un allié invulnérable un instant, ou force un ennemi à marcher vers toi.", "items": ["L'invulnérabilité est brève mais **contre des ults** (Doctor Strange, The Thing, Groot) ou le dive d'un **Venom**. Le timing est dur.", "Le charme empêche un **Black Panther, Venom ou Hulk** d'utiliser sa mobilité : anticipe, l'animation est longue.", "Dans un fight neutre, **aligne un maximum de cibles**.", "Contre une ult de **Magneto**, lance-le pendant que le météore arrive, pas avant.", "Il **charme** l'ennemi (il marche vers toi une seconde) ou rend un allié **invulnérable** une seconde : coupe l'ult de Strange, protège un allié du slam de Thor."], "title": "Renard spectral", "ability": "Spectral Surge"}, {"lead": "Consomme toutes tes queues pour passer au corps à corps : tes griffes soignent toi et les alliés autour, et tu gagnes deux capacités.", "items": ["Contre le **dive**, c'est ton outil de survie : tu peux même gagner un duel contre un Daredevil seul.", "Contre le **brawl**, passe en renard quand l'ennemi a utilisé un gros cooldown (le grand mur de Groot) ou que tu as l'avantage.", "Le **bond** (Maj) te place derrière la cible, puis te permet de la **pousser vers ton équipe**.", "Le **coup de queue** (clic droit) finit une cible ou la repousse.", "**Recharge avant** de passer en renard.", "Inutile de garder trois queues pour ça : **utilise tes renards spectraux** en neutre.", "Combo : **renard spectral**, passage en forme de renard, **bond**, coup de griffe, balayage, puis la deuxième partie du bond.", "C'est ta **seule vraie source d'auto-soin** avec le petit soin de la téléportation : assure-toi d'être en sécurité avant de t'y engager.", "Le bond et la téléportation **n'ont pas le même cooldown** : tu peux bondir, sortir de la forme, puis te téléporter."], "title": "Forme de renard", "ability": "Fox Form Awakening"}, {"lead": "Tu te téléportes vers un allié à travers les murs, crées un bouclier autour de vous et vous soignez instantanément.", "items": ["Rejoins ta **Hela** sur son angle quand elle se fait dive.", "**Feinte** : laisse un diver venir sur toi, puis disparais.", "Elle peut **couper les soins** d'un diver adverse pendant que tu sauves ton allié.", "Elle peut protéger un support d'une **ult de Magneto**, s'il prend de la distance.", "C'est ta **survie** : ne l'utilise pour attaquer que si le pick est quasi sûr.", "Le bouclier qu'elle pose **n'a pas de toit** : ne te téléporte pas sur un allié avec un Magneto juste au-dessus.", "Utilisée au dernier moment sur un allié qui ulte, elle **bloque l'ult de Magneto ou d'Iron Man**.", "Sur PC, mets-la **sur la molette** en second raccourci pour fuir sans viser précisément."], "title": "Téléportation", "ability": "Spirit Sanctuary"}, {"key": "Q", "lead": "Tu deviens un renard à neuf queues avec beaucoup de vie. Tu soignes autour de toi, mais tu ne peux être soignée qu'en frappant les ennemis. Tu peux rendre des alliés imparables et voleurs de vie.", "items": ["Lance-la **en premier**, pendant une vraie poussée sur le point, pas en réaction.", "Reste **derrière tes tanks** : ta hitbox est énorme.", "Donne le bonus à **un allié en ult** (Star-Lord) ou à **tes tanks** au front. Tu peux en booster plusieurs.", "Chaque bonus **te coûte de la vie**.", "Combo : **téléporte-toi** sur ton front qui gagne, puis lance l'ult.", "Tu deviens **énorme et sans mobilité**, et tu ne peux pas être soignée : on peut te stun et te focus.", "Elle soigne moins que les ults d'Invisible Woman ou de Mantis : **tape** pour soigner davantage.", "Ta bénédiction rend un allié **insensible aux contrôles** : idéale pour garantir l'ult de Strange ou de Scarlet Witch."], "title": "Ultime", "ability": "Kumiho Unleashed"}, {"kind": "mistakes", "items": ["Viser **à côté** et compter sur le rebond.", "Gaspiller ses queues quand une **grosse ult** adverse arrive.", "Passer en renard **sans que l'équipe suive**.", "Utiliser la **téléportation** pour attaquer sans raison.", "Lancer l'ult **en réaction** comme une ult de Luna."], "title": "Erreurs fréquentes"}], "synergies": [{"hero": "luna-snow", "note": "Un duo de supports solide."}, {"hero": "groot", "note": "Un tank de brawl qui lance les fights où ta forme de renard brille."}, {"hero": "emma-frost", "note": "Même chose."}, {"hero": "the-thing", "note": "Même chose."}, {"hero": "elsa-bloodstone", "note": "Une DPS de contact qui profite de tes soins."}, {"hero": "star-lord", "note": "Ton ult rend la sienne dévastatrice."}, {"hero": "invisible-woman", "note": "Elle aussi veut des fights groupés."}], "difficulty": 3, "patch_note": "Guide tiré d'une vidéo de Paz (padswagger), reformulé en français. Les chiffres du kit ont été retirés car ils changent à chaque saison ; team-ups et derniers changements sont à jour (saison 10.5) dans la section dédiée.", "kit": {"season": "Saison 10.5", "health": "", "abilities": [], "teamups": [{"name": "Atlas Bond", "partners": ["luna-snow"], "key": "", "text": "Un renard spirituel charme les ennemis et soigne les alliés. **Amélioré :** Le renard revient tout seul."}, {"name": "Kumiho Palm", "partners": ["iron-fist"], "key": "", "text": "Yat Jee Chung Kuen soigne les alliés. **Amélioré :** Portée de verrouillage augmentée."}, {"name": "Lucky Loan", "partners": ["black-cat"], "key": "", "text": "Un orbe de vie alimente l'aura à neuf queues. **Amélioré :** Les queues spirituelles ne coûtent plus rien."}, {"name": "Psionic Fox", "partners": ["psylocke"], "key": "", "text": "La forme de renard ne coûte plus d'énergie. **Amélioré :** Cooldown fortement réduit."}], "changes": [{"season": "Saison 10", "text": "Yeowoo Guseul : soin direct 50 → 55, rebond 35 → 40 ; zone de la forme de renard 35 → 40."}, {"season": "Saison 10", "text": "Tous les Strategists : l'ult se charge un peu moins vite (65 % du soin et 50 % des dégâts convertis en énergie, au lieu de 70 % et 55 %)."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · changements : patch notes des saisons 10 et 10.5", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'white-fox' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"tags": ["Brawl", "Grappin", "Vie bonus", "Anti-dive"], "tldr": ["Joue **avec tes tanks**, pas en flank : c'est là que ton grappin vaut le plus.", "Chaque capacité **recharge ton canon** : enchaîne capacités et tirs.", "Ton ult n'a pas besoin de remplir le kill feed : **un pick et tu survis**, c'est déjà gagné."], "combos": [{"note": "", "steps": [{"key": "Clic G", "label": "tête"}, {"key": "Maj", "label": "dash"}, {"key": "Mêlée", "label": ""}], "title": "Tuer un fragile"}], "sources": [{"url": "https://www.youtube.com/watch?v=mc--EjMwJgA", "title": "Winter Soldier Guide", "author": "Paz (padswagger)"}, {"title": "The Only Bucky Guide You'll Ever Need", "author": "Kingsman", "url": "https://www.youtube.com/watch?v=pm32chmreII"}, {"title": "Ultimate Winter Soldier Guide (Beginner/Advanced)", "author": "Tephra98", "url": "https://www.youtube.com/watch?v=Tu7coC3c2XI"}], "summary": "Winter Soldier est un DPS cogneur qui joue au front avec ses tanks : il attrape les ennemis au grappin, les déplace et les fait exploser avec son canon. Chaque capacité recharge son arme et lui donne de la vie bonus.", "counters": [{"hero": "emma-frost", "note": "Bouclier levé dès qu'elle entend ton grappin."}, {"hero": "magneto", "note": "Sa bulle annule tes grappins."}, {"hero": "the-thing", "note": "Tu ne peux pas le déplacer."}, {"hero": "hela", "note": "Elle te domine à longue distance."}, {"hero": "iron-man", "note": "Les bons volants esquivent tes boules."}, {"hero": "hawkeye", "note": "Il te tue d'une flèche chargée avant que tu sois à portée."}], "sections": [{"kind": "tips", "lead": "Comme Wolverine, il prépare le terrain pour son front en déplaçant les ennemis, surtout les tanks. Il protège aussi très bien sa backline des divers.", "items": ["Reste **près de ton tank** : un ennemi attrapé peut être coupé de ses soins tout de suite.", "Contre un **Black Panther**, ton dash et tes boules le stoppent net.", "Les fights sont longs : tu as **le temps** d'attendre la bonne ouverture.", "Après un pick, tu peux **attirer un tank** dans un passage serré, comme un Wolverine.", "Chaque capacité **recharge ton canon et te donne du bouclier** : vide tes balles, capacité, vide tes balles, capacité… sans jamais recharger.", "Bucky est surtout un **peeler** : reste près de tes supports pour punir Black Panther, Spider-Man et les autres divers.", "Il dépend de son équipe : **annonce qui tu hook et qui tu ultes** pour que tes DPS suivent.", "Si ton équipe perd le front malgré toi et que personne ne s'adapte, passe sur un **diver** qui peut gagner seul."], "title": "Philosophie de jeu", "diagram": "pull"}, {"key": "Clic G", "lead": "Trois tirs explosifs par chargeur. Un tir direct fait mal, et l'explosion touche les ennemis derrière la cible.", "items": ["Deux headshots tuent un fragile.", "**N'importe quelle capacité** recharge entièrement ton canon, même ratée.", "Combo : **headshot, dash, coup de mêlée** pour tuer un fragile.", "Avec le grappin : **grappin, headshot, dash**.", "Joue **juste derrière tes tanks**, près d'un couvert : tes dégâts baissent au-delà d'environ 20 m.", "Les tirs font aussi des **dégâts derrière la cible** touchée.", "Garde la **boule d'énergie** pour enchaîner six tirs sans recharger."], "title": "Canon", "ability": "Roterstern"}, {"lead": "Chaque capacité te donne de la vie bonus, qui s'estompe avec le temps.", "items": ["Grappin, dash et boule d'énergie enchaînés te rendent **très solide** au front.", "Ne lance pas tes capacités **juste pour la vie bonus**, mais sache qu'elle te permet d'être plus agressif."], "title": "Passif", "ability": "Ceaseless Charge"}, {"lead": "Un grappin qui va plus loin si tu le charges. Il peut attraper plusieurs ennemis alignés et applique un mini-étourdissement.", "items": ["Après l'impact, **tourne ton viseur** pour ramener la cible derrière un couvert ou un bouclier, hors de portée de ses soins.", "Le mini-étourdissement **coupe des ults** (Doctor Strange, Star-Lord, Loki).", "Charge-le quand un **bouclier adverse va tomber**, pour attraper la cible juste après.", "Tu peux sortir **Cloak & Dagger** ou un tank d'une ult de soin.", "Charger le grappin pendant une **ult de Luna** adverse, c'est ta façon d'être utile pendant que tout le monde est immortel.", "Charge maximale = **bruit très reconnaissable** : l'ennemi sait que tu es prêt.", "C'est un **contrôle dur** : il sort un Cloak & Dagger de son ult, coupe une ult d'Iron Man, de Strange, d'Emma ou de The Thing.", "Il peut attraper **plusieurs ennemis côte à côte** en même temps.", "Le combo de base contre un tank : **hook, puis uppercut** pour l'envoyer au milieu de ton équipe.", "Il est bloqué par **les murs, les boucliers et les bulles**.", "Combo tank : **hook, passe derrière lui, uppercut** pour le traîner encore plus loin dans ton équipe, idéalement **derrière un mur** pour couper ses soins.", "Combo fragile : **hook, headshot, uppercut, tir**.", "En tournant la caméra pendant que le hook attrape, tu **déplaces un peu** la cible."], "title": "Grappin", "ability": "Bionic Hook"}, {"key": "Maj", "lead": "Un dash qui emporte les ennemis devant toi, même à travers les boucliers, et deux charges d'une boule d'énergie qui traverse et ralentit.", "items": ["Le dash **traverse les boucliers** de Strange et Magneto, mais te laisse exposé de l'autre côté.", "Il sert à **prendre une hauteur**, **plaquer une Luna contre un mur** ou **stopper un diver**.", "La boule **ralentit** et peut faire tomber les volants (Iron Man, Storm).", "Ne la lance pas **dans un bouclier** : garde-la pour quand il tombe.", "L'uppercut sert **à entrer ou à sortir** : avec son cooldown, ne le gaspille pas au hasard.", "La boule d'énergie traverse les ennemis, les ralentit et **fait tomber les flyers** (Iron Man, Human Torch, Storm, Ultron)."], "title": "Dash et boule d'énergie", "ability": "Trooper's Fist · Tainted Voltage"}, {"key": "Q", "lead": "Tu t'envoles puis t'écrases sur une zone, marquant les ennemis touchés. Ceux qui tombent sous un seuil de vie meurent, et chaque élimination te rend l'ult.", "items": ["Choisis ta **zone d'impact** avant de retomber, sinon l'ult est perdue.", "Les **tanks** ont un seuil plus haut, mais il faut que ton équipe suive à temps.", "Combo idéal avec l'**ult de Groot**.", "Face à des **ults de support** prêtes, ne commence pas avec : force-les d'abord avec ton kit.", "Elle peut aussi **protéger ta backline** : écrase-toi sur un diver après qu'il a utilisé ses cooldowns.", "**Un pick et tu survis** valent mieux qu'un dive suicide.", "Ne spamme pas l'ult après un pick : attends que les ennemis soient **groupés et bas en vie**, sinon tu gâches le reset.", "Idéal **par-dessus une ult de soin** : combine-la avec une autre ult (Magneto sur une Luna par exemple).", "Les **clones de Loki** comptent pour les resets.", "**Abîme d'abord une cible** puis ulte dessus pour être sûr du reset : le premier impact abîme souvent un deuxième ennemi.", "Pas besoin de faire le kill toi-même : **n'importe quel kill** sur une cible marquée rend l'ult.", "Vise en priorité les **supports qui ont leur ult** prête."], "title": "Ultime", "ability": "Kraken Impact"}, {"kind": "mistakes", "items": ["Jouer **en flank** comme un Psylocke.", "Lancer grappin et boules **dans un bouclier**.", "Dasher **à travers le front** et mourir de l'autre côté.", "Diver trop loin **pendant l'ult**.", "Oublier que les capacités **rechargent le canon**."], "title": "Erreurs fréquentes"}], "synergies": [{"hero": "groot", "note": "Il emmure chaque cible que tu attrapes."}, {"hero": "magneto", "note": "Coupe les soins de tes cibles derrière son bouclier."}, {"hero": "emma-frost", "note": "Même chose."}, {"hero": "doctor-strange", "note": "Même chose."}, {"hero": "the-punisher", "note": "Ensemble, vous faites fondre le front adverse."}, {"hero": "peni-parker", "note": "Attire les ennemis dans ses mines."}, {"hero": "hela", "note": "Elle s'occupe des snipers adverses pendant que tu punis le reste."}], "difficulty": 2, "patch_note": "Guide tiré d'une vidéo de Paz (padswagger), reformulé en français. Les chiffres du kit ont été retirés car ils changent à chaque saison ; team-ups et derniers changements sont à jour (saison 10.5) dans la section dédiée.", "kit": {"season": "Saison 10.5", "health": "", "abilities": [], "teamups": [{"name": "Expert Instinct", "partners": ["elsa-bloodstone"], "key": "", "text": "Les kills donnent des cumuls d'instinct. **Amélioré :** Augmente la vie bonus de Ceaseless Charge (55 en saison 10)."}, {"name": "Stars Aligned", "partners": ["captain-america"], "key": "", "text": "Saut vers l'allié qui partage de la vie bonus. **Amélioré :** Ralliement mutuel."}, {"name": "Timeless Veterans", "partners": ["the-punisher"], "key": "", "text": "Pointe d'électricité qui repousse. **Amélioré :** Cloue au sol en plus."}], "changes": [{"season": "Saison 10", "text": "Tainted Voltage : charge 5 s → 6 s, ralentissement 35 % → 25 %."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · changements : patch notes des saisons 10 et 10.5", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'winter-soldier' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"tags": ["Anti-tank", "Déplacement d'ennemis", "Rage", "Brawl"], "tldr": ["**Ramène** les cibles dans ton équipe au lieu de diver dans la leur.", "**Hurle avant** chaque attrape : tu deviens la cible de tout le monde.", "Garde ta **rage** haute sans te sacrifier pour elle."], "combos": [{"note": "Presque impossible à rater.", "steps": [{"key": "Clic D", "label": "bond"}, {"key": "", "label": "Attrape"}], "title": "Attrape fiable"}], "sources": [{"url": "https://www.youtube.com/watch?v=J2sqWAV2ubs", "title": "Wolverine Guide", "author": "Paz (padswagger)"}], "summary": "Wolverine est le roi du anti-tank : il attrape les ennemis, surtout les tanks, et les ramène dans son équipe pour les déchiqueter. Sa rage, qui monte au fil du combat, renforce tout son kit.", "counters": [{"hero": "invisible-woman", "note": "Son attraction annule tes attrapes. À bannir."}, {"hero": "magneto", "note": "Sa bulle protège ta cible."}, {"hero": "emma-frost", "note": "Force d'abord sa forme de diamant."}, {"hero": "captain-america", "note": "Il t'esquive toute la partie."}, {"hero": "hela", "note": "Elle n'a pas besoin de s'approcher."}, {"hero": "iron-man", "note": "Les volants sont pénibles à attraper."}], "sections": [{"kind": "tips", "lead": "Wolverine ne flanque presque jamais : il rôde dans l'ombre et ramène les cibles vers son équipe.", "items": ["Les **tanks** sont ta cible principale, mais un **support prêt à ult** ramené chez toi vaut aussi beaucoup.", "Contre une compo **dive**, joue en gardien de ta backline et emporte le Venom qui dive.", "Avec une **ult de Gambit**, tu peux diver sur les supports et faire beaucoup d'espace.", "Quand l'ennemi a son **ult de DPS** clé (Storm), harcèle ce joueur pour qu'il ne puisse jamais la lancer.", "Sans tank à attraper (un Captain America seul), **change de DPS**."], "title": "Philosophie de jeu", "diagram": "pull"}, {"lead": "Tes attaques et les dégâts que tu prends remplissent ta rage, qui augmente tes dégâts. Ton passif te sauve de la mort une fois de temps en temps, avec plus de vie bonus si ta rage est haute.", "items": ["La rage **diminue avec le temps** : reste actif.", "Chaque élimination ou assistance **réduit le cooldown** de ta survie : enchaîne les fights gagnés.", "Une fois ta survie déclenchée, tu peux **rester agressif** quelques secondes pour finir ton pick."], "title": "Rage et régénération", "ability": "Berserker Rage · Regenerative Healing Factor"}, {"key": "Clic G · Clic D", "lead": "Des coups de griffes dont les dégâts dépendent de la vie maximale de la cible (donc très forts sur les tanks), et un bond court qui frappe pareil.", "items": ["En début de fight, frappe pour **remplir ta rage**, puis passe aux attrapes.", "Le bond est surtout ta **sortie de secours**.", "Il sert aussi à **rattraper** une cible qui fuit, ou à **passer derrière un tank** avant de l'attraper."], "title": "Griffes et bond", "ability": "Savage Claw · Vicious Rampage"}, {"lead": "Tu encaisses beaucoup moins de dégâts pendant quelques secondes.", "items": ["**Avant chaque attrape** : tout le lobby va te tirer dessus.", "Joue à couvert pour **ne pas avoir à l'utiliser trop tôt**.", "Astuce : hurle puis bondis dans le **météore de Magneto** pour le bloquer."], "title": "Hurlement", "ability": "Undying Animal"}, {"lead": "Tu bondis, saisis une cible et l'écrases au sol en l'étourdissant. Ensuite, tes griffes frappent beaucoup plus vite pendant un moment.", "items": ["Combo fiable : **bond pour te rapprocher, puis attrape** : presque impossible à rater.", "Après l'attrape, tes griffes rapides font **fondre un tank** en quelques secondes.", "Sur certaines cartes, emporte la cible **dans le vide**.", "Le **Star-Lord** prêt à ult sans contre de ton côté ? Ramène-le chez toi.", "Astuce : en sortant du spawn, **bond puis hurlement** pour annuler l'animation et filer plus vite."], "title": "Attrape", "ability": "Feral Leap"}, {"key": "Q", "lead": "Tu projettes les ennemis devant toi en l'air, puis les écrases au sol en les étourdissant. Les dégâts dépendent de leur vie maximale et de ta rage.", "items": ["L'ult ne donne **pas les griffes rapides** : fais d'abord une attrape, puis l'ult.", "Vise **assez en pente** à l'atterrissage pour ne rater personne.", "Elle **sort un support de son ult** : Invisible Woman, Cloak & Dagger sans intangibilité.", "Pas besoin de toucher tout le monde : **l'ult la plus utile** vaut mieux que la plus spectaculaire."], "title": "Ultime", "ability": "Last Stand"}, {"kind": "mistakes", "items": ["Diver **chez l'ennemi** au lieu de ramener la cible.", "Attraper **sans hurler** avant.", "Gâcher le hurlement **en début de fight**.", "Lancer l'ult **sans attrape** préalable.", "Insister contre une **Invisible Woman** qui annule tes attrapes."], "title": "Erreurs fréquentes"}], "synergies": [{"hero": "the-thing", "note": "Un brawler qui te fait entrer dans le fight."}, {"hero": "hulk", "note": "Même chose."}, {"hero": "phoenix", "note": "Ses explosions finissent tes cibles."}, {"hero": "magneto", "note": "Sa bulle protège tes attrapes."}, {"hero": "winter-soldier", "note": "Un DPS qui suit tes attrapes."}, {"hero": "jeff-the-land-shark", "note": "Ses bulles de vitesse t'aident à rôder."}, {"hero": "rocket-raccoon", "note": "Son pack de saut emporte tes cibles encore plus loin."}], "difficulty": 2, "patch_note": "Guide tiré d'une vidéo de Paz (padswagger), reformulé en français. Les chiffres du kit ont été retirés car ils changent à chaque saison ; team-ups et derniers changements sont à jour (saison 10.5) dans la section dédiée.", "kit": {"season": "Saison 10.5", "health": "", "abilities": [], "teamups": [{"name": "Blast Slash", "partners": ["cyclops"], "key": "", "text": "Griffes plus longues et Kinetic Claws. **Amélioré :** L'effet reste actif en permanence."}, {"name": "Gamma Fastball", "partners": ["hulk"], "key": "", "text": "État furieux et Scars of Rage (+25 % vitesse d'attaque et de déplacement en 10.5). **Amélioré :** Débloque le Fastball Special (Unstoppable : seuil 400, cooldown 45 s en 10.5)."}, {"name": "Pair of Threes", "partners": ["gambit"], "key": "", "text": "Amélioration cinétique avec des particules qui explosent. **Amélioré :** Ajoute un soin continu."}], "changes": [{"season": "Saison 10", "text": "Savage Claw 15 → 18 de dégâts de base ; le soin ne dépend plus de la rage (300 fixes)."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · changements : patch notes des saisons 10 et 10.5", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'wolverine' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"summary": "Cyclops est un tireur hitscan à longue portée, plus mobile que Hela ou Phoenix mais sans aucun contrôle. Il pique des cibles à la tête depuis le high ground, arrose les groupes avec son rayon et finit les fights avec un ult capable d'effacer une équipe groupée.", "patch_note": "Conseils tirés d'une vidéo de Tephra98 enregistrée à la sortie du héros (saison 8.5) : chiffres et team-ups ont pu changer. En 10.5, Optic Blast et Ricochet Force ont été légèrement améliorés et l'ult coûte moins cher.", "tldr": ["Joue comme un **hitscan** : avec ton équipe, sur un **off-angle** ou en **high ground**, et vise la tête.", "**Ricochet Force** dès que possible : elle finit les cibles et te donne de la **vie bonus**.", "Pas de stun : évite les **1v1 au contact**, utilise tes deux mobilités pour reprendre de la distance."], "difficulty": 1, "tags": ["Hitscan", "Longue portée", "High ground", "Mobile"], "sections": [{"title": "Philosophie de jeu", "kind": "tips", "lead": "Tu joues avec ton équipe comme un sniper mobile : tu prends un angle ou une hauteur, tu sors une cible importante, et tu changes de position avant qu'on vienne te chercher.", "items": ["Le **high ground** est ton meilleur ami : tu tires par-dessus les boucliers et tes headshots deviennent plus faciles.", "Tu as **plus de mobilité** que les autres hitscan : sers-t'en pour prendre des angles agressifs sur le flank.", "Tu n'as **aucun stun** : un duel au contact contre un diver est risqué, reprends de la distance.", "Garde un œil sur ta jauge de vie bonus : **Ricochet Force** la recharge."], "diagram": "highground"}, {"title": "Optic Blast", "ability": "Optic Blast", "key": "Clic G", "lead": "Un tir instantané (hitscan) avec une perte de dégâts très lointaine : tu as plus de portée effective que Hela.", "items": ["Deux **headshots** suffisent sur beaucoup de cibles : vise la tête en priorité.", "Chaque touche **réduit le cooldown** de Ricochet Force : plus tu touches, plus tu la relances.", "Pense à recharger entre deux échanges, pas au moment du pick."]}, {"title": "Rayon concussif", "ability": "Concussive Beam", "key": "Clic D", "lead": "Un rayon continu qui touche tous les ennemis dans la zone, avec plus de dégâts sur la cible visée. Il consomme une jauge à part.", "items": ["Le sweet spot : **2 ou 3 ennemis** dans le rayon. Plus il y en a, moins il fait mal à chacun.", "Utilise-le pour **mettre la pression sur toute l'équipe** adverse, pas seulement sur ta cible.", "Utilisé en tombant, il active ton **vol plané** : combine-le avec Optic Ascent pour arroser la backline par-dessus les boucliers."]}, {"title": "Ricochet Force", "ability": "Ricochet Force", "lead": "Un tir qui rebondit sur les joueurs et les surfaces et blesse tous les ennemis touchés. Deux charges, et chaque utilisation donne de la vie bonus.", "items": ["Vise **directement une cible** : les dégâts sont doublés sur elle.", "Utilise-la **après deux Optic Blast** pour finir une cible.", "En panique ou en duel, lance-la même sans viser parfaitement : la **vie bonus** peut te sauver.", "Garde ta vie bonus **au maximum** avant un fight où tu risques d'être divé."]}, {"title": "Mobilité", "ability": "Propulsion Blast · Optic Ascent", "lead": "Propulsion Blast te propulse dans la direction voulue en repoussant et ralentissant les ennemis touchés ; Optic Ascent t'envoie haut dans les airs.", "items": ["Propulsion Blast se **tape pour un petit dash** ou se **maintient pour une longue course** que tu peux orienter avec la caméra.", "Vise un ennemi avec Propulsion Blast pour **le repousser** et créer de la distance.", "Sur les cartes avec du vide (Spider-Islands par exemple), Propulsion Blast peut **sortir un ennemi de la carte**.", "Optic Ascent te met **en hauteur en un instant** : idéal pour reprendre un angle ou préparer ton ult."]}, {"title": "Ultime", "ability": "Ruby Rage", "key": "Q", "lead": "Tu vises, tu confirmes, et un rayon de plus de 60 m rend le sol explosif : tout ce qui se trouve sur la trajectoire prend d'énormes dégâts, en pourcentage de vie.", "items": ["Tu peux **annuler sans pénalité** avant de confirmer : prends le temps de viser le groupe.", "Les dégâts en pourcentage **font mal aux tanks** aussi.", "Le rayon monte sur les surfaces : **le high ground adverse n'est pas à l'abri**, surtout si tu montes avec Optic Ascent.", "Combo idéal avec une **ult de Groot**, un boost de Mantis ou de Rocket. Continue à tirer pendant l'ult."]}, {"title": "Erreurs fréquentes", "kind": "mistakes", "items": ["Accepter un **duel au contact** contre un diver.", "Rester au sol au milieu de la mêlée au lieu de **prendre de la hauteur**.", "Oublier **Ricochet Force** et la vie bonus qu'elle donne.", "Utiliser le rayon sur **un seul ennemi isolé** ou sur un paquet de six.", "Attendre que l'ult finisse le travail **sans tirer à côté**."]}], "counters": [{"hero": "spider-man", "note": "Il te tombe dessus en hauteur et tu n'as pas de stun pour l'arrêter."}, {"hero": "black-panther", "note": "Un diver qui gagne le duel au contact."}, {"hero": "magik", "note": "Elle arrive par portail sur ton angle."}, {"hero": "hela", "note": "Même rôle, avec un stun et plus de burst en duel à distance."}], "synergies": [{"hero": "groot", "note": "Son ult regroupe les ennemis sur la trajectoire de la tienne."}, {"hero": "mantis", "note": "Son bonus de dégâts rend ton ult et tes headshots mortels."}, {"hero": "wolverine", "note": "Team-up commun, et il occupe les tanks pendant que tu tires."}, {"hero": "gambit", "note": "Team-up commun qui te donne vitesse et saut."}], "sources": [{"title": "Ultimate Cyclops Guide (Beginner/Advanced)", "author": "Tephra98", "url": "https://www.youtube.com/watch?v=oN9sOyaQYwA"}], "kit": {"season": "Saison 10.5", "health": "", "abilities": [], "teamups": [{"name": "Blast Slash", "partners": ["wolverine"], "key": "", "text": "Griffes plus longues et Kinetic Claws. **Amélioré :** L'effet reste actif en permanence."}, {"name": "Kinetic Kin", "partners": ["gambit"], "key": "", "text": "Boost de vitesse et de saut (8 s en 10.5). **Amélioré :** Augmente la vitesse d'attaque."}, {"name": "Slim and Red", "partners": ["phoenix"], "key": "", "text": "Embrasement qui brûle et déclenche les étincelles (cooldown 10 s en 10.5). **Amélioré :** Les étincelles réduisent le cooldown de Ricochet Force."}], "changes": [{"season": "Saison 10.5", "text": "Optic Blast 22 → 23 par coup, -0,3 s de cooldown de Ricochet Force par touche (au lieu de 0,25 s), ult moins chère (3700 → 3400)."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · changements : patch notes des saisons 10 et 10.5", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'cyclops' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"summary": "Devil Dinosaur est un tank de brawl qui vit du saignement : il mord, fait saigner, gagne de la vie bonus à chaque dégât et attrape les tanks adverses pour les jeter dans son équipe. Il ne peut pas être déplacé et ses dégâts en pourcentage font fondre les autres tanks.", "patch_note": "Conseils tirés d'une vidéo de Tephra98 enregistrée à la sortie du héros : chiffres et team-ups ont pu changer. Saignement renforcé en saison 10, vie de base 850 → 825 en 10.5.", "tldr": ["**Fais saigner partout** : chaque ennemi qui saigne te rapporte de la vie bonus.", "Ta boucle : **morsure, attrape, jette dans ton équipe, Frenzied Feast**.", "Sois une **nuisance pour le tank adverse** : s'il passe son temps à se sauver, il ne prend pas d'espace."], "difficulty": 1, "tags": ["Brawl", "Tank", "Saignement", "Kidnap"], "sections": [{"title": "Philosophie de jeu", "kind": "tips", "lead": "Tu es probablement le meilleur tank de brawl du jeu : tes dégâts en pourcentage et ta vie bonus te font gagner presque tous les duels de tanks.", "items": ["Joue **au front** et répartis ton saignement sur un maximum d'ennemis.", "Concentre-toi sur **les tanks** : tes dégâts en pourcentage leur font plus mal. Ne prends un fragile que s'il est vraiment mal placé.", "Ton attrape sert surtout à **te replacer ou à fuir**, sauf si ton ult est prêt.", "Tu es **immunisé aux déplacements** (pas de projection ni de recul) et tu prends moins de dégâts à la tête."], "diagram": "brawl"}, {"title": "Morsure et queue", "ability": "Morsure · coup de queue", "key": "Clic G", "lead": "Ta morsure applique le saignement, des dégâts en pourcentage de vie qui te donnent de la vie bonus grâce à ton passif.", "items": ["La morsure est le moyen **le plus rapide** de faire saigner : commence par là.", "Ta mêlée est un **coup de queue** : il ne touche pas ce que tu regardes, il faut tourner la caméra.", "Place-toi **entre deux ennemis** pour mordre l'un et fouetter l'autre."]}, {"title": "Rayon d'impact", "ability": "Impact Beam", "key": "Clic D", "lead": "Un rayon perçant qui fait saigner, ralentit et fait tomber les flyers au sol. Il consomme une jauge.", "items": ["**Maintiens-le 1 à 2 secondes** sur une cible : un simple tap n'applique presque pas de saignement.", "C'est ta réponse aux **flyers** : il les cloue au sol.", "C'est ta seule attaque **bloquée par les boucliers** : contre un bouclier, passe au contact."]}, {"title": "Attraper et jeter", "ability": "Savage Predation", "lead": "Un bond suivi d'une morsure. Si la cible saigne déjà, tu la soulèves et tu la jettes.", "items": ["Regarde le sol pour un **petit bond**, devant toi pour un bond moyen, le ciel pour le plus long.", "Jette la cible **dans ton équipe** pour qu'elle se fasse focus, puis enchaîne Frenzied Feast.", "Ta grosse silhouette **bloque les soins directs** qu'elle reçoit : place-toi entre elle et ses heals.", "C'est aussi ta **seule mobilité** : garde-la pour te sortir d'une mauvaise position."]}, {"title": "Barrière", "ability": "Buddy Barrier", "lead": "Un bouclier qui t'entoure et te suit, et ralentit les ennemis pris dedans.", "items": ["Avance avec pour **prendre de l'espace** au front.", "Pose-la sur la cible que tu viens de jeter : **ralentie, elle reste dans ta backline**.", "Elle protège ton équipe contre les **gros ults de dégâts** (Magneto, Iron Man)."]}, {"title": "Frenzied Feast", "ability": "Frenzied Feast", "lead": "Quatre morsures d'affilée, qui font plus de dégâts aux cibles qui saignent et convertissent les dégâts en vie bonus.", "items": ["Fais toujours **saigner avant** : bonus de dégâts et encore plus de vie bonus.", "Enchaîne-la **juste après avoir jeté** une cible dans ton équipe : c'est souvent un kill assuré."]}, {"title": "Ultime", "ability": "Devil Beast Rampage", "key": "Q", "lead": "Tu deviens enragé : énorme vitesse, et un piétinement chaque seconde qui projette, ralentit et fait saigner tout autour.", "items": ["Pendant l'ult, Frenzied Feast se **relance presque instantanément** : spamme-la.", "Savage Predation revient aussi **très vite** : engage une cible, et si elle saute, rattrape-la.", "C'est le bon moment pour **engager** avec l'attrape."]}, {"title": "Erreurs fréquentes", "kind": "mistakes", "items": ["Taper le rayon **en tap** au lieu de le maintenir.", "Engager à l'attrape **sans ult** et se retrouver seul au milieu de l'ennemi.", "Chasser les fragiles au lieu de **punir le tank** adverse.", "Oublier que la queue **ne frappe pas devant toi**."]}], "counters": [{"hero": "the-punisher", "note": "Des dégâts constants sur une énorme hitbox."}, {"hero": "cyclops", "note": "Son rayon et ses tirs touchent ta grosse silhouette sans effort."}, {"hero": "blade", "note": "Il coupe les soins que tu reçois en brawl."}], "synergies": [{"hero": "the-punisher", "note": "Team-up commun : The Punisher monte sur ton dos et partage tes dégâts."}, {"hero": "elsa-bloodstone", "note": "Team-up commun autour de son piège."}, {"hero": "jeff-the-land-shark", "note": "Team-up commun : Jeff te chevauche et vous vous soignez."}, {"hero": "luna-snow", "note": "Une heal de brawl qui suit ton rythme au front."}], "sources": [{"title": "Ultimate Devil Dinosaur Guide (Beginner/Advanced)", "author": "Tephra98", "url": "https://www.youtube.com/watch?v=Mu48nMPiYdI"}], "kit": {"season": "Saison 10.5", "health": "", "abilities": [], "teamups": [{"name": "Prehistoric Trap", "partners": ["elsa-bloodstone"], "key": "", "text": "Smoky Snare immobilise et gaze (cooldown 15 s depuis la saison 10). **Amélioré :** Deux pièges."}, {"name": "Primal Punishment", "partners": ["the-punisher"], "key": "", "text": "Canons magnétiques qui font saigner (projectiles à 150 m/s depuis la saison 10). **Amélioré :** The Punisher chevauche Devil Dinosaur et partage les dégâts."}, {"name": "Surf & Turf", "partners": ["jeff-the-land-shark"], "key": "", "text": "Jet d'eau qui blesse et soigne. **Amélioré :** Jeff chevauche Devil Dinosaur, et les deux se soignent."}], "changes": [{"season": "Saison 10", "text": "Saignement : cumuls de 1 s au lieu de 0,5 s, dégâts 0,75 % → 1,2 %."}, {"season": "Saison 10.5", "text": "Vie de base 850 → 825."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · changements : patch notes des saisons 10 et 10.5", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'devil-dinosaur' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"summary": "Jubilee est une heal hybride à portée infinie : ses orbes soignent les alliés et blessent les ennemis, et ses marques d'étincelles débloquent un mode de tir rapide où elle soigne et fait mal en même temps. Tout son niveau tient dans la gestion de ses orbes et de ses marques.", "patch_note": "Conseils tirés d'une vidéo de Tephra98 enregistrée à la sortie de l'héroïne (saison 9) : chiffres et team-ups ont pu changer. En 10.5, Sparking Sprint soigne en continu et l'ult soigne plus.", "tldr": ["**Jamais d'orbe en cooldown** : récupère-la avant la fin et relance-la, c'est aussi ta seule vraie source d'auto-soin.", "Fais exploser une orbe **améliorée** pour marquer un maximum de joueurs, puis tire sur les marques.", "Tu es plutôt une **off-heal** avec du burst : reste près de ton équipe contre le dive."], "difficulty": 2, "tags": ["Heal", "Off-heal", "Portée infinie", "Hybride"], "sections": [{"title": "Philosophie de jeu", "kind": "tips", "lead": "Tu soignes et tu fais des dégâts en même temps. La différence entre une bonne et une mauvaise Jubilee, c'est le temps passé en mode étincelles.", "items": ["Ton tir a une **portée infinie** : joue en sécurité, loin du danger.", "Contre une compo **dive** (Venom, Spider-Man), reste près de ton équipe pour qu'elle puisse te peel. Pour fuir un diver, **cours vers tes alliés**.", "Ton soin est correct mais pas énorme : vois-toi comme une **off-heal avec du burst**.", "Début de fight : orbe sur ton tank, explosion pour **marquer plusieurs joueurs**, puis seconde orbe dans la mêlée."], "diagram": "heal"}, {"title": "Tir de lumière", "key": "Clic G", "lead": "Un tir rapide qui blesse les ennemis et soigne les alliés, avec une portée infinie et très peu de perte à distance.", "items": ["C'est un **projectile** : anticipe sur les cibles lointaines.", "Pas de headshot dans le mode normal : vise le corps."]}, {"title": "Orbes", "ability": "Blooming Ball", "lead": "Une orbe qui suit la cible la plus proche : elle soigne les alliés et blesse les ennemis dans sa bulle. Deux charges, et elle s'améliore en soignant ou en blessant.", "items": ["Lance-la **au sol à côté** d'un joueur : elle n'a pas de collision, elle le suivra de toute façon.", "Une orbe améliorée est **plus grande, plus forte** et repart pour une durée complète.", "Tu peux la **récupérer sans ligne de vue** pour relancer son cooldown : fais-le avant qu'elle expire.", "Seule et sans cible, **tire dessus** pour l'améliorer et te soigner."]}, {"title": "Détonation et marques", "ability": "Dazzling Detonation", "lead": "Fait exploser une orbe : soin, vitesse et bonus de soin pour les alliés, dégâts et vulnérabilité pour les ennemis. Tout le monde dans la zone reçoit une marque d'étincelles.", "items": ["Après la première, attends que l'orbe soit **améliorée** avant de la faire exploser : plus de joueurs marqués.", "Tirer sur un joueur marqué consomme la marque : **vie bonus et bonus de soin** pour un allié, dégâts en plus sur un ennemi.", "Consommer une marque déclenche ton **mode étincelles** : cadence très élevée, sans munitions. C'est là que tu es la plus dangereuse."]}, {"title": "Sprint", "ability": "Sparking Sprint", "lead": "Vitesse et hauteur de saut en plus, avec le mode étincelles activé. En sortant, tu libères une explosion qui soigne et repousse.", "items": ["Il consomme une **jauge** et part en cooldown de quelques secondes dès l'activation.", "Depuis la saison 10.5, il **te soigne en continu** : c'est ton outil de survie contre les divers.", "Garde toujours une marque ou le sprint de côté quand tu sais que tu vas être divée."]}, {"title": "Ultime", "ability": "Firework Finale", "key": "Q", "lead": "Un anneau d'énergie qui soigne les alliés, repousse les ennemis et marque tout le monde ; des orbes tournent autour de toi et soignent ou blessent au contact.", "items": ["Réduire le rayon fait **tourner les orbes plus vite** : plus de burst si elles touchent.", "Agrandir le cercle **repousse les ennemis** : utile pour peel ou dégager un point.", "Elle est moins forte que l'ult de Luna ou de Cloak & Dagger : **vise avec les orbes** pour maximiser le soin.", "Tu peux être **stun ou déplacée** pendant l'ult : méfie-toi des tanks qui foncent sur toi."]}, {"title": "Erreurs fréquentes", "kind": "mistakes", "items": ["Laisser une orbe **expirer** au lieu de la récupérer.", "Lancer l'orbe **directement sur un joueur** au lieu du sol.", "Faire exploser une orbe **pas améliorée** au milieu du fight.", "Jouer seule loin de ton équipe contre une compo **dive**.", "Rester immobile pendant l'ult face à des tanks qui peuvent te **stun**."]}], "counters": [{"hero": "venom", "note": "Il arrive sur toi et coupe ton mode étincelles."}, {"hero": "spider-man", "note": "Il te tombe dessus si tu joues trop loin de ton équipe."}, {"hero": "doctor-strange", "note": "Il peut foncer dans ton ult et la casser."}], "synergies": [{"hero": "the-hood", "note": "Team-up commun : ton tir devient hitscan avec vol de vie et headshots."}, {"hero": "blade", "note": "Team-up commun : champ vampirique qui soigne ton équipe."}, {"hero": "human-torch", "note": "Team-up commun avec des étincelles à tête chercheuse."}, {"hero": "gambit", "note": "Team-up commun : un bâton qui soigne et bloque les projectiles."}], "sources": [{"title": "Ultimate Jubilee Guide (Beginner/Advanced)", "author": "Tephra98", "url": "https://www.youtube.com/watch?v=XuEoj9TR284"}], "kit": {"season": "Saison 10.5", "health": "", "abilities": [], "teamups": [{"name": "Fiery Sparks", "partners": ["human-torch"], "key": "", "text": "Étincelles de feu d'artifice à tête chercheuse. **Amélioré :** Vie bonus à l'atterrissage."}, {"name": "Hellfire Sparks", "partners": ["the-hood"], "key": "", "text": "Forme hitscan avec auto-soin. **Amélioré :** Garde la marque de magie du vide."}, {"name": "Hex Fireworks", "partners": ["scarlet-witch"], "key": "", "text": "Détonation de sceau plasmoïde. **Amélioré :** Ajoute un soin continu."}, {"name": "Sparkling Staff", "partners": ["gambit"], "key": "", "text": "Un bâton qui soigne et bloque les projectiles (2 s en 10.5). **Amélioré :** Ajoute des auras de soin continu."}, {"name": "Vampiric Kin", "partners": ["blade"], "key": "", "text": "Champ vampirique qui soigne et donne du vol de vie (soin de 15/s autour pendant 6 s en 10.5). **Amélioré :** Soin supplémentaire."}], "changes": [{"season": "Saison 10.5", "text": "Sparking Sprint soigne 25/s ; aveuglement de Dazzling Detonation 1,5 s → 0,8 s ; ult 150/s → 180/s de soin."}, {"season": "Saison 10", "text": "Tous les Strategists : l'ult se charge un peu moins vite (65 % du soin et 50 % des dégâts convertis en énergie, au lieu de 70 % et 55 %)."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · changements : patch notes des saisons 10 et 10.5", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'jubilee' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"summary": "Spider-Man est l'assassin le plus mobile du jeu : il swingue autour du fight, pose ses traceurs, dive sur un heal isolé et ressort avant que la riposte arrive. Il n'a aucun cooldown défensif : chaque engage doit être choisi, sinon il meurt en une rotation.", "patch_note": "Conseils tirés de vidéos de Tephra98 enregistrées entre la saison 0 et la saison 2. Le plan de jeu reste valable, mais les chiffres, certains combos one-shot et les team-ups ont changé (Amazing Combo est passé à 1 s de cooldown en saison 10) : vérifie en jeu.", "tldr": ["**Pas de cooldown défensif** : entre vite, tue, ressors. Si l'engage n'est pas sûr, fais un **drive-by** et repars.", "Le **traceur** (Clic D) est la base de tout : il ouvre tes combos et permet de te tirer vers la cible.", "Cible les **heals et les flyers**, presque jamais les tanks."], "difficulty": 3, "tags": ["Dive", "Assassin", "Mobilité", "Mécanique"], "sections": [{"title": "Philosophie de jeu", "kind": "tips", "lead": "Spider-Man est un backline assassin fragile : sa survie, c'est son mouvement. Un Spidey qui reste immobile au milieu de l'équipe adverse est un Spidey mort.", "items": ["Swingue autour du fight, choisis **une cible isolée**, pose un traceur, puis engage.", "Avant de commit, **fais sortir les cooldowns** adverses (Soul Bond, sommeil de Mantis, coup de pied de Black Widow) avec un drive-by.", "Après le kill, **ressors tout de suite** : rester une seconde de trop, c'est se faire stun.", "Si la backline est trop protégée, passe en mode **fishing** : tire des ennemis isolés vers ton équipe au lieu de diver."], "diagram": "dive"}, {"title": "Réglages à changer", "kind": "tips", "lead": "Trois réglages du héros changent tout : sans eux, une bonne partie de la tech de Spidey est impossible.", "items": ["Désactive le **swing automatique** : tu choisis toi-même le point d'accroche, et viser sous la ligne de tête déclenche un **web zip** (traction droite).", "Active **maintenir pour grimper aux murs** : tu lâches le mur dès que tu relâches la touche, au lieu de rester collé au pire moment.", "Mets **« tirer la cible vers toi »** (Get Over Here) sur une touche à part : tu peux attirer un ennemi même s'il porte ton traceur.", "Sur PC, mettre le **saut sur la molette** permet de grimper aux murs bien plus vite et sans animation de sortie."]}, {"title": "Traceurs et coups", "ability": "Web-Cluster · Spider-Power", "key": "Clic D · Clic G", "lead": "Le Clic D lance une toile qui pose un traceur : la prochaine capacité sur la cible le fait exploser pour des dégâts en plus. Le Clic G enchaîne deux coups de poing et un coup de pied.", "items": ["Les toiles sont aussi une **ressource de mouvement** : ne les vide pas toutes avant d'engager.", "Tes coups de poing peuvent être **annulés par toutes tes capacités** : glisse-les entre deux pour des dégâts gratuits.", "Après un double saut, le Clic G donne un **slam aérien** : il est au cœur des combos actuels.", "Les traceurs **ne se cumulent pas** : un seul par cible."]}, {"title": "Swing et web zip", "ability": "Web-Swing", "key": "Maj", "lead": "Viser au-dessus de la tête donne un long swing ; viser en dessous donne un web zip, une traction rapide vers le point visé.", "items": ["Annule le web zip avec une toile (Clic D) : tu **gardes l'élan** et tu supprimes l'animation d'arrivée.", "En sautant juste en touchant le sol après un zip, tu fais un **bunny hop** qui conserve ta vitesse : indispensable dans les espaces fermés.", "Un **zip aux pieds** d'un ennemi suivi d'un uppercut donne des dégâts gratuits sans utiliser Get Over Here.", "Garde **toujours un swing en réserve** pour fuir : Invisible Woman peut te sortir de ton swing en l'air."]}, {"title": "Attirer et se tirer", "ability": "Get Over Here!", "key": "E", "lead": "Sur une cible sans traceur, tu l'attires vers toi. Sur une cible avec traceur, c'est toi qui te tires vers elle et tu la frappes d'un coup de pied.", "items": ["La traction est un **étourdissement** : elle coupe l'ult de Scarlet Witch, l'ult d'Iron Man ou le portail de Doctor Strange si tu la gardes pour ça.", "Tu n'as pas besoin de regarder la cible : **zippe vers une ligne de vue**, puis tire-toi vers elle, ton approche devient imprévisible.", "Sur les cartes avec du vide (Hell's Heaven, Spider-Islands), **attirer un tank sans mobilité** au-dessus du vide peut décider le fight.", "Contre une ult de zone statique (Cloak & Dagger, Invisible Woman), **tire le support hors de sa zone**."]}, {"title": "Uppercut", "ability": "Amazing Combo", "key": "F", "lead": "Un uppercut à deux charges qui projette en l'air : c'est ton outil de combo principal, avec un cooldown très court depuis la saison 10.", "items": ["Il **annule ton swing en gardant l'élan** : un uppercut en passant (drive-by) fait des dégâts et te laisse filer.", "Il touche large : sur un groupe, il charge vite ton ult et **force les cooldowns** adverses.", "Après un uppercut, la cible suit une trajectoire prévisible : idéal pour **l'attirer loin de son équipe**."]}, {"title": "Combos", "kind": "tips", "lead": "La logique de base : traceur, approche, uppercut, puis un slam aérien ou une toile pour finir. Plus la cible a de vie, plus tu rallonges la fin.", "items": ["**Fragile (250 PV)** : traceur, Get Over Here, uppercut, swing annulé en slam aérien.", "**Un peu plus de vie** : remplace la fin par un zip annulé par une toile, puis un slam.", "**Sans Get Over Here** : zip aux pieds, toile, uppercut, zip annulé, toile, slam.", "**Contre les tanks** (seulement si tu n'as pas d'autre cible) : uppercut, toile, slam, saut, second slam, et on recommence.", "Entraîne chaque combo sur les **bots du champ de tir** (fragiles, volants, tanks) avant de le tenter en ranked."]}, {"title": "Ultime", "ability": "Spectacular Spin", "key": "Q", "lead": "Spider-Man gagne beaucoup de vie bonus et arrose de toiles tout autour de lui, qui blessent et immobilisent.", "items": ["Tu **n'es pas insensible aux contrôles** pendant l'ult : un hook de Winter Soldier ou une toile de Peni la coupent.", "L'élan du swing se conserve : rapproche-toi **au plus près** avant de la lancer, sinon tu dépasses ta cible.", "Elle se contre facilement avec d'autres ults : **lance-la après** les ults défensives adverses."]}, {"title": "Les matchups clés", "kind": "tips", "lead": "Presque tout le roster a une réponse à Spidey : savoir quoi attendre de chacun évite les engages suicide.", "items": ["**Adam Warlock** : force son Soul Bond, attends qu'il retombe, puis reviens.", "**Mantis** : son sommeil se pose facilement sur un mêlée, ressors dès ton uppercut.", "**Rocket** : cherche sa **balise de résurrection** en swinguant, et ne le chasse pas s'il a ses dashes.", "**Black Widow** : son coup de pied touche tout autour d'elle, entre et sors très vite.", "**Winter Soldier, Namor et The Punisher** sont tes vrais counters : écoute le hook, attends que les tourelles tombent, recule quand le fusil à pompe sort.", "Contre un autre Spidey, **la première toile qui touche gagne** le duel."]}, {"title": "Erreurs fréquentes", "kind": "mistakes", "items": ["Garder le **swing automatique**.", "Engager **sans traceur** sur la cible.", "Rester au milieu de l'équipe adverse **après le kill**.", "Diver un heal qui a encore **Soul Bond, sommeil ou stun**.", "Gaspiller ses toiles et n'avoir **plus rien pour fuir**.", "Focus les **tanks** au lieu des heals et des flyers."]}], "combos": [{"title": "Fragile", "steps": [{"key": "Clic D", "label": "traceur"}, {"key": "E", "label": "se tirer"}, {"key": "F", "label": "uppercut"}, {"key": "", "label": "Swing annulé"}, {"key": "Clic G", "label": "slam"}], "note": "Le swing doit s'accrocher à une surface pour donner l'slam aérien."}, {"title": "Fishing", "steps": [{"key": "Clic D", "label": "traceur"}, {"key": "", "label": "Attirer la cible"}, {"key": "Clic G", "label": "coup"}, {"key": "Clic D", "label": "annule le coup"}, {"key": "F", "label": "uppercut"}], "note": "Mets « attirer la cible » sur une touche à part pour pouvoir le faire même avec un traceur."}, {"title": "Drive-by", "steps": [{"key": "Clic D", "label": "traceur"}, {"key": "", "label": "Zip aux pieds"}, {"key": "F", "label": "uppercut en passant"}, {"key": "Clic D", "label": "toile"}, {"key": "E", "label": "se tirer"}, {"key": "Clic G", "label": "finir"}], "note": "Zippe à côté de la cible, pas devant elle, sinon tu restes bloqué contre elle."}], "counters": [{"hero": "winter-soldier", "note": "Son hook coupe tes combos et ton ult, et il encaisse beaucoup."}, {"hero": "namor", "note": "Ses tourelles te repèrent et te ralentissent dès que tu approches."}, {"hero": "the-punisher", "note": "Son fusil à pompe te tue en deux tirs."}, {"hero": "black-widow", "note": "Son coup de pied tout autour d'elle t'étourdit même de dos."}, {"hero": "adam-warlock", "note": "Soul Bond absorbe ton burst."}, {"hero": "mantis", "note": "Son sommeil se pose facilement sur un mêlée."}, {"hero": "peni-parker", "note": "Son nid protège sa backline et ses toiles coupent ton ult."}], "synergies": [{"hero": "venom", "note": "Le partenaire de dive idéal, avec un team-up commun."}, {"hero": "mantis", "note": "Son bonus de dégâts juste avant ton engage rend tes combos mortels."}, {"hero": "luna-snow", "note": "Son flocon te soigne même hors de sa ligne de vue."}, {"hero": "hulk", "note": "Un tank de dive qui attire l'attention pendant que tu frappes."}, {"hero": "black-cat", "note": "Team-up commun pour marquer et voler de la Fortune."}], "sources": [{"title": "Ultimate Spider-Man Guide (Beginner/Advanced)", "author": "Tephra98", "url": "https://www.youtube.com/watch?v=Mwf3_k7gffw"}, {"title": "The Complete Advanced Spider-Man Tech Guide", "author": "Tephra98", "url": "https://www.youtube.com/watch?v=9h5BoOXEgOE"}, {"title": "Season 2 Spider-Man Combos Guide", "author": "Tephra98", "url": "https://www.youtube.com/watch?v=kHP_8vkpk3c"}, {"title": "37 Spider-Man Tips to Instantly Improve", "author": "Tephra98", "url": "https://www.youtube.com/watch?v=AX2BsGJ_ZvU"}], "kit": {"season": "Saison 10.5", "health": "", "abilities": [], "teamups": [{"name": "Binding Ties", "partners": ["black-cat"], "key": "", "text": "Un grappin de toile vole de la Fortune et marque la cible, qui prend plus de dégâts."}, {"name": "ESU Alumnus", "partners": ["squirrel-girl"], "key": "", "text": "Bombe de toile qui explose et laisse une zone de toile. **Amélioré :** La toile collante reste au sol."}, {"name": "Parker Power-Up", "partners": ["peni-parker"], "key": "", "text": "Bombe-araignée collante qui marque les ennemis (cooldown 10 s depuis la saison 10). **Amélioré :** Vie bonus à la détonation."}, {"name": "Symbiote Bond", "partners": ["venom"], "key": "", "text": "Pointes de symbiote qui repoussent les ennemis. **Amélioré :** Ajoute des tentacules qui relient."}], "changes": [{"season": "Saison 10", "text": "Amazing Combo : cooldown 2 s → 1 s."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · changements : patch notes des saisons 10 et 10.5", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'spider-man' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"summary": "The Hood est un tank à distance qui tire sans arrêt pour charger son énergie démoniaque : à 100, il se transforme en démon armé de mitrailleuses avec vol de vie. Entre deux transformations, il tient avec sa bulle d'absorption, son voile et sa marche dans le vide.", "patch_note": "Conseils tirés d'une vidéo de Tephra98 enregistrée à la sortie du héros (saison 9.5) : chiffres et team-ups ont pu changer. En saison 10 : vie de base 600 → 550, bulle à 12 s de cooldown.", "tldr": ["**Tire en continu** : chaque balle qui touche charge ton énergie démoniaque.", "À 100, passe en **forme de démon** : mitrailleuses, vol de vie, vie bonus. C'est ton pic de pression.", "Place ton **voile derrière le tank adverse** pour couper les soins et les dégâts de son équipe."], "difficulty": 2, "tags": ["Tank", "Distance", "Off-tank", "Pression"], "sections": [{"title": "Philosophie de jeu", "kind": "tips", "lead": "Tu joues au front, idéalement en second tank. Ton objectif : rester en vie assez longtemps pour charger ta forme de démon, puis faire fondre l'équipe adverse.", "items": ["Ne t'arrête jamais de tirer : l'énergie **ne baisse pas** tant que tu n'es pas en forme de démon.", "Ta bulle te garde en vie **et** te donne de l'énergie : utilise-la souvent.", "Ta force, c'est la **guerre d'usure au front** : force les cooldowns des heals adverses."], "diagram": "space"}, {"title": "Pistolets et énergie", "ability": "Pistolets · Ruinous Pact", "key": "Clic G", "lead": "Deux pistolets qui peuvent faire des headshots. Chaque balle qui touche charge ton énergie démoniaque : cadence plus rapide à 50, forme de démon à 100.", "items": ["En forme de démon, tes pistolets deviennent des **mitrailleuses** (Clic G et Clic D pour chaque arme) avec vol de vie et vie bonus.", "L'énergie se vide dès que tu te transformes : **choisis le bon moment**, pas juste quand la jauge est pleine.", "Tu peux sortir de la forme de démon au-dessus de 50 : tu gardes 25 d'énergie au lieu de retomber à zéro."]}, {"title": "Bulle d'absorption", "ability": "Mantle of Oblivion", "key": "Clic D", "lead": "Une bulle très courte qui absorbe n'importe quelle quantité de dégâts et de soins, et te rend de l'énergie. Indisponible en forme de démon.", "items": ["Passe-la en **mode bascule** dans les réglages pour ne pas l'annuler par erreur.", "Au-dessus de 50 d'énergie, elle est **plus grande**.", "Saute sur tes heals ou dans un ult adverse (Iron Man, Magneto) pour **absorber les dégâts** à leur place : le timing est serré."]}, {"title": "Marche dans le vide", "ability": "Void Walk", "lead": "Tu deviens inciblable et tu te déplaces librement un court instant ; en sortant, une explosion blesse autour de toi et tu gagnes un peu de vitesse.", "items": ["C'est ta **carte « sortie de prison »** : garde-la pour te sauver.", "Elle te donne aussi de l'**énergie démoniaque**.", "Elle peut te monter **en l'air** pour lancer ton ult en hauteur."]}, {"title": "Voile", "ability": "Abyssal Veil", "lead": "Un grand voile qui réduit les dégâts et les soins ennemis qui le traversent. Tirer à travers donne plus d'énergie et plus de vol de vie.", "items": ["Besoin de survivre et de charger ? Pose-le **entre toi et le tank adverse**.", "En position de force, lance-le **juste derrière le tank adverse** : moins de soins pour lui, moins de dégâts de son équipe.", "Il se pose **en l'air** : place-le devant une Hela ou un Iron Man qui ultent.", "Un ennemi qui le traverse prend des dégâts et est **aveuglé**."]}, {"title": "Ultime", "ability": "Demon of the End", "key": "Q", "lead": "Tu te soignes complètement et deviens une tourelle de 1000 PV avec six tirs perçants dévastateurs, qui donnent aussi de la vie bonus à ton équipe.", "items": ["Le **sixième tir** fait presque le double des autres : garde-le pour la cible importante.", "La portée est **courte** : lance-la au contact du fight.", "Utilise-la comme **deuxième vie** quand tu es sur le point de mourir : tu ressors avec toute ta vie.", "Combinée à une autre ult (Winter Soldier), elle peut **tuer un heal dans son ult**."]}, {"title": "Erreurs fréquentes", "kind": "mistakes", "items": ["Arrêter de tirer et **laisser l'énergie stagner**.", "Se transformer **hors du fight** et gaspiller la forme de démon.", "Oublier que la bulle est **indisponible en forme de démon**.", "Poser le voile au hasard au lieu de **couper les soins du tank** adverse.", "Utiliser la marche dans le vide pour engager et n'avoir **plus de sortie**."]}], "counters": [{"hero": "the-punisher", "note": "Ses dégâts constants cassent ta bulle et ta vie bonus."}, {"hero": "blade", "note": "Son anti-soin coupe ton vol de vie en forme de démon."}, {"hero": "hela", "note": "Elle te punit en duel à distance avant que tu sois chargé."}], "synergies": [{"hero": "jubilee", "note": "Team-up commun : son tir devient hitscan avec vol de vie."}, {"hero": "moon-knight", "note": "Team-up commun : barrière lunaire et rebonds."}, {"hero": "scarlet-witch", "note": "Team-up commun : zone arcanique et téléportation."}, {"hero": "magik", "note": "Team-up commun autour des disques et des démons du Limbo."}, {"hero": "winter-soldier", "note": "Son ult combinée à la tienne tue les heals dans leur ult."}], "sources": [{"title": "Ultimate The Hood Guide (Beginner/Advanced)", "author": "Tephra98", "url": "https://www.youtube.com/watch?v=QCuItyqk75U"}], "kit": {"season": "Saison 10.5", "health": "", "abilities": [], "teamups": [{"name": "Chaos Collision", "partners": ["scarlet-witch"], "key": "", "text": "Zone arcanique et téléportation. **Amélioré :** Ajoute une onde de choc."}, {"name": "Hellfire Sparks", "partners": ["jubilee"], "key": "", "text": "Forme hitscan avec auto-soin. **Amélioré :** Garde la marque de magie du vide."}, {"name": "New Moon's Shadow", "partners": ["moon-knight"], "key": "", "text": "Une barrière lunaire explose (détection des rebonds à 6 m depuis la saison 10). **Amélioré :** Les attaques rebondissent."}, {"name": "Oblivion Shroud", "partners": ["cloak-and-dagger"], "key": "", "text": "Les voiles affaiblissent dégâts et soins ennemis. **Amélioré :** Plus larges, avec un boost de dégâts."}, {"name": "Void Pentagram", "partners": ["magik"], "key": "", "text": "Les Stepping Discs rendent de l'énergie et invoquent des démons du Limbo (cooldown 20 s depuis la saison 10). **Amélioré :** Démons plus solides, plus de portée."}], "changes": [{"season": "Saison 10", "text": "Vie de base 600 → 550, Mantle of Oblivion 10 s → 12 s de cooldown, réduction des dégâts des projectiles 35 % → 20 %."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · changements : patch notes des saisons 10 et 10.5", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'the-hood' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);

-- 7. Guides de cartes : placement par rôle et héros adaptés ; guides des cartes qui n'en avaient pas
insert into public.guides (kind, map_id, status, content) select 'map', m.id, 'published', $j${"summary": "Une carte Convoi très verticale, avec des téléporteurs (certains à sens unique), de longs murs, des murs cassables et beaucoup de hauteurs. Chaque section a un choke final à tenir : l'équipe qui contrôle à la fois le main et le high ground gagne.", "tldr": ["Jouez **en deux groupes** : un groupe sur le main avec le convoi, un autre (DPS, tank) qui conteste le **high ground**.", "Les **téléporteurs** sont sous-utilisés : flanks, fuites, ou attendre l'ennemi derrière lui.", "En défense, **cassez les murs à l'avance** : en plein fight, tu n'auras pas le temps d'ouvrir ta sortie."], "difficulty": 0, "tags": ["Convoi", "Téléporteurs", "High ground", "Rocket"], "sections": [{"title": "Le plan de jeu", "kind": "tips", "lead": "Une des meilleures cartes pour Rocket et Peni Parker (longs murs, spots cachés), et une excellente carte pour les flankers grâce à la verticalité.", "items": ["Le tank principal **ancre le convoi** sur le main ; un DPS (et idéalement un second joueur) tient l'**off-angle** en hauteur. Un 1v1 seul en hauteur est un pile ou face.", "Les supports jouent **loin**, là où ils voient à la fois le main et la hauteur.", "En défense, ton but est de **faire tourner l'horloge**, pas de chercher les kills ; en attaque, il suffit en général de **gagner deux fights** par point.", "Ne restez **jamais collés** : une ult de Strange, de Groot ou d'Angela vous touche tous."]}, {"title": "Téléporteurs", "lead": "Certains ne marchent que dans un sens (anneau rouge à la sortie), d'autres dans les deux.", "items": ["Un téléporteur près du spawn de l'attaque emmène **directement en hauteur** derrière la défense : surveille-le (Rocket peut y poser des mines de Peni via le team-up).", "Sur la dernière section, un téléporteur **à double sens** permet de passer derrière l'ennemi, puis de revenir si ça tourne mal : idéal avec une ult (Star-Lord).", "Enchaîner les téléporteurs permet de **fuir** ou de rejoindre une position plus vite qu'en marchant."]}, {"title": "Premier point", "lead": "Les tanks peuvent tenir haut si la pression est bonne, puis reculent au coin. Mais le high ground au-dessus du coin est la clé.", "items": ["Quand vous tenez le coin, **quelqu'un doit garder le high ground** : sinon, l'attaque y monte et vous tire dans le dos.", "Un hitscan (Hela) a un très bon angle **côté droit**, avec un pack de soin et du couvert pour reculer ; c'est aussi un spot fréquent des nids de Peni.", "En défense, une cachette près du spawn adverse peut offrir **un pick surprise**, une seule fois : mourir si près de leur spawn coûte cher.", "Le **dernier choke** de la section est crucial : ton spawn est tout proche, reste en vie et tiens."], "diagram": "choke"}, {"title": "Deuxième et troisième points", "lead": "Les mêmes règles, avec plus de murs cassables et de longues routes extérieures que personne ne surveille.", "items": ["Les **longues routes extérieures** sont parfaites pour un flanker ou pour cacher une balise de résurrection.", "Supports : garde le **pilier sur ta droite** pour ne pas être dans la ligne de vue des flankers qui arrivent par le doorway latéral.", "Un DPS doit **tenir le doorway** que prennent les flankers : c'est le chemin le plus court.", "Une fois le convoi passé le dernier choke de la carte, il n'y a **plus de couvert** pour défendre : tout se joue avant."], "diagram": "space"}, {"title": "Astuces Rocket", "kind": "tips", "lead": "Arakko est faite pour Rocket : de longs murs pour se déplacer et des spots cachés partout.", "items": ["Les **dashes contre un mur** t'envoient bien plus loin que les dashes en l'air.", "Pose la **balise de résurrection** sur un chemin de repli (près d'un téléporteur) : un allié ressuscité au milieu des ennemis meurt deux fois.", "Place **l'amplificateur derrière un mur** pour couper l'équipe adverse en deux, pas devant tout le monde où il fond.", "Les ennemis regardent rarement **en l'air** : une balise posée en hauteur survit longtemps."]}, {"title": "Erreurs fréquentes", "kind": "mistakes", "items": ["Défendre **tous sur le main** sans personne en hauteur.", "Un seul joueur en hauteur, **sans soins**, qui meurt seul.", "Devoir **casser un mur en plein fight** pour s'enfuir.", "Poser une balise de résurrection **au milieu de l'ennemi**.", "Mourir près de **son propre spawn** en défense, en cherchant un kill inutile."]}], "counters": [], "synergies": [{"hero": "rocket-raccoon", "note": "Longs murs pour ses dashes et spots cachés pour sa balise et son amplificateur."}, {"hero": "peni-parker", "note": "Beaucoup de spots pour cacher son nid et ses mines."}, {"hero": "psylocke", "note": "Les routes verticales et peu surveillées offrent des picks faciles."}, {"hero": "hela", "note": "Un angle en hauteur côté droit, avec un pack de soin et un abri pour reculer."}], "sources": [{"title": "How to Win on Arakko", "author": "", "url": "https://www.youtube.com/watch?v=8d04_ClbODg"}], "roles": {"Vanguard": ["Le tank principal **ancre le convoi** sur le main ; l'autre tank aide à tenir la hauteur au-dessus du coin.", "Ne restez **pas collés** : une ult de Strange, Groot ou Angela touche toute l'équipe."], "Duelist": ["Un DPS (idéalement deux) tient **l'off-angle en hauteur** au-dessus du coin : seul là-haut, c'est un pile ou face.", "Garde **le doorway latéral** que prennent les flankers adverses sur les derniers points.", "Les **longues routes extérieures** sont parfaites pour flank, peu de monde les surveille."], "Strategist": ["Joue **loin**, là où tu vois à la fois le main et la hauteur.", "Sur la fin, garde **le pilier sur ta droite** pour sortir de la ligne de vue des flankers.", "Rocket : balise sur **un chemin de repli** près d'un téléporteur, jamais au milieu de l'ennemi."]}, "title": "Arakko"}$j$::jsonb from public.maps m where m.name = 'Hellfire Gala: Arakko' on conflict (map_id) where kind = 'map' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, map_id, status, content) select 'map', m.id, 'published', $j${"summary": "Une carte Convergence à chokes : le premier point se défend dans un entonnoir, puis le convoi tourne autour de bâtiments destructibles et reconstructibles. On gagne en prenant les routes latérales plutôt qu'en forçant le main.", "tldr": ["Pour casser le premier choke, **n'entrez pas tous par le main** : envoie quelqu'un par la route de gauche (bâtiment reconstruit) sur leur backline.", "Sur le convoi, **reste à gauche** : à droite, c'est le vide, et Invisible Woman ou Spider-Man t'y envoient.", "En défense, tiens **le coin** avant le dernier choke : une fois passé, tout devient un brawl ouvert."], "difficulty": 0, "tags": ["Convergence", "Chokes", "Bâtiments", "Vide"], "sections": [{"title": "Le plan de jeu", "kind": "tips", "lead": "Les chokes de Central Park font entonnoir : l'équipe qui force le passage prend tous les dégâts sans couvert. La solution, c'est d'attaquer par plusieurs côtés à la fois.", "items": ["Une attaque en **pince** (main + côté) vaut mieux qu'un deathball : même une Squirrel Girl ou une Hela peut prendre la route latérale.", "Les bâtiments se **détruisent et se reconstruisent** : reconstruis-les tôt pour gagner du couvert, et ne reste jamais sur un bâtiment en reconstruction.", "En défense, ton but est de **ne pas mourir** et de gagner du temps ; en attaque, de **prendre des picks** et donc des risques."]}, {"title": "Sortie de spawn", "lead": "Il n'y a que deux sorties, et la plus courte est surveillée.", "items": ["Méfie-toi d'un **portail de Strange** juste devant la sortie la plus proche.", "Un **Spider-Man** guette souvent la sortie pour tirer quelqu'un dans le vide : attends une seconde et garde un bouclier ou une mobilité prête."]}, {"title": "Premier point : attaquer", "lead": "Trois routes en plus du main, et elles ne se valent pas.", "items": ["**La route de gauche** (une fois le bâtiment reconstruit) est la meilleure : tu passes à couvert et tu tombes sur leurs supports sans utiliser de mobilité.", "**Les ponts en hauteur** donnent un angle correct, mais la défense les casse souvent avant.", "**La route de droite** est la pire : il faut griller une mobilité pour y aller, et une Invisible Woman t'y attend pour te pousser dans le vide."]}, {"title": "Premier point : défendre", "lead": "Le main est un entonnoir : il suffit d'y envoyer des dégâts, mais il faut surveiller les côtés.", "items": ["Supports : joue **derrière les piliers** de part et d'autre du point, pas dessus : tu es à l'abri des flanks et du spam du main.", "**Surveille la route de droite** : un ennemi qui y grille sa mobilité est une cible facile.", "Un Rocket peut cacher sa **balise de résurrection** dans le trou du chemin en hauteur, près du point."], "diagram": "choke"}, {"title": "Le convoi", "lead": "Le passage le plus dur pour l'attaque, c'est le coin juste après le point : la défense y a du couvert, des ponts et des hauteurs.", "items": ["Un **tank de dive** (Captain America, Venom, Hulk) peut **s'asseoir sur le convoi** et le bloquer pendant plusieurs fights, en allant chercher les packs de soin.", "Reste **à gauche du convoi** : le côté droit donne sur le vide.", "Quand l'attaque prend le point, envoie du monde **sur les deux doorways** : un seul joueur qui passe par l'autre porte peut bloquer le convoi.", "Prends ta route de flank **avant** que le fight éclate : après, c'est trop tard."], "diagram": "space"}, {"title": "Fin de carte", "lead": "La défense veut tenir le coin avec ses hauteurs et ses lignes de vue ; l'attaque veut le passer pour se servir du convoi comme couvert.", "items": ["Reconstruis **le grand bâtiment** dès que possible : en reconstruction, il bloque la vue du main et peut t'enfermer.", "En attaque, des routes passent par **les escaliers de chaque côté** jusqu'au flank de leur backline ; une hauteur peu utilisée attend même une Black Widow.", "En défense, **regroupez-vous à six** avant de retourner sur le point : y aller un par un, c'est se faire stagger."]}, {"title": "Erreurs fréquentes", "kind": "mistakes", "items": ["Forcer **le main** à six contre un spam (Squirrel Girl, Moon Knight).", "Prendre **la route de droite** en grillant sa mobilité.", "Jouer **du côté du vide** du convoi contre Invisible Woman ou Spider-Man.", "Revenir **un par un** après un fight perdu.", "Laisser un **bâtiment en reconstruction** te bloquer."]}], "counters": [], "synergies": [{"hero": "captain-america", "note": "Il bloque le convoi longtemps et attire l'attention sans avoir besoin de tuer."}, {"hero": "invisible-woman", "note": "Elle pousse les ennemis dans le vide le long du convoi."}, {"hero": "spider-man", "note": "Il tire des ennemis dans le vide à la sortie du spawn et le long du convoi."}, {"hero": "squirrel-girl", "note": "Son spam punit l'équipe qui force le main."}], "sources": [{"title": "How to Win Central Park", "author": "", "url": "https://www.youtube.com/watch?v=o6ho_K2bRK8"}], "roles": {"Vanguard": ["En attaque, un **tank de dive** (Captain America, Venom, Hulk) peut s'asseoir sur le convoi et le bloquer en allant chercher les packs de soin.", "Après un fight gagné, envoie quelqu'un sur **chaque doorway** : un ennemi qui passe par l'autre porte bloque le convoi."], "Duelist": ["Attaque **en pince** : la route de gauche (bâtiment reconstruit) mène à couvert jusqu'à leurs supports.", "Évite **la route de droite** : elle coûte une mobilité et donne sur le vide.", "Prends ta route de flank **avant** le fight, pas pendant."], "Strategist": ["En défense, joue **derrière les piliers** de chaque côté du point, pas dessus.", "Reste **à gauche du convoi** : le côté droit donne sur le vide (Invisible Woman, Spider-Man).", "À la sortie de spawn, attends une seconde : un Spider-Man ou un portail de Strange guette souvent."]}, "title": "Central Park"}$j$::jsonb from public.maps m where m.name = 'Empire of Eternal Night: Central Park' on conflict (map_id) where kind = 'map' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, map_id, status, content) select 'map', m.id, 'published', $j${"summary": "Une carte Convergence avec de longues lignes de vue et beaucoup de hauteurs. Elle récompense les équipes qui se battent à couvert et sur les chokes, et punit celles qui se jettent dans les grands espaces vides.", "tldr": ["On défend **depuis les chokes et les coins**, pas au milieu du point : quand on perd de l'espace, on recule au **prochain choke sûr**.", "En attaque, **évitez le main** contre des hitscan : passez par les hauteurs et les flancs pour prendre des angles.", "Les heals à longue portée jouent **loin, en hauteur, près d'un pack de soin** : jamais collés à l'équipe."], "difficulty": 0, "tags": ["Convergence", "Lignes de vue", "Chokes", "High ground"], "sections": [{"title": "Le plan de jeu", "kind": "tips", "lead": "Les longues lignes de vue favorisent les hitscan (Hela, The Punisher, Hawkeye) et punissent les héros de courte portée qui s'avancent à découvert.", "items": ["Un joueur doit toujours **surveiller l'angle de flank** pendant que l'équipe regarde devant : un flanker qui passe gratuitement tue un support.", "Bats-toi pour **l'espace le plus sûr**, pas en plein milieu : celui qui se place mieux bat souvent celui qui vise mieux.", "Dans un fight perdu, **reste en vie et gagne du temps** : ça laisse le temps à un allié de passer Strange et de portailer sur le point."]}, {"title": "Défendre le premier point", "lead": "Tout le monde a tendance à s'agglutiner sur le point. Le problème : en reculant, il n'y a aucun couvert, sauf en tournant le coin.", "items": ["Les **DPS bloquent la fenêtre en hauteur** et les angles latéraux : depuis là-haut, un Hawkeye ou une Psylocke verrait le dos de tes tanks.", "Supports : joue **en hauteur, collé au pilier**, du côté opposé à l'arrivée habituelle d'un Spider-Man, avec un pack de soin derrière toi.", "Ne pousse pas **au-delà du coin** vers leur spawn : il n'y a aucun couvert et c'est le terrain des hitscan. Laisse-les venir à vos chokes.", "Le perchoir que Loki aime bien est risqué pour un heal sans téléportation : il faut traverser du vide pour en sortir."], "diagram": "choke"}, {"title": "Défendre le convoi", "lead": "Une fois le convoi sorti, on se replie de choke en choke : chaque doorway tenu fait gagner du temps.", "items": ["Essaie de **bloquer le convoi dans le doorway** à la sortie du point : après, il roule en terrain ouvert.", "Quand l'espace est perdu, recule au **coin suivant** : la salle, le pack de soin et les off-angles y sont de ton côté.", "Une **plateforme en hauteur se casse** et donne un excellent spot à Psylocke, Rocket ou The Punisher (tyrolienne).", "Si tu vas mourir de toute façon, **meurs sur le convoi** pour le bloquer le plus longtemps possible."]}, {"title": "Attaquer", "lead": "Le main est un long couloir sans couvert : contre une Hela, un Punisher ou un Hawkeye, l'emprunter, c'est perdre des PV avant même le fight.", "items": ["Envoie **des DPS sur les hauteurs** de chaque côté : même sans kill, la pression force la défense à reculer et contourne les murs de Groot.", "Les flankers (Black Panther, Magik) arrivent **sur les supports adverses à découvert** par les côtés.", "Ne saute pas **sur le point trop tôt** : vous n'y avez pas plus de couvert qu'eux. Chasse d'abord ceux qui tiennent la hauteur d'en face.", "Ne prends le long flank que si ton équipe **est encore en train de se placer** : une fois le fight lancé, il est trop tard.", "Une fois le convoi passé les doorways, **tournez autour** pour reprendre les hauteurs au-dessus de la sortie de leur spawn."]}, {"title": "Placement des supports", "kind": "tips", "lead": "Rocket, Luna et Cloak & Dagger soignent aussi bien de loin : autant le faire depuis un endroit dur à atteindre.", "items": ["Joue **loin de la mêlée** : une ult de Groot ou de Psylocke sur ton équipe ne doit pas te toucher aussi.", "En attaque comme en défense, cherche **la hauteur avec un pack de soin** à proximité.", "Ne te rapproche pour finir des kills **qu'avec une raison** (ult prête, avantage numérique), puis recule tout de suite."], "diagram": "heal"}, {"title": "Erreurs fréquentes", "kind": "mistakes", "items": ["Défendre **tous collés sur le point**.", "Pousser **au-delà du coin** vers le spawn adverse.", "Attaquer **par le main** contre des hitscan.", "Supports **collés à leur équipe** : une seule ult touche tout le monde.", "Utiliser son ult **pour rien** parce qu'on croit qu'un allié va toucher le point."]}], "counters": [], "synergies": [{"hero": "hela", "note": "Les longues lignes de vue sont faites pour elle."}, {"hero": "the-punisher", "note": "Hitscan sur le long couloir du main, et la tyrolienne sur la plateforme cassable."}, {"hero": "rocket-raccoon", "note": "Soigne de loin depuis une hauteur avec un pack de soin."}], "sources": [{"title": "How to Win Hall of Djalia", "author": "", "url": "https://www.youtube.com/watch?v=upHrObyiUNY"}], "roles": {"Vanguard": ["En défense, essaie de **bloquer le convoi dans le doorway** à la sortie du point : après, il roule en terrain ouvert.", "En attaque, n'avance pas dans **le long couloir du main** contre des hitscan : laisse les DPS prendre les hauteurs d'abord."], "Duelist": ["Les **hitscan** (Hela, The Punisher, Hawkeye) sont rois ici : prends les hauteurs de chaque côté.", "En défense, **bloque la fenêtre en hauteur** et les angles latéraux au premier point.", "Flankers (Black Panther, Magik) : passe par les côtés pour tomber sur les supports à découvert."], "Strategist": ["Cherche **une hauteur avec un pack de soin** à côté, collée à un pilier.", "Joue **loin de la mêlée** : une ult de Groot ou de Psylocke ne doit pas te toucher aussi.", "Évite le perchoir à Loki si tu n'as pas de téléportation : on n'en sort qu'en traversant du vide."]}, "title": "Hall of Djalia"}$j$::jsonb from public.maps m where m.name = 'Wakanda: Hall of Djalia' on conflict (map_id) where kind = 'map' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, map_id, status, content) select 'map', m.id, 'published', $j${"summary": "Une carte Convergence dont le premier choke est l'un des plus durs du jeu à casser. Ensuite, le convoi avance d'abord tout seul, puis traverse un tunnel, un brouillard et une montée sans couvert : la défense doit l'arrêter avant.", "tldr": ["En défense comme en attaque, **deux groupes** : un de chaque côté du premier choke, plus quelqu'un sur le **high ground**.", "La règle d'or du convoi : l'équipe qui le contrôle **se bat loin de lui** (il avance seul), la défense **se bat dessus** (il s'arrête).", "Le **brouillard** est sous-utilisé : il cache une fuite, un piège ou une balise de résurrection."], "difficulty": 0, "tags": ["Convergence", "Choke", "Brouillard", "High ground"], "sections": [{"title": "Le plan de jeu", "kind": "tips", "lead": "Le premier point se joue en pince : si l'un des deux côtés tombe, l'équipe se fait prendre à revers.", "items": ["Le **high ground** est très dur à reprendre une fois perdu (il faut griller une mobilité pour y monter) : envoie **deux joueurs** pour le prendre ou le tenir.", "Un hitscan te harcèle depuis la hauteur ? **Colle-toi au mur sous lui** : pour te toucher, il doit s'avancer et s'exposer.", "Contre le poke à longue portée en général : place-toi là où l'ennemi doit **prendre un risque** pour te tirer dessus.", "Tu peux **casser la structure** du high ground pour retirer son couvert à l'ennemi."]}, {"title": "Premier point : défendre", "lead": "Le côté principal est l'endroit où la défense se tient le plus souvent ; les salles latérales sont la porte d'entrée de l'attaque.", "items": ["Surveille **les salles sur le côté** : c'est par là que l'attaque contourne.", "Le long couloir arrière mène derrière la défense, mais **sans couvert ni fuite** : rarement rentable.", "Supports : un spot en hauteur voit **les deux côtés du pilier** ; sous pression, recule dans le **petit renfoncement** avec fenêtre pour choisir qui tu vois.", "Le brouillard près du point cache bien, mais l'espace autour est **à découvert**."]}, {"title": "Premier point : attaquer", "lead": "Forcer le choke à six ne marche presque jamais : il faut attaquer des deux côtés en même temps.", "items": ["Un groupe passe **par chaque côté**, et un joueur mobile (Rogue, Iron Fist) prend la hauteur.", "Un dive à deux sur leur backline fait **lâcher les soins à leur tank** : même sans kill, c'est l'ouverture pour ton équipe.", "Une fois ce choke passé, **la partie se rejoue** : ne lâche pas."], "diagram": "flank"}, {"title": "Le convoi", "lead": "Après la prise du point, le convoi avance tout seul un moment : personne ne peut l'accélérer ni l'arrêter.", "items": ["Pendant cette phase, **l'attaque prend un maximum d'espace** ; la défense joue prudemment, inutile de mourir.", "Le meilleur endroit pour l'arrêter, c'est **le tunnel** : on y tient facilement à couvert. Une fois sur la hauteur, c'est beaucoup plus dur.", "La **montée finale** n'a presque aucun couvert : ensuite, la défense n'a plus que ses ults pour la tenir.", "Un **tank de dive** (Captain America) peut sauter sur le convoi, attirer l'attention et le bloquer, puis ressortir, encore et encore.", "En attaque, ne mets **trois joueurs sur le convoi** que si tu es sûr qu'il arrivera avant leur retour : sinon, bats-toi pour l'espace devant lui."]}, {"title": "Fin de carte", "lead": "Sur le dernier point, presque tout est à découvert.", "items": ["Supports : recule **près de ton spawn**, à couvert, et soigne de loin.", "En attaque, après un fight gagné, les tanks **bloquent les deux escaliers** de sortie : la défense doit sortir son ult loin du point.", "Un spot en hauteur accessible par des escaliers est **idéal pour un hitscan**, et la balise de Rocket y est rarement vue."], "diagram": "ultcombo"}, {"title": "Erreurs fréquentes", "kind": "mistakes", "items": ["Laisser **un côté** du premier point sans personne.", "Envoyer **un seul joueur** prendre le high ground.", "En attaque, se battre **sur le convoi** au lieu de devant.", "En défense, mourir pendant que le convoi **avance tout seul**.", "Supports **au milieu** de la zone découverte finale."]}], "counters": [], "synergies": [{"hero": "captain-america", "note": "Il saute sur le convoi pour le bloquer, puis ressort chercher un pack de soin."}, {"hero": "rogue", "note": "Assez mobile et solide pour tenir le high ground du premier point."}, {"hero": "iron-fist", "note": "Assez mobile pour monter prendre le high ground."}, {"hero": "mantis", "note": "Souvent citée parmi les meilleurs supports de la carte."}], "sources": [{"title": "How to Win on Heart of Heaven", "author": "", "url": "https://www.youtube.com/watch?v=-CY0Er3r3do"}], "roles": {"Vanguard": ["Au premier point, attaque **des deux côtés en même temps** : forcer le choke à six ne marche presque jamais.", "Sur le convoi, un **tank de dive** saute dessus, attire l'attention, le bloque, puis ressort.", "Après un fight gagné, **bloque les deux escaliers** de sortie du dernier point."], "Duelist": ["Envoie **deux joueurs** prendre ou tenir le high ground : une fois perdu, il est très dur à reprendre.", "Un hitscan te harcèle d'en haut ? **Colle-toi au mur sous lui**.", "Sur la fin, un spot en hauteur accessible par les escaliers est **idéal pour un hitscan**."], "Strategist": ["Au premier point, un spot en hauteur voit **les deux côtés du pilier** ; sous pression, recule dans le renfoncement à fenêtre.", "Sur le dernier point, presque tout est à découvert : **recule près de ton spawn** et soigne de loin.", "Le tunnel du convoi se tient bien à couvert : reste derrière tes tanks."]}, "title": "Heart of Heaven"}$j$::jsonb from public.maps m where m.name = 'K''un-Lun: Heart of Heaven' on conflict (map_id) where kind = 'map' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, map_id, status, content) select 'map', m.id, 'published', $j${"summary": "Une carte Domination en trois manches, en miroir, dont le décor bouge : plateformes, portes et pièces centrales montent et descendent selon des cycles. Les connaître, c'est savoir quand se battre et quand ne pas se faire couper de son équipe.", "tldr": ["Quand tu tiens le point, **ne pousse pas trop loin** : c'est l'erreur qui fait perdre le plus de manches en Domination.", "Apprends les **cycles du décor** (sirène et lumières avant que la pièce centrale redescende) et ne te fais **jamais couper** de ton équipe.", "Contre un Rocket, un DPS mobile va **casser sa balise** dès le début : elle est presque toujours au même endroit."], "difficulty": 0, "tags": ["Domination", "Décor mobile", "Vide", "High ground"], "sections": [{"title": "Le plan de jeu", "kind": "tips", "lead": "Les tanks prennent l'espace vite sur le main pour que les DPS puissent s'installer sur les off-angles. Les trois manches sont en miroir : un côté vaut l'autre.", "items": ["Avec le point, **joue pour survivre** : chaque seconde tenue fait monter le pourcentage. Les kills ne deviennent indispensables qu'à 99 %.", "Un mort à 6 contre 5 et l'ennemi **rush le point** : ne prends pas de 1v6 inutile.", "Tout le monde peut prendre un off-angle, **tanks compris** : Magneto et Emma font très bien la pression latérale.", "Pas besoin de kill : **forcer un cooldown défensif** à l'ennemi lui retire de quoi jouer offensif."]}, {"title": "Manche 1 : la base", "lead": "Des escaliers d'un côté (vers la hauteur) et une rampe de l'autre (vers le vide). Choisis selon ton héros : Spider-Man à la rampe, Psylocke ou Hela aux escaliers.", "items": ["La **pièce centrale** monte (environ 35 s) puis descend (environ 22 s) : **sirène et lumières** annoncent la descente. Bats-toi quand elle est levée, c'est ton meilleur couvert.", "Avec le point, tiens **le doorway** devant, puis recule au **choke suivant** si on te repousse : c'est le meilleur spot défensif de la carte.", "Rocket peut y poser son **amplificateur** de façon à couper l'équipe adverse en deux.", "Le côté **vide** est le terrain de chasse des Spider-Man : méfie-toi des tractions."], "diagram": "angle"}, {"title": "Manche 2 : les roches rouges", "lead": "Des cristaux d'un côté, un bassin de lave de l'autre ; la carte change d'état environ 40 secondes après chaque capture.", "items": ["Au début, une **cachette en contrebas** avec pack de soin et jump pad offre un angle sûr à un DPS mobile ou un endroit où attendre ton équipe.", "La **hauteur latérale** est l'endroit le plus disputé par les DPS : gagner le duel là-haut fait souvent gagner le point.", "Une balise de Rocket est presque toujours **au même endroit en début de manche** : va la casser avec un héros mobile ; ton équipe joue prudemment pendant ce temps."], "diagram": "highground"}, {"title": "Manche 3 : le mur qui bouge", "lead": "Tout le monde part par le main, casse les portes, puis la carte bascule vers 50 % de progression totale.", "items": ["Après la bascule, une porte se ferme et une autre s'ouvre : **ne reste pas dans la salle du jump pad**, elle peut t'écraser.", "**Ne te fais pas couper** de ton équipe par la bascule : soit vous sortez tous, soit vous attendez la fin du mouvement.", "Le **vide ne s'ouvre qu'après la bascule** (vers 60 %) : avant, inutile d'essayer d'y envoyer quelqu'un (Jeff).", "Une salle sur le côté permet de **laisser passer l'ennemi** pour le prendre à revers : gros risque, gros gain."]}, {"title": "Erreurs fréquentes", "kind": "mistakes", "items": ["Pousser **trop loin** quand on tient le point.", "Se battre **à découvert** loin du coin qu'on devrait tenir.", "Être **coupé de son équipe** par le décor qui bouge.", "Rester dans **une salle qui se referme**.", "Oublier de **casser la balise** de Rocket."]}], "counters": [], "synergies": [{"hero": "spider-man", "note": "Les bords de vide lui offrent des kills par traction."}, {"hero": "rocket-raccoon", "note": "Son amplificateur posé derrière un choke coupe l'ennemi en deux."}, {"hero": "jeff-the-land-shark", "note": "Son ult peut jeter des ennemis dans le vide une fois la manche 3 basculée."}, {"hero": "psylocke", "note": "Côté escaliers, elle prend la hauteur de la manche 1."}, {"hero": "magneto", "note": "Un tank qui fait la pression latérale."}], "sources": [{"title": "How to Win on Hell's Heaven", "author": "", "url": "https://www.youtube.com/watch?v=_qFq8WCalyg"}], "roles": {"Vanguard": ["Prends l'espace **vite sur le main** pour que tes DPS s'installent sur les off-angles.", "Magneto et Emma Frost font très bien **la pression latérale** : un tank peut aussi prendre un off-angle.", "Avec le point, tiens **le doorway** devant, puis le choke suivant si on te repousse."], "Duelist": ["Manche 1 : **Spider-Man côté rampe** (le vide), **Hela ou Psylocke côté escaliers** (la hauteur).", "Manche 2 : la **hauteur latérale** est l'endroit le plus disputé ; gagner ce duel fait souvent gagner le point.", "Va casser **la balise de Rocket**, presque toujours au même endroit en début de manche."], "Strategist": ["Bats-toi **derrière la pièce centrale** quand elle est levée : sirène et lumières annoncent sa descente.", "Manche 3 : ne reste pas dans **la salle du jump pad** pendant la bascule, elle peut t'écraser.", "Avec le point, **joue pour survivre** : chaque seconde tenue fait monter le pourcentage."]}, "title": "Hell's Heaven"}$j$::jsonb from public.maps m where m.name = 'Hydra Charteris Base: Hell''s Heaven' on conflict (map_id) where kind = 'map' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, map_id, status, content) select 'map', m.id, 'published', $j${"summary": "Une carte Domination en trois manches, plus « deathmatch » qu'une carte à convoi : pas de vrai choke unique, on se bat autour des piliers, des arbres et des salles qui entourent le point. Des portails s'ouvrent en cours de manche et changent les rotations.", "tldr": ["Ne te bats **pas au milieu du point** : joue autour des piliers, des fenêtres et des salles qui l'entourent, et ne monte dessus que pour capturer.", "Les **portails s'ouvrent vers 50 à 60 %** : en te plaçant à côté, tu vois où ils mènent (contour blanc).", "Supports : **loin, en hauteur, près d'un pack de soin**. Le point, c'est le travail des tanks."], "difficulty": 0, "tags": ["Domination", "Portails", "Off-angles", "Couverts"], "sections": [{"title": "Le plan de jeu", "kind": "tips", "lead": "Sur une carte Domination, le fight se joue en tournant autour des petits murs et piliers pour prendre un angle sur un ennemi qui croit être à l'abri.", "items": ["Ne reste jamais **à découvert** en attendant les soins : tes heals rechargent et soignent les autres, mets-toi à couvert.", "**Tire de haut en bas**, pas l'inverse : en hauteur, l'ennemi doit griller une mobilité pour t'atteindre ; toi, tu peux toujours redescendre.", "Plus ton angle est profond chez l'ennemi, meilleur il est, mais **plus tu risques le collapse** : réserve les angles profonds aux héros mobiles (Psylocke).", "Les cartes sont **en miroir** : ce qui marche d'un côté marche de l'autre."], "diagram": "angle"}, {"title": "Les portails", "lead": "Ils n'existent pas en début de manche : ils s'ouvrent quand le point atteint environ 50 à 60 %.", "items": ["Place-toi à côté d'un portail : **sa sortie s'affiche avec un contour blanc** au loin.", "Certains portails mènent **en hauteur** : un héros sans mobilité s'en sert pour aller chercher une Hela perchée.", "Sur le point, un portail latéral t'envoie **juste sur un pack de soin** : prends-le, puis reviens.", "Utilise les portails pour **sortir** d'un fight perdu ou contourner un choke, pas pour arriver par le bas dans le fight."]}, {"title": "Les zones à tenir", "lead": "Les salles et fenêtres qui bordent le point sont les meilleures positions : couvert à gauche et à droite, vue sur le point.", "items": ["En DPS, **dispute les salles latérales** : depuis une fenêtre, tu tires et tu te remets à couvert.", "La salle centrale en hauteur est bonne mais **sans issue latérale** : tu ne peux que reculer.", "Quand l'équipe adverse est repoussée, **tenez le choke qui mène à leur spawn**… sans le dépasser : au-delà, c'est vous qui êtes à découvert.", "Le **tunnel latéral** est un flank isolé, sans couvert : à utiliser rarement."], "diagram": "highground"}, {"title": "La manche à la cascade", "lead": "Une manche avec des arbres, une cascade et un doorway que l'équipe repoussée doit traverser.", "items": ["Joue **autour des arbres** : tu prends l'angle, et tu te caches derrière dès que tu prends des dégâts.", "Derrière la cascade, un rebord te laisse **voir à travers sans être bien vu** : un bon spot pour un DPS sans mobilité.", "Le choke à tenir est **le doorway** : un joueur à gauche, un à droite, un DPS **en hauteur** au-dessus avec le pack de soin.", "Une hauteur au-dessus du point donne des headshots faciles : **prends-la ou interdis-la**."]}, {"title": "Ne pas se perdre", "kind": "tips", "lead": "Beaucoup de zones de la carte sont trop loin du point pour servir.", "items": ["Si tu tombes en bas, le **jump pad est lent** : prends le pack de soin puis le portail qui te dépose sur le point (si le fight le permet).", "Un pack de soin isolé à l'arrière est le **repaire des Spider-Man** : si l'un d'eux disparaît par là, tu sais où il est."]}, {"title": "Erreurs fréquentes", "kind": "mistakes", "items": ["Brawler **au milieu du point** sans couvert.", "Prendre un angle **par le bas**.", "Partir trop loin du point **sur les ailes**.", "Supports **en première ligne**.", "Prendre un portail **sans savoir où il mène**."]}], "counters": [], "synergies": [{"hero": "psylocke", "note": "Assez mobile pour les angles profonds autour du point."}, {"hero": "hela", "note": "Les fenêtres des salles latérales sont parfaites pour elle."}, {"hero": "peni-parker", "note": "Les petites zones autour du point se défendent bien avec des mines."}], "sources": [{"title": "How to Win Krakoa", "author": "", "url": "https://www.youtube.com/watch?v=3aNQQPFjj9Q"}], "roles": {"Vanguard": ["Ne brawl **pas au milieu du point** : tourne autour des murs et des piliers.", "Quand l'ennemi est repoussé, tenez **le choke vers leur spawn**, sans le dépasser."], "Duelist": ["**Dispute les salles latérales** : depuis une fenêtre, tu tires puis tu te remets à couvert.", "Manche à la cascade : un DPS **en hauteur au-dessus du doorway**, avec le pack de soin.", "Réserve les angles profonds aux **héros mobiles** (Psylocke) : les autres risquent le collapse."], "Strategist": ["Ne reste jamais **à découvert** en attendant les soins de l'autre heal.", "Derrière la cascade, un rebord te laisse **voir sans être bien vu**.", "Les portails (vers 50-60 %) servent à **sortir** d'un fight perdu ou à rejoindre un pack de soin."]}, "title": "Krakoa"}$j$::jsonb from public.maps m where m.name = 'Hellfire Gala: Krakoa' on conflict (map_id) where kind = 'map' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, map_id, status, content) select 'map', m.id, 'published', $j${"summary": "Une carte Convoi en trois sections, pleine de coins, de salles et de bâtiments qui se reconstruisent. Le convoi avance de coin en coin : l'équipe qui tient le bon coin, et ses routes de flank, contrôle la partie.", "tldr": ["Les DPS ont un double travail : faire des dégâts **et tenir les routes de flank** (surtout celle du haut) pour protéger leurs supports.", "En défense, tiens **chaque coin** le plus longtemps possible : une fois le coin perdu, le convoi avance presque seul jusqu'au suivant.", "Prends des **angles différents** de ton équipe : deux angles à la fois, c'est l'ennemi qui n'a plus de couvert."], "difficulty": 0, "tags": ["Convoi", "Coins", "Flank", "High ground"], "sections": [{"title": "Le plan de jeu", "kind": "tips", "lead": "Sur Midtown, presque chaque fight se décide par une pression venue de côté : un DPS sur un angle, et l'ennemi qui se croyait à couvert ne l'est plus.", "items": ["Pas besoin d'un kill à chaque flank : **la distraction** suffit souvent à faire gagner l'avant.", "Héros mobiles (Psylocke, Magik) : angles profonds. Héros sans mobilité (Hela, The Punisher) : **angles courts**, avec un chemin rapide vers le couvert.", "Les supports ne se collent pas : **à portée l'un de l'autre**, mais pas au même endroit, pour qu'un seul dive ne touche pas les deux.", "Ce sont les **morts** qui décident les fights : chaque risque doit être calculé."]}, {"title": "Premier point", "lead": "En défense, la route du haut est la plus courte pour les flankers adverses : il faut quelqu'un dessus dès le début.", "items": ["**Un DPS surveille la route du haut** ; si tu entends des pas en haut sans voir personne, annonce qu'ils passent par en bas.", "Les tanks tiennent **le coin à couvert** devant le point, avec la salle derrière pour reculer.", "En attaque, un hitscan peut **poke les tanks depuis un off-angle** pendant que le convoi avance.", "Le checkpoint est **plus proche qu'on ne croit** : on s'y précipite trop tard."], "diagram": "choke"}, {"title": "Deuxième section", "lead": "Après un premier point perdu, il faut savoir lâcher l'espace et se regrouper à six.", "items": ["En sous-nombre, **ne restez pas** : reculez loin et revenez à six, plutôt que d'enchaîner les staggers.", "Rocket peut cacher sa **balise de résurrection** dans une salle peu visitée près du premier virage.", "La **pièce centrale** sert de couvert tant qu'elle n'est pas reconstruite ; reconstruite, elle donne une hauteur et un pack de soin pour flank.", "Un pack de soin dans les **égouts** aide l'attaque et les héros mobiles, beaucoup moins la défense."]}, {"title": "Fin de carte", "lead": "Le dernier coin avant le point final est la dernière vraie position de défense.", "items": ["Défends **le dernier coin** : une fois perdu, il ne reste que le convoi et un pilier pour se cacher.", "Fais **reconstruire les bâtiments** tôt : tu ne veux pas être dedans quand ils se reconstruisent, et ils ouvrent des hauteurs.", "En attaque, des routes de flank permettent d'**attendre l'ennemi à la sortie de son spawn** : idéal pour un flanker ou un ult.", "Le **high ground** au-dessus du dernier virage est décisif : prends-le ou interdis-le."], "diagram": "brawl"}, {"title": "Erreurs fréquentes", "kind": "mistakes", "items": ["Laisser **la route du haut** sans personne.", "Rester se battre **en sous-nombre** au lieu de se regrouper.", "Avancer dans **une longue ligne de vue** sans couvert contre des hitscan.", "Un DPS sans mobilité qui prend un **angle profond**.", "Être **dans un bâtiment** au moment où il se reconstruit."]}], "counters": [], "synergies": [{"hero": "psylocke", "note": "Angles profonds et retour rapide à couvert."}, {"hero": "magik", "note": "Elle passe par les côtés et ressort aussi vite."}, {"hero": "hela", "note": "Un angle court, avec un abri juste à côté."}], "sources": [{"title": "How to Win Midtown", "author": "", "url": "https://www.youtube.com/watch?v=yVry00w0tdQ"}], "roles": {"Vanguard": ["Tiens **le coin à couvert** devant le premier point, avec la salle derrière pour reculer.", "Après un point perdu, **reculez loin et revenez à six** plutôt que d'enchaîner les staggers."], "Duelist": ["En défense, **un DPS surveille la route du haut** dès le début : c'est la plus courte pour les flankers.", "Héros mobiles : angles profonds. Hela, The Punisher : **angles courts** avec un abri à côté.", "Le **high ground** au-dessus du dernier virage est décisif : prends-le ou interdis-le."], "Strategist": ["Ne vous collez pas : **à portée l'un de l'autre**, mais pas au même endroit, pour qu'un dive ne touche pas les deux.", "Rocket : une salle peu visitée près du premier virage cache bien **la balise**.", "Le pack de soin des égouts aide surtout **l'attaque** : en défense, ne compte pas dessus."]}, "title": "Midtown"}$j$::jsonb from public.maps m where m.name = 'Empire of Eternal Night: Midtown' on conflict (map_id) where kind = 'map' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, map_id, status, content) select 'map', m.id, 'published', $j${"summary": "Une carte Convoi pleine de hauteurs destructibles, de routes cachées et de bords de vide : le paradis des flankers. La défense recule de coin en coin, l'attaque gagne en prenant des angles que l'équipe d'en face oublie.", "tldr": ["À la sortie de spawn, la porte de gauche est **le spot préféré des Spider-Man et des portails de Strange** : sors prudemment.", "Les tanks bouchent **le doorway principal**, mais un DPS doit **surveiller l'autre entrée** : un seul ennemi qui passe peut bloquer le convoi.", "Évite **les bords de vide** le long du convoi : Spider-Man, Invisible Woman et les repoussements t'y attendent."], "difficulty": 0, "tags": ["Convoi", "Flank", "High ground", "Vide"], "sections": [{"title": "Le plan de jeu", "kind": "tips", "lead": "Énormément de routes, de hauteurs et de murs destructibles : celui qui connaît la carte trouve toujours un angle que l'ennemi ne surveille pas.", "items": ["Les supports regardent presque toujours **droit devant** : les angles latéraux sont des boulevards pour les flankers.", "Quelqu'un te harcèle depuis une hauteur ? Beaucoup de structures **se détruisent** : casse-la pour le faire redescendre.", "**Utilise les packs de soin** : tu reviens plus vite dans le fight, et tes supports peuvent soigner quelqu'un d'autre.", "Très bonne carte pour **Psylocke et Magik** ; Magik peut même ouvrir un mur avec son démon pour tomber derrière."]}, {"title": "Premier point", "lead": "Trois sorties de spawn pour l'attaque, et la défense se cache derrière le coin avant le point.", "items": ["La porte du milieu sert aux **snipers** (Black Widow) qui veulent la longue ligne de vue du main ; celle de droite est **la plus rapide pour flank**.", "Prendre **l'angle au-dessus du coin** de la défense lui retire son couvert : c'est l'espace que les deux équipes se disputent.", "Le pont du haut **se casse** ; un mur cassable plus loin permet de descendre directement sur leur backline.", "La défense ne tient près de son spawn qu'après avoir pris des kills : sinon, elle reste **derrière le coin**."], "diagram": "flank"}, {"title": "Pousser et tenir", "lead": "Une fois le premier coin pris, l'attaque doit empêcher la défense de revenir sur le convoi.", "items": ["Les tanks bloquent **le doorway principal** ; un DPS garde **la seconde entrée**, plus loin, pour qu'aucun ennemi ne passe gratuitement.", "Supports, ne sautez pas **sur le point** : soignez à distance à couvert.", "Le coin suivant offre du couvert et des salles où reculer : en défense, surveille **les flanks par l'intérieur** pendant que tu regardes le convoi."], "diagram": "space"}, {"title": "Deuxième point et fin de carte", "lead": "Les murs et piliers se détruisent au fil du fight : les abris du début ne durent pas.", "items": ["En attaque, une **route très large et peu surveillée** contourne par l'extérieur jusqu'au dos de la défense : idéale pour un flanker.", "Une **rampe** apparaît quand un élément se casse : un hitscan y tient un excellent angle sur le dernier coin.", "Le long couloir vitré et la salle du jump pad sont des **lignes de vue sans couvert** : à éviter pour se battre.", "Une fenêtre en hauteur côté défense est **rarement contestée** : un bon spot pour un hitscan, mais loin des soins.", "Bien tenu, le dernier coin oblige l'attaque à utiliser **une ult de support** pour passer."]}, {"title": "Erreurs fréquentes", "kind": "mistakes", "items": ["Sortir par **la porte de gauche** sans faire attention à Spider-Man.", "Oublier **la seconde entrée** du point.", "Jouer **au bord du vide** le long du convoi.", "Se battre dans **un couloir ouvert** sans couvert.", "Compter sur un couvert **qui va se détruire**."]}], "counters": [], "synergies": [{"hero": "psylocke", "note": "Ses angles profonds profitent de toutes les routes cachées."}, {"hero": "magik", "note": "Son démon ouvre les murs pour tomber dans le dos de la défense."}, {"hero": "venom", "note": "Il ralentit le convoi et plonge dans la backline pendant que tu flank."}], "sources": [{"title": "How to Win Spider Islands", "author": "", "url": "https://www.youtube.com/watch?v=_-a1jtJKiXw"}], "roles": {"Vanguard": ["Bloque **le doorway principal** pendant qu'un DPS garde la seconde entrée.", "Méfie-toi des **bords de vide** le long du convoi : Spider-Man et les repoussements t'y attendent."], "Duelist": ["Côté attaque, la porte de droite est **la plus rapide pour flank** ; celle du milieu sert aux snipers.", "Prends **l'angle au-dessus du coin** de la défense : il lui retire son couvert.", "Fin de carte : une **route extérieure large** contourne jusqu'au dos de la défense."], "Strategist": ["Ne saute pas **sur le point** : soigne à distance, à couvert.", "Les murs se détruisent : **change d'abri** avant que le tien tombe.", "Sors prudemment par **la porte de gauche** : c'est le spot préféré des Spider-Man."]}, "title": "Spider-Islands"}$j$::jsonb from public.maps m where m.name = 'Tokyo 2099: Spider-Islands' on conflict (map_id) where kind = 'map' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, map_id, status, content) select 'map', m.id, 'published', $j${"summary": "Une carte Convergence : un premier point très exposé, puis un convoi qui traverse des zones où le high ground et les off-angles décident des fights. L'équipe qui contrôle les hauteurs au-dessus du convoi gagne presque toujours.", "tldr": ["En défense, **ne reste pas sur le point** : il n'y a aucun couvert dessus. Défends depuis les salles et les murs autour.", "Après le premier point, **prends tout de suite le high ground** au-dessus du chemin du convoi.", "Ne passez jamais **tous par le même couloir** : prenez des angles différents, surtout dans le tunnel."], "difficulty": 0, "tags": ["Convergence", "High ground", "Off-angles"], "sections": [{"title": "Le plan de jeu", "kind": "tips", "lead": "Sur cette carte, presque chaque fight se gagne par un pick sur un off-angle : pendant que les tanks occupent l'avant, un joueur sur une hauteur ou un côté touche des ennemis qui n'ont plus de couvert.", "items": ["Restez **dans la ligne de vue** les uns des autres, mais **pas collés** : sinon un seul spam (Squirrel Girl) vous touche tous.", "Un pick suffit souvent : à **6 contre 5**, on avance, puis on enchaîne les **staggers**.", "Même un DPS peu mobile (Psylocke, Squirrel Girl) peut prendre un angle latéral ou une petite hauteur."]}, {"title": "Défendre le premier point", "lead": "Le point est à découvert : rester dessus quand l'ennemi pousse ou flank, c'est mourir.", "items": ["Garde **un joueur qui surveille le flank** sur le côté : ne laisse pas cet espace sans personne.", "Si un **Doctor Strange** ouvre un portail sur la hauteur de la salle latérale, **ne vous regroupez pas sur le point** : mettez-vous derrière les murs et dans les salles, forcez-les à descendre sur le point, puis punissez par les côtés.", "Quand la pression monte, **recule dans la salle** derrière le point plutôt que de rester en plein milieu.", "Les heals à longue portée (Rocket, Luna, Cloak & Dagger) ont une **salle avec un toit, un pack de soin et de la couverture** : soignez de là contre le dive."]}, {"title": "Attaquer le premier point", "lead": "L'objectif : mettre assez de dégâts pour faire reculer la défense vers ses salles, puis prendre les angles qu'elle abandonne.", "items": ["**Séparez-vous** sur les différentes entrées au lieu d'entrer tous par la même.", "Une défense mise sous pression **recule naturellement vers la salle** derrière le point : préparez-vous à la punir pendant qu'elle traverse le vide."], "diagram": "dive"}, {"title": "Pousser le convoi", "lead": "Une fois le point pris, l'avantage numérique est souvent de votre côté : avancez tout de suite pour refuser l'espace, et le convoi avancera presque seul.", "items": ["La priorité : **le high ground au-dessus du chemin**. Depuis là-haut, tu tires dans le dos de l'équipe qui défend le convoi.", "Utilise **le convoi comme couvert** : chaque mètre qu'il avance vous ouvre de nouveaux angles.", "Repère les **packs de soin** sur les côtés : ils rendent les flanks bien plus viables.", "Le **tunnel** crée un face-à-face où l'équipe qui a le plus de dégâts gagne : passez par les angles de chaque côté au lieu d'y entrer tous.", "Certains passages se ferment : un flank sans mobilité peut **se retrouver bloqué**."]}, {"title": "Défendre le convoi", "lead": "En défense, chaque mètre laissé au convoi donne des angles à l'attaque.", "items": ["Ne laisse pas le convoi avancer **si tu peux l'éviter**, mais pas au prix d'une mort inutile.", "Défends **à couvert derrière le tunnel**, pas dans le tunnel lui-même.", "Sur la fin de carte, le high ground reste ton meilleur atout tant que le convoi n'est pas trop avancé : tiens-le avec un héros mobile."], "diagram": "peel"}, {"title": "Erreurs fréquentes", "kind": "mistakes", "items": ["Défendre **debout sur le point** sans couvert.", "Laisser le **high ground** à l'adversaire après le premier point.", "Passer **tous par le tunnel** ou le même couloir.", "Jouer heal **à découvert** au lieu de passer d'un abri à l'autre.", "Un tank seul qui meurt : avec un **solo tank**, l'équipe entière s'écroule derrière."]}], "counters": [], "synergies": [{"hero": "mantis", "note": "Souvent citée comme la meilleure support de la carte."}, {"hero": "squirrel-girl", "note": "Un angle latéral sur une défense qui recule."}, {"hero": "doctor-strange", "note": "Son portail sur la hauteur de la salle latérale change le fight."}], "sources": [{"title": "How to Win Symbiotic Surface", "author": "", "url": "https://www.youtube.com/watch?v=3k4yFqTe0iM"}], "roles": {"Vanguard": ["Contre un portail de Strange sur la hauteur, ne vous regroupez **pas sur le point** : tenez les salles et forcez-les à descendre.", "Avec **un seul tank**, ne meurs pas en premier : toute l'équipe s'écroule derrière.", "Sur le convoi, utilise **le convoi lui-même comme abri**."], "Duelist": ["Garde **un joueur sur le flank** au premier point : ne laisse pas ce côté vide.", "Après le premier point, la priorité est **le high ground au-dessus du chemin**.", "Ne passez pas **tous par le tunnel** : prenez les angles de chaque côté."], "Strategist": ["Rocket, Luna, Cloak & Dagger : la **salle avec un toit et un pack de soin** derrière le point est faite pour vous.", "Restez **dans la ligne de vue** de l'équipe mais pas collés : un seul spam vous toucherait tous.", "En défense du convoi, reste **à couvert derrière le tunnel**, pas dedans."]}, "title": "Symbiotic Surface"}$j$::jsonb from public.maps m where m.name = 'Klyntar: Symbiotic Surface' on conflict (map_id) where kind = 'map' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, map_id, status, content) select 'map', m.id, 'published', $j${"summary": "Une carte Domination d'Asgard aux couloirs étroits et à la salle du trône tout en hauteur. Les salles serrées favorisent les brawlers, les jardins les flankers, et un joueur isolé dans un couloir latéral y meurt vite.", "tldr": ["Bats-toi **autour du point**, pas dessus : piliers, coins et hauteurs valent plus que le cercle.", "Dans les **couloirs étroits**, une ult de zone touche tout le monde : ne vous entassez pas.", "Un flanker **isolé** dans un couloir latéral est une proie : flank avec un plan de retour."], "tags": ["Domination", "Couloirs", "Brawl", "Flank"], "sections": [{"title": "Le plan de jeu", "lead": "Trois zones qui ne se jouent pas pareil : il faut adapter sa position à chaque manche.", "items": ["Comme sur toute Domination, **tiens le couvert autour du point** et ne monte dessus que pour capturer.", "Les salles serrées rendent les **contrôles et les ults de zone** très forts (Scarlet Witch) : espacez-vous.", "Un pick suffit souvent : à **6 contre 5**, avancez tout de suite."], "kind": "tips", "diagram": "angle"}, {"title": "La salle du trône", "lead": "Beaucoup de verticalité autour de l'objectif.", "items": ["**Prends la hauteur** autour du point avant de te battre dessus : d'en haut, tu vois tout le cercle.", "Un héros sans mobilité qui se fait chasser d'une hauteur doit **avoir un chemin pour redescendre** à couvert."], "kind": "default", "diagram": "highground"}, {"title": "Les archives et les jardins", "lead": "Une zone très serrée, une autre qui ouvre des routes de flank.", "items": ["Dans les archives, l'espace est réduit : un **brawler** (The Thing, Emma Frost) ferme le passage.", "Dans les jardins, un DPS mobile (Spider-Man) **attire l'ennemi dans une embuscade** par les côtés.", "Annonce tes flanks : un joueur qui disparaît sans prévenir laisse son équipe à 5."], "kind": "default", "diagram": "flank"}, {"title": "Erreurs fréquentes", "lead": "", "items": ["S'entasser dans **un couloir** face à une ult de zone.", "Monter sur le point **sans couvert** autour.", "Flank **seul et sans retour**.", "Ignorer **la hauteur** de la salle du trône."], "kind": "mistakes"}], "synergies": [{"hero": "spider-man", "note": "Les jardins lui offrent des routes pour tendre des embuscades."}, {"hero": "scarlet-witch", "note": "Ses zones et son ult punissent les équipes entassées dans les couloirs."}, {"hero": "the-thing", "note": "Il ferme les passages étroits des archives."}], "sources": [{"title": "Marvel Rivals Maps Ranked: Strategy Guide", "author": "", "url": "https://www.esports.net/news/gaming/marvel-rivals-maps/"}, {"title": "Every Marvel Rivals Map Explained (2026)", "author": "", "url": "https://esports.gg/guides/marvel-rivals/every-marvel-rivals-map-explained-your-complete-2026-guide/"}], "difficulty": 0, "counters": [], "roles": {"Vanguard": ["Dans les salles serrées, un brawler (The Thing, Emma Frost) **ferme le passage** pendant que l'équipe joue autour.", "Ne tiens pas le point **seul au milieu** : sur une Domination, le couvert autour du point vaut mieux que le point."], "Duelist": ["Les **jardins** offrent des routes de flank : un DPS mobile (Spider-Man) y tend des embuscades.", "Dans la salle du trône, **prends la hauteur** autour du point avant de te battre dessus.", "Un flanker **isolé dans un couloir latéral** meurt vite : annonce-toi et reviens."], "Strategist": ["Joue **près d'un coin ou d'un pilier**, jamais dans un couloir étroit où une ult de zone te piège.", "Garde **une sortie** vers ton spawn : les couloirs latéraux punissent les heals isolés."]}, "title": "Royal Palace"}$j$::jsonb from public.maps m where m.name = 'Yggsgard: Royal Palace' on conflict (map_id) where kind = 'map' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, map_id, status, content) select 'map', m.id, 'published', $j${"summary": "Une longue carte Convoi à travers les racines de l'arbre-monde. La défense peut tenir plusieurs fois, et le choke du milieu est la section la plus dure ; les routes latérales et les hauteurs font la différence.", "tldr": ["Dès la sortie de spawn, une **porte latérale** ouvre trois angles sur l'objectif : derrière, au-dessus, à côté.", "Au choke, prends **une route latérale** pendant que les tanks occupent l'avant ; une vitre cassable mène à une passerelle en hauteur.", "La **dernière ligne droite** se gagne en groupe autour du convoi, avec des ults bien synchronisées."], "tags": ["Convoi", "High ground", "Flank"], "sections": [{"title": "Le plan de jeu", "lead": "La défense peut se replier et retenir le convoi plusieurs fois : l'attaque doit varier ses routes.", "items": ["Ne pousse pas **à six par le chemin du convoi** : les angles latéraux sont nombreux, utilise-les.", "Les héros volants et mobiles profitent de la verticalité ; la défense, elle, **se sert des hauteurs** pour poke."], "kind": "tips", "diagram": "flank"}, {"title": "Sortie de spawn", "lead": "Le premier fight se joue autour d'une porte latérale.", "items": ["Une **petite salle** sur le côté donne accès à trois angles sur l'objectif.", "Une route mène à **un balcon au-dessus de la défense** : bon spot pour harceler la backline (Moon Knight), mais il faut passer près du convoi.", "La petite salle sert aussi **à se soigner** entre deux fights."], "kind": "default", "diagram": "highground"}, {"title": "Le choke du milieu", "lead": "La section la plus complexe de la carte.", "items": ["Un **chemin latéral** avec un pack de soin permet de flank puis de se replier.", "Une route plus large passe **derrière la défense**, surtout utile en début de push.", "Une **vitre cassable** ouvre une passerelle en hauteur : The Punisher ou Loki y sont très bien.", "En défense, cette passerelle sert aussi **de flank précoce** sur l'attaque."], "kind": "default", "diagram": "choke"}, {"title": "La dernière ligne droite", "lead": "Une poussée presque droite avec quelques virages.", "items": ["Restez **groupés autour du convoi** et gardez une ult pour passer le dernier virage.", "Des **portes au début de la section** mènent à un couloir de flank : la défense s'en sert pour passer derrière, surveille-les."], "kind": "default", "diagram": "ultcombo"}, {"title": "Erreurs fréquentes", "lead": "", "items": ["Pousser **uniquement par le chemin du convoi**.", "Oublier **la passerelle en hauteur** du choke.", "Laisser les **portes de la dernière section** sans surveillance.", "Lancer les ults **une par une** dans la dernière ligne droite."], "kind": "mistakes"}], "synergies": [{"hero": "moon-knight", "note": "Le balcon au-dessus de la défense est fait pour lui."}, {"hero": "the-punisher", "note": "La passerelle en hauteur du choke lui donne un angle de poke."}, {"hero": "loki", "note": "Il tient bien la passerelle en hauteur."}], "sources": [{"title": "Yggsgard: Yggdrasill Path map guide", "author": "", "url": "https://marvelrivals.gg/yggsgard-yggdrasill-path/"}, {"title": "Marvel Rivals Maps Ranked: Strategy Guide", "author": "", "url": "https://www.esports.net/news/gaming/marvel-rivals-maps/"}, {"title": "Every Marvel Rivals Map Explained (2026)", "author": "", "url": "https://esports.gg/guides/marvel-rivals/every-marvel-rivals-map-explained-your-complete-2026-guide/"}], "difficulty": 0, "counters": [], "roles": {"Vanguard": ["Le **choke du milieu** est la section la plus dure : passe en même temps que les DPS qui contournent, pas avant.", "Sur la dernière ligne droite, **restez groupés autour du convoi** et gardez une ult pour le dernier virage."], "Duelist": ["Dès la sortie de spawn, une **porte latérale** donne accès à trois angles : derrière, au-dessus et à côté de l'objectif.", "Le **balcon** au-dessus de la défense est fait pour un DPS qui harcèle la backline (Moon Knight).", "Une **vitre cassable** ouvre une passerelle en hauteur, bon spot pour The Punisher ou un poke."], "Strategist": ["Au choke, un **chemin latéral avec un pack de soin** sert de repli.", "Garde la **petite salle près du spawn** d'attaque pour te soigner entre deux fights.", "En défense, surveille **les portes de la dernière ligne droite** : l'ennemi s'en sert pour passer derrière."]}, "title": "Yggdrasill Path"}$j$::jsonb from public.maps m where m.name = 'Yggsgard: Yggdrasill Path' on conflict (map_id) where kind = 'map' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, map_id, status, content) select 'map', m.id, 'published', $j${"summary": "Une carte Domination wakandaise en trois manches (institut des sciences, chutes des guerriers, spaceport). Le point est surélevé : la défense a la hauteur, mais elle est visible de plusieurs côtés. Plusieurs éléments du décor se cassent et changent les lignes de vue.", "tldr": ["Chaque manche a **trois chemins** depuis le spawn : un direct, un vers la hauteur, un qui contourne derrière l'objectif.", "À l'institut, le **balcon au-dessus du point** est le meilleur angle (jump pad ou route extérieure).", "À la spaceport, méfie-toi **des bords** : un repoussement et tu tombes."], "tags": ["Domination", "High ground", "Destructible", "Vide"], "sections": [{"title": "Le plan de jeu", "lead": "Le point est en hauteur : la défense le voit bien, mais elle est exposée à plusieurs approches.", "items": ["Les héros qui **couvrent plusieurs routes depuis une hauteur** sont très forts ici.", "Attaque **par deux chemins** à la fois : la défense ne peut pas regarder partout."], "kind": "tips", "diagram": "highground"}, {"title": "Institut des sciences", "lead": "Le balcon et le pilier central changent tout.", "items": ["Le **balcon au-dessus du point** se prend par un jump pad ou par la route extérieure ; casser une vitre donne un angle latéral.", "Détruire **le pilier central** ouvre un passage sous l'objectif et fait monter des murs de chaque côté.", "Packs de soin : dans la salle du chemin direct, derrière la grande jardinière, sur le balcon extérieur et dans le couloir sous l'objectif.", "Rocket peut cacher sa **balise** dans un coin abrité de la salle du point."], "kind": "default"}, {"title": "Chutes des guerriers", "lead": "Une manche avec un étage et un plafond qui peut s'effondrer.", "items": ["L'**étage** se prend par un jump pad, ou par une rampe une fois un pilier abattu.", "Casser **trois structures** fait tomber le plafond : nouvelles lignes de vue, et l'escalier central se bloque.", "Un chemin contourne **par l'avant de l'objectif** : surveille-le."], "kind": "default", "diagram": "angle"}, {"title": "Spaceport", "lead": "La manche la plus ouverte, avec des bords dangereux.", "items": ["Un tank à bouclier (Captain America, Groot) **tient la zone** autour du point.", "Une **salle en hauteur** à côté de l'objectif et un rebord extérieur offrent de bons angles ; un passage caché s'ouvre derrière un escalier quand on le casse.", "Un pack de soin **au-dessus du centre de l'objectif** attire tout le monde : Invisible Woman le surveille bien.", "Les bords sont parfaits pour **pousser dans le vide** (ult de Jeff, repoussement d'Invisible Woman)."], "kind": "default", "diagram": "space"}, {"title": "Erreurs fréquentes", "lead": "", "items": ["Attaquer **par un seul chemin**.", "Se placer **au bord** de la spaceport.", "Oublier que **le décor se casse** et change les lignes de vue.", "Laisser le **balcon de l'institut** à l'ennemi."], "kind": "mistakes"}], "synergies": [{"hero": "black-panther", "note": "Sa mobilité harcèle la backline par les chemins de contournement."}, {"hero": "invisible-woman", "note": "Elle surveille le pack de soin central et pousse dans le vide."}, {"hero": "jeff-the-land-shark", "note": "Son ult sort les ennemis par les bords de la spaceport."}, {"hero": "doctor-strange", "note": "Il tient le point et ouvre des routes avec ses portails."}], "sources": [{"title": "Intergalactic Empire of Wakanda: Birnin T'Challa map guide", "author": "", "url": "https://marvelrivals.gg/?p=2261"}, {"title": "Marvel Rivals Maps Ranked: Strategy Guide", "author": "", "url": "https://www.esports.net/news/gaming/marvel-rivals-maps/"}, {"title": "Every Marvel Rivals Map Explained (2026)", "author": "", "url": "https://esports.gg/guides/marvel-rivals/every-marvel-rivals-map-explained-your-complete-2026-guide/"}], "difficulty": 0, "counters": [], "roles": {"Vanguard": ["À la spaceport, un tank à bouclier (Captain America, Groot) **tient la zone** autour du point.", "Sur l'institut, casser **le pilier central** ouvre un passage sous l'objectif et change les lignes de vue : décide-le avec ton équipe."], "Duelist": ["Chaque manche a **trois chemins depuis le spawn** : un direct, un vers la hauteur, un qui contourne derrière l'objectif.", "Prends **le balcon au-dessus du point** (jump pad ou route extérieure) : c'est le meilleur angle de l'institut.", "Aux chutes, la **hauteur** se prend par un jump pad, ou par une rampe une fois un pilier abattu."], "Strategist": ["Repère les **packs de soin** : à l'institut, il y en a un sous l'objectif, un sur le balcon extérieur et un derrière la grande jardinière.", "Rocket : un **coin abrité de la salle du point** à l'institut garde bien la balise.", "À la spaceport, ne te place pas **près du bord** : Jeff et Invisible Woman y poussent dans le vide."]}, "title": "Birnin T'Challa"}$j$::jsonb from public.maps m where m.name = 'Wakanda: Birnin T''Challa' on conflict (map_id) where kind = 'map' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, map_id, status, content) select 'map', m.id, 'published', $j${"summary": "Une carte Convergence en trois sections : capturer l'araignée, l'escorter dans les rues, puis la pousser jusqu'à la salle finale. Des ruelles étroites, des toits pour les héros volants et beaucoup de routes de flank.", "tldr": ["En attaque, **cassez le mur et le bâtiment** au premier point : sinon toute l'équipe s'entasse dans un seul couloir.", "Deuxième section : la défense tient un **balcon avec un pack de soin** ; l'attaque passe par une ruelle arrière.", "La salle finale a **peu d'entrées** : utilisez les chemins latéraux pour ne pas vous bloquer dans le doorway."], "tags": ["Convergence", "Ruelles", "Flank", "Toits"], "sections": [{"title": "Le plan de jeu", "lead": "Des ruelles qui font entonnoir : le premier qui ouvre une deuxième route gagne le fight.", "items": ["Les **brawlers** sont à l'aise dans les ruelles ; les héros volants passent **par les toits**.", "Un portail de Strange permet de **contourner un choke** entier."], "kind": "tips", "diagram": "choke"}, {"title": "Section 1 : capturer l'araignée", "lead": "L'approche depuis le spawn passe sous un toit suspendu, dans un couloir étroit.", "items": ["Cassez **le mur et le bâtiment** marqués pour ouvrir d'autres routes.", "Deux chemins s'ouvrent après le choke ; le plus long **fait le tour du bâtiment** et arrive de l'autre côté de l'objectif.", "En défense, plusieurs **points en hauteur** tiennent l'approche (Namor, Loki y sont bien).", "Packs de soin : **derrière le bâtiment central** et dans le bâtiment de gauche."], "kind": "default", "diagram": "flank"}, {"title": "Section 2 : dans les rues", "lead": "La défense a un balcon en hauteur ; l'attaque a des routes par l'arrière.", "items": ["En défense, prends **le balcon** : hauteur et pack de soin.", "En attaque, une **ruelle arrière** permet de prendre le bâtiment latéral à revers ; un passage à travers un bâtiment mène à une porte arrière, avec un pack de soin.", "Les **toits** offrent une troisième route aux héros mobiles."], "kind": "default", "diagram": "highground"}, {"title": "Section 3 : la salle finale", "lead": "Peu d'entrées : un piège pour l'équipe qui arrive par un seul côté.", "items": ["Utilisez **les chemins latéraux** et le pont au-dessus de l'objectif pour entrer de plusieurs côtés.", "En défense, un **jump pad** remonte sur le balcon de la section 2."], "kind": "default", "diagram": "ultcombo"}, {"title": "Erreurs fréquentes", "lead": "", "items": ["Passer **à six dans le couloir** du premier point.", "Oublier de **casser le mur** qui ouvre une route.", "Laisser **le balcon** de la section 2 à la défense sans contester.", "Entrer dans la salle finale **par une seule porte**."], "kind": "mistakes"}], "synergies": [{"hero": "doctor-strange", "note": "Ses portails contournent les chokes."}, {"hero": "namor", "note": "Ses tourelles défendent les ruelles."}, {"hero": "star-lord", "note": "Il met la pression depuis les toits."}, {"hero": "loki", "note": "Il tient bien les points en hauteur du premier point."}], "sources": [{"title": "Tokyo 2099: Shin-Shibuya map guide", "author": "", "url": "https://marvelrivals.gg/tokyo-2099-shin-shibuya/"}, {"title": "Marvel Rivals Maps Ranked: Strategy Guide", "author": "", "url": "https://www.esports.net/news/gaming/marvel-rivals-maps/"}, {"title": "Every Marvel Rivals Map Explained (2026)", "author": "", "url": "https://esports.gg/guides/marvel-rivals/every-marvel-rivals-map-explained-your-complete-2026-guide/"}], "difficulty": 0, "counters": [], "roles": {"Vanguard": ["En attaque, **cassez le mur et le bâtiment marqués** au premier point : sinon toute l'équipe passe par un seul couloir.", "Les ruelles sont étroites : **les brawlers** y sont à l'aise, les tanks de poke moins."], "Duelist": ["Deux routes s'ouvrent après le premier choke : la **plus longue fait le tour** du bâtiment et arrive de l'autre côté.", "Deuxième section : une **ruelle arrière** et un passage à travers un bâtiment mènent derrière la défense.", "Les héros volants passent **par-dessus les bâtiments** pour atteindre l'objectif."], "Strategist": ["En défense, le **balcon de la deuxième section** donne la hauteur et un pack de soin ; un jump pad y remonte depuis la fin de carte.", "Au premier point, des packs de soin sont **derrière le bâtiment central** et dans celui de gauche.", "Dans la salle finale, peu d'entrées : **ne te fais pas enfermer** dans le doorway avec ton équipe."]}, "title": "Shin-Shibuya"}$j$::jsonb from public.maps m where m.name = 'Tokyo 2099: Shin-Shibuya' on conflict (map_id) where kind = 'map' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, map_id, status, content) select 'map', m.id, 'published', $j${"summary": "Une carte Convergence où le QG d'Alchemax s'est écrasé sur Manhattan. Particularité : un système de surveillance révèle régulièrement la position, la vie et la charge d'ult de tout le monde. Les flanks doivent se caler sur ces scans.", "tldr": ["Le **scan** (annoncé par une alarme) révèle tout le monde : lance tes flanks juste après, pas juste avant.", "Autour de la statue de Jeff, **les balcons** décident du fight : prends-les avec un héros de longue portée.", "Sur la fin, l'attaque **se répartit** : volants par l'étage, tanks au centre, flankers sur la backline."], "tags": ["Convergence", "Scan", "Balcons", "Poke"], "sections": [{"title": "Le plan de jeu", "lead": "Le scan revient régulièrement et punit les joueurs isolés.", "items": ["Le scan montre **la charge d'ult** de chacun : l'ennemi sait quand tu as la tienne.", "Les flankers classiques souffrent ici : **joue en groupe** et cale tes routes sur les scans.", "Poke et burst (The Punisher, Hela, Star-Lord) sont à l'aise dans les rues."], "kind": "tips", "diagram": "poke"}, {"title": "Le jardin et l'école", "lead": "Le premier point se prend en groupe.", "items": ["L'attaque passe par **l'arche** ou par **le deli** sur la gauche ; en défense, un tank solide tient l'arche.", "Au point de capture, poussez **ensemble par l'entrée du milieu** ; les flankers prennent le couloir de droite ou l'étage de gauche.", "La défense tient **les plateformes en hauteur** autour du point ; burst et zones sont très forts dans cet espace serré."], "kind": "default", "diagram": "choke"}, {"title": "Les rues et la statue de Jeff", "lead": "D'abord des rues étroites, puis un rond-point entouré de balcons.", "items": ["Dans les rues, l'attaque utilise **un bâtiment latéral** pour prendre des picks ; la défense surveille ses fenêtres.", "Au rond-point, **qui tient les balcons gagne** : envoie un héros de longue portée.", "Une boutique latérale permet à l'ennemi d'arriver **dans le dos** de la backline : garde un œil dessus."], "kind": "default", "diagram": "highground"}, {"title": "La forteresse et le pont final", "lead": "Une rue en zigzag avec des falaises, puis un face-à-face.", "items": ["Les **falaises** de la forteresse récompensent les repoussements, mais tenir les plateformes reste la priorité.", "Sur le pont, c'est un face-à-face : un **tank solide** et un DPS qui suppresse la zone.", "Les héros volants peuvent **passer par les fenêtres** de chaque côté du pont."], "kind": "default", "diagram": "space"}, {"title": "Erreurs fréquentes", "lead": "", "items": ["Flank **juste avant un scan**.", "Lancer son ult **quand l'ennemi sait** qu'il a la sienne prête.", "Laisser **les balcons** de la statue de Jeff.", "S'engager dans un passage où **une seule poussée** contrôle toute l'équipe."], "kind": "mistakes"}], "synergies": [{"hero": "peni-parker", "note": "Souvent citée comme l'une des meilleures de la carte : les espaces serrés se défendent bien."}, {"hero": "the-punisher", "note": "Poke dans les rues étroites, et le team-up avec Rocket."}, {"hero": "groot", "note": "Ses murs ferment les entrées du jardin."}, {"hero": "luna-snow", "note": "Assez de self-peel pour survivre aux flanks."}], "sources": [{"title": "Lower Manhattan map guide", "author": "", "url": "https://marvelrivals.gg/lower-manhattan/"}, {"title": "Lower Manhattan Map Guide: Best Chokepoints, Team Comp", "author": "", "url": "https://beebom.com/marvel-rivals-lower-manhattan-map-guide/amp/"}, {"title": "Every Marvel Rivals Map Explained (2026)", "author": "", "url": "https://esports.gg/guides/marvel-rivals/every-marvel-rivals-map-explained-your-complete-2026-guide/"}], "difficulty": 0, "counters": [], "roles": {"Vanguard": ["En défense, **un tank solide tient l'arche** du jardin ; en attaque, on pousse **au centre, en groupe**.", "Sur le pont final, c'est un face-à-face : un tank solide plus un DPS qui **suppresse** la zone.", "Évite les passages où **une seule poussée** peut enchaîner les contrôles sur toute ton équipe."], "Duelist": ["Les **balcons** autour de la statue de Jeff décident du fight : prends-les avec un héros de longue portée.", "Le **scan** révèle tout le monde régulièrement (alarme avant) : lance tes flanks juste après un scan, pas juste avant.", "Poke et burst (The Punisher, Hela, Star-Lord) sont à l'aise dans les rues étroites."], "Strategist": ["Tiens **les plateformes en hauteur** autour du point, loin du centre.", "Le scan montre aussi **ta charge d'ult** : l'ennemi sait quand tu l'as, garde-la pour le bon moment.", "Les packs de soin sont nombreux (deli, parking, salles latérales) : **tourne entre eux**."]}, "title": "Lower Manhattan"}$j$::jsonb from public.maps m where m.name = 'Lower Manhattan' on conflict (map_id) where kind = 'map' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, map_id, status, content) select 'map', m.id, 'published', $j${"summary": "Une carte Convoi qui mélange galeries fermées, petites salles et une fin en extérieur. Les salles réduisent la valeur des héros de longue portée au début, puis la fin de carte ouverte leur rend l'avantage.", "tldr": ["Premier choke : **la grande porte** devant le spawn d'attaque. Passez ensemble, ou par la porte de droite.", "Au deuxième point, la défense tient **le pont latéral** qui voit presque toutes les entrées.", "La fin en extérieur est ouverte, avec **une falaise** d'un côté : héros volants et de longue portée y brillent."], "tags": ["Convoi", "Salles", "Flank", "Vide"], "sections": [{"title": "Le plan de jeu", "lead": "Chaque section demande un autre type de héros : sois prêt à swap.", "items": ["Au premier point : **courte portée et flankers** (Magik, Blade, Black Panther).", "Au deuxième : **burst** pour la défense (Squirrel Girl, The Punisher, Moon Knight).", "À l'extérieur : **volants et longue portée** (Iron Man, Hela, Ultron)."], "kind": "tips", "diagram": "brawl"}, {"title": "Premier point", "lead": "Des fights chaotiques, avec beaucoup de routes.", "items": ["Le choke est **la grande porte** juste devant le spawn de l'attaque.", "La **porte de droite** mène dans le dos de la défense.", "Les **cages** de la première salle servent d'abris."], "kind": "default", "diagram": "flank"}, {"title": "Deuxième point", "lead": "Des salles, des chemins latéraux et un couloir en zigzag.", "items": ["En défense, **tenez le pont latéral** : il surplombe presque toutes les entrées.", "Le **couloir en zigzag** est un excellent spot pour les mines de Peni et le burst."], "kind": "default", "diagram": "choke"}, {"title": "L'extérieur et l'arrivée", "lead": "Une route presque droite avec des ponts et des bâtiments en hauteur.", "items": ["Contrôler **les ponts** est la clé pour les deux équipes.", "Un côté donne sur **une falaise** : un repoussement suffit.", "La route est droite : attends-toi à des **fights frontaux**, gagnés par la meilleure combinaison d'ults."], "kind": "default", "diagram": "highground"}, {"title": "Erreurs fréquentes", "lead": "", "items": ["Garder **le même héros** sur les trois sections sans s'adapter.", "Passer **un par un** par la grande porte.", "Laisser **le pont latéral** du deuxième point.", "Se placer **au bord de la falaise** en fin de carte."], "kind": "mistakes"}], "synergies": [{"hero": "black-panther", "note": "Efficace sur toute la carte grâce à la verticalité."}, {"hero": "peni-parker", "note": "Ses mines tiennent le couloir en zigzag."}, {"hero": "iron-man", "note": "La fin en extérieur est faite pour lui."}, {"hero": "magik", "note": "Les salles du premier point favorisent la courte portée."}], "sources": [{"title": "Museum of Contemplation map guide", "author": "", "url": "https://marvelrivals.gg/museum-of-contemplation/"}, {"title": "Every Marvel Rivals Map Explained (2026)", "author": "", "url": "https://esports.gg/guides/marvel-rivals/every-marvel-rivals-map-explained-your-complete-2026-guide/"}], "difficulty": 0, "counters": [], "roles": {"Vanguard": ["Le premier choke est **la grande porte devant le spawn** de l'attaque : passez ensemble, pas un par un.", "Brawlers et héros de courte portée sont à l'aise **dans les salles du premier point**."], "Duelist": ["En défense, **tenez le pont latéral** du deuxième point : il voit presque toutes les entrées.", "Flankers : la **porte de droite** du premier point mène dans le dos de la défense.", "À l'extérieur, la fin de carte est **ouverte et en hauteur** : héros volants et de longue portée y brillent."], "Strategist": ["Les **cages** de la première salle font de bons abris.", "Dans le couloir en zigzag du deuxième point, **reste derrière un angle** : les mines et le burst y font très mal.", "Sur la fin, un côté donne sur **le vide** : ne te place pas au bord."]}, "title": "Museum of Contemplation"}$j$::jsonb from public.maps m where m.name = 'Museum of Contemplation' on conflict (map_id) where kind = 'map' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, map_id, status, content) select 'map', m.id, 'published', $j${"summary": "La carte Convoi de la saison 9, dans le royaume d'Apocalypse. Grande et très verticale : plateformes, ruelles étroites, chokes et routes de flank récompensent le placement. Le troisième point s'ouvre sur une grande zone avec une falaise.", "tldr": ["Premier point : **trois chemins** (plateforme à gauche, ruelle du convoi au milieu, ruelle avec tour à droite), avec des escaliers de flank des deux côtés.", "Deuxième point : surveille **la plateforme de gauche**, un raccourci derrière le convoi.", "Troisième point : attire le fight **dans la zone ouverte** de gauche, bordée d'une falaise."], "tags": ["Convoi", "Verticalité", "Flank", "Vide"], "sections": [{"title": "Le plan de jeu", "lead": "Une carte grande et verticale : celui qui connaît les routes prend l'avantage.", "items": ["En attaque, **restez avec le convoi** et ne vous séparez que quand une route latérale donne un vrai avantage.", "Mélanger **mêlée et longue portée**, sol et vol, couvre tous les angles."], "kind": "tips", "diagram": "flank"}, {"title": "Premier point", "lead": "Dès la sortie, le premier gros choke, entouré de plateformes.", "items": ["À gauche, une plateforme mène à **une salle en hauteur** avec deux packs de soin ; à droite, une ruelle avec une tour, une falaise et deux packs de soin.", "Des **escaliers de chaque côté** passent derrière le choke : parfaits pour attraper un support.", "Les héros de **burst à distance** et à tourelles (Moon Knight, The Punisher) y sont à l'aise."], "kind": "default", "diagram": "choke"}, {"title": "Deuxième point", "lead": "Un intérieur futuriste sur plusieurs niveaux.", "items": ["La **plateforme de gauche** est un raccourci derrière le convoi : la défense doit la surveiller.", "La **grande plateforme de droite** mène à l'étage : la tenir donne la hauteur sur tout le combat.", "En bas, un **jump pad** fait monter puis glisser jusqu'à un pack de soin : une sortie pour les flankers."], "kind": "default", "diagram": "highground"}, {"title": "Troisième point et salle finale", "lead": "Plus ouvert, fait pour les fights à six.", "items": ["À gauche, une **grande zone ouverte** longée par une falaise : les repoussements y tuent net. En défense, attirez le fight là-bas.", "Dans la salle finale, la défense tient **les entrées latérales** pour forcer l'attaque dans le couloir central, où le burst de zone fait mal."], "kind": "default", "diagram": "ultcombo"}, {"title": "Erreurs fréquentes", "lead": "", "items": ["Se séparer du convoi **sans raison**.", "Oublier **la plateforme de gauche** au deuxième point.", "Se battre **au bord de la falaise** au troisième point.", "Laisser **les entrées latérales** de la salle finale ouvertes."], "kind": "mistakes"}], "synergies": [{"hero": "moon-knight", "note": "Le premier point convient à son burst à distance."}, {"hero": "the-punisher", "note": "Sa tourelle et son poke tiennent les chokes du premier point."}, {"hero": "black-cat", "note": "Les escaliers de flank mènent droit aux supports."}, {"hero": "spider-man", "note": "La verticalité et les flanks sont faits pour lui."}], "sources": [{"title": "Thebes map guide", "author": "", "url": "https://marvelrivals.gg/thebes/"}, {"title": "Every Marvel Rivals Map Explained (2026)", "author": "", "url": "https://esports.gg/guides/marvel-rivals/every-marvel-rivals-map-explained-your-complete-2026-guide/"}], "difficulty": 0, "counters": [], "roles": {"Vanguard": ["Au premier point, le chemin du convoi passe par **une ruelle étroite** : un tank qui la bouche gagne beaucoup de temps.", "Au troisième point, l'espace s'ouvre : **contrôle la grande zone ouverte** et pousse l'ennemi vers la falaise."], "Duelist": ["Des **escaliers de chaque côté** du premier choke mènent derrière : idéal pour attraper un support.", "Deuxième point : la **plateforme de gauche** est un raccourci derrière le convoi, la défense doit la surveiller.", "Le **jump pad** du niveau bas te fait monter puis glisser jusqu'à un pack de soin : une porte de sortie pour flankers."], "Strategist": ["Les packs de soin sont regroupés sur **les deux premiers points** : place-toi à couvert près d'eux.", "Au troisième point, une **grande falaise** borde la zone de gauche : un repoussement et c'est fini.", "Salle finale : la défense tient **les entrées latérales** pour forcer l'attaque dans le couloir central."]}, "title": "Thebes"}$j$::jsonb from public.maps m where m.name = 'Thebes' on conflict (map_id) where kind = 'map' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, map_id, status, content) select 'map', m.id, 'published', $j${"summary": "La version Domination de Klyntar. La carte est circulaire et n'a pas d'angle défensif dominant : on tourne autour du point plutôt que de s'installer. Les équipes de dive y sont à l'aise. Guide court, à compléter avec vos parties.", "tldr": ["Pas de spot défensif parfait : **tourne autour du point** et change d'angle souvent.", "Les divers trouvent beaucoup d'accès : **heals, restez à portée** de votre équipe.", "Comme sur toute Domination, **tiens le couvert autour du point**, pas le cercle lui-même."], "tags": ["Domination", "Dive"], "sections": [{"title": "Le plan de jeu", "lead": "Une carte circulaire, sans position qui domine toutes les autres.", "items": ["Plutôt que de t'installer, **tourne autour du point** avec ton équipe.", "Les équipes de **dive** profitent des nombreux accès : engagez ensemble, puis ressortez.", "Une manche se joue autour d'une **statue avec l'œuf du Phénix** au centre du point."], "kind": "tips", "diagram": "dive"}, {"title": "Erreurs fréquentes", "lead": "", "items": ["Rester **planté** au même angle toute la manche.", "Heals **isolés** face à une équipe de dive.", "Se battre **au milieu du point** sans abri."], "kind": "mistakes"}], "synergies": [{"hero": "venom", "note": "Un tank de dive à l'aise avec les nombreux accès."}, {"hero": "spider-man", "note": "Les accès multiples facilitent ses dives."}], "sources": [{"title": "Every Marvel Rivals Map Explained (2026)", "author": "", "url": "https://esports.gg/guides/marvel-rivals/every-marvel-rivals-map-explained-your-complete-2026-guide/"}, {"title": "Severed Outpost achievement (Celestial Husk)", "author": "", "url": "https://marvelrivals.gg/?p=8692"}], "difficulty": 0, "counters": [], "roles": {"Vanguard": ["Carte circulaire **sans angle défensif dominant** : ne t'installe pas, tourne autour du point avec ton équipe.", "Les tanks de dive y sont à l'aise : **engagez ensemble** sur une cible, puis ressortez."], "Duelist": ["Pas de spot parfait : **change d'angle** souvent pour ne pas être lu.", "Les divers trouvent beaucoup d'accès : **cherche les heals isolés**."], "Strategist": ["Sans hauteur dominante, **reste à portée de ton équipe** : un dive te trouve vite sinon.", "Garde **un abri entre toi et le point** pour soigner sans être vu de partout."]}, "title": "Celestial Husk"}$j$::jsonb from public.maps m where m.name = 'Klyntar: Celestial Husk' on conflict (map_id) where kind = 'map' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, map_id, status, content) select 'map', m.id, 'published', $j${"summary": "La carte Domination de la saison 10, en trois sections : House of Ideas, Halls of All-Knowing et Confessional Eternity. Des salles fermées où les soins passent mal, beaucoup de hauteur et des falaises.", "tldr": ["House of Ideas : le point est **à l'étage**, le niveau du bas ne compte pas.", "Halls of All-Knowing : la **structure suspendue** au-dessus du point domine le combat.", "Confessional Eternity : l'orbe central **se détruit**, ne compte pas sur lui comme abri."], "tags": ["Domination", "High ground", "Salles", "Vide"], "sections": [{"title": "Le plan de jeu", "lead": "Des salles serrées : les soins passent mal, il faut toujours une sortie vers ses heals.", "items": ["Attaque **par plusieurs angles** : portes, passages souterrains, étages.", "Héros volants, flankers et brawlers sont conseillés ; Emma Frost brille dans les espaces serrés.", "Garde toujours **un chemin de retour** vers tes supports."], "kind": "tips", "diagram": "brawl"}, {"title": "House of Ideas", "lead": "Une salle carrée et étroite, avec le point à l'étage.", "items": ["Le point est **en haut** : le niveau du bas ne compte pas pour la capture.", "Les couloirs sont couverts par **des murs indestructibles** : les héros de longue portée doivent se rapprocher.", "Le **balcon** est relié directement au point et donne la hauteur ; les couloirs latéraux servent aux flankers."], "kind": "default", "diagram": "choke"}, {"title": "Halls of All-Knowing", "lead": "Plusieurs étages et une structure suspendue au-dessus du point.", "items": ["La **structure suspendue** et les étages permettent d'attaquer le point de plusieurs côtés.", "Des **falaises** des deux côtés récompensent les repoussements.", "Après la capture, repoussez l'ennemi **dans les bibliothèques** derrière le point.", "**Trois packs de soin** sont regroupés d'un côté."], "kind": "default", "diagram": "highground"}, {"title": "Confessional Eternity", "lead": "Le point est entouré de murs et d'espaces étroits ; beaucoup de verticalité.", "items": ["Un tank **ancre le centre** ; on tient la porte extérieure et la plateforme de l'autel.", "Des escaliers latéraux depuis le spawn mènent à **un spot de sniper** en hauteur.", "Des routes de flank des deux côtés, dont une par **le bassin de lave** ; les bords récompensent les repoussements.", "L'**orbe central** se détruit : ne t'en sers pas comme abri durable."], "kind": "default", "diagram": "space"}, {"title": "Erreurs fréquentes", "lead": "", "items": ["Se battre **au rez-de-chaussée** de House of Ideas.", "Compter sur **l'orbe** comme abri.", "Flank **sans chemin de retour** vers les heals.", "Laisser **la structure suspendue** aux ennemis."], "kind": "mistakes"}], "synergies": [{"hero": "emma-frost", "note": "Les murs des salles rendent ses repoussements et contrôles redoutables."}, {"hero": "iron-man", "note": "La verticalité de Confessional Eternity lui convient."}, {"hero": "invisible-woman", "note": "Souvent conseillée sur deux des trois sections."}, {"hero": "hela", "note": "Les spots en hauteur lui donnent de bons angles."}], "sources": [{"title": "God Quarry Map Guide: Best Routes, Team Comp", "author": "", "url": "https://beebom.com/marvel-rivals-god-quarry-map-guide/"}, {"title": "God Quarry map guide", "author": "", "url": "https://www.games.gg/marvel-rivals/guides/marvel-rivals-god-quarry-map-guide/"}], "difficulty": 0, "counters": [], "roles": {"Vanguard": ["House of Ideas : le point est **à l'étage**, le niveau du bas ne compte pas ; tenez les entrées du haut.", "Confessional Eternity : un tank **ancre le centre** ; l'orbe central se détruit, ne compte pas sur lui comme abri.", "Dans les salles serrées, les repoussements contre les murs (Emma Frost) font très mal."], "Duelist": ["Halls of All-Knowing : la **structure suspendue** au-dessus du point et les étages offrent la hauteur.", "Confessional Eternity : des escaliers latéraux depuis le spawn mènent à **un spot de sniper** en hauteur.", "Les **bords de falaise** (bassin de sang, côtés des Halls) récompensent les repoussements."], "Strategist": ["Dans les salles fermées, **les lignes de vue sont courtes** : place-toi pour voir tes tanks, avec une sortie derrière.", "Halls of All-Knowing : **trois packs de soin** sont regroupés d'un côté, joue à proximité.", "Invisible Woman et Jubilee sont souvent conseillées ici."]}, "title": "God Quarry"}$j$::jsonb from public.maps m where m.name = 'God Quarry' on conflict (map_id) where kind = 'map' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);

-- 8. Guides généraux
insert into public.guides (kind, slug, status, content) values ('general', 'game-sense', 'published', $j${"title": "Game sense", "summary": "Le game sense, c'est savoir à chaque instant ce qui se passe, où, quand et pourquoi : cooldowns, ults, espace, staggers. À haut niveau, c'est lui qui fait la différence bien plus que la visée.", "tldr": ["**Suis les cooldowns clés** adverses (diamant d'Emma, soin de Loki, ult de Strange) : sans eux, l'ennemi est vulnérable.", "Gagne **le cycle d'ults** : utiliser son ult après celle de l'adversaire vaut presque toujours mieux qu'avant.", "**Communique** : la moitié du game sense, c'est dire à ton équipe ce que tu sais."], "difficulty": 0, "tags": ["Fondamentaux", "Cooldowns", "Ults", "Espace"], "sections": [{"title": "Les cooldowns", "lead": "Forcer un gros cooldown défensif, puis attaquer pendant qu'il recharge : c'est la base de tous les engages.", "items": ["Demande à ton équipe d'**annoncer les cooldowns** dès qu'ils partent : « Emma sans diamant », « Loki sans soin ».", "Pas d'annonce ? **Force-le toi-même**, recule, puis reviens pendant qu'il recharge.", "Repère qui **n'a pas utilisé son ult** depuis longtemps (un Strange qui attend) et garde ton contrôle (gel de Luna, hook de Winter Soldier) pour lui."], "diagram": "reset"}, {"title": "Le cycle d'ults", "lead": "Les ults de support gagnent presque un fight à elles seules : savoir qui a la sienne, et quand, décide des fights suivants.", "items": ["Un kill au début d'un fight donne de l'ult à **toute ton équipe**, et aucune aux heals adverses qui n'ont rien soigné : tu as ton ult avant la leur.", "Avec la moitié de ta jauge, fais **forcer l'ult adverse** par tes DPS ; elle tombera à un mauvais moment, et la tienne arrivera pour gagner la fin du fight.", "Après un fight perdu, compte les ults : si l'ennemi a **tout utilisé**, le prochain fight est à toi.", "**Ults miroir** : si l'ennemi lance son ult de soin, lance la tienne ensuite ou attends qu'elle se termine. Garde les ults défensives (Magneto) pour couper la leur."], "diagram": "ultcombo"}, {"title": "Les staggers", "lead": "Un stagger, c'est un joueur qui revient seul après un fight et meurt seul. C'est le meilleur moyen de perdre du terrain sans se battre.", "items": ["Fight perdu ? **Meurs en même temps** que ton équipe ou fuis, mais ne prolonge pas un fight perdu : tu retardes le prochain vrai fight.", "Fight gagné ? **Avance tout de suite** pour attraper ceux qui reviennent un par un."]}, {"title": "L'espace", "lead": "L'espace, c'est le terrain que l'ennemi n'occupe pas. Plus ton équipe en a, plus elle a d'angles.", "items": ["Tanks : **avancez les premiers** sur le point, bouclier levé, pour que vos DPS jouent autour de vous sans prendre le spam.", "DPS : vous prenez aussi de l'espace en **jouant les coins** et en menaçant la backline.", "Après un fight gagné, **occupez les positions** d'où l'ennemi pourrait recontester."], "diagram": "space"}, {"title": "Peel et focus", "lead": "Les heals sont la cible la plus facile du jeu : les protéger passe avant n'importe quel espace.", "items": ["Si tes heals se font dive, **un ou deux joueurs se retournent** sur le diver : un tank qui avance sans soins meurt.", "Heals : **soignez-vous entre vous** en priorité, vous gardez toute l'équipe en vie.", "Quand ton équipe choisit une cible, **ne tire sur personne d'autre** : elle tombera dix fois plus vite."], "diagram": "peel"}], "counters": [], "synergies": [], "combos": [], "sources": [{"title": "How to Get Perfect Game Sense in Marvel Rivals", "author": "Kingsman", "url": "https://www.youtube.com/watch?v=zRGtV4MVo3I"}]}$j$::jsonb) on conflict (slug) where kind = 'general' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, slug, status, content) values ('general', 'solo-queue', 'published', $j${"title": "Survivre en solo queue", "summary": "Monter seul, c'est possible à tous les rôles : il faut un mental solide, plusieurs héros par rôle, jouer l'espace plutôt que les stats, et parler. Ce guide regroupe les conseils de quelqu'un qui est monté au plus haut rang en solo, en heal, en tank et en DPS.", "tldr": ["**Ne lâche jamais une partie** : tes points gagnés et perdus dépendent aussi de ta performance individuelle.", "Apprends **plusieurs héros** par rôle et **change** quand tu es contré : l'ego ne fait pas gagner.", "**Allume ton micro** : surtout en heal, c'est ce qui fait que ton équipe te protège."], "difficulty": 0, "tags": ["Solo queue", "Mental", "Communication", "Réglages"], "sections": [{"title": "Le mental", "lead": "Les parties qui semblent perdues se retournent souvent, et même perdue, une bonne performance limite la perte de points.", "items": ["**Mute** celui qui insulte au lieu d'entrer dans le conflit : garde ta tête dans la partie.", "Les stats de fin de partie (dégâts, soins) **ne mesurent pas ton impact** : un tank qui occupe trois ennemis sans kill peut être le meilleur joueur de la partie.", "Les morts comptent bien plus que les dégâts : **20 morts** pèsent plus lourd que 50 000 soins."]}, {"title": "Flex", "lead": "Un one-trick dont le héros est banni ou contré ne monte pas.", "items": ["Connais **plusieurs héros par rôle**, et au moins un pour chaque situation : dive, brawl, peel.", "Si le front perd malgré ton dive (Spider-Man, Captain America), **change** pour aider le main.", "Changer pour un support qui contre la compo adverse vaut mieux que perdre avec ton main."]}, {"title": "Selon ton rôle", "lead": "Chaque rôle a un travail différent, mais tous servent l'espace et l'objectif.", "items": ["**DPS** : crée de l'espace (en forçant les heals à te regarder) ou profite-en pour les picks. Vis dans les murs, utilise les angles morts, ne te montre aux supports qu'une fois sur eux.", "DPS de dive : n'aie pas peur du **brawl pendant les ults de soin** : tu y recharges ton ult très vite.", "**Tank** : peel quand tes heals appellent, crée l'espace, suis l'état et la position de tes supports, et sers d'éponge à dégâts **près d'un coin** pour charger leurs ults.", "**Support** : lance ton ult **après** celle de l'adversaire, presque jamais en premier. Tenir la tienne plus longtemps que lui gagne les fights."], "diagram": "pocket"}, {"title": "Communication", "lead": "En solo, ta voix est ton meilleur outil.", "items": ["Heal qui se fait dive : **annonce-le**. Sans info, ton équipe pense juste que tu es mauvais.", "Annonce tes **boosts de dégâts** (Mantis, Luna) au moment où tes DPS engagent.", "Toujours **comm, flex, swap** : c'est la recette pour monter seul."]}, {"title": "Réglages", "kind": "tips", "lead": "Pas de réglage magique, mais une logique : une sensibilité par type de héros.", "items": ["Garde une **sensibilité de base** pour tous les héros, puis ajuste les héros qui en ont besoin.", "Héros de **dive** (Magik, Iron Fist) : sensibilité **plus haute** pour te retourner vite.", "Héros de **précision** (Winter Soldier, Hela) : sensibilité **plus basse**.", "Spider-Man : la seule exception où l'on peut mettre **la verticale plus haute que l'horizontale**, pour swinguer de haut en bas.", "Sur manette, beaucoup de bons joueurs **coupent la vibration**."]}], "counters": [], "synergies": [], "combos": [], "sources": [{"title": "The Marvel Rivals Solo Queue Survival Guide", "author": "Kingsman", "url": "https://www.youtube.com/watch?v=9uSEasE8vNw"}, {"title": "Console Top 500 Settings Guide", "author": "Kingsman", "url": "https://www.youtube.com/watch?v=7VQjYLq2Co8"}]}$j$::jsonb) on conflict (slug) where kind = 'general' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);

-- 9. Compos : vocabulaire corrigé
update public.team_comps set content = $c${"name": "Brawl au contact", "style": "brawl", "heroes": [{"job": "Ouvre le combat, prend l'espace et reste au contact des ennemis.", "hero": "the-thing", "role": "Vanguard"}, {"job": "Bouclier pour traverser la zone dangereuse, portail pour revenir vite sur le point.", "hero": "doctor-strange", "role": "Vanguard"}, {"job": "Tape les tanks adverses : plus le combat dure, plus il fait mal.", "hero": "wolverine", "role": "Duelist"}, {"job": "Dégâts constants à courte distance, tourelle pour tenir une entrée.", "hero": "the-punisher", "role": "Duelist"}, {"job": "Soins de groupe constants, ult pour gagner le combat prolongé.", "hero": "luna-snow", "role": "Strategist"}, {"job": "Bonus de dégâts sur les duellistes, soins sur la durée, sommeil sur un diver.", "hero": "mantis", "role": "Strategist"}], "summary": "La compo la plus simple à jouer en groupe : deux tanks qui encaissent, deux duellistes qui tapent au contact, deux heals qui soignent large. Personne ne part seul : la force de la compo, c'est d'être collés.", "tagline": "On avance tous ensemble et on gagne le combat au corps à corps.", "weak_vs": [{"comp": "poke", "note": "Ils vous usent de loin avant le contact : coupez la distance par un mur ou un flank."}], "best_when": ["Les cartes avec des **passages étroits** et des points fermés.", "Ton équipe aime jouer **groupée** et parle peu : il y a peu de timing à caler.", "L'équipe d'en face **dive** sur vos heals : groupés, vous les punissez."], "game_plan": ["Regroupez-vous **derrière un mur** juste avant la zone de combat.", "Le tank principal annonce le départ, puis **tout le monde avance en même temps**.", "Bouclier levé pour traverser la zone découverte, sans s'arrêter.", "Au contact, **tapez tous la même cible**, en commençant par le plus proche.", "Gardez l'**ult de soin** pour le moment où les ennemis lancent leurs ults."], "strong_vs": [{"comp": "dive", "note": "Groupés, vous attrapez les divers qui arrivent dans votre zone."}], "difficulty": 1, "patch_note": "Compo type à adapter à la saison : si un héros a été affaibli, prends un remplaçant du même style.", "alternatives": [{"hero": "thor", "note": "Plus de mobilité pour ramener un tank ennemi dans ta zone.", "replaces": "the-thing"}, {"hero": "emma-frost", "note": "Bouclier solide et forme de diamant pour tenir le point.", "replaces": "doctor-strange"}, {"hero": "magik", "note": "Plus de burst au contact, mais demande des combos.", "replaces": "wolverine"}, {"hero": "adam-warlock", "note": "Sa résurrection de groupe sauve un combat perdu.", "replaces": "mantis"}], "failure_signs": ["Vous **perdez de la vie avant même le contact** : l'ennemi vous harcèle de loin.", "Un tank part **seul devant** et meurt avant que les autres arrivent.", "Les heals se retrouvent **loin derrière** et ne soignent plus personne."]}$c$::jsonb where slug = 'brawl';
update public.team_comps set content = $c${"name": "Plongée coordonnée", "style": "dive", "heroes": [{"job": "Dive le premier sur la backline et encaisse grâce à sa vie bonus.", "hero": "venom", "role": "Vanguard"}, {"job": "Suit Venom, protège les divers et relance la pression.", "hero": "captain-america", "role": "Vanguard"}, {"job": "Élimine la cible marquée par le dive, puis ressort avec ses dashes.", "hero": "black-panther", "role": "Duelist"}, {"job": "Arrive par derrière, achève les cibles basses, repart invisible.", "hero": "psylocke", "role": "Duelist"}, {"job": "Suit l'équipe avec son jetpack, balise de résurrection pour les dives ratés.", "hero": "rocket-raccoon", "role": "Strategist"}, {"job": "Vole avec les divers et les soigne là où les autres heals ne vont pas.", "hero": "ultron", "role": "Strategist"}], "summary": "Une compo très mobile qui gagne en éliminant un heal ou un tireur avant que le combat commence vraiment. Elle demande de la communication : un dive à deux réussit, un dive en solo meurt.", "tagline": "Tout le monde saute sur la même cible au même moment, puis ressort.", "weak_vs": [{"comp": "brawl", "note": "Une équipe collée vous attend et vous écrase."}, {"comp": "anti-dive", "note": "Elle est construite exprès pour vous punir."}], "best_when": ["Les cartes **ouvertes avec de la hauteur** et plusieurs chemins.", "L'équipe d'en face a des **tireurs fixes** (snipers, harceleurs à distance).", "Vous jouez **en vocal** : le moment du dive doit être annoncé."], "game_plan": ["Choisissez **une seule cible** avant le combat, idéalement un heal isolé.", "Annoncez le compte « 3, 2, 1 » et **plongez tous en même temps**.", "Tuez la cible, puis **ressortez tout de suite** vers votre équipe.", "Rechargez vos capacités à l'abri, et recommencez sur la cible suivante."], "strong_vs": [{"comp": "poke", "note": "Les tireurs à distance sont isolés : plongez dessus."}], "difficulty": 3, "patch_note": "Compo type à adapter à la saison : si un héros a été affaibli, prends un remplaçant du même style.", "alternatives": [{"hero": "thor", "note": "Plus de dégâts, et son dash ramène une cible.", "replaces": "captain-america"}, {"hero": "spider-man", "note": "Très mobile, idéal pour harceler les heals.", "replaces": "black-panther"}, {"hero": "magik", "note": "Portails pour entrer et sortir, gros burst.", "replaces": "psylocke"}, {"hero": "jeff-the-land-shark", "note": "Se faufile partout et soigne en mouvement.", "replaces": "rocket-raccoon"}], "failure_signs": ["Les divers **arrivent un par un** et meurent un par un.", "La cible du dive **survit à chaque fois** : elle a trop de soins ou de protection.", "Les ennemis jouent **collés en brawl** : vous plongez au milieu de six joueurs."]}$c$::jsonb where slug = 'dive';
update public.team_comps set content = $c${"name": "Poke à distance", "style": "poke", "heroes": [{"job": "Bouclier frontal pour protéger les tireurs, portail pour reprendre la position.", "hero": "doctor-strange", "role": "Vanguard"}, {"job": "Boucliers et bulles pour que les tireurs survivent aux échanges.", "hero": "magneto", "role": "Vanguard"}, {"job": "Tirs à la tête de loin, élimine tout ce qui sort à découvert.", "hero": "hela", "role": "Duelist"}, {"job": "Flèches à très longue portée sur les cibles qui reculent.", "hero": "hawkeye", "role": "Duelist"}, {"job": "Bouclier sur les alliés et poussée pour éloigner ceux qui s'approchent.", "hero": "invisible-woman", "role": "Strategist"}, {"job": "Soins à distance et résurrection pour retourner un combat.", "hero": "adam-warlock", "role": "Strategist"}], "summary": "Une compo qui gagne les combats avant qu'ils commencent : les tireurs touchent de loin, les tanks protègent avec leurs boucliers, et l'ennemi arrive au contact déjà affaibli. Il faut viser juste et tenir sa position.", "tagline": "On use l'adversaire de loin, derrière les boucliers, avant tout contact.", "weak_vs": [{"comp": "dive", "note": "Les divers arrivent sur vos tireurs sans passer par vos boucliers."}], "best_when": ["Les cartes avec de **longues lignes de vue** et des positions en hauteur.", "Vos tireurs **visent bien** : la compo dépend de leurs dégâts.", "L'équipe d'en face **avance lentement** et doit traverser une zone découverte."], "game_plan": ["Prenez une **position avec une longue ligne de vue**, boucliers devant.", "Tirez **avant le combat** : chaque dégât compte quand ils traversent la zone.", "Concentrez le feu sur le **tank** pour casser leur avancée, puis les fragiles.", "Si quelqu'un dive, **reculez ensemble** et tapez-le tous."], "strong_vs": [{"comp": "brawl", "note": "Ils doivent traverser votre zone de tir pour vous atteindre."}], "difficulty": 2, "patch_note": "Compo type à adapter à la saison : si un héros a été affaibli, prends un remplaçant du même style.", "alternatives": [{"hero": "emma-frost", "note": "Bouclier solide, et elle tient mieux si l'ennemi arrive au contact.", "replaces": "doctor-strange"}, {"hero": "iron-man", "note": "Harcèlement depuis les airs, difficile à atteindre.", "replaces": "hawkeye"}, {"hero": "elsa-bloodstone", "note": "Dégâts à distance avec de quoi fuir un dive.", "replaces": "hela"}, {"hero": "ultron", "note": "Soins à distance en restant en hauteur.", "replaces": "adam-warlock"}], "failure_signs": ["Des divers **atteignent vos tireurs** à chaque combat.", "Vos boucliers **tombent avant** que l'ennemi ait perdu de la vie.", "L'ennemi **contourne par les flancs** au lieu de traverser votre ligne de tir."]}$c$::jsonb where slug = 'poke';
update public.team_comps set content = $c${"name": "Anti-dive", "style": "peel", "heroes": [{"job": "Murs pour couper les chemins d'entrée et isoler les divers.", "hero": "groot", "role": "Vanguard"}, {"job": "Toiles et mines autour des heals, nid d'araignées pour tenir la zone.", "hero": "peni-parker", "role": "Vanguard"}, {"job": "Tourelles près des heals : elles tapent tout ce qui dive.", "hero": "namor", "role": "Duelist"}, {"job": "Dégâts constants pour finir les divers coincés.", "hero": "the-punisher", "role": "Duelist"}, {"job": "Soins de groupe, et une boule de neige qui arrête un diver.", "hero": "luna-snow", "role": "Strategist"}, {"job": "Poussée pour renvoyer un diver, bouclier sur l'allié ciblé.", "hero": "invisible-woman", "role": "Strategist"}], "summary": "La réponse quand l'équipe d'en face dive sans arrêt sur vos heals. Murs, toiles, tourelles et poussées : chaque diver qui arrive est ralenti, isolé puis éliminé à plusieurs.", "tagline": "On protège les heals et on punit chaque diver.", "weak_vs": [{"comp": "poke", "note": "Vos outils de protection ne servent à rien contre des tirs de loin."}], "best_when": ["L'équipe d'en face joue **plusieurs divers** (Venom, Spider-Man, Black Panther, Psylocke…).", "Vos heals **meurent en premier** à chaque combat.", "Les points avec **peu d'entrées** : les murs et les mines les bloquent facilement."], "game_plan": ["Posez tourelles, mines et toiles **autour des heals**, pas devant.", "Dès qu'un diver arrive, **tout le monde se retourne** sur lui.", "Coupez sa sortie avec un mur ou un étourdissement, puis **finissez-le à plusieurs**.", "Une fois le diver mort, **reprenez l'espace** devant : c'est du 6 contre 5."], "strong_vs": [{"comp": "dive", "note": "Chaque diver est attendu et puni."}], "difficulty": 2, "patch_note": "Compo type à adapter à la saison : si un héros a été affaibli, prends un remplaçant du même style.", "alternatives": [{"hero": "emma-frost", "note": "Son étranglement arrête un diver net.", "replaces": "groot"}, {"hero": "squirrel-girl", "note": "Le gland étourdissant immobilise les divers, même en ult.", "replaces": "the-punisher"}, {"hero": "mantis", "note": "Le sommeil endort un diver au bon moment.", "replaces": "invisible-woman"}, {"hero": "rocket-raccoon", "note": "Sa balise de résurrection rattrape un dive réussi.", "replaces": "luna-snow"}], "failure_signs": ["L'ennemi **ne dive plus** et vous harcèle de loin : passez sur une autre compo.", "Vos tourelles et mines sont **posées trop loin** des heals.", "Tout le monde **court après un diver** et abandonne le point."]}$c$::jsonb where slug = 'anti-dive';
update public.team_comps set content = $c${"name": "Piège de Groot", "style": "ultcombo", "heroes": [{"job": "Lance l'ult qui regroupe les ennemis, et coupe le terrain avec ses murs.", "hero": "groot", "role": "Vanguard"}, {"job": "Tank principal : tient le front pendant que Groot prépare son ult.", "hero": "emma-frost", "role": "Vanguard"}, {"job": "Ult sur le groupe retenu par Groot : énormes dégâts de zone.", "hero": "moon-knight", "role": "Duelist"}, {"job": "Ult en combo avec Groot, et solide au front le reste du temps.", "hero": "winter-soldier", "role": "Duelist"}, {"job": "Voile pour que ton équipe frappe à travers le combo.", "hero": "cloak-and-dagger", "role": "Strategist"}, {"job": "Soins de groupe, et ult pour survivre au combo adverse.", "hero": "luna-snow", "role": "Strategist"}], "summary": "Une compo construite autour d'un combo d'ults : Groot attire et retient les ennemis au même endroit, puis Moon Knight et Winter Soldier les éliminent en groupe. Le reste du temps, elle joue comme un brawl solide.", "tagline": "L'ult de Groot regroupe les ennemis, les autres ults finissent le travail.", "weak_vs": [{"comp": "dive", "note": "Des divers éparpillés évitent le piège."}], "best_when": ["Les **points fermés** où les ennemis restent groupés.", "Vous avez **les ults chargées en même temps** : comptez-les avant le combat.", "L'équipe d'en face joue **un seul heal avec une ult de soin** : forcez-la d'abord."], "game_plan": ["Avant le combat, **annoncez qui a son ult** : Groot, Moon Knight, Winter Soldier.", "Jouez un brawl classique jusqu'à ce que les ennemis **se regroupent**.", "Groot lance son ult **sur le groupe**, puis les ults de dégâts suivent immédiatement.", "Si l'ennemi lance une ult de soin, **attendez sa fin** pour relancer le combo."], "strong_vs": [{"comp": "brawl", "note": "Une équipe groupée est le rêve de Groot."}], "difficulty": 2, "patch_note": "Compo type à adapter à la saison : si un héros a été affaibli, prends un remplaçant du même style.", "alternatives": [{"hero": "namor", "note": "Ses tourelles et son ult se combinent bien avec Groot.", "replaces": "moon-knight"}, {"hero": "human-torch", "note": "Zones de feu sur les ennemis regroupés.", "replaces": "winter-soldier"}, {"hero": "angela", "note": "Ses ennemis attachés ne peuvent plus fuir l'ult.", "replaces": "emma-frost"}], "failure_signs": ["Un **Adam Warlock** ressuscite tout le monde après votre combo.", "Le **bouclier de Magneto** bloque le projectile de Groot.", "Vous lancez les ults **les unes après les autres** au lieu d'ensemble."]}$c$::jsonb where slug = 'groot-trap';
update public.team_comps set content = $c${"name": "Pression aérienne", "style": "highground", "heroes": [{"job": "Occupe le front au sol et protège la zone avec son bouclier.", "hero": "doctor-strange", "role": "Vanguard"}, {"job": "Pression au sol : force l'ennemi à regarder devant pendant que les volants frappent.", "hero": "thor", "role": "Vanguard"}, {"job": "Harcèle depuis les airs avec de gros dégâts de zone.", "hero": "iron-man", "role": "Duelist"}, {"job": "Pose des zones de feu depuis le ciel pour couper l'équipe adverse.", "hero": "human-torch", "role": "Duelist"}, {"job": "Vole avec les duellistes et les soigne en hauteur.", "hero": "ultron", "role": "Strategist"}, {"job": "Soins à distance et lien d'âmes pour encaisser les tirs.", "hero": "adam-warlock", "role": "Strategist"}], "summary": "Une compo qui met deux duellistes volants en hauteur : ils touchent tout le monde depuis des angles que l'ennemi ne couvre pas. Elle punit les équipes sans tireurs capables de viser en l'air.", "tagline": "Les duellistes attaquent du ciel, l'équipe adverse doit lever la tête.", "weak_vs": [{"comp": "poke", "note": "Des tireurs à distance vous visent sans difficulté."}], "best_when": ["L'équipe d'en face n'a **pas de tireurs précis** (peu de Hela, Hawkeye, Punisher…).", "Les cartes avec **un ciel dégagé** et peu de plafonds.", "Vos volants savent **changer d'angle** plutôt que rester immobiles."], "game_plan": ["Les tanks occupent l'avant **au sol** pour attirer l'attention.", "Les volants montent **sur deux angles différents** : l'ennemi ne peut pas regarder les deux.", "Visez d'abord les **tireurs capables de vous toucher** en l'air.", "Redescendez derrière un mur quand vous êtes bas en vie : **pas de soin en plein ciel**."], "strong_vs": [{"comp": "brawl", "note": "Une équipe de mêlée ne peut pas vous atteindre en l'air."}], "difficulty": 2, "patch_note": "Compo type à adapter à la saison : si un héros a été affaibli, prends un remplaçant du même style.", "alternatives": [{"hero": "storm", "note": "Volante aussi, avec des auras pour l'équipe.", "replaces": "human-torch"}, {"hero": "phoenix", "note": "Mobile en hauteur, gros dégâts de zone.", "replaces": "iron-man"}, {"hero": "magneto", "note": "Plus solide, et ses bulles protègent les volants.", "replaces": "thor"}], "failure_signs": ["Vos volants **tombent dès qu'ils décollent** : l'ennemi a des tireurs précis.", "Les tanks au sol **meurent seuls** parce que les volants sont trop loin.", "Vos heals **ne voient plus** les volants et ne les soignent pas."]}$c$::jsonb where slug = 'air';
